window.GEO=[{"id":"AFG","name":"Afghanistan","cont":"Asia","emoji":"🇦🇫","latlng":[33,65],"q":{"easy":[{"q":"Which valley of cliff niches once held two giant standing figures destroyed in 2001?","a":"Bamiyan","o":["Bamiyan","Bam","Taxila","Petra"],"f":"The Bamiyan valley held colossal Buddha statues carved into the cliff. The niches remain."},{"q":"Which rice dish with lamb, carrots, and raisins is a feast meal?","a":"Kabuli pulao","o":["Kabuli pulao","Sushi","Biryani only of Hyderabad","Paella"],"f":"Kabuli pulao is steamed rice with meat and sweet carrots. It is served at celebrations."},{"q":"Which mountain range crosses the east and center of the country?","a":"The Hindu Kush","o":["The Hindu Kush","The Alps","The Andes","The Rockies"],"f":"The Hindu Kush includes high passes such as the Salang. Its name is often linked to the region's harsh history."},{"q":"Which city is the capital of Afghanistan?","a":"Kabul","o":["Kabul","Juba","Paris","Tegucigalpa"],"f":"Kabul is the capital of Afghanistan.","kind":"capital"},{"q":"Which flag belongs to Afghanistan?","a":"AFG","o":["AFG","GNB","COD","NOR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Afghanistan.","kind":"flag"}],"medium":[{"q":"Which Sufi poet was born in Balkh in 1207, before his family fled west?","a":"Jalal al-Din Rumi","o":["Jalal al-Din Rumi","Hafez","Omar Khayyam","Ferdowsi"],"f":"He wrote the Masnavi later in Konya, in present-day Türkiye. Hafez and Khayyam were Persian poets from cities in present-day Iran, and Ferdowsi wrote the Shahnameh."},{"q":"The Minaret of Jam, a UNESCO tower of about 65 meters in a remote valley, was built in the 12th century under which dynasty?","a":"The Ghurids","o":["The Ghurids","The Mughals","The Safavids","The Ottomans"],"f":"The Ghurids ruled from the mountains of central Afghanistan and, for a time, northern India. The brick tower may have inspired later minarets farther west."},{"q":"In 1747 a loya jirga chose a young commander as leader. He is widely called the founder of the modern Afghan state. Who was he?","a":"Ahmad Shah Durrani","o":["Ahmad Shah Durrani","Babur","Ismail I","Timur"],"f":"He is also known as Ahmad Shah Baba. The Durrani Empire he built became a major power from the Indus to eastern Iran."},{"q":"What is the capital city of Afghanistan?","a":"Kabul","o":["Kabul","Yerevan","Amman","Damascus"],"f":"Kabul is the capital of Afghanistan.","kind":"capital"},{"q":"Which of these flags belongs to Afghanistan?","a":"AFG","o":["AFG","LKA","ISR","KOR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Afghanistan.","kind":"flag"}],"hard":[{"q":"The blue stone lapis lazuli has been mined for thousands of years in which northeastern region?","a":"Badakhshan","o":["Badakhshan","Helmand","Kandahar","Herat"],"f":"Sar-e-Sang in Badakhshan supplied lapis to ancient trade routes, including Egypt."},{"q":"Buzkashi riders compete to carry what to a goal circle?","a":"A goat carcass","o":["A goat carcass","A leather ball","A wooden ring","A torch"],"f":"The name means goat pulling. A skilled rider controls the carcass at a gallop."},{"q":"Which traditional coat of striped silk, worn over loose trousers, is a common men's outfit?","a":"A perahan tunban","o":["A perahan tunban","A kimono","A kilt","A sari"],"f":"The perahan tunban is a long shirt and trousers. A vest or wool coat is added in the cold."},{"q":"Which of these cities is the capital of Afghanistan?","a":"Kabul","o":["Kabul","Kandahar","Herat","Mazar-i-Sharif"],"f":"Kabul is the capital of Afghanistan.","kind":"capital"},{"q":"Which flag is the flag of Afghanistan?","a":"AFG","o":["AFG","TUR","DMA","VUT"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Afghanistan.","kind":"flag"}]}},{"id":"AGO","name":"Angola","cont":"Africa","emoji":"🇦🇴","latlng":[-12.5,18.5],"q":{"easy":[{"q":"Which coastal desert shared with Namibia reaches the shore of southern Angola?","a":"The Namib","o":["The Namib","The Gobi","The Sahara","The Kalahari"],"f":"The Namib is a foggy coastal desert. Its dunes continue from Angola into Namibia."},{"q":"Which chicken stew with palm oil and okra is home cooking in Angola?","a":"Muamba de galinha","o":["Muamba de galinha","Paella","Ceviche","Poutine"],"f":"Muamba simmers chicken in palm oil with okra. It is often served with funge, a cassava porridge."},{"q":"Which 16th-century fortress overlooks Luanda Bay?","a":"Fortaleza de Sao Miguel","o":["Fortaleza de Sao Miguel","Elmina Castle","Goree","Cape Coast Castle"],"f":"Sao Miguel fortress guarded the Portuguese port of Luanda. The city grew around that Atlantic harbor."},{"q":"Which city is the capital of Angola?","a":"Luanda","o":["Luanda","Belmopan","Abu Dhabi","Damascus"],"f":"Luanda is the capital of Angola.","kind":"capital"},{"q":"Which flag belongs to Angola?","a":"AGO","o":["AGO","KHM","WSM","LTU"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Angola.","kind":"flag"}],"medium":[{"q":"Which 17th-century ruler of Ndongo and Matamba negotiated with the Portuguese and also fought them?","a":"Queen Nzinga","o":["Queen Nzinga","Queen Amina","Yaa Asantewaa","Nandi"],"f":"She ruled from about 1624 to 1663. Amina was a Hausa queen in what is now Nigeria, Yaa Asantewaa led Asante resistance in Ghana, and Nandi was the mother of Shaka."},{"q":"A huge waterfall on the Lucala River, once called the Duque de Braganca Falls, is now named what?","a":"Kalandula Falls","o":["Kalandula Falls","Victoria Falls","Tugela Falls","Augrabies Falls"],"f":"The drop is in Malanje province. Victoria Falls lie on the Zambia-Zimbabwe border, Tugela is in South Africa, and Augrabies is on the Orange River."},{"q":"A long war against Portugal ended in independence in which year?","a":"1975","o":["1975","1960","1961","1992"],"f":"Independence came on 11 November 1975, the same year as Mozambique. A civil war then lasted until 1992. The armed revolt had begun in 1961."},{"q":"What is the capital city of Angola?","a":"Luanda","o":["Luanda","Monrovia","Mbabane","Freetown"],"f":"Luanda is the capital of Angola.","kind":"capital"},{"q":"Which of these flags belongs to Angola?","a":"AGO","o":["AGO","MDG","TZA","SSD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Angola.","kind":"flag"}],"hard":[{"q":"In the 1600s, Queen Nzinga ruled Ndongo and Matamba while resisting which European power?","a":"Portugal","o":["Portugal","Spain","Britain","France"],"f":"Nzinga mixed war and diplomacy for decades. She is remembered as a founder of Angolan resistance."},{"q":"Funge, the daily porridge of Angola, is usually stirred from which flour?","a":"Cassava","o":["Cassava","Rye","Quinoa","Buckwheat"],"f":"Cassava flour makes a stiff porridge. Maize versions are common too."},{"q":"The giant sable, an antelope with long curved horns, survives in reserves of which Angolan province?","a":"Malanje","o":["Malanje","Cabinda","Namibe","Zaire"],"f":"After the civil war the giant sable was feared gone. Biologists photographed living herds again in the 2000s."},{"q":"Which of these cities is the capital of Angola?","a":"Luanda","o":["Luanda","Huambo","Lobito","Benguela"],"f":"Luanda is the capital of Angola.","kind":"capital"},{"q":"Which flag is the flag of Angola?","a":"AGO","o":["AGO","ISR","BRB","MCO"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Angola.","kind":"flag"}]}},{"id":"ALB","name":"Albania","cont":"Europe","emoji":"🇦🇱","latlng":[41,20],"q":{"easy":[{"q":"Which stone Ottoman town in the south, with a fortress and slate roofs, is a UNESCO site?","a":"Gjirokaster","o":["Gjirokaster","Berat","Sarajevo","Dubrovnik"],"f":"Gjirokaster's houses climb a hillside under a castle. It is one of Albania's best-preserved museum cities."},{"q":"Which flaky pie of spinach, cheese, or meat is sold at every bakery?","a":"Byrek","o":["Byrek","Sushi","Pretzels","Empanadas"],"f":"Byrek is layered pastry. Cheese and spinach fillings are everyday snacks."},{"q":"Which clear blue spring near Sarande is a famous swimming hole?","a":"The Blue Eye","o":["The Blue Eye","Plitvice","Pamukkale","The Blue Lagoon"],"f":"Syri i Kalter, the Blue Eye, is a deep spring in the woods. Its color comes from the depth of the water."},{"q":"Which city is the capital of Albania?","a":"Tirana","o":["Tirana","Yerevan","Mexico City","Juba"],"f":"Tirana is the capital of Albania.","kind":"capital"},{"q":"Which flag belongs to Albania?","a":"ALB","o":["ALB","BGD","VEN","LBR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Albania.","kind":"flag"}],"medium":[{"q":"Which novelist, born in Gjirokaster, wrote The General of the Dead Army and chronicled life under dictatorship?","a":"Ismail Kadare","o":["Ismail Kadare","Ivo Andric","Orhan Pamuk","Naguib Mahfouz"],"f":"Several of his books use fable and Ottoman history to talk about modern power. He later split his time between Albania and France."},{"q":"Gjergj Kastrioti, Albania's national hero, is better known by which name from his resistance to the Ottomans?","a":"Skanderbeg","o":["Skanderbeg","Suleiman","Mehmed the Conqueror","Barbarossa"],"f":"In the 1440s he left Ottoman service and held the mountains of Albania for about 25 years. A fortress museum in Kruje tells his story."},{"q":"From the 1960s to the 1980s the government poured concrete into hundreds of thousands of small domes. What were they?","a":"Military bunkers","o":["Military bunkers","Bread ovens","Beehives","Well covers"],"f":"Enver Hoxha's government expected invasion from every side. Most bunkers were never used in war, and many still dot fields and beaches."},{"q":"What is the capital city of Albania?","a":"Tirana","o":["Tirana","Vienna","Brussels","Moscow"],"f":"Tirana is the capital of Albania.","kind":"capital"},{"q":"Which of these flags belongs to Albania?","a":"ALB","o":["ALB","POL","SVN","LTU"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Albania.","kind":"flag"}],"hard":[{"q":"Iso-polyphony of the south stacks voices in a drone. UNESCO lists it as what kind of singing?","a":"A cappella group song","o":["A cappella group song","Opera","Yodeling only","Rap"],"f":"Two or three voices hold a chord while a melody floats above. It is sung at weddings and funerals."},{"q":"Which mountain pass road, the Llogara, drops from pine forest to which coast?","a":"The Ionian shore","o":["The Ionian shore","The French Riviera","The Amalfi Coast","The Black Sea"],"f":"The road from Vlore toward Himare is famous for switchbacks above the Ionian Sea."},{"q":"The Kanun of Leke Dukagjini was a traditional law of which northern highland communities?","a":"The Geg highlanders","o":["The Geg highlanders","The Vikings","The Cossacks","The Samurai"],"f":"The Kanun set rules for honor, hospitality, and feud. It survived alongside the state for centuries."},{"q":"Which of these cities is the capital of Albania?","a":"Tirana","o":["Tirana","Durrës","Shkodër","Vlorë"],"f":"Tirana is the capital of Albania.","kind":"capital"},{"q":"Which flag is the flag of Albania?","a":"ALB","o":["ALB","WSM","FIN","MCO"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Albania.","kind":"flag"}]}},{"id":"AND","name":"Andorra","cont":"Europe","emoji":"🇦🇩","latlng":[42.5,1.5],"q":{"easy":[{"q":"Which large ski area in the Pyrenees is the country's best-known modern landmark?","a":"Grandvalira","o":["Grandvalira","Chamonix","Zermatt","Aspen"],"f":"Grandvalira links several villages. Winter sports, not a coastline, drive tourism."},{"q":"Which stew of meats, beans, and vegetables is cold-weather food in the valleys?","a":"Escudella","o":["Escudella","Sushi","Poutine","Pho"],"f":"Escudella simmers vegetables and meat. It is a mountain-house meal in cold weather."},{"q":"Which Romanesque churches with tall bell towers dot the parishes?","a":"Parish churches of the valleys","o":["Parish churches of the valleys","Gothic cathedrals of France","Stave churches","Mosques of the Sahel"],"f":"Stone churches such as Santa Coloma keep round or square Romanesque towers."},{"q":"Which city is the capital of Andorra?","a":"Andorra la Vella","o":["Andorra la Vella","Sana'a","Riyadh","Nassau"],"f":"Andorra la Vella is the capital of Andorra.","kind":"capital"},{"q":"Which flag belongs to Andorra?","a":"AND","o":["AND","ETH","NAM","GAB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Andorra.","kind":"flag"}],"medium":[{"q":"Since a 1278 agreement, Andorra has been ruled jointly by the Bishop of Urgell and which French officeholder?","a":"The president of France","o":["The president of France","The king of Spain","The mayor of Toulouse","The pope"],"f":"The French role passed from the count of Foix to the French head of state. The two co-princes remain the system even though Andorra adopted a constitution in 1993."},{"q":"Laws and public schooling in Andorra are written mainly in which language, shared with Catalonia?","a":"Catalan","o":["Catalan","Basque","Occitan","Galician"],"f":"French and Spanish are widely heard in shops, but the language of law and school is Catalan."},{"q":"The Madriu-Perafita-Claror valley, a UNESCO site, is protected as a cultural landscape of high pastures. Shepherds traditionally moved animals up in summer. That seasonal movement is called what?","a":"Transhumance","o":["Transhumance","Terrace flooding","Slash and burn","Fjord fishing"],"f":"Stone huts, terraces, and tracks in the valley record centuries of this mountain farming. The whole parish landscape was listed in 2004."},{"q":"What is the capital city of Andorra?","a":"Andorra la Vella","o":["Andorra la Vella","Tallinn","Athens","Bratislava"],"f":"Andorra la Vella is the capital of Andorra.","kind":"capital"},{"q":"Which of these flags belongs to Andorra?","a":"AND","o":["AND","LIE","LVA","MCO"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Andorra.","kind":"flag"}],"hard":[{"q":"The 1278 agreement of joint rule is called what?","a":"A pareage","o":["A pareage","A caliphate","A shogunate","A republic of only one prince"],"f":"Two co-princes, the Bishop of Urgell and the French head of state, still share the role created in the Middle Ages."},{"q":"Which river runs down the main valley toward Spain?","a":"The Valira","o":["The Valira","The Danube","The Rhine","The Ebro"],"f":"The Gran Valira drains the parishes. Tributaries meet it before the border."},{"q":"Tobacco was long a main crop in the lower parishes. It was dried in what?","a":"Wooden sheds","o":["Wooden sheds","Ice houses","Glass skyscrapers","Ship holds"],"f":"Racks of leaves hung in barns. The crop has shrunk, but the sheds remain in the landscape."},{"q":"Which of these cities is the capital of Andorra?","a":"Andorra la Vella","o":["Andorra la Vella","Escaldes-Engordany","Encamp","La Massana"],"f":"Andorra la Vella is the capital of Andorra.","kind":"capital"},{"q":"Which flag is the flag of Andorra?","a":"AND","o":["AND","ROU","TCD","MDA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Andorra.","kind":"flag"}]}},{"id":"ARE","name":"United Arab Emirates","cont":"Asia","emoji":"🇦🇪","latlng":[24,54],"q":{"easy":[{"q":"Which white marble mosque in Abu Dhabi is a landmark of courtyards and pools?","a":"The Sheikh Zayed Grand Mosque","o":["The Sheikh Zayed Grand Mosque","The Blue Mosque","The Hassan II Mosque","The Faisal Mosque"],"f":"The mosque opened in 2007. It holds one of the world's largest carpets and many chandeliers."},{"q":"Which spiced rice with meat or fish is a Gulf home dish?","a":"Machboos","o":["Machboos","Sushi","Paella","Jollof"],"f":"Machboos, or kabsa, cooks rice in the broth of lamb or chicken with dried lime and spices."},{"q":"Which creek in Dubai was the old port of pearl divers and dhows?","a":"Dubai Creek","o":["Dubai Creek","The Thames","The Bosphorus","The Chao Phraya"],"f":"Dubai Creek split the old town of Deira from Bur Dubai. Abras still ferry people across."},{"q":"Which city is the capital of United Arab Emirates?","a":"Abu Dhabi","o":["Abu Dhabi","Nouakchott","Majuro","Djibouti"],"f":"Abu Dhabi is the capital of United Arab Emirates.","kind":"capital"},{"q":"Which flag belongs to United Arab Emirates?","a":"ARE","o":["ARE","POL","KIR","MRT"],"f":"Compare the colors and symbols. One of these four flags is the national flag of United Arab Emirates.","kind":"flag"}],"medium":[{"q":"When the Burj Khalifa opened in 2010 it became, and long remained, the world's tallest what?","a":"Building","o":["Building","Bridge","Radio mast","Dam"],"f":"It stands a little over 828 meters. The design uses a stepping Y-shaped plan, partly to reduce the force of the wind."},{"q":"Before oil, the coastal towns lived from trade, fishing, and diving for what?","a":"Pearls","o":["Pearls","Sponges","Coral for lime","Ambergris only"],"f":"Divers went down on a single breath with a nose clip and a stone weight. The pearl economy collapsed in the 1930s after Japan began culturing pearls."},{"q":"Falconry, practiced across the Arabian Peninsula, was inscribed by UNESCO as heritage shared by several countries. The bird is trained to hunt what?","a":"Other birds and small game","o":["Other birds and small game","Fish at sea","Wild camels","Snakes only"],"f":"Houbara bustards were the classic quarry. Today many falcons are bred and tracked with radio, but the old partnership of hunter and bird remains."},{"q":"What is the capital city of United Arab Emirates?","a":"Abu Dhabi","o":["Abu Dhabi","Ashgabat","Kuala Lumpur","Tbilisi"],"f":"Abu Dhabi is the capital of United Arab Emirates.","kind":"capital"},{"q":"Which of these flags belongs to United Arab Emirates?","a":"ARE","o":["ARE","OMN","TUR","PHL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of United Arab Emirates.","kind":"flag"}],"hard":[{"q":"The falaj, or aflaj, shares water through channels. A related system in the emirates taps what?","a":"Groundwater","o":["Groundwater","Glaciers","Desalination only","Rain barrels"],"f":"Traditional aflaj move groundwater to date gardens. Some still run beside modern pipes."},{"q":"Liwa's oasis villages stand at the edge of which great sand desert?","a":"The Empty Quarter","o":["The Empty Quarter","The Gobi","The Namib","The Sahara"],"f":"The Rub al Khali, the Empty Quarter, begins south of Liwa. Huge dunes rise beyond the palms."},{"q":"A dhow is a wooden trading boat traditionally built with which edge-to-edge plank method?","a":"Sewn or nailed planks","o":["Sewn or nailed planks","Steel welding","Fiberglass only","Birch bark"],"f":"Gulf dhows carried dates, pearls, and dried fish. Builders still work in yards along the coast."},{"q":"Which of these cities is the capital of United Arab Emirates?","a":"Abu Dhabi","o":["Abu Dhabi","Dubai","Sharjah","Al Ain"],"f":"Abu Dhabi is the capital of United Arab Emirates.","kind":"capital"},{"q":"Which flag is the flag of United Arab Emirates?","a":"ARE","o":["ARE","ZMB","DOM","JAM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of United Arab Emirates.","kind":"flag"}]}},{"id":"ARG","name":"Argentina","cont":"South America","emoji":"🇦🇷","latlng":[-34,-64],"q":{"easy":[{"q":"Which waterfall system on the border with Brazil is a UNESCO site?","a":"Iguazu Falls","o":["Iguazu Falls","Angel Falls","Kaieteur","Victoria Falls"],"f":"Iguazu means big water. Hundreds of falls drop through the forest on the border."},{"q":"Which grilled beef, cooked over coals, is a national ritual?","a":"Asado","o":["Asado","Churrasco of Brazil","Barbecue","Braai"],"f":"An asado is a social grill of ribs, sausage, and steak. Chimichurri sauce is the usual companion."},{"q":"Which dance of the Rio de la Plata, with a bandoneon, grew in port neighborhoods?","a":"Tango","o":["Tango","Samba","Milonga only as a cousin","Cumbia"],"f":"Tango took shape in Buenos Aires and Montevideo around 1900. The bandoneon is its signature squeeze-box."},{"q":"Which city is the capital of Argentina?","a":"Buenos Aires","o":["Buenos Aires","Pretoria","Dushanbe","N'Djamena"],"f":"Buenos Aires is the capital of Argentina.","kind":"capital"},{"q":"Which flag belongs to Argentina?","a":"ARG","o":["ARG","MCO","ARE","LSO"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Argentina.","kind":"flag"}],"medium":[{"q":"Which writer, born in Buenos Aires, filled books such as Ficciones with labyrinths, mirrors, and infinite libraries?","a":"Jorge Luis Borges","o":["Jorge Luis Borges","Gabriel Garcia Marquez","Pablo Neruda","Mario Vargas Llosa"],"f":"Borges later went blind and composed by dictation. He became the best-known figure of Argentine literature worldwide."},{"q":"Which Andean summit in Argentina is the highest mountain in the Americas by elevation above sea level?","a":"Aconcagua","o":["Aconcagua","Chimborazo","Huascaran","Cotopaxi"],"f":"Aconcagua rises about 6,961 meters. Ecuador's Chimborazo is lower, yet its peak sits farther from Earth's center because the planet bulges at the equator."},{"q":"The oldest stenciled hands at Cueva de las Manos in Patagonia are roughly how old?","a":"About 9,000 years","o":["About 9,000 years","About 500 years","About 2,000 years","About 200 years"],"f":"Hunters blew pigment around their hands onto the cliff. The UNESCO site records life in Patagonia long before Europeans arrived."},{"q":"What is the capital city of Argentina?","a":"Buenos Aires","o":["Buenos Aires","Montevideo","Brasília","Santiago"],"f":"Buenos Aires is the capital of Argentina.","kind":"capital"},{"q":"Which of these flags belongs to Argentina?","a":"ARG","o":["ARG","COL","GUY","VEN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Argentina.","kind":"flag"}],"hard":[{"q":"Which folk singer, born in Tucuman, was called a voice of Latin America?","a":"Mercedes Sosa","o":["Mercedes Sosa","Violeta Parra","Chavela Vargas","Caetano Veloso"],"f":"Mercedes Sosa sang nueva cancion and was exiled in the late 1970s. She returned to huge concerts in the 1980s."},{"q":"The Perito Moreno glacier in Patagonia is famous for doing what?","a":"Calving into a lake","o":["Calving into a lake","Melting only in summer stories","Erupting","Hosting a city"],"f":"The glacier advances across a channel of Lake Argentino and periodically breaks in a loud rupture."},{"q":"Which 19th-century gaucho poem is the national epic?","a":"Martin Fierro","o":["Martin Fierro","Facundo","Don Segundo Sombra","El Gaucho"],"f":"Jose Hernandez published Martin Fierro in two parts. It defends the outlaw cowboy of the pampas."},{"q":"Which of these cities is the capital of Argentina?","a":"Buenos Aires","o":["Buenos Aires","Córdoba","Rosario","Mendoza"],"f":"Buenos Aires is the capital of Argentina.","kind":"capital"},{"q":"Which flag is the flag of Argentina?","a":"ARG","o":["ARG","URY","BGD","ZMB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Argentina.","kind":"flag"}]}},{"id":"ARM","name":"Armenia","cont":"Asia","emoji":"🇦🇲","latlng":[40,45],"q":{"easy":[{"q":"Which snowy mountain, a national symbol, has its summit across the border in Turkey?","a":"Mount Ararat","o":["Mount Ararat","Mount Damavand","Elbrus","Kazbek"],"f":"Armenians have long seen Ararat as a sacred mountain. The main summit stands in Turkey, visible from the Armenian side."},{"q":"Which grilled meat skewers are the classic picnic food?","a":"Khorovats","o":["Khorovats","Souvlaki","Satay","Seekh kebab only"],"f":"Khorovats is pork, lamb, or chicken grilled over vine trimmings or charcoal, often with vegetables."},{"q":"Which thin bread, baked in a tonir oven and listed by UNESCO, is a daily staple?","a":"Lavash","o":["Lavash","Naan","Pita","Tortilla"],"f":"Lavash is slapped onto the hot wall of a tonir. It dries into sheets that keep for months."},{"q":"Which city is the capital of Armenia?","a":"Yerevan","o":["Yerevan","Brasília","Washington, D.C.","Port of Spain"],"f":"Yerevan is the capital of Armenia.","kind":"capital"},{"q":"Which flag belongs to Armenia?","a":"ARM","o":["ARM","UKR","PRY","COD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Armenia.","kind":"flag"}],"medium":[{"q":"Around 405, Mesrop Mashtots designed a new alphabet so holy texts could be written in the local language. How many letters did that original alphabet have?","a":"36","o":["36","22","24","26"],"f":"Two further letters were added in later centuries. The script made a literature of its own possible. Georgian uses a different alphabet from about the same era, and 22, 24, and 26 are the counts of Phoenician, Greek, and Latin."},{"q":"Armenia is often described as the first state to adopt Christianity as its official religion. Tradition dates that decision to about which year?","a":"301","o":["301","33","800","1453"],"f":"The story credits King Tiridates III and Gregory the Illuminator. The exact year is traditional, but the conversion in the early 4th century is not in serious doubt."},{"q":"In 451, Vardan Mamikonian led a defeat against Sassanian Persia in defense of the Christian faith. What is that battle called?","a":"The Battle of Avarayr","o":["The Battle of Avarayr","The Battle of Manzikert","The Battle of Carrhae","The Battle of Nineveh"],"f":"Persia won the field, but the church survived. Manzikert, in 1071, was a later battle between Byzantines and Seljuks. Carrhae was a Roman defeat by the Parthians, centuries earlier."},{"q":"What is the capital city of Armenia?","a":"Yerevan","o":["Yerevan","Ashgabat","Islamabad","Thimphu"],"f":"Yerevan is the capital of Armenia.","kind":"capital"},{"q":"Which of these flags belongs to Armenia?","a":"ARM","o":["ARM","KHM","SGP","ARE"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Armenia.","kind":"flag"}],"hard":[{"q":"Which composer of the Sabre Dance was born in Tbilisi and worked in Armenia?","a":"Aram Khachaturian","o":["Aram Khachaturian","Komitas","Glinka","Stravinsky"],"f":"Khachaturian wrote the ballets Gayane and Spartacus. The Sabre Dance became a worldwide encore."},{"q":"The temple of Garni is a Hellenistic colonnade rebuilt in which material?","a":"Basalt","o":["Basalt","Marble","Mud brick","Timber"],"f":"Garni, east of Yerevan, is the best-preserved pre-Christian temple in the country. It was toppled by an earthquake and later re-erected."},{"q":"Which apricot, a national fruit, appears in brandy, leather, and the color of the flag's symbolism?","a":"The apricot","o":["The apricot","The apple","The fig","The date"],"f":"The Latin name Prunus armeniaca recalls an old idea that the fruit came from this region. Dried apricot sheets are a snack."},{"q":"Which of these cities is the capital of Armenia?","a":"Yerevan","o":["Yerevan","Gyumri","Vanadzor","Dilijan"],"f":"Yerevan is the capital of Armenia.","kind":"capital"},{"q":"Which flag is the flag of Armenia?","a":"ARM","o":["ARM","TGO","COD","FJI"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Armenia.","kind":"flag"}]}},{"id":"ATG","name":"Antigua and Barbuda","cont":"North America","emoji":"🇦🇬","latlng":[17.05,-61.8],"q":{"easy":[{"q":"Which harbor town of restored Georgian docks is a famous yachting stop?","a":"English Harbour","o":["English Harbour","Codrington","St. John's","Liberta"],"f":"Nelson's Dockyard at English Harbour serviced Royal Navy ships. The restored yard is a UNESCO site."},{"q":"Which peppery sauce of the island seasons grilled lobster and fungee?","a":"Susie","o":["Susie","Mole","Chimichurri","Pesto"],"f":"Fungee is a cornmeal ball. The sauce beside it is hot with local peppers and is often just called pepper sauce."},{"q":"Which street festival of costumes and calypso fills the roads after Easter?","a":"Carnival","o":["Carnival","Crop Over","Junkanoo","Mardi Gras"],"f":"Bands parade in jeweled costumes. The season is the island's biggest party."},{"q":"Which city is the capital of Antigua and Barbuda?","a":"St. John's","o":["St. John's","Harare","Manila","Warsaw"],"f":"St. John's is the capital of Antigua and Barbuda.","kind":"capital"},{"q":"Which flag belongs to Antigua and Barbuda?","a":"ATG","o":["ATG","BRN","IDN","ALB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Antigua and Barbuda.","kind":"flag"}],"medium":[{"q":"Which cricketer, born in St. John's, is widely ranked among the greatest batsmen and captained the West Indies?","a":"Vivian Richards","o":["Vivian Richards","Brian Lara","Garfield Sobers","Clive Lloyd"],"f":"Richards played from 1974 to 1991 and was known for attacking bowling without a helmet. Lara was born in Trinidad, Sobers in Barbados, and Lloyd in Guyana."},{"q":"Nelson's Dockyard at English Harbour is a restored Georgian yard built to repair warships. Why was this harbor so useful?","a":"High hills shielded it from hurricanes","o":["High hills shielded it from hurricanes","It never experienced a low tide","It was a freshwater lake","It froze solid each winter"],"f":"The UNESCO site served the British fleet in the 18th century. Horatio Nelson was stationed here as a young captain and reportedly disliked the post."},{"q":"Antigua and Barbuda became an independent state in which year?","a":"1981","o":["1981","1962","1974","1991"],"f":"Britain had held the islands since the 17th century, after earlier Spanish and French claims. Independence came as a constitutional monarchy in the Commonwealth."},{"q":"What is the capital city of Antigua and Barbuda?","a":"St. John's","o":["St. John's","Guatemala City","Panama City","Santo Domingo"],"f":"St. John's is the capital of Antigua and Barbuda.","kind":"capital"},{"q":"Which of these flags belongs to Antigua and Barbuda?","a":"ATG","o":["ATG","LCA","SLV","BHS"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Antigua and Barbuda.","kind":"flag"}],"hard":[{"q":"Which sport did Vivian Richards captain for the West Indies?","a":"Cricket","o":["Cricket","Football","Rugby","Baseball"],"f":"Richards, born on the larger island, was one of cricket's great batsmen. The stadium in North Sound is named for him."},{"q":"Redonda, a steep uninhabited rock, is legally part of the country and once had what odd claim?","a":"A self-styled king of a micronation story","o":["A self-styled king of a micronation story","A volcano city","A pirate republic recognized by Spain","A space port"],"f":"Phosphate was dug there. Later writers played at a fictional kingdom. The rock itself is a real dependency."},{"q":"Which category-5 hurricane in 2017 stripped roofs and the dockyard's landscape?","a":"Hurricane Irma","o":["Hurricane Irma","Katrina","Andrew","Gilbert"],"f":"Irma passed over Barbuda with devastating winds. The whole island was evacuated for a time."},{"q":"Which of these cities is the capital of Antigua and Barbuda?","a":"St. John's","o":["St. John's","English Harbour","Codrington","Liberta"],"f":"St. John's is the capital of Antigua and Barbuda.","kind":"capital"},{"q":"Which flag is the flag of Antigua and Barbuda?","a":"ATG","o":["ATG","LUX","BEL","MDA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Antigua and Barbuda.","kind":"flag"}]}},{"id":"AUS","name":"Australia","cont":"Oceania","emoji":"🇦🇺","latlng":[-27,133],"q":{"easy":[{"q":"Which red sandstone monolith in the center is a sacred site of the Anangu?","a":"Uluru","o":["Uluru","Kata Tjuta","The Olgas only as a neighbor","Devils Marbles"],"f":"Uluru rises from the desert in the Northern Territory. The Anangu ask visitors not to climb it."},{"q":"Which spread of yeast and black salt on toast is a breakfast favorite?","a":"Vegemite","o":["Vegemite","Marmite","Peanut butter","Nutella"],"f":"Vegemite was developed in Melbourne in the 1920s from brewer's yeast. It is very salty."},{"q":"Which large shell opera house stands on a harbor?","a":"The Sydney Opera House","o":["The Sydney Opera House","The Harbour Bridge","Federation Square","The Arts Centre"],"f":"Jorn Utzon designed the shells. The building opened in 1973 on Bennelong Point."},{"q":"Which city is the capital of Australia?","a":"Canberra","o":["Canberra","Tokyo","Castries","Cairo"],"f":"Canberra is the capital of Australia.","kind":"capital"},{"q":"Which flag belongs to Australia?","a":"AUS","o":["AUS","MRT","ALB","MDA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Australia.","kind":"flag"}],"medium":[{"q":"Which Australian scientist, born in Adelaide, led the work that turned penicillin into a medicine that could be mass-produced?","a":"Howard Florey","o":["Howard Florey","Alexander Fleming","Louis Pasteur","Marie Curie"],"f":"Fleming noticed penicillin in 1928. Florey and Ernst Chain showed it could cure infections, and all three shared the 1945 Nobel Prize."},{"q":"Uluru is a sacred sandstone monolith for which Aboriginal people of central Australia?","a":"The Anangu","o":["The Anangu","The Yolngu","The Maori","The Noongar"],"f":"The Anangu ask visitors not to climb Uluru. The climb was closed in 2019 out of respect for that tradition."},{"q":"The First Fleet anchored in Botany Bay in 1788, but the penal colony was founded days later at which cove?","a":"Sydney Cove","o":["Sydney Cove","Botany Bay","Hobart","Darwin"],"f":"Captain Arthur Phillip found Botany Bay a poor harbor and moved the ships north to Port Jackson, landing at Sydney Cove."},{"q":"What is the capital city of Australia?","a":"Canberra","o":["Canberra","Yaren","Apia","Nuku'alofa"],"f":"Canberra is the capital of Australia.","kind":"capital"},{"q":"Which of these flags belongs to Australia?","a":"AUS","o":["AUS","TON","NRU","WSM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Australia.","kind":"flag"}],"hard":[{"q":"Which goldfields town west of Melbourne keeps a reconstructed 1850s street?","a":"Ballarat","o":["Ballarat","Kalgoorlie","Broken Hill","Coober Pedy"],"f":"The Victorian gold rushes of the 1850s drew people from around the world. At Ballarat, miners rebelled over licenses at the Eureka Stockade in 1854."},{"q":"The Great Barrier Reef is built by which tiny animals?","a":"Coral polyps","o":["Coral polyps","Fish","Sponges only","Algae only"],"f":"Polyps secrete limestone cups. The reef is the largest living structure of its kind and a UNESCO site."},{"q":"Which airborne medical service, begun in 1928, reaches remote stations?","a":"The Royal Flying Doctor Service","o":["The Royal Flying Doctor Service","CareFlight only","The ambulance","The navy"],"f":"John Flynn organized the service from Cloncurry. Radios and planes linked isolated homesteads."},{"q":"Which of these cities is the capital of Australia?","a":"Canberra","o":["Canberra","Sydney","Melbourne","Perth"],"f":"Canberra is the capital of Australia.","kind":"capital"},{"q":"Which flag is the flag of Australia?","a":"AUS","o":["AUS","TUV","FJI","NZL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Australia.","kind":"flag"}]}},{"id":"AUT","name":"Austria","cont":"Europe","emoji":"🇦🇹","latlng":[47.33333333,13.33333333],"q":{"easy":[{"q":"Which palace on the edge of Vienna was the Habsburg summer residence?","a":"Schonbrunn","o":["Schonbrunn","Versailles","The Hermitage","Topkapi"],"f":"Schonbrunn's yellow facade and gardens were the stage for Habsburg court life. Mozart played there as a child."},{"q":"Which thin breaded cutlet is a Vienna classic?","a":"Wiener schnitzel","o":["Wiener schnitzel","Sushi","Tempura","Fish and chips"],"f":"A schnitzel is veal or pork, pounded thin, breaded, and fried. Potato salad often comes with it."},{"q":"Which composer of symphonies and operas was born in Salzburg in 1756?","a":"Wolfgang Amadeus Mozart","o":["Wolfgang Amadeus Mozart","Beethoven","Bach","Chopin"],"f":"Mozart's birthplace is a museum in Salzburg's old town. The city still holds a famous music festival."},{"q":"Which city is the capital of Austria?","a":"Vienna","o":["Vienna","Mexico City","Havana","Managua"],"f":"Vienna is the capital of Austria.","kind":"capital"},{"q":"Which flag belongs to Austria?","a":"AUT","o":["AUT","VEN","BRN","GNB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Austria.","kind":"flag"}],"medium":[{"q":"Which physicist, born in Vienna, imagined a cat both alive and dead to question quantum measurement?","a":"Erwin Schrodinger","o":["Erwin Schrodinger","Niels Bohr","Werner Heisenberg","Max Planck"],"f":"He published the cat thought experiment in 1935. He shared the 1933 Nobel Prize for the wave equation that carries his name."},{"q":"Hallstatt and the Dachstein mountains sit above Bronze Age salt mines. Salt preserved food, so the mineral was valuable enough to be called what?","a":"White gold","o":["White gold","Black iron","Red ochre","Blue clay"],"f":"The town's name is tied to an ancient Celtic culture, the Hallstatt culture. Its lake setting is now a UNESCO cultural landscape."},{"q":"The Congress of Vienna, which redrew Europe after Napoleon, met in 1814 and 1815 under which Austrian statesman?","a":"Klemens von Metternich","o":["Klemens von Metternich","Otto von Bismarck","Talleyrand alone","Giuseppe Garibaldi"],"f":"Talleyrand represented France, but Metternich hosted and steered the talks. The settlement included recognizing Switzerland's permanent neutrality."},{"q":"What is the capital city of Austria?","a":"Vienna","o":["Vienna","Belgrade","Ljubljana","Monaco"],"f":"Vienna is the capital of Austria.","kind":"capital"},{"q":"Which of these flags belongs to Austria?","a":"AUT","o":["AUT","BGR","BLR","BEL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Austria.","kind":"flag"}],"hard":[{"q":"The Spanish Riding School in Vienna trains white horses from which stud?","a":"The Lipizzaner stud","o":["The Lipizzaner stud","Arabian only","Mustang","Thoroughbred only"],"f":"Lipizzaners perform collected steps in the Winter Riding School. The breed is shared with Slovenia's Lipica."},{"q":"Which lake and cliffs in the Salzkammergut are a classic Alpine view?","a":"Hallstatt and its lake","o":["Hallstatt and its lake","Lake Balaton","Lake Geneva","Lake Como"],"f":"Hallstatt's church spire sits under limestone walls. Salt mines above the village are thousands of years old."},{"q":"The Congress of Vienna in 1814 and 1815 redrew Europe after which wars?","a":"The Napoleonic Wars","o":["The Napoleonic Wars","World War I","The Punic Wars","The Thirty Years' War only"],"f":"Diplomats danced and bargained while they settled borders after Napoleon's defeat."},{"q":"Which of these cities is the capital of Austria?","a":"Vienna","o":["Vienna","Salzburg","Graz","Innsbruck"],"f":"Vienna is the capital of Austria.","kind":"capital"},{"q":"Which flag is the flag of Austria?","a":"AUT","o":["AUT","LBN","LVA","PER"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Austria.","kind":"flag"}]}},{"id":"AZE","name":"Azerbaijan","cont":"Asia","emoji":"🇦🇿","latlng":[40.5,47.5],"q":{"easy":[{"q":"Which medieval tower in the old city of Baku is linked to a legend of a princess?","a":"The Maiden Tower","o":["The Maiden Tower","Galata Tower","The Leaning Tower","Devils Tower"],"f":"The Maiden Tower stands in Baku's walled city, a UNESCO site. Its original purpose is still debated."},{"q":"Which saffron rice with dried fruit and meat is a feast dish?","a":"Plov","o":["Plov","Sushi","Paella","Risotto"],"f":"Azerbaijani plov is cooked in layers of rice, meat, and dried apricots or chestnuts."},{"q":"Which petroglyph reserve on the Caspian shore shows dancers and boats?","a":"Gobustan","o":["Gobustan","Tassili","Alta","Twyfelfontein"],"f":"Gobustan's rocks hold thousands of carvings, some several thousand years old, plus mud volcanoes nearby."},{"q":"Which city is the capital of Azerbaijan?","a":"Baku","o":["Baku","Rome","Copenhagen","Bern"],"f":"Baku is the capital of Azerbaijan.","kind":"capital"},{"q":"Which flag belongs to Azerbaijan?","a":"AZE","o":["AZE","MLT","MAR","SEN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Azerbaijan.","kind":"flag"}],"medium":[{"q":"Which mathematician, born in Baku in 1921, founded fuzzy logic, a way of reasoning with degrees of truth?","a":"Lotfi A. Zadeh","o":["Lotfi A. Zadeh","Al-Khwarizmi","Omar Khayyam","Maryam Mirzakhani"],"f":"He later taught at the University of California, Berkeley. Fuzzy logic is used in everything from washing machines to train brakes."},{"q":"Azerbaijan has more mud volcanoes than any other country. A mud volcano erupts what, rather than lava?","a":"Mud, water, and gas","o":["Mud, water, and gas","Molten basalt","Ash and pumice","Liquid sulfur only"],"f":"Gobustan and the Absheron Peninsula are dotted with them. Some cold eruptions throw mud tens of meters into the air."},{"q":"Yanar Dag, a hillside near Baku, has flames that burn continuously because natural gas seeps from the rock. That sight helped earn the country which nickname?","a":"The Land of Fire","o":["The Land of Fire","The Land of Winds","The Land of Gold","The Land of Cedar"],"f":"Zoroastrian fire temples once stood nearby, including the Ateshgah at Surakhani, later used by Hindu and Sikh pilgrims as well."},{"q":"What is the capital city of Azerbaijan?","a":"Baku","o":["Baku","Jakarta","Abu Dhabi","Ulaanbaatar"],"f":"Baku is the capital of Azerbaijan.","kind":"capital"},{"q":"Which of these flags belongs to Azerbaijan?","a":"AZE","o":["AZE","KAZ","BGD","LKA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Azerbaijan.","kind":"flag"}],"hard":[{"q":"Which flatbread baked on a saj is eaten at almost every meal?","a":"Tendir or saj bread","o":["Tendir or saj bread","Lavash only of Armenia","Baguette","Pita"],"f":"Bread is baked fresh in a round pan or a clay oven. It tears and scoops the stews."},{"q":"The carpet schools of Shirvan, Karabakh, and Quba weave which kind of textile?","a":"Pile carpets with geometric motifs","o":["Pile carpets with geometric motifs","Silk kimonos","Tartan","Batik"],"f":"Village workshops knot wool carpets whose patterns name a region. UNESCO lists the carpet craft."},{"q":"Which wind, a cold northern blast, crosses the Absheron Peninsula in winter?","a":"The khazri","o":["The khazri","The harmattan","The sirocco","The monsoon"],"f":"The khazri blows off the Caspian. A warmer southern wind is called the gilavar."},{"q":"Which of these cities is the capital of Azerbaijan?","a":"Baku","o":["Baku","Ganja","Sumqayit","Lankaran"],"f":"Baku is the capital of Azerbaijan.","kind":"capital"},{"q":"Which flag is the flag of Azerbaijan?","a":"AZE","o":["AZE","BLZ","COD","IRN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Azerbaijan.","kind":"flag"}]}},{"id":"BDI","name":"Burundi","cont":"Africa","emoji":"🇧🇮","latlng":[-3.5,30],"q":{"easy":[{"q":"Which tall conical drum is a national symbol and a palace instrument in Burundi?","a":"The karyenda","o":["The karyenda","The djembe","The bodhran","The taiko"],"f":"The karyenda was a royal drum. Drumming troupes still perform the fast, layered style."},{"q":"Which fried bean fritter, sold on the street, is a common snack in Burundi?","a":"Ibharage","o":["Ibharage","Sushi","Pretzels","Empanadas"],"f":"Beans are a daily protein. Fried or sauced beans show up in home meals and at markets."},{"q":"Which deep rift lake on the northern border is shared with Rwanda?","a":"Lake Kivu","o":["Lake Kivu","Lake Victoria","Lake Malawi","Lake Chad"],"f":"Lake Kivu drains toward Lake Tanganyika by the Ruzizi River. Methane lies dissolved in its deep water."},{"q":"Which city is the political capital of Burundi?","a":"Gitega","o":["Gitega","Moscow","Muscat","Tbilisi"],"f":"Gitega has been the political capital since 2019. Bujumbura, the former capital, remains the largest city.","kind":"capital"},{"q":"Which flag belongs to Burundi?","a":"BDI","o":["BDI","PRK","UZB","AND"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Burundi.","kind":"flag"}],"medium":[{"q":"Which prince led the push for independence and was assassinated in October 1961, months before independence day?","a":"Louis Rwagasore","o":["Louis Rwagasore","Patrice Lumumba","Julius Nyerere","Jomo Kenyatta"],"f":"Independence from Belgium came on 1 July 1962, so he never governed the new state. Lumumba was killed in the Congo that same era. Nyerere and Kenyatta led Tanzania and Kenya."},{"q":"The country touches the northeastern shore of the deepest lake in Africa. Which lake is it?","a":"Lake Tanganyika","o":["Lake Tanganyika","Lake Victoria","Lake Kivu","Lake Malawi"],"f":"Only Siberia's Lake Baikal is deeper among freshwater lakes. Tanganyika is shared with Tanzania, DR Congo, and Zambia. This country holds only a short piece of the shore."},{"q":"Independence in 1962 kept a king, the mwami. A coup ended the monarchy in which year?","a":"1966","o":["1966","1962","1972","1993"],"f":"Michel Micombero then became the first president. The later crises of 1972 and 1993 are a different history from the end of the crown."},{"q":"What is the political capital city of Burundi?","a":"Gitega","o":["Gitega","São Tomé","Windhoek","Port Louis"],"f":"Gitega has been the political capital since 2019. Bujumbura, the former capital, remains the largest city.","kind":"capital"},{"q":"Which of these flags belongs to Burundi?","a":"BDI","o":["BDI","TUN","BEN","GHA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Burundi.","kind":"flag"}],"hard":[{"q":"Drummers in Burundi carry the instrument on the head and strike it with which tool?","a":"Wooden sticks","o":["Wooden sticks","Bows","Foot pedals","Metal forks"],"f":"Teams play interlocking rhythms, dancing while the drums boom."},{"q":"Which crop on the hills around the capital region is Burundi's main export?","a":"Coffee","o":["Coffee","Vanilla","Rubber","Olives"],"f":"Coffee bushes cover many ridges. The beans are the country's best-known farm export."},{"q":"The royal drum Sanctuary of Gishora preserves which tradition?","a":"Sacred drumming","o":["Sacred drumming","Glacier skiing","Pearl diving","Reindeer herding"],"f":"Gishora keeps the court style of drumming that once accompanied the mwami, the king."},{"q":"Which of these cities is the political capital of Burundi?","a":"Gitega","o":["Gitega","Bujumbura","Ngozi","Muyinga"],"f":"Gitega has been the political capital since 2019. Bujumbura, the former capital, remains the largest city.","kind":"capital"},{"q":"Which flag is the flag of Burundi?","a":"BDI","o":["BDI","NRU","LVA","SRB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Burundi.","kind":"flag"}]}},{"id":"BEL","name":"Belgium","cont":"Europe","emoji":"🇧🇪","latlng":[50.83333333,4],"q":{"easy":[{"q":"Which iron crystal enlarged 165 billion times was built for the 1958 world's fair?","a":"The Atomium","o":["The Atomium","The Eiffel Tower","The Space Needle","The CN Tower"],"f":"The Atomium represents a unit cell of iron. It still stands in the Heysel district with tubes visitors can walk through."},{"q":"Which rectangular waffle, sold hot with toppings, is a street snack?","a":"A Belgian waffle","o":["A Belgian waffle","A crepe","A pretzel","A donut"],"f":"Brussels and Liege waffles differ. The Liege kind is thicker and sweeter, with pearl sugar."},{"q":"Which painter of floating men in bowler hats was a Belgian surrealist?","a":"Rene Magritte","o":["Rene Magritte","Picasso","Dali","Monet"],"f":"Magritte painted ordinary objects in impossible ways. He was born in Lessines in 1898."},{"q":"Which city is the capital of Belgium?","a":"Brussels","o":["Brussels","Funafuti","Panama City","Nassau"],"f":"Brussels is the capital of Belgium.","kind":"capital"},{"q":"Which flag belongs to Belgium?","a":"BEL","o":["BEL","UZB","CAF","KHM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Belgium.","kind":"flag"}],"medium":[{"q":"Which instrument maker, born in Dinant, invented the saxophone in the 1840s?","a":"Adolphe Sax","o":["Adolphe Sax","Antonio Stradivari","Bartolomeo Cristofori","Theobald Boehm"],"f":"He was working in Paris and wanted a woodwind with the power of a brass instrument. The saxophone later found its most famous home in jazz."},{"q":"Belgium's three official languages are Dutch, French, and which third?","a":"German","o":["German","English","Spanish","Latin"],"f":"Dutch is the language of Flanders, French of Wallonia, and German of a small eastern community. Brussels is officially bilingual in French and Dutch."},{"q":"Georges Remi, born in Etterbeek, drew a boy reporter who travels with a dog named Snowy. What pen name did Remi use?","a":"Herge","o":["Herge","Peyo","Morris","Uderzo"],"f":"Herge comes from his initials reversed, R.G. Peyo drew the Smurfs, also Belgian, and Morris drew Lucky Luke."},{"q":"What is the capital city of Belgium?","a":"Brussels","o":["Brussels","Rome","Athens","Sofia"],"f":"Brussels is the capital of Belgium.","kind":"capital"},{"q":"Which of these flags belongs to Belgium?","a":"BEL","o":["BEL","UKR","PRT","NOR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Belgium.","kind":"flag"}],"hard":[{"q":"Which battle in 1815, south of Brussels, ended Napoleon's return to power?","a":"Waterloo","o":["Waterloo","Austerlitz","Trafalgar","Leipzig"],"f":"Wellington and Blucher defeated Napoleon on 18 June 1815. A lion monument now marks the ridge."},{"q":"Lace from which Flemish city was famous across Europe in the 1600s?","a":"Bruges","o":["Bruges","Ghent","Antwerp","Liege"],"f":"Bobbin lace from Bruges and Brussels dressed collars and altars. The skill is still taught."},{"q":"Which cartoonist created the little blue forest people in a 1958 comic?","a":"Peyo","o":["Peyo","Goscinny","Uderzo","Walt Disney"],"f":"Peyo, whose real name was Pierre Culliford, drew them in a Brussels studio. They began as a side story and became a worldwide comic."},{"q":"Which of these cities is the capital of Belgium?","a":"Brussels","o":["Brussels","Antwerp","Ghent","Bruges"],"f":"Brussels is the capital of Belgium.","kind":"capital"},{"q":"Which flag is the flag of Belgium?","a":"BEL","o":["BEL","DEU","MCO","SLV"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Belgium.","kind":"flag"}]}},{"id":"BEN","name":"Benin","cont":"Africa","emoji":"🇧🇯","latlng":[9.5,2.25],"q":{"easy":[{"q":"Which stilt village stands in Lake Nokoue near Cotonou?","a":"Ganvie","o":["Ganvie","Venice","Kampong Phluk","The Uros islands"],"f":"Ganvie's houses sit on stilts above the lagoon. It is often nicknamed the Venice of Africa."},{"q":"Which grilled meat on a stick is common street food in Benin?","a":"Chichinga","o":["Chichinga","Sushi","Arepa","Poutine"],"f":"Chichinga is seasoned meat grilled on skewers and sold at roadside stands."},{"q":"The royal palaces of Abomey, with their painted bas-reliefs, belonged to which kingdom?","a":"Dahomey","o":["Dahomey","Ashanti","Mali","Kongo"],"f":"Dahomey kings ruled from Abomey. The palace reliefs record symbols of each reign."},{"q":"Which city is the official capital of Benin?","a":"Porto-Novo","o":["Porto-Novo","Vienna","Baghdad","Athens"],"f":"Porto-Novo is the official capital. Cotonou is the seat of government and the largest city.","kind":"capital"},{"q":"Which flag belongs to Benin?","a":"BEN","o":["BEN","MLT","CYP","AZE"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Benin.","kind":"flag"}],"medium":[{"q":"Which singer, born in Ouidah in 1960, brought Fon and Yoruba songs to audiences far beyond West Africa?","a":"Angélique Kidjo","o":["Angélique Kidjo","Miriam Makeba","Cesária Évora","Oumou Sangaré"],"f":"She left for Paris in the 1980s. Makeba was South African, Évora was Cape Verdean, and Sangaré is Malian. Ouidah was also a major port of the Atlantic slave trade."},{"q":"The Kingdom of Dahomey kept an all-woman regiment that Europeans called Amazons. Locally those soldiers were called what?","a":"The Mino","o":["The Mino","The Janissaries","The Impi","The Askari"],"f":"Mino means our mothers. They were a trained unit of the king, especially under Ghezo in the 19th century, and they fought the French in the 1890s. Janissaries, impi, and askari were soldiers of other places."},{"q":"A memorial arch on the beach at Ouidah marks the last point where many captives saw home before the Atlantic crossing. What is it called?","a":"The Door of No Return","o":["The Door of No Return","Elmina Castle","Bunce Island","Cape Coast Castle"],"f":"The road from the town to the beach is still walked as a memorial. Historians argue about exact numbers shipped from any one door, so the lesson is the trade itself, not a tally. Elmina and Cape Coast are in Ghana, and Bunce Island is in Sierra Leone."},{"q":"What is the official capital city of Benin?","a":"Porto-Novo","o":["Porto-Novo","Mbabane","N'Djamena","Asmara"],"f":"Porto-Novo is the official capital. Cotonou is the seat of government and the largest city.","kind":"capital"},{"q":"Which of these flags belongs to Benin?","a":"BEN","o":["BEN","ETH","CIV","SEN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Benin.","kind":"flag"}],"hard":[{"q":"The memorial called the Door of No Return stands on the old slave route in which Beninese city?","a":"Ouidah","o":["Ouidah","Parakou","Natitingou","Abomey"],"f":"Captives were taken from Ouidah's beach onto Atlantic ships. A memorial now marks that path."},{"q":"Which bright cloth art, with cut-out figures of kings and animals, comes from the Abomey court?","a":"Applique banners","o":["Applique banners","Kente cloth","Batik","Tartan"],"f":"Court artists sewed colored cloth into pictures of royal deeds and animals."},{"q":"Which religion of spirits and shrines has a major annual festival on the coast?","a":"Vodun","o":["Vodun","Shinto","Norse paganism","Olympian cult"],"f":"The January festival honors vodun spirits. The religion remains widely practiced in the south."},{"q":"Which of these cities is the official capital of Benin?","a":"Porto-Novo","o":["Porto-Novo","Cotonou","Abomey","Parakou"],"f":"Porto-Novo is the official capital. Cotonou is the seat of government and the largest city.","kind":"capital"},{"q":"Which flag is the flag of Benin?","a":"BEN","o":["BEN","GHA","TGO","CMR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Benin.","kind":"flag"}]}},{"id":"BFA","name":"Burkina Faso","cont":"Africa","emoji":"🇧🇫","latlng":[13,-2],"q":{"easy":[{"q":"Which field of sandstone spires near Sindou is a famous landscape in southwestern Burkina Faso?","a":"The Sindou Peaks","o":["The Sindou Peaks","The Tsingy","Meteora","Cappadocia"],"f":"Wind and rain carved the Sindou Peaks from sandstone. Paths wind between the towers."},{"q":"Which thick millet or sorghum porridge is the daily starch in Burkina Faso?","a":"To","o":["To","Sushi","Risotto","Poutine"],"f":"To is rolled into a ball and dipped in sauce. Millet and sorghum suit the dry climate."},{"q":"The Grand Mosque of Bobo-Dioulasso is best known for being built mainly of what?","a":"Mud brick","o":["Mud brick","Marble","Steel and glass","Ice blocks"],"f":"The mosque is a large Sahelian building of mud brick, with wooden beams sticking from the walls."},{"q":"Which city is the capital of Burkina Faso?","a":"Ouagadougou","o":["Ouagadougou","San Marino","Manama","Port of Spain"],"f":"Ouagadougou is the capital of Burkina Faso.","kind":"capital"},{"q":"Which flag belongs to Burkina Faso?","a":"BFA","o":["BFA","MEX","BTN","IND"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Burkina Faso.","kind":"flag"}],"medium":[{"q":"In 1984 Thomas Sankara replaced the colonial name Upper Volta. The new name means roughly what?","a":"Land of upright people","o":["Land of upright people","Land of the long river","Land of gold","Land beside the dunes"],"f":"Burkina is Moore and Faso is Dioula, so the name joins two local languages. Sankara was killed in 1987. The old name had described only the upper courses of the Volta rivers."},{"q":"The UNESCO ruins of Loropéni are stone enclosures linked by archaeologists to which old trade?","a":"The gold trade","o":["The gold trade","The Baltic amber trade","The silk trade of China","The spice trade of Malacca"],"f":"The walls stand in the southwest. Their exact century is still debated, so the question does not ask for a date. Gold from the West African savanna, not Chinese silk, is the trade they are tied to."},{"q":"A major pan-African film festival, founded in 1969, is held in Ouagadougou. What is it called?","a":"FESPACO","o":["FESPACO","Cannes","Carthage Film Festival","TIFF"],"f":"The full name is the Pan-African Film and Television Festival of Ouagadougou. The Carthage Film Festival is the other great African film meeting, held in Tunisia. Cannes and TIFF are European and Canadian."},{"q":"What is the capital city of Burkina Faso?","a":"Ouagadougou","o":["Ouagadougou","Addis Ababa","Malabo","Port Louis"],"f":"Ouagadougou is the capital of Burkina Faso.","kind":"capital"},{"q":"Which of these flags belongs to Burkina Faso?","a":"BFA","o":["BFA","SEN","MLI","TCD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Burkina Faso.","kind":"flag"}],"hard":[{"q":"The Mossi kingdoms of the central plateau organized power around which mounted soldiers?","a":"Cavalry horsemen","o":["Cavalry horsemen","Camel gunners","War elephants","Longship crews"],"f":"Horses carried Mossi rulers and fighters across the savanna before colonial rule."},{"q":"Which goldworking region of southwestern Burkina Faso supplied ore to old Sahel trade routes?","a":"The Lobi country","o":["The Lobi country","The Copperbelt","The Witwatersrand","The Klondike"],"f":"Lobi communities mined and traded gold. The metal moved north toward the Niger towns."},{"q":"Masks of the Bwa people are often painted in bold geometric patterns of which colors?","a":"Black, white, and red","o":["Black, white, and red","Only gold","Pastel pink","Neon green"],"f":"Bwa plank masks use strong black, white, and red shapes in village ceremonies."},{"q":"Which of these cities is the capital of Burkina Faso?","a":"Ouagadougou","o":["Ouagadougou","Bobo-Dioulasso","Koudougou","Ouahigouya"],"f":"Ouagadougou is the capital of Burkina Faso.","kind":"capital"},{"q":"Which flag is the flag of Burkina Faso?","a":"BFA","o":["BFA","BHR","LUX","HUN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Burkina Faso.","kind":"flag"}]}},{"id":"BGD","name":"Bangladesh","cont":"Asia","emoji":"🇧🇩","latlng":[24,90],"q":{"easy":[{"q":"Which long sandy beach south of Chittagong is the country's best-known shore?","a":"Cox's Bazar","o":["Cox's Bazar","Bondi","Copacabana","Waikiki"],"f":"Cox's Bazar is a continuous beach more than 100 kilometers long. It is a major domestic resort."},{"q":"Which oily fish, a national favorite, swims from the sea into the rivers to spawn?","a":"Hilsa","o":["Hilsa","Salmon","Cod","Tuna"],"f":"Hilsa, or ilish, is fried or cooked in mustard. The monsoon run is a celebrated season."},{"q":"Which New Year festival in April includes processions of huge animal models?","a":"Pohela Boishakh","o":["Pohela Boishakh","Songkran","Nowruz","Diwali"],"f":"Pohela Boishakh opens the Bengali calendar. Dhaka holds a Mangal Shobhajatra parade of masks and figures."},{"q":"Which city is the capital of Bangladesh?","a":"Dhaka","o":["Dhaka","Asunción","Yaren","Castries"],"f":"Dhaka is the capital of Bangladesh.","kind":"capital"},{"q":"Which flag belongs to Bangladesh?","a":"BGD","o":["BGD","FIN","GHA","MLT"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Bangladesh.","kind":"flag"}],"medium":[{"q":"Which artist, born in Kishoreganj, drew the starving figures of the 1943 Bengal famine and later led the country's modern art?","a":"Zainul Abedin","o":["Zainul Abedin","Jamini Roy","Rabindranath Tagore","Abanindranath Tagore"],"f":"His famine sketches used stark black ink. He also founded the art institute in Dhaka. The Tagores were giants of Bengali culture, but they were based in Kolkata."},{"q":"The Sundarbans, shared with India, is the world's largest forest of which trees, and it shelters Bengal tigers?","a":"Mangroves","o":["Mangroves","Teak","Baobabs","Pines"],"f":"The name means beautiful forest. Tigers there swim between islands, and the roots of the mangroves slow the storm surges of the Bay of Bengal."},{"q":"On 21 February 1952 students in Dhaka were killed demanding that Bengali be recognized alongside Urdu. That date is now marked worldwide as what?","a":"International Mother Language Day","o":["International Mother Language Day","World Book Day","Human Rights Day","Press Freedom Day"],"f":"UNESCO chose 21 February because of those martyrs. The movement showed that language, not only religion, would define the later break with Pakistan."},{"q":"What is the capital city of Bangladesh?","a":"Dhaka","o":["Dhaka","Damascus","Amman","Thimphu"],"f":"Dhaka is the capital of Bangladesh.","kind":"capital"},{"q":"Which of these flags belongs to Bangladesh?","a":"BGD","o":["BGD","PSE","KHM","PAK"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Bangladesh.","kind":"flag"}],"hard":[{"q":"The language movement of 1952 defended the right to use which language in public life?","a":"Bengali","o":["Bengali","Urdu only","English only","Hindi"],"f":"Students were killed at Dhaka University on 21 February 1952. The day became International Mother Language Day."},{"q":"Which tea gardens in the northeast cover the hills around Sylhet?","a":"Sylhet tea estates","o":["Sylhet tea estates","Darjeeling only","Assam only","Ceylon only"],"f":"British planters opened estates in Sylhet. The hills still produce black tea."},{"q":"The shipbreaking yards of which port dismantle old ocean vessels on the beach?","a":"Chittagong","o":["Chittagong","Khulna","Mongla","Rajshahi"],"f":"Workers cut hulls at Sitakunda. The industry is a major source of steel and a known hazard."},{"q":"Which of these cities is the capital of Bangladesh?","a":"Dhaka","o":["Dhaka","Chittagong","Khulna","Rajshahi"],"f":"Dhaka is the capital of Bangladesh.","kind":"capital"},{"q":"Which flag is the flag of Bangladesh?","a":"BGD","o":["BGD","PLW","LAO","JPN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Bangladesh.","kind":"flag"}]}},{"id":"BGR","name":"Bulgaria","cont":"Europe","emoji":"🇧🇬","latlng":[43,25],"q":{"easy":[{"q":"Which monastery in the Rila Mountains is the country's most famous Orthodox house?","a":"Rila Monastery","o":["Rila Monastery","Mount Athos","Studenica","Ostrog"],"f":"Rila was founded in the 900s by the hermit John of Rila. Its black-and-white arches surround a courtyard."},{"q":"Which cheese pastry, coiled or layered, is a breakfast classic?","a":"Banitsa","o":["Banitsa","Croissant","Pretzel","Empanada"],"f":"Banitsa is filo dough with egg and sirene cheese. It is eaten at New Year with lucky charms baked inside."},{"q":"Which valley around Kazanlak is famous for oil-bearing flowers?","a":"The Valley of Roses","o":["The Valley of Roses","The Loire","Napa","The Douro"],"f":"Rosa damascena fields bloom in May and June. The petals are distilled for perfume oil."},{"q":"Which city is the capital of Bulgaria?","a":"Sofia","o":["Sofia","Funafuti","Phnom Penh","Maputo"],"f":"Sofia is the capital of Bulgaria.","kind":"capital"},{"q":"Which flag belongs to Bulgaria?","a":"BGR","o":["BGR","EGY","GUY","MDV"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Bulgaria.","kind":"flag"}],"medium":[{"q":"In 1905 Stamen Grigorov, a Bulgarian scientist, first described the bacterium later named for the country's famous food. Which food?","a":"Yogurt","o":["Yogurt","Feta cheese","Sourdough bread","Cured ham"],"f":"Lactobacillus bulgaricus is part of traditional yogurt starters. Grigorov identified it while studying in Geneva."},{"q":"The oldest worked gold yet found comes from a cemetery near which Black Sea city, dating to about 4500 BCE?","a":"Varna","o":["Varna","Sofia","Plovdiv","Burgas"],"f":"The Varna graves held hundreds of gold beads and ornaments. They show that social rank was already marked by metal long before the pyramids."},{"q":"Cyril and Methodius devised Glagolitic. Their disciples in the First Bulgarian Empire then developed which alphabet still used today?","a":"Cyrillic","o":["Cyrillic","Greek","Armenian","Georgian"],"f":"The Preslav and Ohrid schools spread the new letters. Many Slavic languages still use scripts descended from that work."},{"q":"What is the capital city of Bulgaria?","a":"Sofia","o":["Sofia","Reykjavík","Lisbon","London"],"f":"Sofia is the capital of Bulgaria.","kind":"capital"},{"q":"Which of these flags belongs to Bulgaria?","a":"BGR","o":["BGR","ALB","ESP","MLT"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Bulgaria.","kind":"flag"}],"hard":[{"q":"The Madara Rider, a cliff carving, shows a knight from which early medieval court?","a":"The khans of Pliska","o":["The khans of Pliska","The Roman Republic","The Inca","Kievan Rus only"],"f":"The relief near Shumen dates from the early 700s. It is a UNESCO site."},{"q":"Which voices, women singing in close dissonant harmony, are a famous folk sound?","a":"The open-throat choir style","o":["The open-throat choir style","Gregorian chant","Yodeling","Rap"],"f":"The ensemble Le Mystere des Voix Bulgares popularized village choirs. The intervals sound sharp to outsiders."},{"q":"Which Thracian tombs, with frescoes of horses and a burial feast, were found at Kazanlak?","a":"The Kazanlak tomb","o":["The Kazanlak tomb","A Viking ship","A Maya crypt","A pyramid"],"f":"The tomb dates from the 300s BCE. A replica protects the original paintings."},{"q":"Which of these cities is the capital of Bulgaria?","a":"Sofia","o":["Sofia","Plovdiv","Varna","Burgas"],"f":"Sofia is the capital of Bulgaria.","kind":"capital"},{"q":"Which flag is the flag of Bulgaria?","a":"BGR","o":["BGR","TJK","IRN","HUN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Bulgaria.","kind":"flag"}]}},{"id":"BHR","name":"Bahrain","cont":"Asia","emoji":"🇧🇭","latlng":[26,50.55],"q":{"easy":[{"q":"Which ancient harbor mound, later topped by a Portuguese fort, is a UNESCO site?","a":"The Dilmun port mound","o":["The Dilmun port mound","Failaka","Julfar","Ed-Dur"],"f":"Qal'at al-Bahrain was a Dilmun port. Layers of cities lie under the Portuguese fort on top."},{"q":"Which sweet cardamom coffee is served in small cups to guests?","a":"Qahwa","o":["Qahwa","Espresso","Tea","Turkish coffee only"],"f":"Gulf qahwa is light coffee with cardamom, poured from a dallah pot into finjan cups."},{"q":"Which island formula circuit and a causeway to Saudi Arabia are modern links?","a":"The King Fahd Causeway","o":["The King Fahd Causeway","The Suez","The Panama","The Bosphorus Bridge"],"f":"The causeway opened in 1986 and ties Bahrain to the Saudi mainland. A circuit nearby hosts a Grand Prix."},{"q":"Which city is the capital of Bahrain?","a":"Manama","o":["Manama","Mogadishu","Freetown","Nairobi"],"f":"Manama is the capital of Bahrain.","kind":"capital"},{"q":"Which flag belongs to Bahrain?","a":"BHR","o":["BHR","CIV","GIN","SRB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Bahrain.","kind":"flag"}],"medium":[{"q":"Dilmun traders linked Mesopotamia to the Indus Valley and to Magan. Magan is thought to lie mainly in which modern country?","a":"Oman","o":["Oman","Yemen","India","Egypt"],"f":"Dilmun itself, praised for sweet water, left thousands of burial mounds on the main island, now a UNESCO site."},{"q":"Before oil, the island's wealth came from the best natural pearls in the Gulf. Divers descended how?","a":"On a single held breath","o":["On a single held breath","In copper helmets from the 1400s","From glass submarines","With scuba gear invented locally"],"f":"A stone weight pulled them down and a rope pulled them up. The trade faded after cultured pearls appeared in the 1930s."},{"q":"Oil was first found in the Gulf states in Bahrain, in which year?","a":"1932","o":["1932","1908","1951","1971"],"f":"The well was at Jabal al-Dukhan, the mountain of smoke. Iran had oil earlier, at Masjed Soleyman in 1908, but Bahrain's strike was the first on the Arab side of the Gulf."},{"q":"What is the capital city of Bahrain?","a":"Manama","o":["Manama","Pyongyang","Kuwait City","Damascus"],"f":"Manama is the capital of Bahrain.","kind":"capital"},{"q":"Which of these flags belongs to Bahrain?","a":"BHR","o":["BHR","TUR","TKM","LAO"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Bahrain.","kind":"flag"}],"hard":[{"q":"Dilmun, named in Sumerian texts, was a Bronze Age trading hub famous for what?","a":"Fresh water and trade","o":["Fresh water and trade","Gold of the Inca","Silk","Spices of Malacca"],"f":"Dilmun shipped copper and pearls and was praised for sweet water. The burial mounds still cover the island."},{"q":"Which traditional pearl-diving wood clothespin closed the nose?","a":"A nose clip of turtle shell or wood","o":["A nose clip of turtle shell or wood","A scuba mask","A snorkel","An iron helmet"],"f":"Divers descended on one breath with a stone weight. The pearl economy collapsed after cultured pearls spread."},{"q":"The burial mounds at A'ali number in the thousands and date mostly from which age?","a":"The Bronze Age","o":["The Bronze Age","The Roman era","The 20th century","The Stone Age only of Europe"],"f":"Dilmun elites were buried in mound fields. Some chambers still hold pottery."},{"q":"Which of these cities is the capital of Bahrain?","a":"Manama","o":["Manama","Muharraq","Riffa","Hamad Town"],"f":"Manama is the capital of Bahrain.","kind":"capital"},{"q":"Which flag is the flag of Bahrain?","a":"BHR","o":["BHR","QAT","SWE","GBR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Bahrain.","kind":"flag"}]}},{"id":"BHS","name":"Bahamas","cont":"North America","emoji":"🇧🇸","latlng":[24.25,-76],"q":{"easy":[{"q":"Which pink sand beach on Harbour Island is a famous view?","a":"Pink Sands Beach","o":["Pink Sands Beach","Cable Beach","Cabbage Beach","Taino Beach"],"f":"Crushed shells of foraminifera tint the sand pink. The beach is on Harbour Island off Eleuthera."},{"q":"Which spiny lobster and conch dishes are the islands' signature seafood?","a":"Cracked conch and lobster","o":["Cracked conch and lobster","Cod","Salmon","Ceviche of only Peru"],"f":"Conch is pounded and fried. Lobster, often called crawfish, is grilled in the season."},{"q":"Which parade of drums, cowbells, and crepe-paper costumes runs on Boxing Day?","a":"Junkanoo","o":["Junkanoo","Carnival","Crop Over","Mardi Gras"],"f":"Groups practice all year. Goatskin drums, cowbells, and crepe-paper costumes fill Bay Street."},{"q":"Which city is the capital of Bahamas?","a":"Nassau","o":["Nassau","Ngerulmud","Jakarta","Bangkok"],"f":"Nassau is the capital of Bahamas.","kind":"capital"},{"q":"Which flag belongs to Bahamas?","a":"BHS","o":["BHS","MWI","NER","SYR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Bahamas.","kind":"flag"}],"medium":[{"q":"Which sprinter, born in Nassau, won Olympic 400-meter gold in 2016 and again in 2021?","a":"Shaunae Miller-Uibo","o":["Shaunae Miller-Uibo","Allyson Felix","Shelly-Ann Fraser-Pryce","Christine Ohuruogu"],"f":"She dove across the line to win in Rio. Felix is American, Fraser-Pryce is Jamaican, and Ohuruogu is British."},{"q":"Andros Island is known for an unusual number of blue holes. A blue hole is mainly what?","a":"A flooded limestone sinkhole","o":["A flooded limestone sinkhole","A volcanic crater lake","A coral atoll lagoon","A glacial kettle"],"f":"Some open into cave systems below sea level. Divers explore them, and their still water can look a deep blue from above."},{"q":"Most historians place Columbus's first 1492 landfall in the Americas on which Bahamian island, the one he called San Salvador?","a":"Guanahani, today's San Salvador","o":["Guanahani, today's San Salvador","Hispaniola","Cuba","Trinidad"],"f":"A few researchers have argued for other islands, but San Salvador in the eastern Bahamas is the standard identification of Guanahani."},{"q":"What is the capital city of Bahamas?","a":"Nassau","o":["Nassau","Kingstown","Mexico City","Kingston"],"f":"Nassau is the capital of Bahamas.","kind":"capital"},{"q":"Which of these flags belongs to Bahamas?","a":"BHS","o":["BHS","MEX","CUB","BLZ"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Bahamas.","kind":"flag"}],"hard":[{"q":"Which island is the usual identification of Columbus's first landfall in 1492?","a":"San Salvador","o":["San Salvador","New Providence","Grand Bahama","Andros"],"f":"Columbus called the island Guanahani. The modern identification with San Salvador is the usual one, though scholars have debated it."},{"q":"Andros, the largest island, is known for which deep ocean trench just offshore?","a":"The Tongue of the Ocean","o":["The Tongue of the Ocean","The Puerto Rico Trench","The Mariana Trench","The Cayman Trench"],"f":"The Tongue is a steep-walled canyon of deep water beside the shallow bank. Divers use the wall."},{"q":"Which native hut of palm thatch and which straw work are a traditional craft?","a":"Palm-thatch houses","o":["Palm-thatch houses","Igloos","Adobe","Longhouses"],"f":"Thatch was the old roof. Straw vendors still plait bags and hats for the market."},{"q":"Which of these cities is the capital of Bahamas?","a":"Nassau","o":["Nassau","Freeport","Marsh Harbour","George Town"],"f":"Nassau is the capital of Bahamas.","kind":"capital"},{"q":"Which flag is the flag of Bahamas?","a":"BHS","o":["BHS","TLS","NER","DEU"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Bahamas.","kind":"flag"}]}},{"id":"BIH","name":"Bosnia and Herzegovina","cont":"Europe","emoji":"🇧🇦","latlng":[44,18],"q":{"easy":[{"q":"Which Ottoman bridge in Mostar, destroyed in 1993 and later rebuilt, is the city's symbol?","a":"Stari Most","o":["Stari Most","The Rialto","Tower Bridge","Charles Bridge"],"f":"Stari Most means the old bridge. It was rebuilt with local stone and reopened in 2004."},{"q":"Which grilled minced-meat sausages in bread are a shared Balkan street food?","a":"Cevapi","o":["Cevapi","Sushi","Hot dogs only","Bratwurst"],"f":"Cevapi are eaten with onion and somun bread. Sarajevo and Travnik both claim a special recipe."},{"q":"Which river runs under Stari Most through a green gorge?","a":"The Neretva","o":["The Neretva","The Danube","The Sava","The Drina"],"f":"The Neretva is cold and green. Diving from the bridge is an old local dare."},{"q":"Which city is the capital of Bosnia and Herzegovina?","a":"Sarajevo","o":["Sarajevo","Thimphu","Bridgetown","Tegucigalpa"],"f":"Sarajevo is the capital of Bosnia and Herzegovina.","kind":"capital"},{"q":"Which flag belongs to Bosnia and Herzegovina?","a":"BIH","o":["BIH","TLS","COM","URY"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Bosnia and Herzegovina.","kind":"flag"}],"medium":[{"q":"Which writer, born near Travnik, won the 1961 Nobel Prize and set The Bridge on the Drina in Visegrad?","a":"Ivo Andric","o":["Ivo Andric","Ismail Kadare","Mesa Selimovic","Danilo Kis"],"f":"The novel follows a bridge across centuries of Ottoman and Austro-Hungarian rule. Selimovic and Kis are major Yugoslav writers who did not win that prize."},{"q":"The old bridge of Mostar, destroyed in 1993 during the war, was rebuilt and reopened in which year?","a":"2004","o":["2004","1995","2010","1984"],"f":"The original 16th-century Ottoman arch was the work of Mimar Hayruddin. Divers still jump from the rebuilt stone into the Neretva."},{"q":"Sarajevo hosted the Winter Olympics in which year, a decade before the city was besieged?","a":"1984","o":["1984","1976","1992","1968"],"f":"The bobsled track and the Olympic mountains are still above the city. The games were the first Winter Olympics in a socialist country."},{"q":"What is the capital city of Bosnia and Herzegovina?","a":"Sarajevo","o":["Sarajevo","Bratislava","Zagreb","Vilnius"],"f":"Sarajevo is the capital of Bosnia and Herzegovina.","kind":"capital"},{"q":"Which of these flags belongs to Bosnia and Herzegovina?","a":"BIH","o":["BIH","DNK","ISL","BGR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Bosnia and Herzegovina.","kind":"flag"}],"hard":[{"q":"Stecci, the medieval tombstones scattered on hills, are carved with what?","a":"Spirals, crosses, and hunting scenes","o":["Spirals, crosses, and hunting scenes","Hieroglyphs","Runes only","Chinese characters"],"f":"Stecci belong to medieval Christian communities of the region. UNESCO lists the cemeteries."},{"q":"Which coffee, boiled in a small pot and served in a metal cup, is a daily ritual?","a":"Bosnian coffee","o":["Bosnian coffee","Espresso","Tea","Mate"],"f":"The drink is close to Turkish coffee, a legacy of Ottoman cities, served with a sweet."},{"q":"Which novelist from Tuzla wrote Death and the Dervish, a classic of Bosnian literature?","a":"Mesa Selimovic","o":["Mesa Selimovic","Ivo Andric","Njegos","Kadare"],"f":"Selimovic's novel follows a dervish caught in Ottoman political intrigue. It is widely read in the region."},{"q":"Which of these cities is the capital of Bosnia and Herzegovina?","a":"Sarajevo","o":["Sarajevo","Mostar","Banja Luka","Tuzla"],"f":"Sarajevo is the capital of Bosnia and Herzegovina.","kind":"capital"},{"q":"Which flag is the flag of Bosnia and Herzegovina?","a":"BIH","o":["BIH","WSM","CHE","BDI"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Bosnia and Herzegovina.","kind":"flag"}]}},{"id":"BLR","name":"Belarus","cont":"Europe","emoji":"🇧🇾","latlng":[53,28],"q":{"easy":[{"q":"Which huge fortress complex in the west is a UNESCO castle of red brick?","a":"Mir Castle","o":["Mir Castle","Neuschwanstein","Bran Castle","The Kremlin"],"f":"Mir Castle, with its towers and courtyard, was a residence of noble families on the road toward Poland."},{"q":"Which potato pancakes, fried crisp, are a home favorite?","a":"Draniki","o":["Draniki","Sushi","Crepes only sweet","Tortillas"],"f":"Draniki are grated potato fried in oil. Sour cream is the usual topping."},{"q":"Which forest and bison reserve is a shared wilderness with Poland?","a":"The Belovezhskaya Pushcha","o":["The Belovezhskaya Pushcha","The Black Forest","The Taiga of Yakutia","Sherwood"],"f":"The Bialowieza forest holds European bison. Part of it lies in Belarus and part in Poland."},{"q":"Which city is the capital of Belarus?","a":"Minsk","o":["Minsk","South Tarawa","Rabat","Cairo"],"f":"Minsk is the capital of Belarus.","kind":"capital"},{"q":"Which flag belongs to Belarus?","a":"BLR","o":["BLR","CHL","SYC","CHN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Belarus.","kind":"flag"}],"medium":[{"q":"Which painter, born near Vitebsk in 1887, floated fiddlers and goats over village roofs?","a":"Marc Chagall","o":["Marc Chagall","Wassily Kandinsky","Kazimir Malevich","Amedeo Modigliani"],"f":"He left for Paris but kept painting the wooden town of his childhood. Kandinsky and Malevich were different Russian avant-garde painters."},{"q":"Mir Castle, a UNESCO site, was built in the 16th century as a fortress that later became what?","a":"A noble residence","o":["A noble residence","A Buddhist monastery","A naval dockyard","A salt mine"],"f":"It combines Gothic, Renaissance, and Baroque work. It stands in a small town southwest of Minsk and is paired with the Nesvizh palace on the heritage list."},{"q":"Belovezhskaya Pushcha, shared with Poland, sheltered the European bison when the species was nearly gone. The bison was brought back mainly by what method?","a":"Breeding from zoo animals","o":["Breeding from zoo animals","Importing American buffalo","Cloning from fossils","Crossing with cattle"],"f":"The last wild European bison were killed in the early 20th century. A few captive animals founded the herds that were later released into the forest."},{"q":"What is the capital city of Belarus?","a":"Minsk","o":["Minsk","Reykjavík","Sarajevo","Madrid"],"f":"Minsk is the capital of Belarus.","kind":"capital"},{"q":"Which of these flags belongs to Belarus?","a":"BLR","o":["BLR","POL","ESP","RUS"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Belarus.","kind":"flag"}],"hard":[{"q":"Which striped cloth and woven rush mats are traditional crafts of the villages?","a":"Rush weaving","o":["Rush weaving","Kente","Tartan","Batik"],"f":"Rush mats and embroidered towels appear at weddings. Geometric weaving is an old household art."},{"q":"The Radziwill family endowed which palace and park at Nesvizh?","a":"Nesvizh Castle","o":["Nesvizh Castle","The Louvre","Versailles","Schonbrunn"],"f":"Nesvizh was a Renaissance residence and a printing center. It is a UNESCO site."},{"q":"Which midsummer rite, with wreaths and bonfires, is still celebrated in the countryside?","a":"Kupalle","o":["Kupalle","Carnival","Diwali","Hanukkah"],"f":"Kupalle falls near the summer solstice. Young people jump fires and float flower wreaths."},{"q":"Which of these cities is the capital of Belarus?","a":"Minsk","o":["Minsk","Brest","Gomel","Grodno"],"f":"Minsk is the capital of Belarus.","kind":"capital"},{"q":"Which flag is the flag of Belarus?","a":"BLR","o":["BLR","VEN","JPN","IRL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Belarus.","kind":"flag"}]}},{"id":"BLZ","name":"Belize","cont":"North America","emoji":"🇧🇿","latlng":[17.25,-88.75],"q":{"easy":[{"q":"Which long coral reef runs the length of the coast?","a":"The coastal barrier reef","o":["The coastal barrier reef","The Great Barrier Reef","The Red Sea reef","The Ningaloo"],"f":"The reef is a UNESCO site. Cayes and a famous Blue Hole sit inside the atoll system."},{"q":"Which rice-and-beans plate with stewed chicken is Sunday food?","a":"Rice and beans","o":["Rice and beans","Jollof","Gallo pinto","Pabellon"],"f":"Red beans are cooked with coconut milk and rice. Stewed chicken and potato salad complete the plate."},{"q":"Which Maya site with a tall limestone temple stands near the Guatemalan border?","a":"Caracol","o":["Caracol","Tikal","Xunantunich","Lamanai"],"f":"Caracol was a major Classic city and a rival of Tikal. Its main temple, Caana, is still a climb."},{"q":"Which city is the capital of Belize?","a":"Belmopan","o":["Belmopan","Manama","Dili","Seoul"],"f":"Belmopan is the capital of Belize.","kind":"capital"},{"q":"Which flag belongs to Belize?","a":"BLZ","o":["BLZ","TKM","SVN","MRT"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Belize.","kind":"flag"}],"medium":[{"q":"Which Garifuna musician, born in Barranco, led a revival of Garifuna music and won a WOMEX award?","a":"Andy Palacio","o":["Andy Palacio","Bob Marley","Ruben Blades","Celia Cruz"],"f":"His album Watina, released in 2007, brought Garifuna songs to listeners worldwide. He died in 2008."},{"q":"The Great Blue Hole, a giant circular sinkhole in the reef off Belize, is roughly how wide?","a":"About 300 meters","o":["About 300 meters","About 30 meters","About 3 kilometers","About 30 kilometers"],"f":"Jacques Cousteau popularized it in 1971. It is a collapsed cave in the limestone, now open to the sea."},{"q":"Caracol was a major Maya city in Belize whose monuments show it once defeated which famous rival?","a":"Tikal","o":["Tikal","Teotihuacan","Cuzco","Tenochtitlan"],"f":"An altar from the 6th century records a victory over Tikal. Caracol's causeways and tallest temple still rise above the forest."},{"q":"What is the capital city of Belize?","a":"Belmopan","o":["Belmopan","Kingstown","St. John's","Washington, D.C."],"f":"Belmopan is the capital of Belize.","kind":"capital"},{"q":"Which of these flags belongs to Belize?","a":"BLZ","o":["BLZ","JAM","GTM","CRI"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Belize.","kind":"flag"}],"hard":[{"q":"Which black howler monkey is a national symbol of the river forests?","a":"The Yucatan black howler","o":["The Yucatan black howler","The spider monkey","The capuchin","The baboon"],"f":"Howlers roar at dawn along the rivers. The Community Baboon Sanctuary at Bermudian Landing protects them."},{"q":"The Garifuna people, shipwrecked and exiled ancestors mixed with Caribs and Africans, celebrate a November arrival with what?","a":"Drumming and reenactment","o":["Drumming and reenactment","A silent fast","A bull run","A regatta only"],"f":"Settlement Day recalls the arrival at Belize in the 1800s. Punta music uses drums and call-and-response."},{"q":"Which cave system holds Maya pottery left as offerings?","a":"Actun Tunichil Muknal","o":["Actun Tunichil Muknal","Harrison's Cave","The Blue Hole","Rio Frio"],"f":"The ATM cave contains skeletons and pots. Visitors swim in and walk in socks to protect the formations."},{"q":"Which of these cities is the capital of Belize?","a":"Belmopan","o":["Belmopan","Belize City","San Pedro","Orange Walk"],"f":"Belmopan is the capital of Belize.","kind":"capital"},{"q":"Which flag is the flag of Belize?","a":"BLZ","o":["BLZ","CIV","BRN","TUN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Belize.","kind":"flag"}]}},{"id":"BOL","name":"Bolivia","cont":"South America","emoji":"🇧🇴","latlng":[-17,-65],"q":{"easy":[{"q":"Which white salt flat in the southwest is the world's largest?","a":"The Salar de Uyuni","o":["The Salar de Uyuni","The Atacama salt","The Etosha pan","The Bonneville flats"],"f":"Uyuni is the bed of a prehistoric lake. In the rainy season a thin sheet of water mirrors the sky."},{"q":"Which high lake, shared with Peru, is the highest navigable lake of its size?","a":"Lake Titicaca","o":["Lake Titicaca","Lake Poopo","Lake Junin","Junin"],"f":"Titicaca sits in the Andes at about 3,800 meters. Reed boats and island communities live on it."},{"q":"Which peanut soup and a spicy chicken, aji de pollo's cousin, share the table with which freeze-dried potato?","a":"Saltena and chuno","o":["Saltena and chuno","Ceviche","Empanadas only","Arepa"],"f":"A saltena is a juicy baked pastry eaten mid-morning. Chuno is potato dried in the freeze-thaw of the altiplano."},{"q":"Which city is the constitutional capital of Bolivia?","a":"Sucre","o":["Sucre","Tallinn","Guatemala City","Ramallah"],"f":"Sucre is the constitutional capital. The government sits in La Paz.","kind":"capital"},{"q":"Which flag belongs to Bolivia?","a":"BOL","o":["BOL","BDI","TGO","ATG"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Bolivia.","kind":"flag"}],"medium":[{"q":"Which Aymara leader, born near Lake Titicaca, besieged La Paz in 1781 during a major uprising against Spanish rule?","a":"Tupac Katari","o":["Tupac Katari","Atahualpa","Lautaro","Moctezuma"],"f":"He took a name that honored earlier rebels Tupac Amaru and Tomas Katari. Bolivia remembers him as a founder of Indigenous resistance."},{"q":"The Salar de Uyuni is the world's largest example of which landscape?","a":"A salt flat","o":["A salt flat","A field of sand dunes","A coral reef","An ice cap"],"f":"After rain, a thin sheet of water turns the surface into a mirror. In many places the salt crust is thick enough to drive on."},{"q":"Tiwanaku, near Lake Titicaca, was a great ceremonial city that flourished centuries before which empire?","a":"The Inca Empire","o":["The Inca Empire","The Mali Empire","The Roman Empire","The Mongol Empire"],"f":"Its Gate of the Sun and tightly fitted stones still stand. The culture was at its height from roughly 500 to 1000 CE."},{"q":"What is the constitutional capital city of Bolivia?","a":"Sucre","o":["Sucre","Georgetown","Caracas","Buenos Aires"],"f":"Sucre is the constitutional capital. The government sits in La Paz.","kind":"capital"},{"q":"Which of these flags belongs to Bolivia?","a":"BOL","o":["BOL","GUY","ARG","ECU"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Bolivia.","kind":"flag"}],"hard":[{"q":"Which silver mountain above Potosi funded the Spanish empire in the 1500s and 1600s?","a":"Cerro Rico","o":["Cerro Rico","Potosi is the city","Huancavelica","Zacatecas"],"f":"Millions of people, including forced indigenous laborers and enslaved Africans, worked the mines. The city is a UNESCO site."},{"q":"The Aymara and Quechua new year, Willkakuti, is marked at which solstice?","a":"The June solstice","o":["The June solstice","The March equinox","Christmas","The September equinox only"],"f":"Communities greet the sunrise at Tiwanaku and other sites. The state recognizes the day."},{"q":"Tiwanaku, near the lake, was the ceremonial center of a state that fell around which century?","a":"The 11th or 12th","o":["The 11th or 12th","The 16th only","The 5th BCE","The 19th"],"f":"The Gate of the Sun and raised platforms remain. The city's influence once reached far across the Andes."},{"q":"Which of these cities is the constitutional capital of Bolivia?","a":"Sucre","o":["Sucre","La Paz","Santa Cruz","Cochabamba"],"f":"Sucre is the constitutional capital. The government sits in La Paz.","kind":"capital"},{"q":"Which flag is the flag of Bolivia?","a":"BOL","o":["BOL","ETH","PHL","NOR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Bolivia.","kind":"flag"}]}},{"id":"BRA","name":"Brazil","cont":"South America","emoji":"🇧🇷","latlng":[-10,-55],"q":{"easy":[{"q":"Which statue of open arms stands on a mountain above Rio de Janeiro?","a":"Christ the Redeemer","o":["Christ the Redeemer","Cristo Rei","The Christ of the Andes","Sugarloaf"],"f":"The art deco figure was finished in 1931. It looks over the bay from Corcovado."},{"q":"Which bean-and-meat stew, cooked for hours, is a national Saturday dish?","a":"Feijoada","o":["Feijoada","Moqueca","Churrasco","Vatapa"],"f":"Feijoada simmers black beans with salted meats. Rice, greens, and orange slices come with it."},{"q":"Which music and dance of the Afro-Brazilian communities of Bahia and Rio became Carnival's beat?","a":"Samba","o":["Samba","Bossa nova","Forro","Frevo"],"f":"Samba's parade form fills the Sambadrome in Rio. Its roots are in Angola and in the city's black neighborhoods."},{"q":"Which city is the capital of Brazil?","a":"Brasília","o":["Brasília","Basseterre","Maputo","Luxembourg City"],"f":"Brasília is the capital of Brazil.","kind":"capital"},{"q":"Which flag belongs to Brazil?","a":"BRA","o":["BRA","ZAF","NIC","MNG"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Brazil.","kind":"flag"}],"medium":[{"q":"Which aviation pioneer, born in Minas Gerais, flew a steerable airship around the Eiffel Tower in 1901?","a":"Alberto Santos-Dumont","o":["Alberto Santos-Dumont","Orville Wright","Louis Bleriot","Ferdinand von Zeppelin"],"f":"In 1906 his 14-bis made a public powered airplane flight in Paris. Brazilians celebrate him as a father of flight."},{"q":"In the rainy season, the white dunes of Lencois Maranhenses fill with thousands of what?","a":"Freshwater lagoons","o":["Freshwater lagoons","Lava pools","Oil seeps","Salt pans"],"f":"Rain sits on a waterproof layer beneath the sand. Fish eggs can survive in the sand and hatch when the pools return."},{"q":"Fleeing Napoleon in 1808, the Portuguese royal court ruled the empire from which Brazilian city?","a":"Rio de Janeiro","o":["Rio de Janeiro","Salvador","Sao Paulo","Recife"],"f":"Salvador had been the older colonial capital, which makes it a tempting wrong answer. Rio stayed Brazil's capital until Brasilia was inaugurated in 1960."},{"q":"What is the capital city of Brazil?","a":"Brasília","o":["Brasília","Bogotá","Montevideo","Caracas"],"f":"Brasília is the capital of Brazil.","kind":"capital"},{"q":"Which of these flags belongs to Brazil?","a":"BRA","o":["BRA","PRY","URY","COL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Brazil.","kind":"flag"}],"hard":[{"q":"Which inland falls on the border are shared with Argentina?","a":"Iguazu Falls","o":["Iguazu Falls","Paulo Afonso","Kaieteur","Angel Falls"],"f":"The Brazilian side walks close to the spray of the Devil's Throat. A national park protects the forest around it."},{"q":"The architect Oscar Niemeyer shaped which planned capital's white curves?","a":"Brasilia's civic buildings","o":["Brasilia's civic buildings","Rio's Christ","Sao Paulo's avenues","Salvador's lifts"],"f":"Niemeyer and Lucio Costa designed the new capital in the late 1950s. The city became a UNESCO site."},{"q":"Which writer of Dom Casmurro and other novels was born in Rio in 1839?","a":"Machado de Assis","o":["Machado de Assis","Jorge Amado","Clarice Lispector","Euclides da Cunha"],"f":"Machado, the grandson of enslaved people, is often called Brazil's greatest novelist. He edited a major literary review."},{"q":"Which of these cities is the capital of Brazil?","a":"Brasília","o":["Brasília","São Paulo","Rio de Janeiro","Salvador"],"f":"Brasília is the capital of Brazil.","kind":"capital"},{"q":"Which flag is the flag of Brazil?","a":"BRA","o":["BRA","URY","LCA","BHS"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Brazil.","kind":"flag"}]}},{"id":"BRB","name":"Barbados","cont":"North America","emoji":"🇧🇧","latlng":[13.16666666,-59.53333333],"q":{"easy":[{"q":"Which crop, once called white gold, built the island's plantation wealth?","a":"Sugar cane","o":["Sugar cane","Cotton","Tobacco","Bananas"],"f":"Sugar and enslaved labor shaped the island from the 1600s. Rum is the later product of the same cane."},{"q":"Which national plate pairs a fried ocean fish with a cornmeal ball?","a":"Flying fish and cou-cou","o":["Flying fish and cou-cou","Ackee and saltfish","Jerk chicken","Roti"],"f":"Cou-cou is stirred cornmeal and okra. Fried flying fish sits beside it."},{"q":"Which tram-like buses painted blue and yellow are the everyday ride?","a":"ZR vans and buses","o":["ZR vans and buses","Jeepneys","Matatus","Dolmus"],"f":"The island's public buses and ZR vans run set routes. They are a familiar part of the road."},{"q":"Which city is the capital of Barbados?","a":"Bridgetown","o":["Bridgetown","London","Juba","Seoul"],"f":"Bridgetown is the capital of Barbados.","kind":"capital"},{"q":"Which flag belongs to Barbados?","a":"BRB","o":["BRB","MKD","BDI","SGP"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Barbados.","kind":"flag"}],"medium":[{"q":"Which singer, born Robyn Fenty in Saint Michael, became one of the world's best-known pop artists?","a":"Rihanna","o":["Rihanna","Beyonce","Nicki Minaj","Alicia Keys"],"f":"She was born in 1988 and grew up in Barbados before her career took off in the United States. Beyonce, Minaj, and Keys were born in the United States."},{"q":"In 1751 a 19-year-old George Washington sailed to Barbados, which is notable because it was his only trip where?","a":"Outside mainland North America","o":["Outside mainland North America","Across the Pacific","To Antarctica","Around Africa"],"f":"He came with his ill brother Lawrence and caught smallpox, which later protected him during the Revolutionary War. He never left the mainland again."},{"q":"Mount Gay, on Barbados, traces its rum-making history to which year, making it one of the oldest commercial rum distilleries?","a":"1703","o":["1703","1492","1867","1966"],"f":"Sugar and molasses from the plantations fed the stills. Rum became the island's signature export."},{"q":"What is the capital city of Barbados?","a":"Bridgetown","o":["Bridgetown","St. John's","Castries","Mexico City"],"f":"Bridgetown is the capital of Barbados.","kind":"capital"},{"q":"Which of these flags belongs to Barbados?","a":"BRB","o":["BRB","USA","VCT","BLZ"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Barbados.","kind":"flag"}],"hard":[{"q":"Which Jewish synagogue in Bridgetown is one of the oldest in the Americas still on its site?","a":"Nidhe Israel","o":["Nidhe Israel","Touro","Kahal Zur","Mikve Israel"],"f":"Sephardic families built Nidhe Israel in the 1600s. A mikvah was found in the yard in the 2000s."},{"q":"Crop Over, the harvest festival, ends with a costume jump-up called what?","a":"Grand Kadooment","o":["Grand Kadooment","Junkanoo","Carnival Tuesday","Mashramani"],"f":"Kadooment is the last big parade. It grew from the old sugar harvest celebration."},{"q":"The island's coral limestone has hundreds of caves, including which famous one with a pool?","a":"Harrison's Cave","o":["Harrison's Cave","The Blue Hole","Dean's Blue Hole","Waitomo"],"f":"Harrison's Cave is a crystallized limestone cavern with an underground stream. Visitors ride a tram through it."},{"q":"Which of these cities is the capital of Barbados?","a":"Bridgetown","o":["Bridgetown","Speightstown","Oistins","Holetown"],"f":"Bridgetown is the capital of Barbados.","kind":"capital"},{"q":"Which flag is the flag of Barbados?","a":"BRB","o":["BRB","ETH","FIN","LCA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Barbados.","kind":"flag"}]}},{"id":"BRN","name":"Brunei","cont":"Asia","emoji":"🇧🇳","latlng":[4.5,114.66666666],"q":{"easy":[{"q":"Which golden-domed mosque stands beside a lagoon in the capital?","a":"The Omar Ali Saifuddien Mosque","o":["The Omar Ali Saifuddien Mosque","The Hassan II Mosque","The Blue Mosque","The Grand Mosque of Muscat"],"f":"The mosque, finished in 1958, is surrounded by a lagoon and a ceremonial barge."},{"q":"Which rainforest park in the Temburong district is reached by boat and a canopy walk?","a":"Ulu Temburong","o":["Ulu Temburong","Kinabalu","Taman Negara","Khao Yai"],"f":"Ulu Temburong protects unlogged forest. A walkway sits in the canopy above the river."},{"q":"Which water village of stilt houses is the historic heart of the capital?","a":"Kampong Ayer","o":["Kampong Ayer","Ganvie","The Uros","Venice"],"f":"Kampong Ayer has stood for centuries on the Brunei River. Schools and mosques sit among the houses."},{"q":"Which city is the capital of Brunei?","a":"Bandar Seri Begawan","o":["Bandar Seri Begawan","Tegucigalpa","Santiago","Niamey"],"f":"Bandar Seri Begawan is the capital of Brunei.","kind":"capital"},{"q":"Which flag belongs to Brunei?","a":"BRN","o":["BRN","SLE","URY","GTM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Brunei.","kind":"flag"}],"medium":[{"q":"Kampong Ayer, on the Brunei River, is a cluster of houses, schools, and mosques built on what?","a":"Stilts over the water","o":["Stilts over the water","Cliff ledges","Houseboats that sail","Reclaimed desert"],"f":"Europeans called it the Venice of the East. Many families have moved ashore, but thousands of people still live in the water village."},{"q":"Ambuyat, the national dish, is a sticky starch made from the trunk of which plant?","a":"The sago palm","o":["The sago palm","The coconut palm","Cassava","Rice"],"f":"Diners twirl it onto a bamboo fork and dip it in a sour sauce. It has almost no taste of its own, so the sauce does the work."},{"q":"The proboscis monkey, found only on Borneo, is named for the male's large what?","a":"Nose","o":["Nose","Tail fan","Thumb","Ear tufts"],"f":"The nose may amplify calls through the mangrove. The monkey is an excellent swimmer, unusual for a primate, and Brunei's forests are one of its refuges."},{"q":"What is the capital city of Brunei?","a":"Bandar Seri Begawan","o":["Bandar Seri Begawan","Seoul","Singapore","Ramallah"],"f":"Bandar Seri Begawan is the capital of Brunei.","kind":"capital"},{"q":"Which of these flags belongs to Brunei?","a":"BRN","o":["BRN","PAK","TJK","IRN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Brunei.","kind":"flag"}],"hard":[{"q":"The proboscis monkey, found in the mangroves, is nicknamed for which feature?","a":"Its long nose","o":["Its long nose","Its striped tail","Its horns","Its pouch"],"f":"Males grow a large fleshy nose. The monkeys live in riverside forest on Borneo, including Brunei."},{"q":"In 1963 the sultan declined to join the new Malaysian federation. The state remained what?","a":"An independent sultanate","o":["An independent sultanate","A Malaysian state","A Philippine province","An Indonesian province"],"f":"Oil and gas later funded a high standard of living."},{"q":"Songkok caps and which gold-threaded cloth are worn at court ceremonies?","a":"Songket","o":["Songket","Batik","Ikat","Kente"],"f":"Songket weaves gold or silver thread into silk. It is reserved for weddings and royal rites."},{"q":"Which of these cities is the capital of Brunei?","a":"Bandar Seri Begawan","o":["Bandar Seri Begawan","Kuala Belait","Seria","Tutong"],"f":"Bandar Seri Begawan is the capital of Brunei.","kind":"capital"},{"q":"Which flag is the flag of Brunei?","a":"BRN","o":["BRN","GRC","MDA","KAZ"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Brunei.","kind":"flag"}]}},{"id":"BTN","name":"Bhutan","cont":"Asia","emoji":"🇧🇹","latlng":[27.5,90.5],"q":{"easy":[{"q":"Which dzong at the confluence of two rivers is the winter home of the central monk body?","a":"Punakha Dzong","o":["Punakha Dzong","Paro Dzong","Trongsa Dzong","Tashichho Dzong"],"f":"Punakha Dzong stands where the Pho and Mo rivers meet. Jacaranda trees bloom in its courtyard."},{"q":"Which chili-and-cheese stew is the national dish?","a":"Ema datshi","o":["Ema datshi","Curry","Goulash","Chili con carne"],"f":"Ema datshi is chilies melted with local cheese. Rice and a side of meat often come with it."},{"q":"Which pass of 108 memorial chortens looks toward the high Himalaya?","a":"Dochula Pass","o":["Dochula Pass","Nathu La","Khardung La","Rohtang"],"f":"The Druk Wangyal chortens were built at Dochula. On clear mornings the snow peaks line the horizon."},{"q":"Which city is the capital of Bhutan?","a":"Thimphu","o":["Thimphu","Asunción","Suva","Freetown"],"f":"Thimphu is the capital of Bhutan.","kind":"capital"},{"q":"Which flag belongs to Bhutan?","a":"BTN","o":["BTN","DNK","ETH","BHS"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Bhutan.","kind":"flag"}],"medium":[{"q":"Taktsang, or the Tiger's Nest, is a monastery clinging to a cliff above Paro. Tradition says a saint flew there on the back of what?","a":"A tigress","o":["A tigress","A snow lion","A dragon","A garuda"],"f":"The saint is Guru Rinpoche, Padmasambhava, who brought Buddhism to the region in the 8th century. The buildings were rebuilt after a fire in 1998."},{"q":"In the 1970s the king promoted a development goal he ranked above income alone. What did he call it?","a":"Gross National Happiness","o":["Gross National Happiness","Gross National Product","The Middle Way economy","Five-year steel plans"],"f":"The idea is that policy should guard culture, environment, and well-being, not only cash. How to measure it is debated, but the phrase is now the country's signature."},{"q":"The national sport is not football. In village contests, teams shoot at small targets with what?","a":"Bows and arrows","o":["Bows and arrows","Blowpipes","Javelins","Slingshots"],"f":"Archery matches are loud, with singing and teasing of the opposing archer. The targets can be more than 100 meters away."},{"q":"What is the capital city of Bhutan?","a":"Thimphu","o":["Thimphu","Baghdad","Damascus","Manama"],"f":"Thimphu is the capital of Bhutan.","kind":"capital"},{"q":"Which of these flags belongs to Bhutan?","a":"BTN","o":["BTN","MMR","UZB","BRN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Bhutan.","kind":"flag"}],"hard":[{"q":"The national sport besides archery is a form of what?","a":"Darts thrown at a short target","o":["Darts thrown at a short target","Cricket","Baseball","Polo"],"f":"Khuru is a heavy wooden dart thrown at a target a few dozen meters away. Teams sing and jeer."},{"q":"Which cloth, woven in bright stripes, is worn as a knee-length robe by men?","a":"The gho","o":["The gho","The kira","The kimono","The kilt"],"f":"The gho is hoisted to the knee and belted, making a pocket at the chest. Women wear the kira."},{"q":"Takins, the national animal, look like a cross between which creatures?","a":"A goat and an antelope","o":["A goat and an antelope","A bear and a pig","A horse and a zebra","A camel and a llama"],"f":"The takin lives in bamboo and rhododendron forests. A golden takin is the national animal."},{"q":"Which of these cities is the capital of Bhutan?","a":"Thimphu","o":["Thimphu","Paro","Punakha","Phuentsholing"],"f":"Thimphu is the capital of Bhutan.","kind":"capital"},{"q":"Which flag is the flag of Bhutan?","a":"BTN","o":["BTN","PRY","IRL","LVA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Bhutan.","kind":"flag"}]}},{"id":"BWA","name":"Botswana","cont":"Africa","emoji":"🇧🇼","latlng":[-22,24],"q":{"easy":[{"q":"Which inland delta spreads the Okavango River into wetlands that never reach the sea?","a":"The Okavango Delta","o":["The Okavango Delta","The Nile Delta","The Mekong Delta","The Lena Delta"],"f":"The Okavango fans out into the Kalahari and dries up in the sand."},{"q":"Which stiff maize porridge is the everyday starch in Botswana?","a":"Pap","o":["Pap","Sushi","Risotto","Fondue"],"f":"Pap, or bogobe, is maize meal cooked firm and eaten with meat or greens."},{"q":"Which park on the Chobe River is famous for huge herds of elephants?","a":"Chobe National Park","o":["Chobe National Park","Kruger","Etosha","Serengeti"],"f":"Visitors watch elephants from boats. Chobe holds one of Africa's largest elephant gatherings."},{"q":"Which city is the capital of Botswana?","a":"Gaborone","o":["Gaborone","Kathmandu","Seoul","Ankara"],"f":"Gaborone is the capital of Botswana.","kind":"capital"},{"q":"Which flag belongs to Botswana?","a":"BWA","o":["BWA","EST","TLS","KAZ"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Botswana.","kind":"flag"}],"medium":[{"q":"Who married Ruth Williams, was exiled by the British in the 1950s, and became the first president in 1966?","a":"Seretse Khama","o":["Seretse Khama","Jomo Kenyatta","Julius Nyerere","Kenneth Kaunda"],"f":"London disliked the interracial marriage and kept him out for years. He returned to lead independence. Kenyatta, Nyerere, and Kaunda were the independence leaders of Kenya, Tanzania, and Zambia."},{"q":"Water from the Angolan highlands spreads into the Okavango and then stops. Unlike the Zambezi, this inland delta never reaches what?","a":"The ocean","o":["The ocean","The Kalahari","Lake Ngami","A wetland"],"f":"The flood arrives in the dry season and turns the channels green. The delta is a UNESCO site inside the Kalahari, and some water pools at Lake Ngami. There is no outlet to the sea."},{"q":"The Tsodilo Hills, sacred to the San and the Hambukushu, are covered with what?","a":"Thousands of rock paintings","o":["Thousands of rock paintings","Roman mosaics","Soapstone birds","Bronze portrait heads"],"f":"UNESCO lists the hills. There are no captions on the paintings, so meanings stay partly open. Soapstone birds belong to Great Zimbabwe, and the bronze heads to Benin City in Nigeria."},{"q":"What is the capital city of Botswana?","a":"Gaborone","o":["Gaborone","Mogadishu","N'Djamena","Moroni"],"f":"Gaborone is the capital of Botswana.","kind":"capital"},{"q":"Which of these flags belongs to Botswana?","a":"BWA","o":["BWA","ETH","SDN","TGO"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Botswana.","kind":"flag"}],"hard":[{"q":"San communities of the Kalahari are known for click consonants and which older way of finding food?","a":"Hunting and gathering","o":["Hunting and gathering","Rice terraces","Trawl fishing","Reindeer herding"],"f":"Tracking and gathering still matter in some communities, alongside newer jobs."},{"q":"Which 1967 mineral find turned Botswana into a major gem exporter?","a":"Diamonds","o":["Diamonds","Emeralds","Rubies","Opals"],"f":"The Orapa pipe was the first great discovery. Diamond income reshaped a dry country."},{"q":"Which bowed lute with a tin or calabash body accompanies praise songs in Botswana?","a":"The segaba","o":["The segaba","The sitar","The bagpipe","The didgeridoo"],"f":"Players sing about cattle, family, and chiefs while bowing the segaba."},{"q":"Which of these cities is the capital of Botswana?","a":"Gaborone","o":["Gaborone","Francistown","Maun","Kasane"],"f":"Gaborone is the capital of Botswana.","kind":"capital"},{"q":"Which flag is the flag of Botswana?","a":"BWA","o":["BWA","KHM","LTU","BRB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Botswana.","kind":"flag"}]}},{"id":"CAF","name":"Central African Republic","cont":"Africa","emoji":"🇨🇫","latlng":[7,21],"q":{"easy":[{"q":"Which river system and rainforest cover much of the southern Central African Republic?","a":"The Congo Basin forest","o":["The Congo Basin forest","The Sahara dunes","The Okavango Delta","The Atlas cedar forest"],"f":"The south of the country is equatorial forest. Rivers drain toward the Congo."},{"q":"Which grilled meat and cassava meal is simple everyday food in the Central African Republic?","a":"Bushbutter and gozo","o":["Bushbutter and gozo","Sushi","Fondue","Poutine"],"f":"Gozo is a cassava porridge. Palm butter, called moambe or bushbutter, sauces meat and greens."},{"q":"Which waterfall on the Mbali River, near the capital, is the country's best-known cascade?","a":"Boali Falls","o":["Boali Falls","Victoria Falls","Iguazu Falls","Augrabies Falls"],"f":"Boali Falls drop about 50 meters. A small hydro plant stands beside the gorge."},{"q":"Which city is the capital of Central African Republic?","a":"Bangui","o":["Bangui","Tashkent","Dublin","Astana"],"f":"Bangui is the capital of Central African Republic.","kind":"capital"},{"q":"Which flag belongs to Central African Republic?","a":"CAF","o":["CAF","ESP","MNG","NOR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Central African Republic.","kind":"flag"}],"medium":[{"q":"UNESCO inscribed, in 2003, the polyphonic singing of which forest people of this country?","a":"The Aka","o":["The Aka","The Maasai","The Dogon","The Himba"],"f":"Several melodies run at once, a rare way of building a song. The same communities live by the Dzanga-Sangha forest. Maasai, Dogon, and Himba are peoples of East Africa, Mali, and Namibia."},{"q":"Which priest and politician, killed in a plane crash in 1959, is remembered as the father of independence?","a":"Barthélemy Boganda","o":["Barthélemy Boganda","Félix Houphouët-Boigny","Léopold Sédar Senghor","Ahmed Sékou Touré"],"f":"Independence from France came in 1960, the year after his death. Houphouët-Boigny, Senghor, and Sékou Touré led Ivory Coast, Senegal, and Guinea."},{"q":"Dzanga Bai, a mineral clearing in the rainforest, draws large gatherings of which animal?","a":"Forest elephants","o":["Forest elephants","Mountain gorillas","Wildebeest","Giraffes"],"f":"Visitors watch from a platform while the elephants dig for salts. Mountain gorillas live on the Virunga volcanoes, far to the east. Wildebeest and giraffes are animals of open savanna."},{"q":"What is the capital city of Central African Republic?","a":"Bangui","o":["Bangui","Gaborone","Addis Ababa","Nouakchott"],"f":"Bangui is the capital of Central African Republic.","kind":"capital"},{"q":"Which of these flags belongs to Central African Republic?","a":"CAF","o":["CAF","ETH","CMR","GNB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Central African Republic.","kind":"flag"}],"hard":[{"q":"Aka people of the southern forest are known for which complex vocal music?","a":"Polyphonic singing","o":["Polyphonic singing","Opera choruses","Brass bands","Throat singing of Tuva only"],"f":"Aka polyphony, listed by UNESCO, weaves yodels and whistles into group song."},{"q":"Which long river rises near the country's north and later joins the Chari on its way to Lake Chad?","a":"The Ouham","o":["The Ouham","The Nile","The Zambezi","The Senegal"],"f":"The Ouham is a major northern river. It feeds the Chari system rather than the Congo."},{"q":"Bark cloth and crossbows are traditional crafts of which forest communities in the southwest?","a":"The Aka and related groups","o":["The Aka and related groups","The Maasai","The Tuareg","The Zulu"],"f":"Forest hunters used nets, spears, and sometimes crossbows, and beat bark into cloth."},{"q":"Which of these cities is the capital of Central African Republic?","a":"Bangui","o":["Bangui","Bambari","Berbérati","Bouar"],"f":"Bangui is the capital of Central African Republic.","kind":"capital"},{"q":"Which flag is the flag of Central African Republic?","a":"CAF","o":["CAF","IRN","GHA","FRA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Central African Republic.","kind":"flag"}]}},{"id":"CAN","name":"Canada","cont":"North America","emoji":"🇨🇦","latlng":[60,-95],"q":{"easy":[{"q":"Which waterfall on the Niagara River is shared with the United States?","a":"Niagara Falls","o":["Niagara Falls","Victoria Falls","Iguazu","Angel Falls"],"f":"The Horseshoe Falls are mostly on the Canadian side. The river is the border."},{"q":"Which gravy-covered fries with cheese curds are a Quebec snack?","a":"Poutine","o":["Poutine","Fish and chips","Chips and gravy","Nachos"],"f":"Poutine began in rural Quebec. Cheese curds, not shredded cheese, are the traditional topping."},{"q":"Which red-coated police force, founded in 1873, is a national symbol?","a":"The Mounties","o":["The Mounties","The FBI","Scotland Yard","The Texas Rangers"],"f":"The North-West Mounted Police became the Royal Canadian Mounted Police. The red serge is now mostly ceremonial."},{"q":"Which city is the capital of Canada?","a":"Ottawa","o":["Ottawa","Kigali","Niamey","Palikir"],"f":"Ottawa is the capital of Canada.","kind":"capital"},{"q":"Which flag belongs to Canada?","a":"CAN","o":["CAN","CHN","ARM","PAK"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Canada.","kind":"flag"}],"medium":[{"q":"Which physician, born in Alliston, Ontario, shared the 1923 Nobel Prize for the discovery of insulin?","a":"Frederick Banting","o":["Frederick Banting","Alexander Fleming","Louis Pasteur","Jonas Salk"],"f":"In 1921 Banting and Charles Best isolated insulin at the University of Toronto. Banting sold the patent rights for one dollar so treatment could spread."},{"q":"The Bay of Fundy, between New Brunswick and Nova Scotia, is famous for the world's highest what?","a":"Tides","o":["Tides","Waterfalls","Sand dunes","Icebergs"],"f":"The difference between high and low tide can exceed 15 meters. At low tide, people walk on harbor floors that ships float over hours later."},{"q":"Which 1867 law of the British Parliament united Ontario, Quebec, Nova Scotia, and New Brunswick into Canada?","a":"The British North America Act","o":["The British North America Act","The Stamp Act","The Quebec Act","The Magna Carta"],"f":"It is now also called the Constitution Act, 1867. Canada later patriated the constitution in 1982, gaining the power to amend it at home."},{"q":"What is the capital city of Canada?","a":"Ottawa","o":["Ottawa","Havana","Washington, D.C.","Port of Spain"],"f":"Ottawa is the capital of Canada.","kind":"capital"},{"q":"Which of these flags belongs to Canada?","a":"CAN","o":["CAN","NIC","CUB","JAM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Canada.","kind":"flag"}],"hard":[{"q":"Which northwest coastal people are known for cedar totem poles and large clan houses?","a":"The Haida","o":["The Haida","The Inuit","The Cree","The Mi'kmaq"],"f":"Haida villages stood on Haida Gwaii, off the Pacific coast. The village of Ninstints is a UNESCO site of memorial poles."},{"q":"Maple syrup is boiled from the sap of which tree in late winter?","a":"The sugar maple","o":["The sugar maple","The oak","The birch only","The pine"],"f":"Sap runs when nights freeze and days thaw. It takes many liters of sap to make one liter of syrup."},{"q":"Which Inuit stone figure of a stacked human shape is a northern landmark art?","a":"The inuksuk","o":["The inuksuk","The totem pole","The moai","The menhir"],"f":"An inuksuk is a stone marker. A human-shaped one is an inunnguaq. The symbol appears on the territorial flag of Nunavut."},{"q":"Which of these cities is the capital of Canada?","a":"Ottawa","o":["Ottawa","Toronto","Montreal","Vancouver"],"f":"Ottawa is the capital of Canada.","kind":"capital"},{"q":"Which flag is the flag of Canada?","a":"CAN","o":["CAN","KAZ","SYR","ALB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Canada.","kind":"flag"}]}},{"id":"CHE","name":"Switzerland","cont":"Europe","emoji":"🇨🇭","latlng":[47,8],"q":{"easy":[{"q":"Which pot of melted cheese, shared with bread, is an Alpine supper?","a":"Fondue","o":["Fondue","Raclette","Quiche","Rosti"],"f":"Cheese fondue is melted with white wine in a shared pot. Bread is dipped from long forks."},{"q":"Which portable timepieces made the country's workshops world famous?","a":"Wristwatches and pocket watches","o":["Wristwatches and pocket watches","Sundials","Hourglasses","Church bells"],"f":"Geneva, the Jura, and towns such as Le Locle specialized in precise gears. Watchmaking is a UNESCO craft."},{"q":"Which mountain railway climbs toward the Jungfrau in the Bernese Oberland?","a":"The Jungfrau railway","o":["The Jungfrau railway","The Glacier Express only","The Orient Express","The TGV"],"f":"Tunnels cut through the Eiger and Monch. The line reaches a station high in the rock and ice."},{"q":"Which city is the capital of Switzerland?","a":"Bern","o":["Bern","Kingston","Maseru","Wellington"],"f":"Bern is the capital of Switzerland.","kind":"capital"},{"q":"Which flag belongs to Switzerland?","a":"CHE","o":["CHE","TCD","ARE","QAT"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Switzerland.","kind":"flag"}],"medium":[{"q":"Which mathematician, born in Basel in 1707, is honored in the number e and in a formula linking exponentials and circles?","a":"Leonhard Euler","o":["Leonhard Euler","Carl Friedrich Gauss","Pierre de Fermat","Bernhard Riemann"],"f":"Euler worked in St. Petersburg and Berlin as well as Switzerland. Even after he went blind he kept producing papers."},{"q":"The Matterhorn, the pyramid-shaped peak above Zermatt, was first climbed in 1865 by a party led by whom?","a":"Edward Whymper","o":["Edward Whymper","Edmund Hillary","Reinhold Messner","George Mallory"],"f":"Four men died on the descent. The tragedy made the mountain famous and began the age of guided Alpine climbing."},{"q":"Henry Dunant, shocked by the wounded at Solferino, helped found the Red Cross in Geneva in which decade?","a":"The 1860s","o":["The 1860s","The 1810s","The 1910s","The 1940s"],"f":"The first Geneva Convention was signed in 1864. Dunant shared the first Nobel Peace Prize in 1901."},{"q":"What is the capital city of Switzerland?","a":"Bern","o":["Bern","Belgrade","Berlin","Moscow"],"f":"Bern is the capital of Switzerland.","kind":"capital"},{"q":"Which of these flags belongs to Switzerland?","a":"CHE","o":["CHE","AUT","DNK","UKR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Switzerland.","kind":"flag"}],"hard":[{"q":"The Red Cross was founded after a battle in 1859 shocked which Genevan businessman?","a":"Henry Dunant","o":["Henry Dunant","Jean-Jacques Rousseau","Calvin","Zwingli"],"f":"Dunant saw the wounded at Solferino. The first Geneva Convention followed in 1864."},{"q":"Which underground bunker-like forts and the Gotthard tunnels guard which pass culture?","a":"Alpine passes","o":["Alpine passes","Desert oases","River deltas","Fjords"],"f":"Switzerland's defense relied on mountain redoubts and armed neutrality through the world wars."},{"q":"Rosti, fried grated potato, comes from which kind of farm breakfast?","a":"A peasant potato cake","o":["A peasant potato cake","A royal souffle","A fish stew","A fruit tart"],"f":"Rosti was a breakfast for farmers in the German-speaking cantons. It is now a national side dish."},{"q":"Which of these cities is the capital of Switzerland?","a":"Bern","o":["Bern","Zurich","Geneva","Basel"],"f":"Bern is the capital of Switzerland.","kind":"capital"},{"q":"Which flag is the flag of Switzerland?","a":"CHE","o":["CHE","NGA","SSD","BDI"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Switzerland.","kind":"flag"}]}},{"id":"CHL","name":"Chile","cont":"South America","emoji":"🇨🇱","latlng":[-30,-71],"q":{"easy":[{"q":"Which long, thin country ends in glaciers and a famous tower of granite?","a":"Patagonia and Torres del Paine","o":["Patagonia and Torres del Paine","The Atacama only","Easter Island only","The lake district only"],"f":"Torres del Paine's horns rise over a national park in the far south. Icebergs float in the grey lakes."},{"q":"Which seafood stew and a completed hot dog with avocado are everyday tastes?","a":"Paila marina and the completo","o":["Paila marina and the completo","Ceviche","Asado","Empanadas only"],"f":"A completo piles avocado, tomato, and mayonnaise on a hot dog. Curanto and seafood stews belong to the coast."},{"q":"Which poet of Twenty Love Poems won the Nobel Prize and was born in Parral?","a":"Pablo Neruda","o":["Pablo Neruda","Gabriela Mistral","Mistral is the other","Nicanor Parra"],"f":"Neruda's houses in Isla Negra, Santiago, and Valparaiso are museums. He died in 1973."},{"q":"Which city is the capital of Chile?","a":"Santiago","o":["Santiago","St. John's","Porto-Novo","Khartoum"],"f":"Santiago is the capital of Chile.","kind":"capital"},{"q":"Which flag belongs to Chile?","a":"CHL","o":["CHL","SVK","KGZ","VCT"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Chile.","kind":"flag"}],"medium":[{"q":"Which poet, born in Vicuna, in 1945 became the first Latin American to win the Nobel Prize in Literature?","a":"Gabriela Mistral","o":["Gabriela Mistral","Pablo Neruda","Gabriel Garcia Marquez","Octavio Paz"],"f":"She had been a rural schoolteacher and diplomat. Another Chilean, Pablo Neruda, won the same prize later, in 1971."},{"q":"The giant stone figures carved on Rapa Nui, a Chilean island in the Pacific, are called what?","a":"Moai","o":["Moai","Tiki","Totem poles","Obelisks"],"f":"Most were cut from volcanic tuff at Rano Raraku. Many stand on platforms called ahu, usually facing inland over a village."},{"q":"The strongest earthquake recorded with modern instruments struck in 1960 near which Chilean city?","a":"Valdivia","o":["Valdivia","Santiago","Antofagasta","Punta Arenas"],"f":"The quake is measured at about magnitude 9.5. The tsunami crossed the Pacific and caused deaths as far away as Japan."},{"q":"What is the capital city of Chile?","a":"Santiago","o":["Santiago","Paramaribo","Georgetown","Asunción"],"f":"Santiago is the capital of Chile.","kind":"capital"},{"q":"Which of these flags belongs to Chile?","a":"CHL","o":["CHL","ECU","GUY","PER"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Chile.","kind":"flag"}],"hard":[{"q":"Which statues on a Pacific island were raised by the Rapa Nui people?","a":"The moai","o":["The moai","The tiki","The inuksuk","The totem"],"f":"The moai stand on ahu platforms. The island, Rapa Nui, is part of Chile and a UNESCO site."},{"q":"The Atacama Desert, one of the driest places on Earth, lies in which north?","a":"The far north","o":["The far north","Patagonia","The lake district","Chiloe"],"f":"Some weather stations there have gone years without rain. Observatories use the clear air."},{"q":"Which folk singer and collector, who died in 1967, wrote Gracias a la Vida?","a":"Violeta Parra","o":["Violeta Parra","Mercedes Sosa","Chabuca Granda","Victor Jara"],"f":"Violeta Parra gathered rural songs and helped start the nueva cancion movement. Gracias a la Vida was among her last recordings."},{"q":"Which of these cities is the capital of Chile?","a":"Santiago","o":["Santiago","Valparaíso","Concepción","Antofagasta"],"f":"Santiago is the capital of Chile.","kind":"capital"},{"q":"Which flag is the flag of Chile?","a":"CHL","o":["CHL","LSO","PER","FSM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Chile.","kind":"flag"}]}},{"id":"CHN","name":"China","cont":"Asia","emoji":"🇨🇳","latlng":[35,105],"q":{"easy":[{"q":"Which long fortification of walls and watchtowers crosses the north of the country?","a":"The Great Wall","o":["The Great Wall","Hadrian's Wall","The Berlin Wall","The Maginot Line"],"f":"Sections of wall were built by several dynasties. The Ming stone wall is the familiar one near Beijing."},{"q":"Which roast duck, served in pancakes with hoisin and scallion, is a Beijing classic?","a":"Peking duck","o":["Peking duck","Cantonese roast goose","Sushi","Tandoori"],"f":"The skin is lacquered and dried, then roasted until it crackles. The meat and skin are wrapped in a thin pancake."},{"q":"Which teacher of the 500s BCE taught filial piety and ritual and shaped later schooling?","a":"Confucius","o":["Confucius","Laozi","Mencius only later","Buddha"],"f":"Confucius was born in Qufu. His Analects were compiled by students after his death."},{"q":"Which city is the capital of China?","a":"Beijing","o":["Beijing","Bratislava","San José","Sofia"],"f":"Beijing is the capital of China.","kind":"capital"},{"q":"Which flag belongs to China?","a":"CHN","o":["CHN","AND","KIR","GRC"],"f":"Compare the colors and symbols. One of these four flags is the national flag of China.","kind":"flag"}],"medium":[{"q":"Which scientist, born in Ningbo, won the 2015 Nobel Prize for a malaria drug drawn from sweet wormwood?","a":"Tu Youyou","o":["Tu Youyou","Jane Goodall","Marie Curie","Dorothy Hodgkin"],"f":"She led a secret project in the 1970s that isolated artemisinin from a plant named in an old medical text. The drug is now a standard treatment worldwide."},{"q":"The Terracotta Army, buried near Xi'an, was made to guard the tomb of which ruler who died in 210 BCE?","a":"Qin Shi Huang","o":["Qin Shi Huang","Kublai Khan","Wu Zetian","Confucius"],"f":"He was the first emperor of a unified China. Farmers drilling a well in 1974 found the pits, which hold thousands of life-size soldiers, no two faces exactly alike."},{"q":"Court records credit Cai Lun, around 105 CE, with improving a cheap writing material made from bark, hemp, and rags. What was it?","a":"Paper","o":["Paper","Parchment","Papyrus","Silk only"],"f":"Earlier scraps of paper have been found, so he may have standardized a craft rather than inventing it from nothing. The new sheets spread along the Silk Road centuries later."},{"q":"What is the capital city of China?","a":"Beijing","o":["Beijing","Bandar Seri Begawan","Manila","New Delhi"],"f":"Beijing is the capital of China.","kind":"capital"},{"q":"Which of these flags belongs to China?","a":"CHN","o":["CHN","KAZ","MNG","MMR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of China.","kind":"flag"}],"hard":[{"q":"Which artificial river, begun in pieces in the 500s and later lengthened, links Hangzhou and Beijing?","a":"The Grand Canal","o":["The Grand Canal","The Suez","The Erie","The Corinth Canal"],"f":"The Grand Canal carried grain north to the capitals. Parts of it are still in use."},{"q":"Peking opera combines singing with which painted face styles and acrobatics?","a":"Jingju","o":["Jingju","Kabuki","Noh","Wayang"],"f":"Roles wear set colors and patterns. The form matured in the 1800s from older regional operas."},{"q":"Which poet of the Tang dynasty wrote thousands of verses and is often paired with Du Fu?","a":"Li Bai","o":["Li Bai","Wang Wei","Qu Yuan","Cao Cao"],"f":"Li Bai was famous for bold, wandering poems. Du Fu wrote more about war and daily hardship."},{"q":"Which of these cities is the capital of China?","a":"Beijing","o":["Beijing","Shanghai","Guangzhou","Xi'an"],"f":"Beijing is the capital of China.","kind":"capital"},{"q":"Which flag is the flag of China?","a":"CHN","o":["CHN","MAR","VNM","BRN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of China.","kind":"flag"}]}},{"id":"CIV","name":"Ivory Coast","cont":"Africa","emoji":"🇨🇮","latlng":[8,-5],"q":{"easy":[{"q":"Which landmark basilica, said to be one of the largest churches on Earth, stands in Yamoussoukro?","a":"The Basilica of Our Lady of Peace","o":["The Basilica of Our Lady of Peace","Sagrada Familia","The Duomo of Milan","Westminster Abbey"],"f":"The basilica was built in the 1980s. Its dome and plaza dominate the planned city."},{"q":"Which spicy grilled fish with onions and tomatoes is a favorite in Ivory Coast?","a":"Poisson braisé","o":["Poisson braisé","Sushi","Poutine","Ceviche"],"f":"Roadside grills cook whole fish with chili and serve it with attiéké, grated cassava."},{"q":"Attiéké, a side of fermented cassava, comes especially from which coastal lagoon people?","a":"The Ebrié and Adioukrou","o":["The Ebrié and Adioukrou","The Inuit","The Maori","The Sami"],"f":"Women prepare attiéké by fermenting and steaming cassava grains until they look like couscous."},{"q":"Which city is the official capital of Ivory Coast?","a":"Yamoussoukro","o":["Yamoussoukro","Kuwait City","Vaduz","Asunción"],"f":"Yamoussoukro is the official capital. Abidjan is the largest city and the main economic center.","kind":"capital"},{"q":"Which flag belongs to Ivory Coast?","a":"CIV","o":["CIV","BTN","MNE","LKA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Ivory Coast.","kind":"flag"}],"medium":[{"q":"Which footballer, born in Abidjan in 1978, captained Chelsea through the club's most successful years?","a":"Didier Drogba","o":["Didier Drogba","Samuel Eto'o","George Weah","Roger Milla"],"f":"In 2005 he and his teammates publicly asked the sides in a civil war to stop fighting, a moment many people here still remember. Eto'o and Milla are Cameroonian, and Weah is Liberian."},{"q":"Grand-Bassam, a UNESCO quarter of verandas beside a lagoon, was the first seat of which administration?","a":"The French colony","o":["The French colony","A Portuguese feitoria","The British Gold Coast","The Belgian Congo"],"f":"Yellow fever pushed the administrators to Bingerville and later to Abidjan. The old French grid is still there. The Gold Coast was Ghana, and the Belgian Congo was the vast colony to the east."},{"q":"The first president, who died in 1993, sponsored a huge basilica in Yamoussoukro modeled on St. Peter's. Who was he?","a":"Félix Houphouët-Boigny","o":["Félix Houphouët-Boigny","Kwame Nkrumah","Léopold Sédar Senghor","Gnassingbé Eyadéma"],"f":"He led the country from independence in 1960 until his death. Claims that the basilica is the world's largest church are disputed, so that ranking is not the question. Nkrumah, Senghor, and Eyadéma led Ghana, Senegal, and Togo."},{"q":"What is the official capital city of Ivory Coast?","a":"Yamoussoukro","o":["Yamoussoukro","Nouakchott","Harare","Mbabane"],"f":"Yamoussoukro is the official capital. Abidjan is the largest city and the main economic center.","kind":"capital"},{"q":"Which of these flags belongs to Ivory Coast?","a":"CIV","o":["CIV","SLE","TGO","DJI"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Ivory Coast.","kind":"flag"}],"hard":[{"q":"Which cocoa beans made Ivory Coast the world's leading grower for many years?","a":"Cacao","o":["Cacao","Vanilla","Cloves","Tea"],"f":"Small farms across the forest zone grow cacao. The beans leave through Abidjan and San-Pedro."},{"q":"The masked dances of the Dan and Guere peoples of the west use which material for the face covering?","a":"Wood","o":["Wood","Glass","Ice","Porcelain"],"f":"Dan masks are smooth wooden faces used in teaching and dispute rituals."},{"q":"Abidjan's Plateau and Treichville neighborhoods helped invent which dance music of the 1970s?","a":"Zouglou","o":["Zouglou","Tango","Waltz","Polka"],"f":"Zouglou began with students and street bands. Lyrics often joke about city life."},{"q":"Which of these cities is the official capital of Ivory Coast?","a":"Yamoussoukro","o":["Yamoussoukro","Abidjan","Bouaké","San-Pédro"],"f":"Yamoussoukro is the official capital. Abidjan is the largest city and the main economic center.","kind":"capital"},{"q":"Which flag is the flag of Ivory Coast?","a":"CIV","o":["CIV","MEX","IRL","ITA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Ivory Coast.","kind":"flag"}]}},{"id":"CMR","name":"Cameroon","cont":"Africa","emoji":"🇨🇲","latlng":[6,12],"q":{"easy":[{"q":"Which active peak on the Gulf of Guinea is the highest mountain in West and Central Africa?","a":"Mount Fako","o":["Mount Fako","Kilimanjaro","Mount Kenya","Table Mountain"],"f":"Mount Cameroon rises straight from the coast near Buea. It still erupts."},{"q":"Which grilled fish dish with spices, sold in Douala, is a point of city pride?","a":"Braised pepper fish","o":["Braised pepper fish","Sushi","Poutine","Ceviche"],"f":"Coastal kitchens cook fish in a hot pepper sauce. Plantains or cassava come alongside."},{"q":"What is the nickname of the national football side?","a":"The Indomitable Lions","o":["The Indomitable Lions","The Samba Kings","The Blue Samurai","The Vikings"],"f":"The Indomitable Lions have won the Africa Cup of Nations and reached a World Cup quarterfinal."},{"q":"Which city is the capital of Cameroon?","a":"Yaoundé","o":["Yaoundé","Riga","Zagreb","Baghdad"],"f":"Yaoundé is the capital of Cameroon.","kind":"capital"},{"q":"Which flag belongs to Cameroon?","a":"CMR","o":["CMR","JPN","SWE","GBR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Cameroon.","kind":"flag"}],"medium":[{"q":"Which striker, born in 1981, became famous at Barcelona and then at Inter Milan?","a":"Samuel Eto'o","o":["Samuel Eto'o","Didier Drogba","George Weah","Roger Milla"],"f":"Milla, born in 1952, was the earlier star from this country, the hero of the 1990 World Cup, not this player. Drogba is Ivorian and Weah is Liberian."},{"q":"Which saxophonist, born in Douala in 1933, recorded Soul Makossa, later heard in the opening of a Michael Jackson hit?","a":"Manu Dibango","o":["Manu Dibango","Fela Kuti","Youssou N'Dour","Hugh Masekela"],"f":"Makossa is a dance music of Douala. Jackson's label later settled with Dibango over the chant in Wanna Be Startin' Somethin'. Fela created Afrobeat in Nigeria, and Masekela was South African."},{"q":"Mount Cameroon, also called Fako, is the highest peak in West Africa. It is also what?","a":"An active volcano","o":["An active volcano","A coral atoll","A peak with permanent glaciers","A meteor crater"],"f":"Eruptions have been recorded into the 21st century. Published heights disagree by tens of meters, which is why there is no number in the question. The summit is far too warm for glaciers."},{"q":"What is the capital city of Cameroon?","a":"Yaoundé","o":["Yaoundé","Antananarivo","Gitega","Pretoria"],"f":"Yaoundé is the capital of Cameroon.","kind":"capital"},{"q":"Which of these flags belongs to Cameroon?","a":"CMR","o":["CMR","BFA","CPV","SYC"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Cameroon.","kind":"flag"}],"hard":[{"q":"The Bamileke chiefdoms of the western highlands are famous for which beaded wooden masks?","a":"Elephant masks","o":["Elephant masks","Venetian carnival masks","Samurai menpo","Inuit bone masks"],"f":"Elephant masks covered in beads appear at royal funerals and dances."},{"q":"Which inland lake, once blamed for a deadly gas burst in 1986, sits in Cameroon's northwest?","a":"Lake Nyos","o":["Lake Nyos","Lake Victoria","Lake Chad","Lake Malawi"],"f":"Carbon dioxide rose from the crater lake and suffocated people and cattle in nearby valleys."},{"q":"The Fang, Beti, and Bulu peoples share which plucked harp-zither of the forest region?","a":"The mvet","o":["The mvet","The banjo","The kora","The sitar"],"f":"A mvet singer tells epic stories while playing the stick-zither."},{"q":"Which of these cities is the capital of Cameroon?","a":"Yaoundé","o":["Yaoundé","Douala","Garoua","Bamenda"],"f":"Yaoundé is the capital of Cameroon.","kind":"capital"},{"q":"Which flag is the flag of Cameroon?","a":"CMR","o":["CMR","GHA","TGO","BEN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Cameroon.","kind":"flag"}]}},{"id":"COD","name":"DR Congo","cont":"Africa","emoji":"🇨🇩","latlng":[0,25],"q":{"easy":[{"q":"Which great apes live on the Virunga volcanoes in the east?","a":"Mountain gorillas","o":["Mountain gorillas","Orangutans","Snow leopards","Polar bears"],"f":"Virunga National Park protects gorillas on the volcanic slopes shared with Rwanda and Uganda."},{"q":"Which cassava-leaf stew, cooked with palm oil, is a national comfort food?","a":"Saka saka","o":["Saka saka","Sushi","Goulash","Poutine"],"f":"Saka saka, or pondu, is pounded cassava leaves simmered for hours, often with fish or meat."},{"q":"Which huge river carries more water than any river except the Amazon?","a":"The Congo","o":["The Congo","The Nile","The Danube","The Rhine"],"f":"The Congo's basin is rainforest. Its mouth pushes fresh water far into the Atlantic."},{"q":"Which city is the capital of DR Congo?","a":"Kinshasa","o":["Kinshasa","Pyongyang","Buenos Aires","Managua"],"f":"Kinshasa is the capital of DR Congo.","kind":"capital"},{"q":"Which flag belongs to DR Congo?","a":"COD","o":["COD","MNG","JPN","BLZ"],"f":"Compare the colors and symbols. One of these four flags is the national flag of DR Congo.","kind":"flag"}],"medium":[{"q":"Which independence leader, born in Katako-Kombe in 1925, was killed in 1961 months after becoming prime minister?","a":"Patrice Lumumba","o":["Patrice Lumumba","Mobutu Sese Seko","Joseph Kasa-Vubu","Laurent-Désiré Kabila"],"f":"His speech in June 1960 angered the departing Belgians. Mobutu later seized power and ruled for decades. Kasa-Vubu was president and a rival. Kabila came to power only in 1997."},{"q":"A park in the east, home to mountain gorillas and the volcano Nyiragongo, was created in 1925 as Albert National Park. What is it called now?","a":"Virunga National Park","o":["Virunga National Park","Kahuzi-Biega","Garamba","Salonga"],"f":"It is often called Africa's first national park, though older game reserves existed in southern Africa. The other three names are also parks in this country, set aside later."},{"q":"The Congo is not the world's longest river. Among rivers it is the deepest, and it ranks second in what?","a":"Fresh water emptied into the sea","o":["Fresh water emptied into the sea","Number of large dams","Length of its glaciers","Height of its tides"],"f":"Only the Amazon sends more water to the ocean. Depths pass 220 meters in places. The Nile is longer. Glaciers and ocean tides are not this river's claim."},{"q":"What is the capital city of DR Congo?","a":"Kinshasa","o":["Kinshasa","Yamoussoukro","Addis Ababa","Banjul"],"f":"Kinshasa is the capital of DR Congo.","kind":"capital"},{"q":"Which of these flags belongs to DR Congo?","a":"COD","o":["COD","CMR","MAR","LBR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of DR Congo.","kind":"flag"}],"hard":[{"q":"Which explorer-missionary's name was given to the colonial state that King Leopold II of Belgium controlled?","a":"Henry Morton Stanley","o":["Henry Morton Stanley","James Cook","Ibn Battuta","Zheng He"],"f":"Stanley's expeditions mapped the river for Leopold's claim. The Congo Free State became infamous for forced labor."},{"q":"The Pende, Kuba, and Luba peoples are renowned for which carved art?","a":"Masks and royal sculpture","o":["Masks and royal sculpture","Ice carving","Totem poles of cedar","Marble fountains"],"f":"Royal cups, masks, and stools from these kingdoms fill museum collections worldwide."},{"q":"Lake Kivu, on the eastern border, is known for dissolved gases and for which fish introduced in the 1950s?","a":"Tilapia and sardine-like sambaza","o":["Tilapia and sardine-like sambaza","Salmon","Cod","Tuna"],"f":"Limnic gases make the lake unusual. Small sambaza are a common fried catch in lakeside towns."},{"q":"Which of these cities is the capital of DR Congo?","a":"Kinshasa","o":["Kinshasa","Lubumbashi","Goma","Kisangani"],"f":"Kinshasa is the capital of DR Congo.","kind":"capital"},{"q":"Which flag is the flag of DR Congo?","a":"COD","o":["COD","GBR","NER","WSM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of DR Congo.","kind":"flag"}]}},{"id":"COG","name":"Congo","cont":"Africa","emoji":"🇨🇬","latlng":[-1,15],"q":{"easy":[{"q":"Which huge river forms the eastern border and was once called Zaire?","a":"The Zaire","o":["The Zaire","The Nile","The Niger","The Volta"],"f":"Brazzaville faces Kinshasa across that river, one of the deepest on Earth. In the late 20th century it was also called the Zaire."},{"q":"Which grilled chicken with palm sauce is a Sunday dish in Congo?","a":"Moambe chicken","o":["Moambe chicken","Sushi","Paella","Poutine"],"f":"Moambe is chicken cooked in palm butter. It is served with cassava leaves or rice."},{"q":"Which wide pool of the Congo River above the capital is a famous stretch of calm water?","a":"Pool Malebo","o":["Pool Malebo","Lake Victoria","The Sudd","The Inner Niger Delta"],"f":"Pool Malebo, once called Stanley Pool, widens the river between Brazzaville and Kinshasa."},{"q":"Which city is the capital of Congo?","a":"Brazzaville","o":["Brazzaville","Bern","Moscow","Sarajevo"],"f":"Brazzaville is the capital of Congo.","kind":"capital"},{"q":"Which flag belongs to Congo?","a":"COG","o":["COG","IND","TUR","DMA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Congo.","kind":"flag"}],"medium":[{"q":"Which novelist, born in Pointe-Noire in 1966, wrote Broken Glass and Memoirs of a Porcupine?","a":"Alain Mabanckou","o":["Alain Mabanckou","Sony Labou Tansi","Emmanuel Dongala","Henri Lopes"],"f":"He writes in French and has taught for years in the United States. The other three are major writers of this country too: Tansi wrote Life and a Half, Dongala wrote Johnny Mad Dog, and Lopes wrote Tribaliks."},{"q":"La Sape is a club of elegant dress in Brazzaville. The short name comes from a French phrase meaning what?","a":"Society of ambiance-makers and elegant people","o":["Society of ambiance-makers and elegant people","Society of port engineers","Union of river pilots","Guild of cocoa planters"],"f":"The same style of sharp suits exists in Kinshasa, across the river. It grew in the late colonial decades as a way to claim dignity in public. It is not a trade union."},{"q":"From 1940, Brazzaville was the African center of which wartime movement led by Charles de Gaulle?","a":"Free France","o":["Free France","Vichy France","The Belgian government in exile","The Commonwealth"],"f":"The Brazzaville Conference of 1944 debated the future of the French colonies. Vichy was the regime that collaborated with Germany. This city sided with de Gaulle."},{"q":"What is the capital city of Congo?","a":"Brazzaville","o":["Brazzaville","Conakry","Nouakchott","Mbabane"],"f":"Brazzaville is the capital of Congo.","kind":"capital"},{"q":"Which of these flags belongs to Congo?","a":"COG","o":["COG","SEN","EGY","TCD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Congo.","kind":"flag"}],"hard":[{"q":"The Kongo Kingdom, whose capital was Mbanza Kongo, stretched from the coast into lands now in this country and Angola. Its rulers took which title?","a":"Manikongo","o":["Manikongo","Pharaoh","Sultan of Zanzibar","Inca"],"f":"The manikongo ruled a centralized kingdom that met the Portuguese in the late 1400s."},{"q":"Which dance music, with interlocking guitars, grew in Brazzaville and Kinshasa in the 20th century?","a":"Rumba","o":["Rumba","Tango","Waltz","Polka"],"f":"Cuban records inspired Congolese rumba. Local guitars and Lingala lyrics made it a new style."},{"q":"The Lesio-Louna reserve is known for protecting which great ape?","a":"Gorillas","o":["Gorillas","Orangutans","Chimpanzees only in Asia","Lemurs"],"f":"Western lowland gorillas live in Congo's forests. Reserves care for orphans and wild groups."},{"q":"Which of these cities is the capital of Congo?","a":"Brazzaville","o":["Brazzaville","Pointe-Noire","Dolisie","Ouesso"],"f":"Brazzaville is the capital of Congo.","kind":"capital"},{"q":"Which flag is the flag of Congo?","a":"COG","o":["COG","MNE","DMA","MEX"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Congo.","kind":"flag"}]}},{"id":"COL","name":"Colombia","cont":"South America","emoji":"🇨🇴","latlng":[4,-72],"q":{"easy":[{"q":"Which walled Caribbean city of balconies and a fortress is a UNESCO port?","a":"Cartagena","o":["Cartagena","Santa Marta","Barranquilla","Bogota"],"f":"Cartagena's stone walls were built against pirates. The old town is a maze of colored houses."},{"q":"Which hillside bean, grown on Andean slopes, is a national export and a point of pride?","a":"Arabica coffee","o":["Arabica coffee","Cocoa","Tea","Yerba mate"],"f":"Arabica grows in the zona cafetera. Juan Valdez was an advertising figure for the growers' federation."},{"q":"Which music of the Caribbean coast, with an accordion, is a dance of the valleys?","a":"Vallenato","o":["Vallenato","Cumbia","Salsa","Bambuco"],"f":"Vallenato's caja drum, guacharaca, and accordion tell stories. It was born in the cattle country around Valledupar."},{"q":"Which city is the capital of Colombia?","a":"Bogotá","o":["Bogotá","Stockholm","Tashkent","Amman"],"f":"Bogotá is the capital of Colombia.","kind":"capital"},{"q":"Which flag belongs to Colombia?","a":"COL","o":["COL","TZA","JPN","USA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Colombia.","kind":"flag"}],"medium":[{"q":"Which novelist, born in Aracataca, wrote One Hundred Years of Solitude and won the 1982 Nobel Prize in Literature?","a":"Gabriel Garcia Marquez","o":["Gabriel Garcia Marquez","Jorge Luis Borges","Pablo Neruda","Julio Cortazar"],"f":"He set the fictional town of Macondo in a world like the Caribbean coast where he grew up. Readers call the style magical realism."},{"q":"Teyuna, called the Lost City, was built in the Sierra Nevada de Santa Marta by which people?","a":"The Tairona","o":["The Tairona","The Inca","The Mapuche","The Aztec"],"f":"Stone stairways and terraces climb the forested mountains. The city was already centuries old when the Spanish arrived on the coast."},{"q":"Cumbia, now danced across Latin America, began on Colombia's Caribbean coast as a mix of Indigenous, European, and which other tradition?","a":"African drumming and dance","o":["African drumming and dance","Japanese court music","Alpine yodeling","Inuit throat singing"],"f":"Enslaved Africans brought rhythms that met Indigenous flutes and later European instruments. The gaita flute is a classic cumbia sound."},{"q":"What is the capital city of Colombia?","a":"Bogotá","o":["Bogotá","Paramaribo","Santiago","Brasília"],"f":"Bogotá is the capital of Colombia.","kind":"capital"},{"q":"Which of these flags belongs to Colombia?","a":"COL","o":["COL","BOL","ARG","PER"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Colombia.","kind":"flag"}],"hard":[{"q":"Which painter of inflated figures was born in Medellin in 1932?","a":"Fernando Botero","o":["Fernando Botero","Gabriel Garcia Marquez is a writer","Obregon","Lam"],"f":"Botero's rounded people and still lifes made him the country's best-known painter. A museum in Bogota holds part of his collection."},{"q":"The Gold Museum in the capital holds objects of which precolonial cultures?","a":"Muisca, Quimbaya, and others","o":["Muisca, Quimbaya, and others","The Inca only","The Aztecs","The Maya"],"f":"The Muisca raft is a small gold scene often linked to the El Dorado story. It is the museum's centerpiece."},{"q":"Which river port on the Magdalena was the setting of a famous love story by Garcia Marquez?","a":"The world of Love in the Time of Cholera","o":["The world of Love in the Time of Cholera","Macondo","Cartagena only as a film","Aracataca"],"f":"Garcia Marquez was born in Aracataca. His novels made the Caribbean coast a literary landscape."},{"q":"Which of these cities is the capital of Colombia?","a":"Bogotá","o":["Bogotá","Medellín","Cali","Cartagena"],"f":"Bogotá is the capital of Colombia.","kind":"capital"},{"q":"Which flag is the flag of Colombia?","a":"COL","o":["COL","VEN","ECU","BLZ"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Colombia.","kind":"flag"}]}},{"id":"COM","name":"Comoros","cont":"Africa","emoji":"🇰🇲","latlng":[-12.16666666,44.25],"q":{"easy":[{"q":"Which large shield volcano forms most of Grande Comore, the biggest Comorian island?","a":"Mount Karthala","o":["Mount Karthala","Kilimanjaro","Etna","Fuji"],"f":"Karthala's crater often holds a lava lake. Eruptions have threatened nearby towns."},{"q":"Which spice, used in ice cream and perfume, is a major export of Comoros?","a":"Vanilla","o":["Vanilla","Saffron","Wasabi","Horseradish"],"f":"Comoros is one of the world's main vanilla growers. Ylang-ylang flowers are another famous crop."},{"q":"The coelacanth, a fish once thought extinct, was rediscovered in the 20th century in which channel?","a":"The Mozambique Channel","o":["The Mozambique Channel","The English Channel","The Bering Strait","The Davis Strait"],"f":"A museum specimen from the Comoros in 1938 showed the coelacanth still lived in the deep channel."},{"q":"Which city is the capital of Comoros?","a":"Moroni","o":["Moroni","Roseau","Seoul","Warsaw"],"f":"Moroni is the capital of Comoros.","kind":"capital"},{"q":"Which flag belongs to Comoros?","a":"COM","o":["COM","BHS","PRY","MYS"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Comoros.","kind":"flag"}],"medium":[{"q":"These islands are a leading source of perfume oil distilled from the flowers of which tree?","a":"Ylang-ylang","o":["Ylang-ylang","Jasmine","Lavender","Damask rose"],"f":"The yellow-green flowers are picked by hand and distilled quickly. The oil sits inside many famous perfumes. Jasmine, lavender, and rose oils are made mainly in other regions."},{"q":"A coelacanth, a fish once thought dead since the age of dinosaurs, was caught off these islands in 1952. Where had the first living one been found, in 1938?","a":"South Africa","o":["South Africa","Madagascar","Mozambique","The Seychelles"],"f":"Marjorie Courtenay-Latimer spotted that 1938 fish in a trawler's catch at East London. The Comoros finds showed there was a real population. Coelacanths are lobe-finned, closer to land animals than most fish."},{"q":"Mount Karthala, which has erupted in living memory and dominates Grande Comore, is what kind of volcano?","a":"A shield volcano","o":["A shield volcano","A coral atoll","A sand dune","A glaciated alp"],"f":"Lava from its wide crater has threatened villages. The islands are volcanic, which is why the slopes can grow perfume trees. There is no glacier and no dune sea here."},{"q":"What is the capital city of Comoros?","a":"Moroni","o":["Moroni","Mogadishu","Harare","Windhoek"],"f":"Moroni is the capital of Comoros.","kind":"capital"},{"q":"Which of these flags belongs to Comoros?","a":"COM","o":["COM","CPV","BFA","MWI"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Comoros.","kind":"flag"}],"hard":[{"q":"Comorian society follows a form of Islam and a custom of big wedding exchanges called what?","a":"Grand mariage","o":["Grand mariage","Potlatch","Dowry of cattle only","Carnival"],"f":"A grand mariage is a costly public wedding that raises a person's status in the village."},{"q":"Which language of the islands is a Bantu language with many Arabic and French words?","a":"Shikomori","o":["Shikomori","Quechua","Maori","Finnish"],"f":"Shikomori is the everyday language. Arabic is used in religion, and French in official papers."},{"q":"Anjouan, Moheli, and Grande Comore are volcanic. Which island of the archipelago is governed with France, not the Union of the Comoros?","a":"Mayotte","o":["Mayotte","Reunion","Zanzibar","Socotra"],"f":"Mayotte voted to stay with France. The other three islands form the Union of the Comoros."},{"q":"Which of these cities is the capital of Comoros?","a":"Moroni","o":["Moroni","Mutsamudu","Fomboni","Domoni"],"f":"Moroni is the capital of Comoros.","kind":"capital"},{"q":"Which flag is the flag of Comoros?","a":"COM","o":["COM","VAT","SOM","URY"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Comoros.","kind":"flag"}]}},{"id":"CPV","name":"Cape Verde","cont":"Africa","emoji":"🇨🇻","latlng":[16,-24],"q":{"easy":[{"q":"Which music style, sung in Cape Verdean Creole with guitars and melancholy lyrics, is the islands' signature?","a":"Morna","o":["Morna","Samba","Reggae","Flamenco"],"f":"Morna is often compared with Portuguese fado. Cesaria Evora made it famous worldwide."},{"q":"Which half-moon fried pastry, often filled with fish, is a beach and market snack?","a":"A tuna pastel","o":["A tuna pastel","A samosa","An empanada","A corn dog"],"f":"The pastry is folded, fried, and sold hot. Tuna or corn are the usual fillings."},{"q":"Which volcano on Fogo island still has a village inside its crater caldera?","a":"Pico do Fogo","o":["Pico do Fogo","Etna","Fuji","Rainier"],"f":"Chã das Caldeiras sits in the caldera. Eruptions have destroyed houses and then people have rebuilt."},{"q":"Which city is the capital of Cape Verde?","a":"Praia","o":["Praia","Sri Jayawardenepura Kotte","Belgrade","Sarajevo"],"f":"Praia is the capital of Cape Verde.","kind":"capital"},{"q":"Which flag belongs to Cape Verde?","a":"CPV","o":["CPV","LCA","VAT","PSE"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Cape Verde.","kind":"flag"}],"medium":[{"q":"Which singer, born in Mindelo in 1941, was called the Barefoot Diva and carried morna to the world?","a":"Cesária Évora","o":["Cesária Évora","Miriam Makeba","Angélique Kidjo","Mariza"],"f":"She sang in Cape Verdean Creole, often with no shoes. Morna is a slow, guitar-led song, and UNESCO inscribed the practice in 2019. Makeba was South African, Kidjo is Beninese, and Mariza is a fado singer raised in Portugal."},{"q":"Pico do Fogo erupted in 2014 and buried houses in lava inside its own crater. The mountain is what?","a":"An active volcano","o":["An active volcano","An extinct coral stack","A meteor crater","A glacier-carved peak"],"f":"People of Chã das Caldeiras farm the black soil of the old crater and had to flee that flow. Every island in the country is volcanic."},{"q":"A slow stew of hominy corn, beans, and fish or meat, often fried again the next morning, is called what?","a":"Cachupa","o":["Cachupa","Feijoada","Jollof","Thieboudienne"],"f":"Cachupa rica adds meat; cachupa pobre is the plain pot. Feijoada is the bean stew of Brazil and Portugal, a cousin, not this recipe. Jollof and thieboudienne are tomato rice dishes of the mainland."},{"q":"What is the capital city of Cape Verde?","a":"Praia","o":["Praia","Dodoma","Victoria","Port Louis"],"f":"Praia is the capital of Cape Verde.","kind":"capital"},{"q":"Which of these flags belongs to Cape Verde?","a":"CPV","o":["CPV","UGA","GNB","GIN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Cape Verde.","kind":"flag"}],"hard":[{"q":"Cape Verdean Creole grew from Portuguese mixed with languages of which region?","a":"West Africa","o":["West Africa","Polynesia","The Andes","Scandinavia"],"f":"Enslaved and free Africans and Portuguese settlers shaped the language on the islands."},{"q":"Which wind, a dry harmattan or a trade wind, shapes the arid climate of these Atlantic islands?","a":"The northeast trade winds","o":["The northeast trade winds","The monsoon of India","The sirocco only","Polar easterlies"],"f":"The islands are dry because cool winds and a cold current limit rain. Fog and dew still help some crops."},{"q":"The old port of Cidade Velha, once called Ribeira Grande, was the first European colonial town in which ocean's tropics?","a":"The Atlantic","o":["The Atlantic","The Arctic","The Caspian","The Black Sea"],"f":"Ribeira Grande began in the 1400s as a way station for ships between Europe, Africa, and the Americas."},{"q":"Which of these cities is the capital of Cape Verde?","a":"Praia","o":["Praia","Mindelo","Santa Maria","Assomada"],"f":"Praia is the capital of Cape Verde.","kind":"capital"},{"q":"Which flag is the flag of Cape Verde?","a":"CPV","o":["CPV","GNB","DMA","SRB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Cape Verde.","kind":"flag"}]}},{"id":"CRI","name":"Costa Rica","cont":"North America","emoji":"🇨🇷","latlng":[10,-84],"q":{"easy":[{"q":"Which cloud-forest volcano park holds the crater of Poas?","a":"Poas Volcano","o":["Poas Volcano","Arenal","Irazu","Rincon de la Vieja"],"f":"Poas has a acid lake in one crater. It sits above the Central Valley's coffee towns."},{"q":"Which rice and beans, served with almost every meal, have a national nickname?","a":"Gallo pinto","o":["Gallo pinto","Casado","Pabellon","Moros y cristianos"],"f":"Gallo pinto is spotted rooster, beans and rice fried together. A casado plate adds meat and plantain."},{"q":"Which sloths, toucans, and a famous conservation story live in which forest ethic?","a":"Rainforest reserves","o":["Rainforest reserves","Deserts","Glaciers","Prairies"],"f":"Costa Rica set aside a large share of its land as parks. Ecotourism became a national industry."},{"q":"Which city is the capital of Costa Rica?","a":"San José","o":["San José","Lima","Bern","Sarajevo"],"f":"San José is the capital of Costa Rica.","kind":"capital"},{"q":"Which flag belongs to Costa Rica?","a":"CRI","o":["CRI","GAB","GMB","PER"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Costa Rica.","kind":"flag"}],"medium":[{"q":"Which president, born in Heredia, won the 1987 Nobel Peace Prize for a regional peace plan?","a":"Oscar Arias","o":["Oscar Arias","Rigoberta Menchu","Nelson Mandela","Desmond Tutu"],"f":"His plan helped end civil wars in neighboring countries. He later served a second term as president, long after the prize."},{"q":"After a brief civil war, Costa Rica's 1949 constitution did something almost unique. It abolished what?","a":"The standing army","o":["The standing army","All elections","The court system","Public schools"],"f":"Article 12 forbids a permanent army. The old military budget was shifted toward education and health, a point Costa Ricans still emphasize."},{"q":"Monteverde is a famous reserve of which ecosystem, where trees drip with moisture blown off the Caribbean?","a":"Cloud forest","o":["Cloud forest","Mangrove swamp","Alpine tundra","Hot desert"],"f":"Orchids, quetzals, and howler monkeys live in the mist. The reserve was expanded with help from local Quaker settlers and biologists."},{"q":"What is the capital city of Costa Rica?","a":"San José","o":["San José","Managua","Kingstown","Ottawa"],"f":"San José is the capital of Costa Rica.","kind":"capital"},{"q":"Which of these flags belongs to Costa Rica?","a":"CRI","o":["CRI","BRB","BHS","GTM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Costa Rica.","kind":"flag"}],"hard":[{"q":"Which president abolished the standing army in 1948 after a civil war?","a":"Jose Figueres Ferrer","o":["Jose Figueres Ferrer","Oscar Arias","Juan Santamaria","Rafael Calderon"],"f":"Figueres announced the army's end on 1 December 1948. The country has kept a civil police instead."},{"q":"Which oxcart painting tradition of bright geometric wheels is a UNESCO craft?","a":"Sarchi oxcarts","o":["Sarchi oxcarts","Truck art","Jeepneys","Fileteado"],"f":"Workshops in Sarchi paint wooden carts that once hauled coffee. The craft is now a national symbol."},{"q":"The Monteverde cloud forest was partly founded by which settlers in the 1950s?","a":"Quaker families from the United States","o":["Quaker families from the United States","Mennonites from Russia","Japanese farmers","Swiss dairymen"],"f":"Quakers looking for a peaceful country bought land and protected the forest above their dairy farms."},{"q":"Which of these cities is the capital of Costa Rica?","a":"San José","o":["San José","Limón","Alajuela","Liberia"],"f":"San José is the capital of Costa Rica.","kind":"capital"},{"q":"Which flag is the flag of Costa Rica?","a":"CRI","o":["CRI","THA","STP","TON"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Costa Rica.","kind":"flag"}]}},{"id":"CUB","name":"Cuba","cont":"North America","emoji":"🇨🇺","latlng":[21.5,-80],"q":{"easy":[{"q":"Which classic cars and a seafront promenade define the capital's old postcard look?","a":"The Malecon and 1950s cars","o":["The Malecon and 1950s cars","The Copacabana","The Croisette","The Corniche"],"f":"The Malecon is Havana's seawall. American cars kept running after imports stopped are a famous sight."},{"q":"Which rice and beans, and a shredded beef called ropa vieja, are home cooking?","a":"Moros y cristianos and ropa vieja","o":["Moros y cristianos and ropa vieja","Gallo pinto","Pabellon","Jollof"],"f":"Moros is black beans with rice. Ropa vieja, old clothes, is beef pulled into strips in tomato sauce."},{"q":"Which music, born in the late 1800s, mixed Spanish guitar with African drums and later fed salsa?","a":"Son","o":["Son","Tango","Samba","Flamenco"],"f":"Son from eastern Cuba mixed Spanish guitar and African percussion. The Buena Vista Social Club revived older players in the 1990s."},{"q":"Which city is the capital of Cuba?","a":"Havana","o":["Havana","Buenos Aires","Bern","Victoria"],"f":"Havana is the capital of Cuba.","kind":"capital"},{"q":"Which flag belongs to Cuba?","a":"CUB","o":["CUB","NPL","SEN","MWI"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Cuba.","kind":"flag"}],"medium":[{"q":"Which poet and organizer, born in Havana in 1853, became the leading writer of Cuba's independence struggle?","a":"Jose Marti","o":["Jose Marti","Simon Bolivar","Ruben Dario","Pablo Neruda"],"f":"He founded the Cuban Revolutionary Party in exile and died in battle in 1895. His verses are still memorized in Cuban classrooms."},{"q":"The Vinales Valley is a landscape of tobacco farms and steep limestone hills that Cubans call what?","a":"Mogotes","o":["Mogotes","Tepuis","Inselbergs","Drumlins"],"f":"The rounded towers are the remains of a limestone plateau. UNESCO listed the valley for both the scenery and the traditional farming."},{"q":"In 1959 a revolution overthrew Fulgencio Batista. Which lawyer, born in Biran, became the new government's central leader?","a":"Fidel Castro","o":["Fidel Castro","Che Guevara","Jose Marti","Fulgencio Batista"],"f":"Guevara, born in Argentina, was a key commander but not the head of state. Castro led Cuba until 2008 and died in 2016."},{"q":"What is the capital city of Cuba?","a":"Havana","o":["Havana","Nassau","San José","Kingston"],"f":"Havana is the capital of Cuba.","kind":"capital"},{"q":"Which of these flags belongs to Cuba?","a":"CUB","o":["CUB","LCA","ATG","GTM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Cuba.","kind":"flag"}],"hard":[{"q":"Which independence general, nicknamed the Bronze Titan, was killed in battle in 1896?","a":"Antonio Maceo","o":["Antonio Maceo","Maximo Gomez","Calixto Garcia","Ignacio Agramonte"],"f":"Maceo refused to end an earlier war while slavery continued. He was killed at Punta Brava in December 1896."},{"q":"The Malecon's old forts, El Morro and La Cabana, guarded which harbor?","a":"Havana Bay","o":["Havana Bay","Santiago Bay","The Panama Canal","Guantanamo only"],"f":"Spain built the forts against pirates and rival empires. A chain once closed the harbor mouth."},{"q":"Which cigar valleys west of Havana are a protected tobacco landscape?","a":"Vuelta Abajo in Pinar del Rio","o":["Vuelta Abajo in Pinar del Rio","Viñales only as a valley view","The Connecticut valley","Sumatra"],"f":"Vuelta Abajo grows the wrapper and filler of the famous cigars. Viñales's limestone mogotes stand nearby."},{"q":"Which of these cities is the capital of Cuba?","a":"Havana","o":["Havana","Santiago de Cuba","Trinidad","Camagüey"],"f":"Havana is the capital of Cuba.","kind":"capital"},{"q":"Which flag is the flag of Cuba?","a":"CUB","o":["CUB","GAB","AZE","ALB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Cuba.","kind":"flag"}]}},{"id":"CYP","name":"Cyprus","cont":"Europe","emoji":"🇨🇾","latlng":[35,33],"q":{"easy":[{"q":"Which grilled white cheese, often served warm, is the island's most famous food?","a":"Halloumi","o":["Halloumi","Feta","Mozzarella","Paneer"],"f":"Halloumi holds its shape in a pan because it is boiled in whey. Mint is sometimes mixed into the curd."},{"q":"Which sea stack and beach is tied to the myth of a goddess born from the waves?","a":"Petra tou Romiou","o":["Petra tou Romiou","The Giant's Causeway","Etretat","The Twelve Apostles"],"f":"The Greek myth of Aphrodite's birth is set on this coast. The rock stands in the surf near Paphos."},{"q":"Which painted churches in the Troodos Mountains are UNESCO-listed for their frescoes?","a":"The Troodos churches","o":["The Troodos churches","The Bucovina monasteries","The Sistine Chapel","Rila"],"f":"Mountain churches such as Asinou keep Byzantine wall paintings under steep roofs."},{"q":"Which city is the capital of Cyprus?","a":"Nicosia","o":["Nicosia","Lomé","Porto-Novo","Bamako"],"f":"Nicosia is the capital of Cyprus.","kind":"capital"},{"q":"Which flag belongs to Cyprus?","a":"CYP","o":["CYP","IRQ","THA","KOR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Cyprus.","kind":"flag"}],"medium":[{"q":"Zeno of Citium, born in what is now Larnaca, founded which school of philosophy in Athens?","a":"Stoicism","o":["Stoicism","Epicureanism","Cynicism","Skepticism"],"f":"He taught in the Stoa Poikile, the painted porch, which gave the school its name. Stoics aimed at virtue and calm in the face of what they could not control."},{"q":"The Latin word for copper, cuprum, comes from the Roman name for Cyprus. The island was famous in antiquity for what?","a":"Copper mines","o":["Copper mines","Tin mines","Diamond pipes","Marble only"],"f":"Aes Cyprium meant metal of Cyprus. Ingots shaped like oxhides were shipped across the Mediterranean in the Bronze Age."},{"q":"Commandaria, a sweet wine from sun-dried grapes, is often called the oldest named wine still made. Crusaders met it on the island. It is named for a region once held by whom?","a":"The Knights Templar and Hospitallers","o":["The Knights Templar and Hospitallers","The Vikings","The Aztecs","The Han dynasty"],"f":"Richard the Lionheart sold Cyprus to the Templars in 1192, and the Hospitallers later held the wine country. The name Commandaria recalls their commandery."},{"q":"What is the capital city of Cyprus?","a":"Nicosia","o":["Nicosia","Stockholm","Dublin","Luxembourg City"],"f":"Nicosia is the capital of Cyprus.","kind":"capital"},{"q":"Which of these flags belongs to Cyprus?","a":"CYP","o":["CYP","SVK","UKR","MNE"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Cyprus.","kind":"flag"}],"hard":[{"q":"Copper gave the island a name used in ancient Greek. Ingots were shipped in the shape of what?","a":"An ox hide","o":["An ox hide","A coin","A sphere","A cross"],"f":"Oxhide ingots of copper appear in Bronze Age shipwrecks. The metal funded the island's early trade."},{"q":"Which sweet wine of sun-dried grapes was praised by medieval crusaders?","a":"Commandaria","o":["Commandaria","Port","Tokaj","Champagne"],"f":"Commandaria is made from sun-dried grapes. It is often called one of the oldest named wines still produced."},{"q":"The tomb complex called the Tombs of the Kings lies at which ancient city?","a":"Paphos","o":["Paphos","Salamis","Kition","Amathus"],"f":"Hellenistic rock tombs at Paphos have Doric columns cut from the stone. The name is traditional, not a list of known kings."},{"q":"Which of these cities is the capital of Cyprus?","a":"Nicosia","o":["Nicosia","Limassol","Larnaca","Paphos"],"f":"Nicosia is the capital of Cyprus.","kind":"capital"},{"q":"Which flag is the flag of Cyprus?","a":"CYP","o":["CYP","CAN","MNG","ISR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Cyprus.","kind":"flag"}]}},{"id":"CZE","name":"Czechia","cont":"Europe","emoji":"🇨🇿","latlng":[49.75,15.5],"q":{"easy":[{"q":"Which stone bridge lined with statues crosses the Vltava in the historic center?","a":"Charles Bridge","o":["Charles Bridge","Tower Bridge","The Rialto","Ponte Vecchio"],"f":"Charles Bridge was begun in the 1300s. Baroque statues were added later."},{"q":"Which roast beef in cream sauce with bread dumplings is a Sunday plate?","a":"Svickova","o":["Svickova","Goulash","Borscht","Paella"],"f":"Svickova is marinated beef with a vegetable cream sauce. Dumplings soak up the sauce."},{"q":"Which composer of the New World Symphony was born in a village near Prague?","a":"Antonin Dvorak","o":["Antonin Dvorak","Smetana","Mozart","Chopin"],"f":"Dvorak used rhythms he heard in Bohemia and, later, in America. He was born in 1841."},{"q":"Which city is the capital of Czechia?","a":"Prague","o":["Prague","Lima","Windhoek","Kuwait City"],"f":"Prague is the capital of Czechia.","kind":"capital"},{"q":"Which flag belongs to Czechia?","a":"CZE","o":["CZE","BWA","TZA","MNG"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Czechia.","kind":"flag"}],"medium":[{"q":"Which monk, born in what is now Vrazne, founded genetics by breeding pea plants in a monastery garden?","a":"Gregor Mendel","o":["Gregor Mendel","Charles Darwin","Louis Pasteur","Carl Linnaeus"],"f":"He tracked traits such as tall and short through generations and found they came in predictable ratios. His 1866 paper was ignored until about 1900."},{"q":"The word robot was introduced in a 1920 Prague play, R.U.R. Who wrote that play?","a":"Karel Capek","o":["Karel Capek","Franz Kafka","Isaac Asimov","H. G. Wells"],"f":"His brother Josef suggested robot, from robota, the old word for forced labor. Asimov later wrote the famous laws, but he did not coin the word."},{"q":"Franz Kafka, born in Prague in 1883, wrote in German about baffling authority. Which unfinished novel begins with Josef K. being arrested and never told the charge?","a":"The Trial","o":["The Trial","The Metamorphosis","The Castle","Amerika"],"f":"The Metamorphosis is the story of a man who wakes as an insect, and it was finished. Kafka asked a friend to burn the manuscripts, and the friend published them instead."},{"q":"What is the capital city of Czechia?","a":"Prague","o":["Prague","Minsk","Nicosia","Athens"],"f":"Prague is the capital of Czechia.","kind":"capital"},{"q":"Which of these flags belongs to Czechia?","a":"CZE","o":["CZE","SMR","FRA","ITA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Czechia.","kind":"flag"}],"hard":[{"q":"Which spa town of colonnades and hot springs hosted European congresses?","a":"Karlovy Vary","o":["Karlovy Vary","Bath","Baden-Baden","Vichy"],"f":"Karlovy Vary's springs were a meeting place for aristocrats and composers. The water is drunk from special cups."},{"q":"Which puppet tradition of traveling theaters is still a national art?","a":"Marionette theater","o":["Marionette theater","Kabuki","Shadow puppets of Java","Bunraku only"],"f":"Workshops in Prague carve wooden marionettes. The form was village entertainment before it became a city art."},{"q":"The Hussite movement of the 1400s followed which Prague preacher?","a":"Jan Hus","o":["Jan Hus","Luther","Calvin","Wycliffe only in England"],"f":"Hus was burned in 1415 after criticizing church abuses. His followers fought the Hussite wars."},{"q":"Which of these cities is the capital of Czechia?","a":"Prague","o":["Prague","Brno","Ostrava","Plzeň"],"f":"Prague is the capital of Czechia.","kind":"capital"},{"q":"Which flag is the flag of Czechia?","a":"CZE","o":["CZE","COL","SRB","DNK"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Czechia.","kind":"flag"}]}},{"id":"DEU","name":"Germany","cont":"Europe","emoji":"🇩🇪","latlng":[51,9],"q":{"easy":[{"q":"Which castle in Bavaria, begun in 1869 for King Ludwig II, looks like a stage set?","a":"Neuschwanstein","o":["Neuschwanstein","Windsor","Bran","The Kremlin"],"f":"Neuschwanstein stands above a gorge near Fussen. It was unfinished when Ludwig died in 1886."},{"q":"Which grilled sausage in a roll is street food across the country?","a":"Bratwurst","o":["Bratwurst","Chorizo","Merguez","Hot dog only"],"f":"Bratwurst recipes change by town. Nuremberg serves them small; Thuringia serves them long and spiced."},{"q":"Which composer, born in Bonn, wrote nine symphonies including the Eroica?","a":"Ludwig van Beethoven","o":["Ludwig van Beethoven","Bach","Mozart","Brahms"],"f":"Beethoven moved to Vienna and lost his hearing. He still conducted the premiere of the Ninth."},{"q":"Which city is the capital of Germany?","a":"Berlin","o":["Berlin","Nairobi","Ashgabat","Kampala"],"f":"Berlin is the capital of Germany.","kind":"capital"},{"q":"Which flag belongs to Germany?","a":"DEU","o":["DEU","TON","ARM","HND"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Germany.","kind":"flag"}],"medium":[{"q":"Which composer, born in Eisenach in 1685, wrote the Brandenburg Concertos and the St. Matthew Passion?","a":"Johann Sebastian Bach","o":["Johann Sebastian Bach","George Frideric Handel","Ludwig van Beethoven","Wolfgang Amadeus Mozart"],"f":"Handel was born the same year, in Halle, but made his career in London. Beethoven came later and was born in Bonn."},{"q":"Around 1440 in Mainz, Johannes Gutenberg combined movable metal type with a screw press adapted from what machine?","a":"A wine press","o":["A wine press","A waterwheel","A spinning jenny","A steam engine"],"f":"Oil-based ink helped the type print cleanly on paper. Movable type already existed in Asia; his workshop made it practical for the Latin alphabet."},{"q":"In 1886 Karl Benz of Mannheim patented a three-wheeled vehicle recognized as the first practical what?","a":"Automobile","o":["Automobile","Steam locomotive","Airplane","Safety bicycle"],"f":"His wife Bertha drove one from Mannheim to Pforzheim to prove it could travel. Gottlieb Daimler was building high-speed engines nearby at the same time."},{"q":"What is the capital city of Germany?","a":"Berlin","o":["Berlin","Helsinki","Bucharest","Madrid"],"f":"Berlin is the capital of Germany.","kind":"capital"},{"q":"Which of these flags belongs to Germany?","a":"DEU","o":["DEU","EST","POL","MDA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Germany.","kind":"flag"}],"hard":[{"q":"The Hanseatic League of merchant cities had a famous kontor in which North Sea port?","a":"Lubeck","o":["Lubeck","Munich","Stuttgart","Frankfurt"],"f":"Lubeck's brick gates and warehouses marked a queen of the medieval trade network. UNESCO lists the old town."},{"q":"Which fairy-tale collectors published household stories in the early 1800s?","a":"The Grimm brothers","o":["The Grimm brothers","Andersen","Perrault","Aesop"],"f":"Jacob and Wilhelm Grimm gathered tales such as Hansel and Gretel from storytellers."},{"q":"The Bauhaus school, founded in 1919, taught design that joined art with what?","a":"Industry and crafts","o":["Industry and crafts","Only oil painting","Court ballet","Cathedral stonework"],"f":"Walter Gropius wanted buildings and objects that could be made for modern life. The school moved from Weimar to Dessau."},{"q":"Which of these cities is the capital of Germany?","a":"Berlin","o":["Berlin","Munich","Hamburg","Cologne"],"f":"Berlin is the capital of Germany.","kind":"capital"},{"q":"Which flag is the flag of Germany?","a":"DEU","o":["DEU","BEL","LBN","ZAF"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Germany.","kind":"flag"}]}},{"id":"DJI","name":"Djibouti","cont":"Africa","emoji":"🇩🇯","latlng":[11.5,43],"q":{"easy":[{"q":"Which strait between Djibouti and Yemen links the Red Sea to the Gulf of Aden?","a":"Bab el-Mandeb","o":["Bab el-Mandeb","The Bosphorus","The Strait of Gibraltar","The Malacca Strait"],"f":"Bab el-Mandeb means gate of tears. A huge share of world shipping passes through it."},{"q":"Which spiced rice with lamb is a feast dish in Djibouti?","a":"Skoudehkaris","o":["Skoudehkaris","Sushi","Poutine","Ceviche"],"f":"Skoudehkaris is rice cooked with lamb, tomatoes, and spices, close to a pilaf."},{"q":"Lake Assal, in the Afar depression, is famous for being very low and very what?","a":"Salty","o":["Salty","Icy","Fresh","Acidic only"],"f":"Lake Assal sits below sea level and is one of the saltiest lakes on Earth. Salt is still cut from its shores."},{"q":"Which city is the capital of Djibouti?","a":"Djibouti","o":["Djibouti","San José","Chișinău","Athens"],"f":"Djibouti is the capital of Djibouti.","kind":"capital"},{"q":"Which flag belongs to Djibouti?","a":"DJI","o":["DJI","TTO","VNM","RUS"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Djibouti.","kind":"flag"}],"medium":[{"q":"In the northern winter, large spotted fish gather to feed in the Gulf of Tadjoura. They strain food from the water and do not hunt people. What are they?","a":"Whale sharks","o":["Whale sharks","Great white sharks","Nile perch","Atlantic salmon"],"f":"The gulf is one of the few places swimmers regularly see them. Great whites are not this gathering. Nile perch are a freshwater fish of the African lakes, and salmon do not run here."},{"q":"Lake Assal, in the Afar depression, is the lowest point in Africa. Its surface sits about how far below sea level?","a":"About 155 meters","o":["About 155 meters","About 15 meters","About 1,550 meters","Level with the sea"],"f":"Salt is cut from the shore in slabs. The lake lies where plates are pulling apart. The Dead Sea is lower, but it is not on this continent."},{"q":"The territory became independent from France in which year?","a":"1977","o":["1977","1960","1967","1993"],"f":"Hassan Gouled Aptidon became the first president. France had called the colony French Somaliland, and later the French Territory of the Afars and the Issas."},{"q":"What is the capital city of Djibouti?","a":"Djibouti","o":["Djibouti","Moroni","Libreville","Harare"],"f":"Djibouti is the capital of Djibouti.","kind":"capital"},{"q":"Which of these flags belongs to Djibouti?","a":"DJI","o":["DJI","LBY","AGO","COM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Djibouti.","kind":"flag"}],"hard":[{"q":"The Afar people herd in the depression and are known for which traditional curved knife?","a":"The jile","o":["The jile","The kukri","The machete of the pampas","The katana"],"f":"The jile is a double-edged dagger carried by Afar men. It is both a tool and a mark of status."},{"q":"Which ancient seafarers of the Red Sea traded incense through ports near today's Djibouti?","a":"South Arabian and Aksumite traders","o":["South Arabian and Aksumite traders","The Vikings","The Inca","The Maori"],"f":"Obsidian and incense moved across the Bab el-Mandeb long before modern ports."},{"q":"The Goda Mountains catch rare mist that supports which forest, a patch of green above the desert?","a":"The Day Forest","o":["The Day Forest","The Black Forest","The Taiga","The Amazon"],"f":"The Day Forest, or Forêt du Day, is a highland woodland of juniper surviving in a dry country."},{"q":"Which of these cities is the capital of Djibouti?","a":"Djibouti","o":["Djibouti","Ali Sabieh","Tadjoura","Obock"],"f":"Djibouti is the capital of Djibouti.","kind":"capital"},{"q":"Which flag is the flag of Djibouti?","a":"DJI","o":["DJI","FRA","FIN","VCT"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Djibouti.","kind":"flag"}]}},{"id":"DMA","name":"Dominica","cont":"North America","emoji":"🇩🇲","latlng":[15.41666666,-61.33333333],"q":{"easy":[{"q":"Which boiling lake in the national park is a flooded fumarole?","a":"The Boiling Lake","o":["The Boiling Lake","The Champagne Pool","Yellowstone's Prismatic","Irazu"],"f":"The Boiling Lake sits in Morne Trois Pitons park. Hikers reach it on a long mountain walk."},{"q":"Which banana export and a dish of saltfish and mountain chicken once fed the island?","a":"Provisions and saltfish","o":["Provisions and saltfish","Ackee","Fungee","Cou-cou"],"f":"Dasheen, green banana, and salt cod are the old plate. The mountain chicken is a large frog, now endangered."},{"q":"Which street festival of sensay costumes is the island's big party?","a":"Carnival","o":["Carnival","Crop Over","Junkanoo","Mash"],"f":"Dominica's carnival uses sensay costumes of layered cloth and a strong creole music scene."},{"q":"Which city is the capital of Dominica?","a":"Roseau","o":["Roseau","Djibouti","Beirut","Bangui"],"f":"Roseau is the capital of Dominica.","kind":"capital"},{"q":"Which flag belongs to Dominica?","a":"DMA","o":["DMA","QAT","FRA","LTU"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Dominica.","kind":"flag"}],"medium":[{"q":"Which novelist, born in Roseau, retold Jane Eyre from the Caribbean in Wide Sargasso Sea?","a":"Jean Rhys","o":["Jean Rhys","Derek Walcott","Jamaica Kincaid","V. S. Naipaul"],"f":"She left Dominica as a teenager and wrote the novel decades later, in 1966. It gives a history and a voice to Mr. Rochester's first wife."},{"q":"High in Morne Trois Pitons National Park, Dominica's Boiling Lake is a flooded volcanic vent famous for water that does what?","a":"It steams and churns from volcanic heat","o":["It steams and churns from volcanic heat","It freezes in midsummer","It glows from fireflies","It turns solid salt"],"f":"The lake sits in a volcanic crater and is one of the largest boiling lakes on Earth. Landslides have emptied and refilled it more than once."},{"q":"The sisserou, or imperial amazon, is a large parrot found in the wild only in Dominica. What is unusual about its home range?","a":"It is endemic to this one island","o":["It is endemic to this one island","It migrates to Antarctica","It lives only in deserts","It nests on glaciers"],"f":"Habitat loss and hurricanes have made it endangered. It appears beside the flag's design, but the bird itself is the national symbol."},{"q":"What is the capital city of Dominica?","a":"Roseau","o":["Roseau","San José","Washington, D.C.","Kingstown"],"f":"Roseau is the capital of Dominica.","kind":"capital"},{"q":"Which of these flags belongs to Dominica?","a":"DMA","o":["DMA","HTI","BLZ","HND"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Dominica.","kind":"flag"}],"hard":[{"q":"Which writer and politician published the novel The Orchid House?","a":"Phyllis Shand Allfrey","o":["Phyllis Shand Allfrey","Jean Rhys","Jamaica Kincaid","Paule Marshall"],"f":"She was born in Dominica in 1908 and co-founded a labour party. The Orchid House appeared in 1953."},{"q":"The Kalinago Territory on the east coast is a reserve of which indigenous people?","a":"The Kalinago, once called Caribs","o":["The Kalinago, once called Caribs","The Taino only","The Maya","The Garifuna"],"f":"The Kalinago kept a territory after colonization. Basketwork and a steep coastline mark the area."},{"q":"Which endemic parrot, the sisserou, is a national symbol?","a":"The imperial amazon","o":["The imperial amazon","The St. Vincent parrot","The St. Lucia parrot","The kea"],"f":"The sisserou lives in the high forest and is endangered. It appears on the flag."},{"q":"Which of these cities is the capital of Dominica?","a":"Roseau","o":["Roseau","Portsmouth","Marigot","Soufrière"],"f":"Roseau is the capital of Dominica.","kind":"capital"},{"q":"Which flag is the flag of Dominica?","a":"DMA","o":["DMA","VNM","GMB","TLS"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Dominica.","kind":"flag"}]}},{"id":"DNK","name":"Denmark","cont":"Europe","emoji":"🇩🇰","latlng":[56,10],"q":{"easy":[{"q":"Which gardens and rides opened in the capital in 1843 and still run?","a":"Tivoli Gardens","o":["Tivoli Gardens","Disneyland","The Prater","Efteling"],"f":"Tivoli inspired later amusement parks. It sits beside the city hall, with lamps and old rides."},{"q":"Which open-faced rye sandwiches are a classic lunch?","a":"Smorrebrod","o":["Smorrebrod","Sushi","Tapas","Meze"],"f":"Smorrebrod is buttered rye piled with herring, egg, or beef. It is eaten with a knife and fork."},{"q":"Which Viking ships were recovered from Roskilde fjord and are shown in a museum there?","a":"The Skuldelev ships","o":["The Skuldelev ships","The Vasa","The Mary Rose","The Kon-Tiki"],"f":"The five Skuldelev ships were scuttled to block a channel. They include a warship and a trader."},{"q":"Which city is the capital of Denmark?","a":"Copenhagen","o":["Copenhagen","Ashgabat","Kuala Lumpur","Lusaka"],"f":"Copenhagen is the capital of Denmark.","kind":"capital"},{"q":"Which flag belongs to Denmark?","a":"DNK","o":["DNK","MRT","IRN","PNG"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Denmark.","kind":"flag"}],"medium":[{"q":"Which physicist, born in Copenhagen, pictured electrons in set orbits around the nucleus?","a":"Niels Bohr","o":["Niels Bohr","Ernest Rutherford","Marie Curie","Enrico Fermi"],"f":"His 1913 model built on Rutherford's discovery of the nucleus. He later helped scientists flee the Nazi occupation and escaped to Sweden himself."},{"q":"A Billund carpenter coined a company name in 1934 from words meaning play well. What is the company?","a":"LEGO","o":["LEGO","BRIO","Playmobil","Duplo"],"f":"Ole Kirk Christiansen started with wooden toys in 1932. The familiar brick that locks onto the one below was patented in 1958. Duplo is a LEGO product, not a rival firm."},{"q":"Which writer, born in Odense, published The Little Mermaid and The Emperor's New Clothes?","a":"Hans Christian Andersen","o":["Hans Christian Andersen","The Brothers Grimm","Charles Perrault","Soren Kierkegaard"],"f":"The Grimms collected German folk tales, and Perrault wrote earlier French ones. Kierkegaard, another Dane, wrote philosophy, not fairy tales."},{"q":"What is the capital city of Denmark?","a":"Copenhagen","o":["Copenhagen","Moscow","Sofia","Tallinn"],"f":"Copenhagen is the capital of Denmark.","kind":"capital"},{"q":"Which of these flags belongs to Denmark?","a":"DNK","o":["DNK","ROU","IRL","EST"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Denmark.","kind":"flag"}],"hard":[{"q":"Which philosopher of existentialism wrote Either/Or and was born in Copenhagen?","a":"Soren Kierkegaard","o":["Soren Kierkegaard","Sartre","Nietzsche","Camus"],"f":"Kierkegaard published Either/Or in 1843. He walked the city and wrote under many pen names."},{"q":"The Jelling stones, raised by Harald Bluetooth, mix which two traditions?","a":"Norse runes and a Christian cross","o":["Norse runes and a Christian cross","Hieroglyphs and Greek","Glagolitic and Latin","Maya and Spanish"],"f":"Harald's stone boasts that he made the Danes Christian. It is often called Denmark's birth certificate."},{"q":"Which white cheese of the islands is washed with a mold and sold as a national export?","a":"Danablu","o":["Danablu","Cheddar","Feta","Brie"],"f":"Danablu is a blue cheese created in the 20th century as a local answer to Roquefort."},{"q":"Which of these cities is the capital of Denmark?","a":"Copenhagen","o":["Copenhagen","Aarhus","Odense","Aalborg"],"f":"Copenhagen is the capital of Denmark.","kind":"capital"},{"q":"Which flag is the flag of Denmark?","a":"DNK","o":["DNK","ISL","SWE","NOR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Denmark.","kind":"flag"}]}},{"id":"DOM","name":"Dominican Republic","cont":"North America","emoji":"🇩🇴","latlng":[19,-70.66666666],"q":{"easy":[{"q":"Which colonial zone of stone palaces is a UNESCO old city on the Ozama River?","a":"The Colonial Zone","o":["The Colonial Zone","The Malecon of Havana","Old San Juan","Cartagena"],"f":"Santo Domingo's colonial city includes the first cathedral of the Americas, begun in the early 1500s."},{"q":"Which mashed green plantain is a breakfast staple?","a":"Mangu","o":["Mangu","Mofongo","Tostones","Fufu"],"f":"Mangu is boiled green plantain mashed with butter. Eggs and salami often come alongside."},{"q":"Which amber from the mountains, sometimes holding insects, is a famous gem?","a":"Dominican amber","o":["Dominican amber","Baltic amber","Copal","Jet"],"f":"The amber is fossil resin of an extinct tree. The blue variety is especially prized."},{"q":"Which city is the capital of Dominican Republic?","a":"Santo Domingo","o":["Santo Domingo","Vatican City","Ashgabat","Kabul"],"f":"Santo Domingo is the capital of Dominican Republic.","kind":"capital"},{"q":"Which flag belongs to Dominican Republic?","a":"DOM","o":["DOM","FSM","NPL","GNQ"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Dominican Republic.","kind":"flag"}],"medium":[{"q":"Which of the country's founders, born in Santo Domingo, led the 1844 movement that separated the nation from Haitian rule?","a":"Juan Pablo Duarte","o":["Juan Pablo Duarte","Simon Bolivar","Jose Marti","Toussaint Louverture"],"f":"Duarte, Francisco del Rosario Sanchez, and Matias Ramon Mella are remembered as the trinity of independence. Duarte spent much of his later life in exile."},{"q":"Pico Duarte, in the Cordillera Central, holds which geographic title in the Caribbean?","a":"The highest peak","o":["The highest peak","The deepest cave","The longest river","The largest desert"],"f":"It rises about 3,098 meters. Older maps called it Pico Trujillo, after a dictator, before the name Duarte was restored."},{"q":"Santo Domingo's colonial zone contains the oldest cathedral and the oldest university in which region?","a":"The Americas","o":["The Americas","Polynesia","Scandinavia","The Sahara"],"f":"The Spanish founded the city in 1496, the first lasting European settlement in the Americas. The Cathedral of Santa Maria la Menor was begun in 1512."},{"q":"What is the capital city of Dominican Republic?","a":"Santo Domingo","o":["Santo Domingo","San José","Nassau","Panama City"],"f":"Santo Domingo is the capital of Dominican Republic.","kind":"capital"},{"q":"Which of these flags belongs to Dominican Republic?","a":"DOM","o":["DOM","BHS","USA","MEX"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Dominican Republic.","kind":"flag"}],"hard":[{"q":"Which three sisters, killed in 1960 for opposing a dictatorship, are national heroes?","a":"The Mirabal sisters","o":["The Mirabal sisters","The Sanchez family","The Duarte brothers","The Trujillo daughters"],"f":"Patria, Minerva, and Maria Teresa Mirabal opposed the Trujillo dictatorship. Their deaths helped end it."},{"q":"Merengue, the national dance, is driven by which scraped drum?","a":"The guira","o":["The guira","The conga","The tambora only","The bongo"],"f":"A guira's metal cylinder is scraped with a brush. The tambora drum and an accordion complete the trio."},{"q":"Pico Duarte, the highest peak in the Caribbean, stands in which range?","a":"The Cordillera Central","o":["The Cordillera Central","The Sierra de Bahoruco","The Blue Mountains","The Pitons"],"f":"The mountain rises above 3,000 meters. Hikers approach from Jarabacoa or the high plains."},{"q":"Which of these cities is the capital of Dominican Republic?","a":"Santo Domingo","o":["Santo Domingo","Santiago de los Caballeros","Puerto Plata","La Romana"],"f":"Santo Domingo is the capital of Dominican Republic.","kind":"capital"},{"q":"Which flag is the flag of Dominican Republic?","a":"DOM","o":["DOM","NIC","TKM","MWI"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Dominican Republic.","kind":"flag"}]}},{"id":"DZA","name":"Algeria","cont":"Africa","emoji":"🇩🇿","latlng":[28,3],"q":{"easy":[{"q":"Which old fortified city of Ottoman houses above the port of Algiers is a UNESCO site?","a":"The Casbah of Algiers","o":["The Casbah of Algiers","The Medina of Fes","Stone Town","Mdina"],"f":"The Casbah is a maze of white houses, fountains, and mosques over the bay."},{"q":"Which steamed semolina, served with stew, is everyday food in Algeria?","a":"Couscous","o":["Couscous","Sushi","Arepa","Poutine"],"f":"Couscous is rolled and steamed, then covered with vegetables and meat. It is shared across the Maghreb."},{"q":"Which Roman city in the Aures region still shows a street grid and a triumphal arch?","a":"Timgad","o":["Timgad","Pompeii","Ephesus","Petra"],"f":"Timgad was founded around the year 100. Sand later buried it and kept the plan clear."},{"q":"Which city is the capital of Algeria?","a":"Algiers","o":["Algiers","Santiago","Ljubljana","Bandar Seri Begawan"],"f":"Algiers is the capital of Algeria.","kind":"capital"},{"q":"Which flag belongs to Algeria?","a":"DZA","o":["DZA","LTU","TON","LVA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Algeria.","kind":"flag"}],"medium":[{"q":"Which bishop and philosopher, author of the Confessions, was born in 354 at Thagaste, now Souk Ahras?","a":"Augustine of Hippo","o":["Augustine of Hippo","Tertullian","Cyprian of Carthage","Athanasius"],"f":"He later served as bishop of Hippo, now Annaba, on this same coast. Tertullian and Cyprian belonged to Carthage, in present-day Tunisia. Athanasius was an Egyptian bishop."},{"q":"The Roman grid city of Timgad, a UNESCO site, was founded around the year 100 under which emperor?","a":"Trajan","o":["Trajan","Augustus","Constantine","Justinian"],"f":"Its formal name was Colonia Marciana Traiana Thamugadi. The arch, forum, and library can still be read in the plan. Constantine and Justinian lived centuries later."},{"q":"A popular music of Oran, mixing older local song with Spanish and cabaret influences, is called what?","a":"Raï","o":["Raï","Gnawa","Chaabi","Andalusian nuba"],"f":"Cheikha Rimitti was a pioneer, and Khaled carried the style worldwide late in the 20th century. Gnawa is a Moroccan trance music. Chaabi and the Andalusian nuba are older urban traditions of the Maghreb."},{"q":"What is the capital city of Algeria?","a":"Algiers","o":["Algiers","Maseru","Conakry","Pretoria"],"f":"Algiers is the capital of Algeria.","kind":"capital"},{"q":"Which of these flags belongs to Algeria?","a":"DZA","o":["DZA","CMR","NAM","CAF"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Algeria.","kind":"flag"}],"hard":[{"q":"The Qalaa of the Beni Hammad, now a mountain ruin, was a capital of which medieval dynasty?","a":"The Hammadids","o":["The Hammadids","The Incas","The Plantagenets","The Tokugawa"],"f":"The Hammadids broke from the Zirids in the 11th century and built a fortified palace city."},{"q":"Rai singers of Oran turned a folk style into protest pop. The city is a port on which sea?","a":"The Mediterranean","o":["The Mediterranean","The Caribbean","The Baltic","The Coral Sea"],"f":"Oran faces Spain across the western Mediterranean. Its clubs shaped modern rai."},{"q":"Tuareg silversmiths of the Sahara set jewelry with which red stone?","a":"Carnelian","o":["Carnelian","Jade","Opal","Amber"],"f":"Silver crosses and necklaces often hold carnelian or coral. Indigo veils are another Saharan mark."},{"q":"Which of these cities is the capital of Algeria?","a":"Algiers","o":["Algiers","Oran","Constantine","Annaba"],"f":"Algiers is the capital of Algeria.","kind":"capital"},{"q":"Which flag is the flag of Algeria?","a":"DZA","o":["DZA","PAK","TUN","TUR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Algeria.","kind":"flag"}]}},{"id":"ECU","name":"Ecuador","cont":"South America","emoji":"🇪🇨","latlng":[-2,-77.5],"q":{"easy":[{"q":"Which snow-capped volcano near the historic center is a famous climb?","a":"Cotopaxi","o":["Cotopaxi","Chimborazo","Cayambe","Antisana"],"f":"Cotopaxi is an active volcano in the Andes. Its cone is one of the classic climbs of the highlands."},{"q":"Which potato soup and a fish soup of the coast are home comforts?","a":"Locro and encebollado","o":["Locro and encebollado","Ceviche only","Cuy only","Seco de chivo"],"f":"Locro is a thick potato and cheese soup. Encebollado is an onion and tuna soup eaten for breakfast on the coast."},{"q":"Which islands of giant tortoises, visited by Darwin, belong to the country?","a":"The Galapagos","o":["The Galapagos","The Juan Fernandez","Easter Island","The Revillagigedo"],"f":"The Galapagos lie about 1,000 kilometers offshore. Their finches helped Darwin think about how species change."},{"q":"Which city is the capital of Ecuador?","a":"Quito","o":["Quito","Yaoundé","Bissau","Kingston"],"f":"Quito is the capital of Ecuador.","kind":"capital"},{"q":"Which flag belongs to Ecuador?","a":"ECU","o":["ECU","PSE","GTM","KOR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Ecuador.","kind":"flag"}],"medium":[{"q":"Which painter, born in Quito, became famous for anguished murals of Indigenous and mestizo suffering?","a":"Oswaldo Guayasamin","o":["Oswaldo Guayasamin","Diego Rivera","Frida Kahlo","Fernando Botero"],"f":"His series The Age of Anger responded to violence in the Americas. Botero, a tempting wrong answer, was Colombian and painted rounded figures."},{"q":"Darwin's observations of finches and tortoises in which Ecuadorian island group later supported his theory of evolution?","a":"The Galapagos Islands","o":["The Galapagos Islands","The Juan Fernandez Islands","The Falkland Islands","The Canary Islands"],"f":"He visited in 1835 aboard HMS Beagle. The islands' isolation had produced species found nowhere else."},{"q":"The straw hats that traders misnamed Panama hats are woven in towns such as Montecristi from the leaves of which plant?","a":"The toquilla palm","o":["The toquilla palm","The coconut palm","Esparto grass","The papyrus reed"],"f":"Merchants shipped the hats through Panama to gold-rush travelers and canal workers, so the wrong country's name stuck."},{"q":"What is the capital city of Ecuador?","a":"Quito","o":["Quito","Georgetown","Brasília","Bogotá"],"f":"Quito is the capital of Ecuador.","kind":"capital"},{"q":"Which of these flags belongs to Ecuador?","a":"ECU","o":["ECU","BRA","CHL","BOL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Ecuador.","kind":"flag"}],"hard":[{"q":"Which Panama-hat fiber, the toquilla palm, is woven in the coast and the highlands?","a":"Toquilla straw","o":["Toquilla straw","Cotton","Wool","Silk"],"f":"Montecristi and Cuenca are weaving centers. The hats were shipped through Panama and misnamed."},{"q":"The Inca road reached which highland city of Inca stones and churches?","a":"Cuenca","o":["Cuenca","Ingapirca","Quito","Loja"],"f":"Ingapirca, nearby, is the best-preserved Inca ruin in the country. Cuenca was a Cañari and then a Spanish city."},{"q":"Which race walker from Cuenca won Olympic gold in the 20-kilometer walk in 1996?","a":"Jefferson Perez","o":["Jefferson Perez","Haile Gebrselassie","Eliud Kipchoge","Abebe Bikila"],"f":"The Atlanta gold was the country's first Olympic title. Perez later won a world championship and an Olympic silver."},{"q":"Which of these cities is the capital of Ecuador?","a":"Quito","o":["Quito","Guayaquil","Cuenca","Manta"],"f":"Quito is the capital of Ecuador.","kind":"capital"},{"q":"Which flag is the flag of Ecuador?","a":"ECU","o":["ECU","COL","VEN","BIH"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Ecuador.","kind":"flag"}]}},{"id":"EGY","name":"Egypt","cont":"Africa","emoji":"🇪🇬","latlng":[27,30],"q":{"easy":[{"q":"Which ancient stone tombs at Giza include the last surviving wonder of the ancient world?","a":"The pyramids","o":["The pyramids","The Colosseum","The Great Wall","Machu Picchu"],"f":"The Great Pyramid was built for Khufu. Nearby sit the pyramids of Khafre and Menkaure and the Great Sphinx."},{"q":"Which street dish of rice, lentils, pasta, and tomato sauce is a Cairo favorite?","a":"Koshari","o":["Koshari","Sushi","Poutine","Paella"],"f":"Koshari mixes cheap staples into one bowl and is sold from big pots all over the city."},{"q":"Which boy king, whose tomb was found in 1922, is the most famous pharaoh to modern visitors?","a":"Tutankhamun","o":["Tutankhamun","Alexander","Julius Caesar","Charlemagne"],"f":"Howard Carter found Tutankhamun's tomb in the Valley of the Kings. The gold mask became a world icon."},{"q":"Which city is the capital of Egypt?","a":"Cairo","o":["Cairo","Oslo","Ottawa","Basseterre"],"f":"Cairo is the capital of Egypt.","kind":"capital"},{"q":"Which flag belongs to Egypt?","a":"EGY","o":["EGY","LCA","SUR","SMR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Egypt.","kind":"flag"}],"medium":[{"q":"Which novelist, born in Cairo, won the Nobel Prize in Literature in 1988?","a":"Naguib Mahfouz","o":["Naguib Mahfouz","Taha Hussein","Nawal El Saadawi","Tawfiq al-Hakim"],"f":"The Cairo Trilogy follows one family through the old city. Hussein, El Saadawi, and al-Hakim are major writers from this country who did not receive that prize."},{"q":"The temples of Abu Simbel were cut apart and rebuilt on higher ground in the 1960s to escape the lake of which dam?","a":"The Aswan High Dam","o":["The Aswan High Dam","The Hoover Dam","The Three Gorges Dam","The Itaipu Dam"],"f":"UNESCO led an international rescue. Ramses II had the temples carved in the 13th century BCE. The lake behind the dam is Lake Nasser."},{"q":"A stone found at Rashid in 1799 repeated one decree in three scripts and unlocked hieroglyphs. What is it called?","a":"The Rosetta Stone","o":["The Rosetta Stone","The Behistun Inscription","The Mesha Stele","The Palermo Stone"],"f":"Champollion announced the decipherment in 1822. Behistun, in Iran, did the same job for cuneiform. The stone is named for Rashid's European name, Rosetta."},{"q":"What is the capital city of Egypt?","a":"Cairo","o":["Cairo","Porto-Novo","Pretoria","São Tomé"],"f":"Cairo is the capital of Egypt.","kind":"capital"},{"q":"Which of these flags belongs to Egypt?","a":"EGY","o":["EGY","CPV","GNB","UGA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Egypt.","kind":"flag"}],"hard":[{"q":"The Rosetta Stone, carved in three scripts, let scholars read which writing?","a":"Hieroglyphs","o":["Hieroglyphs","Cuneiform","Runes","Maya glyphs"],"f":"The same decree appears in hieroglyphs, Demotic, and Greek. Champollion used it to decipher the picture-script."},{"q":"Which medieval mosque and university in Cairo, founded in the 900s, is a center of Sunni learning?","a":"Al-Azhar","o":["Al-Azhar","The Sorbonne","Oxford","Nalanda"],"f":"Al-Azhar University grew from a Fatimid mosque. Students still come from across the Muslim world."},{"q":"Feluccas, the traditional sailboats of the Nile, use what kind of sail?","a":"A triangular lateen sail","o":["A triangular lateen sail","A square Viking sail","A steam paddle","A rotor sail"],"f":"The lateen sail lets a felucca work upriver against a light wind. The design is very old on the Nile."},{"q":"Which of these cities is the capital of Egypt?","a":"Cairo","o":["Cairo","Alexandria","Luxor","Aswan"],"f":"Cairo is the capital of Egypt.","kind":"capital"},{"q":"Which flag is the flag of Egypt?","a":"EGY","o":["EGY","IRQ","YEM","SYR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Egypt.","kind":"flag"}]}},{"id":"ERI","name":"Eritrea","cont":"Africa","emoji":"🇪🇷","latlng":[15,39],"q":{"easy":[{"q":"Which old port has a waterfront of Ottoman houses and later Italian buildings?","a":"Massawa","o":["Massawa","Assab","Aden","Berbera"],"f":"Massawa was a Red Sea trading port for centuries. Much of the old town was damaged in the independence war and later repaired."},{"q":"Which sour flatbread, shared with the highlands next door, is eaten daily in Eritrea?","a":"Injera","o":["Injera","Tortilla","Naan","Crepe"],"f":"Injera is a spongy teff or wheat bread. Stews called tsebhi are spooned on top."},{"q":"The Dahlak Archipelago offshore is known for what?","a":"Coral reefs and pearl history","o":["Coral reefs and pearl history","Ski resorts","Glacier caves","Vineyards"],"f":"The Dahlak islands have reefs, old cisterns, and a past of pearl diving."},{"q":"Which city is the capital of Eritrea?","a":"Asmara","o":["Asmara","Baghdad","Minsk","Reykjavík"],"f":"Asmara is the capital of Eritrea.","kind":"capital"},{"q":"Which flag belongs to Eritrea?","a":"ERI","o":["ERI","VCT","LAO","ROU"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Eritrea.","kind":"flag"}],"medium":[{"q":"Asmara's center, a UNESCO site, is preserved as a showcase of which 20th-century building style?","a":"Italian modernism","o":["Italian modernism","Ottoman wooden houses","Mughal marble tombs","Mud-brick mosques of the Sahel"],"f":"Italy occupied the highlands from the 1890s and built the city as a display, nicknamed little Rome. Cinemas, villas, and a Fiat garage are part of the listing."},{"q":"After a long war, a referendum confirmed independence from Ethiopia in which year?","a":"1993","o":["1993","1941","1974","2018"],"f":"Fighters had already taken Asmara in 1991. The 1993 vote made independence formal. 1941 ended Italy's short occupation of Ethiopia, a different date."},{"q":"The country's name comes from the Greek name for which sea on its coast?","a":"The Red Sea","o":["The Red Sea","The Black Sea","The Dead Sea","The Caspian"],"f":"Erythra means red. Italian mapmakers reused the old Greek name for this shore. The Dead Sea and the Caspian are basins far from here."},{"q":"What is the capital city of Eritrea?","a":"Asmara","o":["Asmara","Addis Ababa","Antananarivo","Algiers"],"f":"Asmara is the capital of Eritrea.","kind":"capital"},{"q":"Which of these flags belongs to Eritrea?","a":"ERI","o":["ERI","LBR","BEN","NER"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Eritrea.","kind":"flag"}],"hard":[{"q":"Which ancient liturgical language is still chanted in church but is no longer everyday speech?","a":"Ge'ez","o":["Ge'ez","Latin","Coptic","Syriac"],"f":"Ge'ez survives in the liturgy of the highland church. Priests learn it as a sacred language."},{"q":"Which monastery tradition of the Eritrean highlands uses Ge'ez, an ancient liturgical language?","a":"The Orthodox Church","o":["The Orthodox Church","Shinto","Lutheran only","Norse paganism"],"f":"Ge'ez is no longer an everyday spoken language, but priests still chant it in the liturgy."},{"q":"The railway from Massawa up to the highlands is famous for which feat?","a":"A steep climb of switchbacks","o":["A steep climb of switchbacks","A tunnel under the sea","A maglev line","A canal lock"],"f":"Italian engineers built a mountain railway that rises from the hot coast to the cool plateau."},{"q":"Which of these cities is the capital of Eritrea?","a":"Asmara","o":["Asmara","Keren","Massawa","Assab"],"f":"Asmara is the capital of Eritrea.","kind":"capital"},{"q":"Which flag is the flag of Eritrea?","a":"ERI","o":["ERI","SSD","RUS","GIN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Eritrea.","kind":"flag"}]}},{"id":"ESP","name":"Spain","cont":"Europe","emoji":"🇪🇸","latlng":[40,-4],"q":{"easy":[{"q":"Which unfinished basilica of towers and biblical stone in Barcelona was designed by Gaudi?","a":"The Sagrada Familia","o":["The Sagrada Familia","The Alhambra","The Mezquita","The Prado"],"f":"Gaudi took over the church in 1883. Work has continued from his models since his death in 1926."},{"q":"Which saffron rice dish from the Valencia region is cooked in a wide pan?","a":"Paella","o":["Paella","Risotto","Jambalaya","Biryani"],"f":"Paella began as a countryside meal of rice, beans, and rabbit or chicken. Seafood versions are now famous."},{"q":"Which novelist created Don Quixote in the early 1600s?","a":"Miguel de Cervantes","o":["Miguel de Cervantes","Lope de Vega","Shakespeare","Dante"],"f":"Don Quixote was published in two parts, 1605 and 1615. It is often called the first modern novel."},{"q":"Which city is the capital of Spain?","a":"Madrid","o":["Madrid","Nassau","Tripoli","Lomé"],"f":"Madrid is the capital of Spain.","kind":"capital"},{"q":"Which flag belongs to Spain?","a":"ESP","o":["ESP","URY","CAN","SSD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Spain.","kind":"flag"}],"medium":[{"q":"Which doctor, born in Petilla de Aragon, shared the 1906 Nobel Prize for showing that the nervous system is made of separate cells?","a":"Santiago Ramon y Cajal","o":["Santiago Ramon y Cajal","Ivan Pavlov","Camillo Golgi","Sigmund Freud"],"f":"He improved Golgi's silver stain and drew neurons by hand. Golgi, who shared the prize, still argued that nerves formed a continuous net."},{"q":"The Alhambra in Granada was the palace of the last Muslim dynasty in Spain. Which dynasty?","a":"The Nasrids","o":["The Nasrids","The Umayyads of Cordoba","The Almohads","The Abbasids"],"f":"Its courtyards, especially the Court of the Lions, use water and carved stucco rather than huge statues. Granada fell to Ferdinand and Isabella in 1492."},{"q":"The cave of Altamira in Cantabria is famous for Ice Age paintings, especially of which animals?","a":"Bison","o":["Bison","Horses only","Whales","Camels"],"f":"When the paintings were found in the 1870s, many experts thought they were too fine to be prehistoric. They are now dated to roughly 14,000 years ago or earlier."},{"q":"What is the capital city of Spain?","a":"Madrid","o":["Madrid","Kyiv","Sofia","Vatican City"],"f":"Madrid is the capital of Spain.","kind":"capital"},{"q":"Which of these flags belongs to Spain?","a":"ESP","o":["ESP","BLR","CHE","CYP"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Spain.","kind":"flag"}],"hard":[{"q":"Which vast monastery-palace did Philip II build near Madrid in the 1500s?","a":"El Escorial","o":["El Escorial","The Alhambra","The Mezquita","The Prado"],"f":"El Escorial holds a palace, a basilica, a library, and a royal crypt. Philip II directed it from a room overlooking the chapel."},{"q":"Which pilgrimage route across the north ends at the shrine of Saint James?","a":"The Camino de Santiago","o":["The Camino de Santiago","The Via Francigena","The Kumano Kodo","The Hajj"],"f":"Walkers have followed the Camino for a thousand years. The cathedral in Santiago de Compostela holds the shrine."},{"q":"Flamenco, of Andalusia, joins the guitar with which sung form and dance?","a":"Cante and baile","o":["Cante and baile","Opera","Fado","Rebetiko"],"f":"Cante jondo is the deep song. Roma, Moorish, and local Andalusian traditions all fed the art."},{"q":"Which of these cities is the capital of Spain?","a":"Madrid","o":["Madrid","Barcelona","Seville","Valencia"],"f":"Madrid is the capital of Spain.","kind":"capital"},{"q":"Which flag is the flag of Spain?","a":"ESP","o":["ESP","FRA","NZL","GIN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Spain.","kind":"flag"}]}},{"id":"EST","name":"Estonia","cont":"Europe","emoji":"🇪🇪","latlng":[59,26],"q":{"easy":[{"q":"Which medieval old town and cathedral hill look over the Gulf of Finland?","a":"The old town of the capital region","o":["The old town of the capital region","A ski jump","A Roman forum","A mud mosque"],"f":"Limestone walls, guild houses, and Toompea castle form a UNESCO old town."},{"q":"Which dark rye loaf is on the table at almost every meal?","a":"Black rye bread","o":["Black rye bread","Baguette","Tortilla","Naan"],"f":"Estonian rye is dense and sour. It is eaten with butter, herring, or cheese."},{"q":"Which huge open-air choir gathering is held every five years?","a":"The Song Festival","o":["The Song Festival","Eurovision","The Proms","Carnival"],"f":"The Laulupidu fills a seaside stage with tens of thousands of singers. It helped carry the independence movement."},{"q":"Which city is the capital of Estonia?","a":"Tallinn","o":["Tallinn","Nairobi","Panama City","Porto-Novo"],"f":"Tallinn is the capital of Estonia.","kind":"capital"},{"q":"Which flag belongs to Estonia?","a":"EST","o":["EST","SLV","HND","SYC"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Estonia.","kind":"flag"}],"medium":[{"q":"Which composer, born in Paide, wrote spare sacred music such as Spiegel im Spiegel and Tabula Rasa?","a":"Arvo Part","o":["Arvo Part","Jean Sibelius","Edvard Grieg","Henryk Gorecki"],"f":"He calls his later style tintinnabuli, like the sound of a bell. Soviet officials had distrusted his earlier experimental work."},{"q":"The first version of Skype was programmed largely in Tallinn. It was software for what?","a":"Voice and video calls over the internet","o":["Voice and video calls over the internet","A search engine","A mobile operating system","A social photo feed"],"f":"Estonian engineers including Ahti Heinla, Priit Kasesalu, and Jaan Tallinn built it with Swedish and Danish founders. The name was a shortening of sky peer-to-peer."},{"q":"On 23 August 1989 about two million people held hands across Estonia, Latvia, and Lithuania. What was that protest called?","a":"The Baltic Way","o":["The Baltic Way","The Velvet Revolution","The Orange Revolution","The Singing Revolution"],"f":"The date marked the 1939 pact that had assigned the Baltic states to the Soviet sphere. The Singing Revolution is the wider movement of song festivals and protests around it."},{"q":"What is the capital city of Estonia?","a":"Tallinn","o":["Tallinn","Berlin","Athens","Oslo"],"f":"Tallinn is the capital of Estonia.","kind":"capital"},{"q":"Which of these flags belongs to Estonia?","a":"EST","o":["EST","SWE","NOR","BGR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Estonia.","kind":"flag"}],"hard":[{"q":"Which university, founded in 1632, is the oldest in the country?","a":"The university at Tartu","o":["The university at Tartu","Uppsala University","The University of Helsinki","Vilnius University"],"f":"King Gustavus Adolphus of Sweden founded it. It closed and reopened more than once and remains the main research university."},{"q":"Kiiking, a sport invented here, involves swinging on what?","a":"A giant metal swing","o":["A giant metal swing","A surfboard","A horse","A parallel bar"],"f":"The kiik is a rigid swing. Riders try to pass over the top in a full circle."},{"q":"Which limestone cliff on the northern coast is a symbol of the national epic?","a":"The Baltic glint","o":["The Baltic glint","The White Cliffs of Dover","The Cliffs of Moher","Etretat"],"f":"The north coast drops in a limestone escarpment. Kalevipoeg, the epic hero, is tied to these landscapes."},{"q":"Which of these cities is the capital of Estonia?","a":"Tallinn","o":["Tallinn","Tartu","Narva","Pärnu"],"f":"Tallinn is the capital of Estonia.","kind":"capital"},{"q":"Which flag is the flag of Estonia?","a":"EST","o":["EST","DMA","VEN","MLT"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Estonia.","kind":"flag"}]}},{"id":"ETH","name":"Ethiopia","cont":"Africa","emoji":"🇪🇹","latlng":[8,38],"q":{"easy":[{"q":"The fossil skeleton called Lucy, an Australopithecus, was found in 1974 in which Ethiopian region?","a":"Afar","o":["Afar","The Danube valley","Patagonia","Hokkaido"],"f":"Lucy lived about 3.2 million years ago. The Afar desert has yielded many early human fossils."},{"q":"Which drink is roasted, brewed, and poured in a long traditional ceremony in Ethiopia?","a":"Coffee","o":["Coffee","Tea","Mate","Kava"],"f":"Ethiopia is a homeland of arabica coffee. The ceremony roasts beans, burns incense, and serves three rounds."},{"q":"Which rock-hewn churches of the 12th century stand at Lalibela?","a":"Churches carved from stone","o":["Churches carved from stone","Glass cathedrals","Wooden stave churches","Ice hotels"],"f":"Lalibela's churches were cut downward out of solid rock, with trenches for courtyards and tunnels between them."},{"q":"Which city is the capital of Ethiopia?","a":"Addis Ababa","o":["Addis Ababa","Guatemala City","Dushanbe","Beirut"],"f":"Addis Ababa is the capital of Ethiopia.","kind":"capital"},{"q":"Which flag belongs to Ethiopia?","a":"ETH","o":["ETH","PRT","PRK","KIR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Ethiopia.","kind":"flag"}],"medium":[{"q":"Which runner won the Olympic marathon at Rome in 1960 while running barefoot?","a":"Abebe Bikila","o":["Abebe Bikila","Haile Gebrselassie","Kenenisa Bekele","Mamo Wolde"],"f":"He won again in Tokyo in 1964, that time in shoes, weeks after an appendix operation. Gebrselassie and Bekele were later stars. Wolde won the marathon in 1968."},{"q":"The churches of Lalibela were not built up from blocks. How were they made?","a":"Carved downward out of solid rock","o":["Carved downward out of solid rock","Cast in concrete","Assembled from imported marble","Woven from reeds"],"f":"King Lalibela, in the 12th or 13th century, is credited with the eleven churches. A stream named Jordan runs among them. Pilgrims still use them."},{"q":"In 1896 an army led by Menelik II and Taytu defeated Italy and stopped a colonial conquest. Which battle was it?","a":"The Battle of Adwa","o":["The Battle of Adwa","The Battle of Magdala","The Battle of Isandlwana","The Battle of Omdurman"],"f":"Italy did occupy the country later, from 1936 to 1941, but 1896 kept it independent through the Scramble. Isandlwana was a Zulu victory, and Omdurman was fought in Sudan."},{"q":"What is the capital city of Ethiopia?","a":"Addis Ababa","o":["Addis Ababa","Brazzaville","Mogadishu","Yamoussoukro"],"f":"Addis Ababa is the capital of Ethiopia.","kind":"capital"},{"q":"Which of these flags belongs to Ethiopia?","a":"ETH","o":["ETH","NAM","SDN","SSD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Ethiopia.","kind":"flag"}],"hard":[{"q":"At the Battle of Adwa in 1896, Ethiopian forces defeated an invading army from which country?","a":"Italy","o":["Italy","Britain","France","Portugal"],"f":"Adwa kept Ethiopia independent during the scramble for Africa. It is a national holiday."},{"q":"Which calendar, still used for many religious dates, runs about seven or eight years behind the Gregorian one?","a":"A 13-month calendar","o":["A 13-month calendar","The Maya long count","The French republican calendar","The Julian calendar only in Russia"],"f":"New Year in Ethiopia falls in September. The calendar has 13 months."},{"q":"The Ark of the Covenant is claimed, in national tradition, to rest in a chapel in which city?","a":"Aksum","o":["Aksum","Lalibela","Gondar","Harar"],"f":"A single monk is said to watch the chapel at Aksum. Historians treat the claim as tradition, not a proven find."},{"q":"Which of these cities is the capital of Ethiopia?","a":"Addis Ababa","o":["Addis Ababa","Dire Dawa","Gondar","Mekelle"],"f":"Addis Ababa is the capital of Ethiopia.","kind":"capital"},{"q":"Which flag is the flag of Ethiopia?","a":"ETH","o":["ETH","MYS","DMA","CRI"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Ethiopia.","kind":"flag"}]}},{"id":"FIN","name":"Finland","cont":"Europe","emoji":"🇫🇮","latlng":[64,26],"q":{"easy":[{"q":"Which steam bath, often by a lake, is a weekly ritual for many families?","a":"The sauna","o":["The sauna","The hammam","The onsen","The banya only"],"f":"Finland has millions of saunas. People steam, then cool off in a lake or a snowbank."},{"q":"Which rice porridge pasty from the east is a common cafe snack?","a":"The Karelian pasty","o":["The Karelian pasty","Sushi","Empanada","Pirogi"],"f":"A rye crust holds rice or potato. Egg butter is spread on top."},{"q":"Which composer wrote the tone poem Finlandia in 1899?","a":"Jean Sibelius","o":["Jean Sibelius","Grieg","Nielsen","Smetana"],"f":"Finlandia became an unofficial anthem under Russian rule. Sibelius is the country's best-known composer."},{"q":"Which city is the capital of Finland?","a":"Helsinki","o":["Helsinki","Tunis","Phnom Penh","Sana'a"],"f":"Helsinki is the capital of Finland.","kind":"capital"},{"q":"Which flag belongs to Finland?","a":"FIN","o":["FIN","OMN","ETH","LBR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Finland.","kind":"flag"}],"medium":[{"q":"Which illustrator and writer, born in Helsinki, created the Moomins?","a":"Tove Jansson","o":["Tove Jansson","Astrid Lindgren","Hans Christian Andersen","Elsa Beskow"],"f":"The first Moomin book appeared in 1945. Jansson later wrote darker fiction for adults, including The Summer Book."},{"q":"Linus Torvalds, born in Helsinki, released the first version of Linux in 1991. Linux is what?","a":"An operating-system kernel","o":["An operating-system kernel","A web browser","A programming language","A search engine"],"f":"He posted it for free and invited others to improve it. It now runs most of the world's supercomputers and a huge share of phones, through Android."},{"q":"The word sauna is Finnish. A traditional smoke sauna is heated by a stove full of stones and has what unusual feature?","a":"No chimney, so smoke fills the room","o":["No chimney, so smoke fills the room","A floor of ice","A pool of seawater inside","Electric lights only"],"f":"Bathers wait until the smoke is vented, then throw water on the hot stones. Public and apartment saunas are everywhere, and the ritual is serious enough to be intangible heritage."},{"q":"What is the capital city of Finland?","a":"Helsinki","o":["Helsinki","Moscow","Chișinău","Vatican City"],"f":"Helsinki is the capital of Finland.","kind":"capital"},{"q":"Which of these flags belongs to Finland?","a":"FIN","o":["FIN","AUT","MDA","ROU"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Finland.","kind":"flag"}],"hard":[{"q":"The Kalevala, compiled by Elias Lonnrot, is a collection of what?","a":"Oral epic poems","o":["Oral epic poems","Royal decrees","Scientific laws","Ship logs"],"f":"Lonnrot wrote down rune songs in the 1800s. The Kalevala shaped Finnish literature and art."},{"q":"Which right, called everyman's right, lets people walk and camp on wild land with care?","a":"The right to roam","o":["The right to roam","A hunting license only","A visa","A fishing monopoly"],"f":"Jokamiehenoikeus allows hiking, berry picking, and short camping if you do not disturb or damage."},{"q":"The fortress of Suomenlinna guards which harbor?","a":"The harbor of Helsinki","o":["The harbor of Helsinki","Stockholm","Tallinn","Oslo"],"f":"Sweden built Sveaborg in the 1700s. It is now a UNESCO sea fortress spread over several islands."},{"q":"Which of these cities is the capital of Finland?","a":"Helsinki","o":["Helsinki","Tampere","Turku","Oulu"],"f":"Helsinki is the capital of Finland.","kind":"capital"},{"q":"Which flag is the flag of Finland?","a":"FIN","o":["FIN","SWE","NOR","ISL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Finland.","kind":"flag"}]}},{"id":"FJI","name":"Fiji","cont":"Oceania","emoji":"🇫🇯","latlng":[-18,175],"q":{"easy":[{"q":"Which garden island's beaches and a clouded peak are the classic postcard?","a":"The Mamanuca and Yasawa islands","o":["The Mamanuca and Yasawa islands","Vanua Levu","Taveuni","Kadavu"],"f":"The Mamanucas sit west of Nadi. Resorts and reef passes draw most visitors."},{"q":"Which root, pounded and fermented, is the ceremonial drink?","a":"Kava","o":["Kava","Cocoa","Tea","Coffee"],"f":"Kava, or yaqona, is drunk from a shared bowl at welcomes. It numbs the mouth and slows conversation."},{"q":"Which team sport is the national passion, with a white palm on the jersey?","a":"Rugby union","o":["Rugby union","The All Blacks","The Wallabies","The Springboks"],"f":"Rugby is the main sport. The men's team has reached the World Cup quarterfinals."},{"q":"Which city is the capital of Fiji?","a":"Suva","o":["Suva","London","Nairobi","Bishkek"],"f":"Suva is the capital of Fiji.","kind":"capital"},{"q":"Which flag belongs to Fiji?","a":"FJI","o":["FJI","PHL","PRY","BHR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Fiji.","kind":"flag"}],"medium":[{"q":"Which golfer, born in Lautoka, reached world number one in 2004?","a":"Vijay Singh","o":["Vijay Singh","Tiger Woods","Ernie Els","Rory McIlroy"],"f":"Singh won three major championships, including the Masters in 2000. He was the first Fijian golfer to top the world ranking."},{"q":"On the island of Beqa, a ceremony of the Sawau people involves crossing a pit of heated stones. What is it?","a":"Firewalking","o":["Firewalking","Land diving","Pearl diving","Stick-chart sailing"],"f":"Tradition says a spirit gave the Sawau power over fire. The walk is still performed for special occasions."},{"q":"From 1879 to 1916, Britain brought indentured sugar workers to Fiji mainly from which country?","a":"India","o":["India","China","Portugal","Japan"],"f":"Descendants call that era girmit, from the English word agreement. Indo-Fijians remain one of Fiji's major communities."},{"q":"What is the capital city of Fiji?","a":"Suva","o":["Suva","Port Vila","Ngerulmud","Apia"],"f":"Suva is the capital of Fiji.","kind":"capital"},{"q":"Which of these flags belongs to Fiji?","a":"FJI","o":["FJI","MHL","VUT","SLB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Fiji.","kind":"flag"}],"hard":[{"q":"Which old port on Ovalau was the first colonial capital before the move in 1882?","a":"Levuka","o":["Levuka","Lautoka","Nadi","Labasa"],"f":"The old town of Levuka is now a UNESCO site."},{"q":"Firewalking on Beqa island is performed on stones heated by what?","a":"A wood fire","o":["A wood fire","Lava","Coal","Gas"],"f":"The sawau people of Beqa walk the pit in ceremony. The stones come from a long fire, not from a volcano myth alone."},{"q":"Indian indentured workers arrived from 1879 to work in which plantations?","a":"Sugar","o":["Sugar","Cotton","Rubber","Tea"],"f":"The girmitiya, indentured laborers, shaped Fiji Hindi and the food of the islands. Their descendants are a large community."},{"q":"Which of these cities is the capital of Fiji?","a":"Suva","o":["Suva","Nadi","Lautoka","Labasa"],"f":"Suva is the capital of Fiji.","kind":"capital"},{"q":"Which flag is the flag of Fiji?","a":"FJI","o":["FJI","AUS","TUV","NZL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Fiji.","kind":"flag"}]}},{"id":"FRA","name":"France","cont":"Europe","emoji":"🇫🇷","latlng":[46,2],"q":{"easy":[{"q":"Which iron tower, opened for the 1889 world's fair, is the symbol of Paris?","a":"The Eiffel Tower","o":["The Eiffel Tower","The Atomium","Blackpool Tower","The CN Tower"],"f":"Gustave Eiffel's company built the tower as a temporary exhibit. It stayed and became the city's landmark."},{"q":"Which long crusty loaf is bought daily at the bakery?","a":"A baguette","o":["A baguette","A pretzel","A tortilla","Naan"],"f":"A traditional baguette is made from flour, water, salt, and yeast. Bakers still bake them through the morning."},{"q":"Which emperor crowned himself in 1804 and redrew much of Europe?","a":"Napoleon Bonaparte","o":["Napoleon Bonaparte","Charlemagne","Louis XIV","Wellington"],"f":"Napoleon rose from the Revolution's armies. His civil code still influences law far beyond France."},{"q":"Which city is the capital of France?","a":"Paris","o":["Paris","Asunción","Port of Spain","Yaoundé"],"f":"Paris is the capital of France.","kind":"capital"},{"q":"Which flag belongs to France?","a":"FRA","o":["FRA","IRN","TCD","SWZ"],"f":"Compare the colors and symbols. One of these four flags is the national flag of France.","kind":"flag"}],"medium":[{"q":"Which scientist, born in Dole, showed that microbes spoil food and developed the heat treatment named after him?","a":"Louis Pasteur","o":["Louis Pasteur","Robert Koch","Alexander Fleming","Antoine Lavoisier"],"f":"Pasteurization heats wine, milk, or beer enough to kill many germs without boiling the liquid away. He also made vaccines against anthrax and rabies."},{"q":"The Lumiere brothers, born in Besancon, held the first paid public screening of motion pictures in Paris in which year?","a":"1895","o":["1895","1877","1905","1927"],"f":"Their short Workers Leaving the Factory was on the program of 28 December 1895. They had improved a camera and projector into one machine, the cinematograph."},{"q":"The cave of Lascaux in the Dordogne is famous for paintings from about 17,000 years ago, especially of which animals?","a":"Horses, bulls, and deer","o":["Horses, bulls, and deer","Dinosaurs","Whales","Camels"],"f":"Teenagers found the cave in 1940. Visitors' breath damaged the walls, so the original was closed and replica caves were built nearby."},{"q":"What is the capital city of France?","a":"Paris","o":["Paris","Stockholm","Riga","Lisbon"],"f":"Paris is the capital of France.","kind":"capital"},{"q":"Which of these flags belongs to France?","a":"FRA","o":["FRA","BIH","DNK","SVN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of France.","kind":"flag"}],"hard":[{"q":"The Lascaux paintings were found by teenagers in 1940 in which region?","a":"Dordogne","o":["Dordogne","Normandy","Alsace","Brittany"],"f":"The cave's horses and bulls are about 17,000 years old. Visitors now see a replica, to protect the original."},{"q":"Which canal, finished in the 1600s, links the Atlantic and the Mediterranean?","a":"The Canal du Midi","o":["The Canal du Midi","The Suez","The Panama","The Erie"],"f":"Pierre-Paul Riquet's canal crosses the south with locks and a tunnel. It is a UNESCO site."},{"q":"The Mont-Saint-Michel abbey stands on an island that becomes what at low tide?","a":"A tidal rock linked by sand","o":["A tidal rock linked by sand","A volcano","A glacier","A coral atoll"],"f":"The mount sits in a bay with the highest tides in Europe. A causeway now keeps the access road open."},{"q":"Which of these cities is the capital of France?","a":"Paris","o":["Paris","Lyon","Marseille","Toulouse"],"f":"Paris is the capital of France.","kind":"capital"},{"q":"Which flag is the flag of France?","a":"FRA","o":["FRA","RUS","NLD","LUX"],"f":"Compare the colors and symbols. One of these four flags is the national flag of France.","kind":"flag"}]}},{"id":"FSM","name":"Micronesia","cont":"Oceania","emoji":"🇫🇲","latlng":[6.91666666,158.25],"q":{"easy":[{"q":"Which ancient stone city of artificial islands and canals is a UNESCO site?","a":"Nan Madol","o":["Nan Madol","Leluh","The latte stones","The marae"],"f":"Nan Madol, off Pohnpei, was built of basalt logs by the Saudeleur dynasty. Canals separate the islets."},{"q":"Which peppery drink pounded from a root is served at meetings?","a":"Sakau","o":["Sakau","Kava is the regional name","Tea","Coffee"],"f":"On Pohnpei sakau is the local kava. It is pounded and strained for ceremonies."},{"q":"Which outrigger sailing canoes linked the high islands?","a":"Traditional canoes","o":["Traditional canoes","Junks","Dhows","Galleons"],"f":"Yap, Chuuk, Pohnpei, and Kosrae each kept canoe and navigation skills. Stone money of Yap is a related famous object."},{"q":"Which city is the capital of Micronesia?","a":"Palikir","o":["Palikir","Ouagadougou","Riga","Bogotá"],"f":"Palikir is the capital of Micronesia.","kind":"capital"},{"q":"Which flag belongs to Micronesia?","a":"FSM","o":["FSM","TCD","RUS","NAM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Micronesia.","kind":"flag"}],"medium":[{"q":"Nan Madol, off Pohnpei, is a ceremonial city of artificial islets walled with which stone?","a":"Basalt columns","o":["Basalt columns","Marble blocks","Fired brick","Sandstone slabs"],"f":"The Saudeleur dynasty built it between about 1200 and 1500. Some basalt pieces weigh many tons and were moved without metal tools or wheels."},{"q":"On Yap, traditional wealth included huge stone discs quarried in which other island group?","a":"Palau","o":["Palau","Hawaii","Tahiti","Fiji"],"f":"Some rai stones are wider than a person. Ownership can change by public agreement even if a stone sank and cannot be moved."},{"q":"Chuuk Lagoon is a famous dive site because of ships sunk in 1944 during which conflict?","a":"World War II","o":["World War II","The Korean War","World War I","The Vietnam War"],"f":"Operation Hailstone sank much of a Japanese fleet in the lagoon. Divers treat the wrecks as war graves."},{"q":"What is the capital city of Micronesia?","a":"Palikir","o":["Palikir","Port Vila","South Tarawa","Funafuti"],"f":"Palikir is the capital of Micronesia.","kind":"capital"},{"q":"Which of these flags belongs to Micronesia?","a":"FSM","o":["FSM","TON","MHL","NZL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Micronesia.","kind":"flag"}],"hard":[{"q":"Yap's huge stone disks, quarried in Palau, served as what?","a":"Ceremonial money","o":["Ceremonial money","Millstones","Anchors","Tomb doors"],"f":"The disks, rai, stayed in the village while ownership changed by agreement. Some are larger than a person."},{"q":"Legend credits which dynasty with building the canal city of artificial islets?","a":"The Saudeleur","o":["The Saudeleur","The Tui Tonga","The Latte chiefs","The Yapese councils"],"f":"Pohnpeian tradition says the Saudeleur ruled from that city. Archaeology places the main building work in the second millennium."},{"q":"The latte stones of the Marianas are not here, but Pohnpei's high title feasts center on which starch?","a":"Yams","o":["Yams","Rice","Breadfruit only","Taro only"],"f":"Prestige yams can be enormous. They are presented at feasts that rank clans."},{"q":"Which of these cities is the capital of Micronesia?","a":"Palikir","o":["Palikir","Kolonia","Weno","Tofol"],"f":"Palikir is the capital of Micronesia.","kind":"capital"},{"q":"Which flag is the flag of Micronesia?","a":"FSM","o":["FSM","MDG","MLT","NIC"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Micronesia.","kind":"flag"}]}},{"id":"GAB","name":"Gabon","cont":"Africa","emoji":"🇬🇦","latlng":[-1,11.75],"q":{"easy":[{"q":"Which coastal reserve of elephants that walk the beach is a famous sight in Gabon?","a":"Loango National Park","o":["Loango National Park","Kruger","Amboseli","Etosha"],"f":"At Loango, forest elephants sometimes come out of the trees onto the Atlantic beach."},{"q":"Which grilled fish with cassava is simple coastal food in Gabon?","a":"Poisson braisé","o":["Poisson braisé","Sushi","Poutine","Ceviche"],"f":"Whole fish is grilled over charcoal and served with cassava or plantain."},{"q":"Which waterfall on the Ogooue basin is among the country's best-known natural sights?","a":"Kongou Falls","o":["Kongou Falls","Victoria Falls","Niagara","Iguazu"],"f":"Kongou drops in steps through the forest of Ivindo National Park."},{"q":"Which city is the capital of Gabon?","a":"Libreville","o":["Libreville","Vientiane","Wellington","Sucre"],"f":"Libreville is the capital of Gabon.","kind":"capital"},{"q":"Which flag belongs to Gabon?","a":"GAB","o":["GAB","ATG","ARE","CYP"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Gabon.","kind":"flag"}],"medium":[{"q":"At Loango, on the Atlantic, forest elephants and buffalo regularly walk where?","a":"On the beaches","o":["On the beaches","Across glaciers","Through city sewers","Inside a coral lagoon only"],"f":"The coastal park is one of the few places this happens in daylight. These are the smaller forest elephants, not the savanna species."},{"q":"Fang byeri figures were carved to sit on containers holding what?","a":"Bones of ancestors","o":["Bones of ancestors","Millet for the dry season","Gold dust","Copies of the Quran"],"f":"A head or a full figure guarded a bark box of relics. Collectors removed many in the colonial period. They are reliquary guardians, not grain gods."},{"q":"Kongou Falls drops across a broad front inside Ivindo National Park. The setting around the falls is what?","a":"Rainforest","o":["Rainforest","A sand sea","A Mediterranean scrub","A high ice field"],"f":"In 2002 the country announced 13 national parks in one sweep, including Ivindo and the coastal park at Loango. Most of the land is forest."},{"q":"What is the capital city of Gabon?","a":"Libreville","o":["Libreville","Ouagadougou","Abuja","Harare"],"f":"Libreville is the capital of Gabon.","kind":"capital"},{"q":"Which of these flags belongs to Gabon?","a":"GAB","o":["GAB","DZA","SEN","KEN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Gabon.","kind":"flag"}],"hard":[{"q":"The Fang people are known for dark wooden carvings used by which secret society?","a":"The Byeri ancestor cult","o":["The Byeri ancestor cult","The Freemasons","The Olympians","The Shogunate"],"f":"Byeri figures guarded relic boxes of ancestors. Many were taken into European collections in the colonial era."},{"q":"Which 1970s leader made Gabon an oil exporter and built much of modern Libreville?","a":"Omar Bongo","o":["Omar Bongo","Nelson Mandela","Kwame Nkrumah","Haile Selassie"],"f":"Oil from offshore fields funded roads and buildings. Bongo held power from 1967 until 2009."},{"q":"Bwiti, a spiritual tradition of the forest, uses the root of which plant in night-long ceremonies?","a":"Iboga","o":["Iboga","Coca","Peyote","Kava"],"f":"Initiates take iboga under the guidance of a nganga. The rite is both religious and a passage to adulthood."},{"q":"Which of these cities is the capital of Gabon?","a":"Libreville","o":["Libreville","Port-Gentil","Franceville","Oyem"],"f":"Libreville is the capital of Gabon.","kind":"capital"},{"q":"Which flag is the flag of Gabon?","a":"GAB","o":["GAB","SOM","GEO","HUN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Gabon.","kind":"flag"}]}},{"id":"GBR","name":"United Kingdom","cont":"Europe","emoji":"🇬🇧","latlng":[54,-2],"q":{"easy":[{"q":"Which playwright of Stratford-upon-Avon wrote Hamlet and many other plays around 1600?","a":"William Shakespeare","o":["William Shakespeare","Marlowe","Chaucer","Dickens"],"f":"Shakespeare's company played at the Globe in London. His exact birthday is traditional, 23 April 1564."},{"q":"Which battered fish with fried potatoes is a classic takeaway meal?","a":"Fish and chips","o":["Fish and chips","Poutine","Tempura","Calamari"],"f":"Fried fish became a cheap hot meal in the 1800s. Malt vinegar and salt are the usual seasoning."},{"q":"Which band from Liverpool released Please Please Me in 1963 and became a worldwide phenomenon?","a":"The Beatles","o":["The Beatles","The Rolling Stones","The Who","Queen"],"f":"John Lennon, Paul McCartney, George Harrison, and Ringo Starr recorded at Abbey Road. The group split in 1970."},{"q":"Which city is the capital of United Kingdom?","a":"London","o":["London","N'Djamena","St. George's","Banjul"],"f":"London is the capital of United Kingdom.","kind":"capital"},{"q":"Which flag belongs to United Kingdom?","a":"GBR","o":["GBR","HTI","CIV","JAM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of United Kingdom.","kind":"flag"}],"medium":[{"q":"Which mathematician, born in London in 1815, wrote notes on Babbage's Analytical Engine that describe what we now call a program?","a":"Ada Lovelace","o":["Ada Lovelace","Charles Babbage","Alan Turing","George Boole"],"f":"She was the daughter of Lord Byron and studied with tutors when few girls did. Babbage designed the machine; her notes saw that it could handle symbols, not only numbers."},{"q":"Stonehenge, on Salisbury Plain, is a ring of giant stones raised mainly in which period?","a":"The late Stone Age and early Bronze Age","o":["The late Stone Age and early Bronze Age","The Roman occupation","The Viking age","The Norman conquest"],"f":"The big sarsen circle went up around 2500 BCE. How the builders moved stones from Wales is still studied, and the site lines up with the midsummer sunrise."},{"q":"In 1215 rebellious barons forced King John to seal a charter limiting royal power. What is that charter called?","a":"Magna Carta","o":["Magna Carta","The Domesday Book","The Bill of Rights","The Act of Union"],"f":"Much of it dealt with feudal fees, but clauses about lawful judgment became a symbol of the rule of law. The original was agreed at Runnymede, by the Thames."},{"q":"What is the capital city of United Kingdom?","a":"London","o":["London","Athens","Budapest","Rome"],"f":"London is the capital of United Kingdom.","kind":"capital"},{"q":"Which of these flags belongs to United Kingdom?","a":"GBR","o":["GBR","ALB","VAT","PRT"],"f":"Compare the colors and symbols. One of these four flags is the national flag of United Kingdom.","kind":"flag"}],"hard":[{"q":"The Domesday Book of 1086 was a survey ordered by which king?","a":"William the Conqueror","o":["William the Conqueror","Alfred","Henry VIII","Victoria"],"f":"Commissioners listed land and livestock across England. The book is a snapshot of Norman rule."},{"q":"Which Scottish engineer improved the steam engine in the late 1700s?","a":"James Watt","o":["James Watt","Stephenson","Brunel","Newcomen only before him"],"f":"Watt's separate condenser made steam power far more efficient. His name became a unit of power."},{"q":"The Bayeux Tapestry shows the events of 1066 in which medium?","a":"Embroidered linen","o":["Embroidered linen","Oil paint","Stained glass","Mosaic"],"f":"The long cloth, probably made in England, depicts Harold, William, and the Battle of Hastings."},{"q":"Which of these cities is the capital of United Kingdom?","a":"London","o":["London","Edinburgh","Manchester","Cardiff"],"f":"London is the capital of United Kingdom.","kind":"capital"},{"q":"Which flag is the flag of United Kingdom?","a":"GBR","o":["GBR","TCD","MHL","CRI"],"f":"Compare the colors and symbols. One of these four flags is the national flag of United Kingdom.","kind":"flag"}]}},{"id":"GEO","name":"Georgia","cont":"Asia","emoji":"🇬🇪","latlng":[42,43.5],"q":{"easy":[{"q":"Which cheese-filled bread, shaped like a boat, is the national dish?","a":"Khachapuri","o":["Khachapuri","Pide","Pizza","Pita"],"f":"Adjarian khachapuri holds cheese and an egg in an open boat of dough. Other regions bake a closed round pie."},{"q":"Which stone towers in the Caucasus highlands were family fortresses?","a":"Svan towers","o":["Svan towers","Genoese towers","The towers of San Gimignano","Minarets"],"f":"Svaneti's villages bristle with medieval stone towers used for defense and storage."},{"q":"Which church under Mount Kazbek is a landmark on the Georgian Military Highway?","a":"Gergeti Trinity Church","o":["Gergeti Trinity Church","Svetitskhoveli","Jvari","Gelati"],"f":"Tsminda Sameba stands above the town of Stepantsminda. Kazbek's snow peak rises behind it."},{"q":"Which city is the capital of Georgia?","a":"Tbilisi","o":["Tbilisi","Athens","Maputo","St. George's"],"f":"Tbilisi is the capital of Georgia.","kind":"capital"},{"q":"Which flag belongs to Georgia?","a":"GEO","o":["GEO","SOM","COM","UGA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Georgia.","kind":"flag"}],"medium":[{"q":"Which painter of animals and feasts, born in Mirzaani, worked as a self-taught sign painter in Tbilisi?","a":"Niko Pirosmani","o":["Niko Pirosmani","Marc Chagall","Ivan Aivazovsky","Kazimir Malevich"],"f":"He often painted on black oilcloth and sometimes took payment in food. His portraits of deer and of ordinary townspeople are now national icons."},{"q":"An 8,000-year-old method ferments wine in large clay jars buried in the ground. What are the jars called?","a":"Qvevri","o":["Qvevri","Amphorae","Pithoi","Dolia"],"f":"Sealed underground, the wine ferments on the skins, which is why many whites come out amber. UNESCO lists the method as intangible heritage."},{"q":"The medieval cave city of Vardzia was carved into a cliff under which queen, as a refuge from invaders?","a":"Tamar","o":["Tamar","Cleopatra","Elizabeth I","Catherine the Great"],"f":"An earthquake in 1283 sheared away the outer rock and exposed the rooms like a dollhouse. A monastery is still active in part of the complex."},{"q":"What is the capital city of Georgia?","a":"Tbilisi","o":["Tbilisi","Kuwait City","Hanoi","Singapore"],"f":"Tbilisi is the capital of Georgia.","kind":"capital"},{"q":"Which of these flags belongs to Georgia?","a":"GEO","o":["GEO","KAZ","AFG","SAU"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Georgia.","kind":"flag"}],"hard":[{"q":"Which alphabet, one of the world's older scripts still in daily use, has 33 letters today?","a":"The mkhedruli script","o":["The mkhedruli script","Armenian","Cyrillic","Greek"],"f":"The mkhedruli script is the everyday one. Older church scripts, asomtavruli and nuskhuri, still appear in icons."},{"q":"Supra, a feast, is led by a toastmaster called what?","a":"A tamada","o":["A tamada","A griot","A bard","A sommelier"],"f":"The tamada gives the order of toasts. Guests drink wine from a horn or a glass and answer with their own words."},{"q":"Which amber wine, fermented in buried clay jars, is an ancient method still used?","a":"Qvevri wine","o":["Qvevri wine","Port","Sherry","Sake"],"f":"Grapes, skins and all, ferment in a qvevri buried in the ground. The method is a UNESCO practice."},{"q":"Which of these cities is the capital of Georgia?","a":"Tbilisi","o":["Tbilisi","Batumi","Kutaisi","Zugdidi"],"f":"Tbilisi is the capital of Georgia.","kind":"capital"},{"q":"Which flag is the flag of Georgia?","a":"GEO","o":["GEO","PHL","CAF","HRV"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Georgia.","kind":"flag"}]}},{"id":"GHA","name":"Ghana","cont":"Africa","emoji":"🇬🇭","latlng":[8,-2],"q":{"easy":[{"q":"Which old slave fort on the Cape Coast is a UNESCO memorial of the Atlantic trade?","a":"Cape Coast Castle","o":["Cape Coast Castle","The Tower of London","Alcatraz","Bran Castle"],"f":"Captives were held in the castle's dungeons before ships left for the Americas. The door to the sea is still there."},{"q":"Which pounded yam or plantain dough, eaten with soup, is a staple in Ghana?","a":"Fufu","o":["Fufu","Sushi","Pretzels","Arepa"],"f":"Fufu is boiled yam, cassava, or plantain pounded until elastic, then dipped in soup."},{"q":"Which colorful woven cloth of the Ashanti is worn at festivals and funerals?","a":"Kente","o":["Kente","Tartan","Batik","Denim"],"f":"Kente strips are sewn into bright robes. Patterns have names and meanings."},{"q":"Which city is the capital of Ghana?","a":"Accra","o":["Accra","Sarajevo","Sri Jayawardenepura Kotte","Castries"],"f":"Accra is the capital of Ghana.","kind":"capital"},{"q":"Which flag belongs to Ghana?","a":"GHA","o":["GHA","GRC","FJI","MKD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Ghana.","kind":"flag"}],"medium":[{"q":"Which UN secretary-general, born in Kumasi in 1938, shared the 2001 Nobel Peace Prize?","a":"Kofi Annan","o":["Kofi Annan","Boutros Boutros-Ghali","U Thant","Dag Hammarskjöld"],"f":"He served from 1997 to 2006, and the prize was shared with the UN itself. Boutros-Ghali was his predecessor, from Egypt. U Thant was from Myanmar, and Hammarskjöld was Swedish."},{"q":"Elmina Castle, begun in 1482 and later a notorious slaving fort, was first built by whom?","a":"Portugal","o":["Portugal","Spain","Belgium","Italy"],"f":"It is among the oldest European buildings still standing south of the Sahara. The Dutch, then the British, held it later. Cape Coast Castle, nearby, is the great British fort. Both are memorials of the trade."},{"q":"Kente, bright strips sewn into a single cloth, was woven for the courts of which people?","a":"The Ashanti","o":["The Ashanti","The Yoruba","The Zulu","The Berbers"],"f":"Narrow looms make the strips. The cloth was once for royalty and great occasions. Yoruba, Zulu, and Berber textiles are real, and they are not kente."},{"q":"What is the capital city of Ghana?","a":"Accra","o":["Accra","Libreville","Brazzaville","Banjul"],"f":"Accra is the capital of Ghana.","kind":"capital"},{"q":"Which of these flags belongs to Ghana?","a":"GHA","o":["GHA","MRT","DJI","UGA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Ghana.","kind":"flag"}],"hard":[{"q":"The Ashanti kingdom, centered on Kumasi, was built in part on which trade item?","a":"Gold","o":["Gold","Silver from Potosi","Amber from the Baltic","Tin from Cornwall"],"f":"The region was long called the Gold Coast. Golden regalia still appears at royal rites."},{"q":"Yaa Asantewaa led a war in 1900 against which colonial power?","a":"Britain","o":["Britain","France","Germany","Portugal"],"f":"She was queen mother of Ejisu. The war was the last major Ashanti uprising before full colonial rule."},{"q":"Highlife music blends local rhythms with which imported instruments?","a":"Brass and guitars","o":["Brass and guitars","Only throat singing","Didgeridoo","Alpine horns"],"f":"Highlife grew in the coastal cities in the early 20th century, with dance bands and later guitars."},{"q":"Which of these cities is the capital of Ghana?","a":"Accra","o":["Accra","Kumasi","Tamale","Cape Coast"],"f":"Accra is the capital of Ghana.","kind":"capital"},{"q":"Which flag is the flag of Ghana?","a":"GHA","o":["GHA","BEN","TGO","CMR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Ghana.","kind":"flag"}]}},{"id":"GIN","name":"Guinea","cont":"Africa","emoji":"🇬🇳","latlng":[11,-10],"q":{"easy":[{"q":"Which highland source of the Niger River lies in the mountains of Guinea?","a":"The Fouta Djallon","o":["The Fouta Djallon","The Ethiopian highlands","The Drakensberg","The Atlas"],"f":"The Niger, the Senegal, and the Gambia all rise in or near these wet highlands."},{"q":"Which spicy meat soup with okra or leaves is a home dish in Guinea?","a":"Sauce feuille","o":["Sauce feuille","Sushi","Borscht","Poutine"],"f":"Leaf sauces, often with palm oil and chili, are eaten with rice grown in the coastal plains."},{"q":"The Bembeya Jazz band helped make which dance-band style famous in Guinea?","a":"Mandingue modern dance bands","o":["Mandingue modern dance bands","Tango","Waltz","Polka"],"f":"After independence, state bands mixed griot songs with electric guitars and horns."},{"q":"Which city is the capital of Guinea?","a":"Conakry","o":["Conakry","Vaduz","London","Moscow"],"f":"Conakry is the capital of Guinea.","kind":"capital"},{"q":"Which flag belongs to Guinea?","a":"GIN","o":["GIN","AND","ESP","BRN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Guinea.","kind":"flag"}],"medium":[{"q":"In 1958 this was the only French territory to vote no to de Gaulle's new community. Who led that vote?","a":"Ahmed Sékou Touré","o":["Ahmed Sékou Touré","Léopold Sédar Senghor","Félix Houphouët-Boigny","Modibo Keïta"],"f":"He said people preferred freedom in poverty to comfort in chains. France pulled its staff out at once, and independence came that same year. The other three led neighbors that joined the community and left in 1960."},{"q":"The Fouta Djallon highlands are called a water tower because they feed the headwaters of which rivers?","a":"The Niger, the Senegal, and the Gambia","o":["The Niger, the Senegal, and the Gambia","The Nile, the Congo, and the Zambezi","The Orange and the Limpopo","The Congo and the Ubangi"],"f":"Rain on the plateau runs west and north and then east with the Niger's great bend. None of these streams is a source of the Nile."},{"q":"A goblet-shaped drum played with bare hands, shared with Mali and its neighbors, is called what?","a":"The djembe","o":["The djembe","The tabla","The bodhrán","The taiko"],"f":"It is a Mandé instrument, so it is not the property of one modern border. Tabla, the bodhrán, and taiko belong to India, Ireland, and Japan."},{"q":"What is the capital city of Guinea?","a":"Conakry","o":["Conakry","Moroni","Banjul","Libreville"],"f":"Conakry is the capital of Guinea.","kind":"capital"},{"q":"Which of these flags belongs to Guinea?","a":"GIN","o":["GIN","CIV","SOM","MUS"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Guinea.","kind":"flag"}],"hard":[{"q":"Which empire of the Middle Ages, told in the Sunjata epic, began in the Manding lands of this region?","a":"The Mali Empire","o":["The Mali Empire","The Inca Empire","The Roman Empire","The Mongol Empire"],"f":"Sunjata Keita founded Mali in the 1200s. Griot families still recite the epic with the kora."},{"q":"The Baga people of the coast carve tall headdresses of which animal for rites?","a":"A serpent or bird spirit","o":["A serpent or bird spirit","The polar bear","The kangaroo","The penguin"],"f":"D'mba and serpent masks are among the best-known Baga sculptures."},{"q":"France's colonial capital for French West Africa was not here, but Guinea became independent in 1958 by voting how?","a":"No to the French constitution","o":["No to the French constitution","To join Portugal","To join Spain","To become a US state"],"f":"Sekou Toure led the no vote. France withdrew abruptly, and Guinea took a hard road to self-rule."},{"q":"Which of these cities is the capital of Guinea?","a":"Conakry","o":["Conakry","Kankan","Labé","Nzérékoré"],"f":"Conakry is the capital of Guinea.","kind":"capital"},{"q":"Which flag is the flag of Guinea?","a":"GIN","o":["GIN","GNB","MLI","SEN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Guinea.","kind":"flag"}]}},{"id":"GMB","name":"Gambia","cont":"Africa","emoji":"🇬🇲","latlng":[13.46666666,-16.56666666],"q":{"easy":[{"q":"Which navigable river runs the whole length of the country to the Atlantic?","a":"The main river to the Atlantic","o":["The main river to the Atlantic","The Nile","The Congo","The Orange"],"f":"The country is a thin strip along both banks of the river, surrounded by Senegal."},{"q":"Which peanut stew with rice is everyday food in The Gambia?","a":"Domoda","o":["Domoda","Sushi","Paella","Poutine"],"f":"Domoda is a peanut sauce with meat or fish, served over rice. Groundnuts are the historic cash crop."},{"q":"Which old British fort on an island in the river is a UNESCO site remembering the slave trade?","a":"Kunta Kinteh Island","o":["Kunta Kinteh Island","Goree","Elmina","Robben Island"],"f":"The island was once called James Island. Warehouses there held captives before the ocean crossing."},{"q":"Which city is the capital of Gambia?","a":"Banjul","o":["Banjul","Zagreb","Stockholm","Kathmandu"],"f":"Banjul is the capital of Gambia.","kind":"capital"},{"q":"Which flag belongs to Gambia?","a":"GMB","o":["GMB","ECU","HRV","PAN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Gambia.","kind":"flag"}],"medium":[{"q":"Kunta Kinteh Island, formerly James Island, is a UNESCO site remembering what?","a":"The Atlantic slave trade","o":["The Atlantic slave trade","A Phoenician copper port","A Viking shipyard","A Chinese treasure fleet"],"f":"Captives were held in the fort before the ocean crossing. Alex Haley set a scene here in Roots, but a novel is not proof of one family's paperwork. The island was renamed in 2011."},{"q":"Among mainland countries in Africa, this one is the smallest by what measure?","a":"Land area","o":["Land area","Number of people","Annual rainfall","Number of languages"],"f":"It is a ribbon on both banks of one river, inside Senegal, with only a short coast. Island countries such as Seychelles are smaller still. Area, unlike population, does not change each year."},{"q":"Britain and France drew the borders in 1889 as a strip about 10 miles to each side of the river. The strip was meant to follow what?","a":"The river upstream from the sea","o":["The river upstream from the sea","A line of latitude only","The crest of the Atlas","An old Roman road"],"f":"The shape is why the country looks like a finger pushed into Senegal. The 10-mile rule relaxed near the coast so the port could function. It is a diplomatic line, not a natural ridge."},{"q":"What is the capital city of Gambia?","a":"Banjul","o":["Banjul","Khartoum","Port Louis","Nouakchott"],"f":"Banjul is the capital of Gambia.","kind":"capital"},{"q":"Which of these flags belongs to Gambia?","a":"GMB","o":["GMB","STP","SLE","TCD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Gambia.","kind":"flag"}],"hard":[{"q":"Alex Haley set part of his book Roots in a village on this river. The story popularized which family name?","a":"Kinte","o":["Kinte","Traore","Okonkwo","Shaka"],"f":"The Kinte family of Juffure became a symbol for visitors, even though the book mixes research and fiction."},{"q":"Groundnuts replaced earlier trade goods in the 1800s. Ships came upriver mainly to buy what?","a":"Peanuts","o":["Peanuts","Gold dust","Ivory only","Diamonds"],"f":"Peanut oil and nuts fed European soap and cooking-oil factories."},{"q":"The griots of the Mandinka, who also live in The Gambia, keep history with which instrument?","a":"The kora","o":["The kora","The piano","The bagpipe","The erhu"],"f":"The kora is a 21-string harp-lute. Griots sing genealogies and epics such as Sunjata."},{"q":"Which of these cities is the capital of Gambia?","a":"Banjul","o":["Banjul","Serekunda","Brikama","Basse"],"f":"Banjul is the capital of Gambia.","kind":"capital"},{"q":"Which flag is the flag of Gambia?","a":"GMB","o":["GMB","ARE","BTN","GTM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Gambia.","kind":"flag"}]}},{"id":"GNB","name":"Guinea-Bissau","cont":"Africa","emoji":"🇬🇼","latlng":[12,-15],"q":{"easy":[{"q":"Which archipelago of islands off the coast is part of Guinea-Bissau and known for mat weaving?","a":"The Bijagos","o":["The Bijagos","The Azores","The Seychelles","The Canaries"],"f":"The Bijagos Islands keep distinct customs, including matrilineal inheritance in several communities."},{"q":"Which rice grown in mangrove paddies is a traditional crop along this coast?","a":"Mangrove rice","o":["Mangrove rice","Basmati from Punjab","Wild rice of Minnesota","Paddy of Hokkaido"],"f":"Farmers build dikes in the tidal creeks and grow rice in the brackish mud."},{"q":"Which music with a fast beat and Creole lyrics fills weddings in Guinea-Bissau?","a":"Gumbe","o":["Gumbe","Fado","Samba","Klezmer"],"f":"Gumbe uses guitars and a water-drum or box. Lyrics are often in Kriol."},{"q":"Which city is the capital of Guinea-Bissau?","a":"Bissau","o":["Bissau","Kingstown","Managua","Santo Domingo"],"f":"Bissau is the capital of Guinea-Bissau.","kind":"capital"},{"q":"Which flag belongs to Guinea-Bissau?","a":"GNB","o":["GNB","CHN","PLW","BGD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Guinea-Bissau.","kind":"flag"}],"medium":[{"q":"Which liberation leader was born in Bafatá in 1924 and assassinated in 1973, before independence?","a":"Amílcar Cabral","o":["Amílcar Cabral","Samora Machel","Agostinho Neto","Eduardo Mondlane"],"f":"He founded the PAIGC and fought for both this country and Cape Verde. His parents' roots were in Cape Verde, but his birthplace was Bafatá. Machel, Neto, and Mondlane led the struggles in Mozambique and Angola."},{"q":"Portugal recognized independence in which year, after the revolution in Lisbon?","a":"1974","o":["1974","1963","1975","1994"],"f":"The PAIGC had declared independence in 1973, while Cabral was already dead. Cape Verde, the partner territory, became independent in 1975."},{"q":"The Bijagós islands are a biosphere reserve. A noted custom there is that important rights pass through whom?","a":"The maternal line","o":["The maternal line","The Portuguese governor","The eldest son only","Foreign trading companies"],"f":"Women hold a decisive place in inheritance and in ritual houses. It is too simple to call the islands the only matriarchy, but the maternal line is central. Mangroves and turtles are why the biosphere exists."},{"q":"What is the capital city of Guinea-Bissau?","a":"Bissau","o":["Bissau","Pretoria","Maseru","Monrovia"],"f":"Bissau is the capital of Guinea-Bissau.","kind":"capital"},{"q":"Which of these flags belongs to Guinea-Bissau?","a":"GNB","o":["GNB","MAR","ZAF","SLE"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Guinea-Bissau.","kind":"flag"}],"hard":[{"q":"Amilcar Cabral led the independence movement from Portugal. He was known first as what?","a":"An agronomist","o":["An agronomist","A submarine captain","A ballet dancer","A glacier guide"],"f":"Cabral studied soils and crops before he organized the PAIGC. He was killed in 1973, just before independence."},{"q":"The Bijagos keep sacred groves and which initiation schools for young people?","a":"Fanado","o":["Fanado","Bar mitzvah","Confirmation only","Sun Dance"],"f":"Fanado is a period of seclusion and teaching. Some islands are famous for their shrines."},{"q":"Kriol, the everyday language, grew mainly from Portuguese and languages of which family?","a":"Atlantic and Mande languages of the coast","o":["Atlantic and Mande languages of the coast","Polynesian","Inuit","Slavic"],"f":"Traders, soldiers, and local communities built Kriol as a shared speech."},{"q":"Which of these cities is the capital of Guinea-Bissau?","a":"Bissau","o":["Bissau","Bafatá","Gabú","Cacheu"],"f":"Bissau is the capital of Guinea-Bissau.","kind":"capital"},{"q":"Which flag is the flag of Guinea-Bissau?","a":"GNB","o":["GNB","MLI","GIN","SEN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Guinea-Bissau.","kind":"flag"}]}},{"id":"GNQ","name":"Equatorial Guinea","cont":"Africa","emoji":"🇬🇶","latlng":[2,10],"q":{"easy":[{"q":"Which short-tailed monkey with a brightly colored face lives in the island and mainland forests?","a":"The drill","o":["The drill","The gelada","The proboscis monkey","The howler monkey"],"f":"The drill is related to the mandrill. It survives in broken patches of forest on the island and the mainland."},{"q":"Which cocoa and coffee farms made the mainland, Rio Muni, an export region?","a":"Cacao","o":["Cacao","Olives","Maple syrup","Dates"],"f":"Equatorial Guinea became a notable cocoa grower under Spanish rule. Oil later overtook farms."},{"q":"Which waterfall in the mainland forest is a well-known natural sight?","a":"The Ilady or Monte Alen cascades","o":["The Ilady or Monte Alen cascades","Victoria Falls","Niagara","Angel Falls"],"f":"The Monte Alen region protects rainforest and waterfalls on the mainland."},{"q":"Which city is the capital of Equatorial Guinea?","a":"Malabo","o":["Malabo","Paramaribo","Stockholm","Luxembourg City"],"f":"Malabo is the capital of Equatorial Guinea.","kind":"capital"},{"q":"Which flag belongs to Equatorial Guinea?","a":"GNQ","o":["GNQ","VUT","CZE","TTO"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Equatorial Guinea.","kind":"flag"}],"medium":[{"q":"Schools and government here use a European language that no other African member of the United Nations uses in that role. Which language?","a":"Spanish","o":["Spanish","Portuguese","Italian","German"],"f":"Spain joined the island of Bioko to the mainland territory of Río Muni. Portuguese is the language of the former Portuguese colonies. French is the common language of the neighbors."},{"q":"The mainland is Río Muni. The large volcanic island that holds Malabo is called what?","a":"Bioko","o":["Bioko","Annobón","São Tomé","Príncipe"],"f":"Under Spanish rule Bioko was Fernando Poo. Annobón is a smaller, distant island that is also part of the country. São Tomé and Príncipe are a separate state."},{"q":"Independence from Spain came in which year?","a":"1968","o":["1968","1956","1975","1990"],"f":"Francisco Macías Nguema became the first president. The Portuguese colonies in Africa became independent around 1975, not in 1968."},{"q":"What is the capital city of Equatorial Guinea?","a":"Malabo","o":["Malabo","Freetown","Lusaka","Abuja"],"f":"Malabo is the capital of Equatorial Guinea.","kind":"capital"},{"q":"Which of these flags belongs to Equatorial Guinea?","a":"GNQ","o":["GNQ","BDI","SYC","SSD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Equatorial Guinea.","kind":"flag"}],"hard":[{"q":"Spanish is an official language because the colony belonged to Spain until which decade?","a":"The 1960s","o":["The 1960s","The 1490s","The 2020s","The 1100s"],"f":"Independence came in 1968. Spanish remains a language of school and government, alongside French and Portuguese."},{"q":"The Fang people of the mainland are known for which dark wooden guardian figures?","a":"Byeri figures","o":["Byeri figures","Marble statues of Rome","Bronze of Benin","Jade of China"],"f":"Byeri carvings protected ancestor relics. Related styles appear across the border in Gabon."},{"q":"Which gas and oil fields offshore changed the economy after the 1990s?","a":"Gulf of Guinea petroleum","o":["Gulf of Guinea petroleum","Coal of the Ruhr","Peat of Ireland","Oil shale of Estonia"],"f":"Offshore platforms made petroleum the main export. Malabo and the mainland both felt the boom."},{"q":"Which of these cities is the capital of Equatorial Guinea?","a":"Malabo","o":["Malabo","Bata","Ebebiyín","Mongomo"],"f":"Malabo is the capital of Equatorial Guinea.","kind":"capital"},{"q":"Which flag is the flag of Equatorial Guinea?","a":"GNQ","o":["GNQ","PRT","ZMB","CUB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Equatorial Guinea.","kind":"flag"}]}},{"id":"GRC","name":"Greece","cont":"Europe","emoji":"🇬🇷","latlng":[39,22],"q":{"easy":[{"q":"Which island of white houses and blue domes looks over a flooded volcanic crater?","a":"Santorini","o":["Santorini","Crete","Rhodes","Corfu"],"f":"Santorini, or Thira, blew apart in a Bronze Age eruption. The caldera cliffs are now a famous view."},{"q":"Which grilled meat on a skewer, wrapped in bread, is everyday street food?","a":"Souvlaki","o":["Souvlaki","Sushi","Bratwurst","Kebab only of Turkey"],"f":"Souvlaki is pork or chicken with tomato and onion. It is sold from small shops late into the night."},{"q":"Which poet is traditionally credited with the Iliad and the Odyssey?","a":"Homer","o":["Homer","Virgil","Dante","Shakespeare"],"f":"The poems were composed in an oral tradition and later written down. Ancient cities argued over Homer's birthplace."},{"q":"Which city is the capital of Greece?","a":"Athens","o":["Athens","Beirut","Nuku'alofa","Banjul"],"f":"Athens is the capital of Greece.","kind":"capital"},{"q":"Which flag belongs to Greece?","a":"GRC","o":["GRC","SYR","LSO","BEN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Greece.","kind":"flag"}],"medium":[{"q":"In the 5th century BCE, Athens developed a system in which free male citizens voted directly on laws. What is that system called?","a":"Democracy","o":["Democracy","Oligarchy","Monarchy","Theocracy"],"f":"Women, enslaved people, and foreigners could not vote. Even so, the assembly on the Pnyx hill is the root of the word democracy, rule by the people."},{"q":"The Parthenon on the Acropolis was a temple dedicated chiefly to which goddess?","a":"Athena","o":["Athena","Hera","Artemis","Aphrodite"],"f":"It was built in the 440s and 430s BCE under Pericles. A huge gold and ivory statue of Athena once stood inside, and the outer sculptures are now partly in Athens and partly in London."},{"q":"The ancient Olympic Games were held every four years at Olympia in honor of which god?","a":"Zeus","o":["Zeus","Apollo","Poseidon","Ares"],"f":"Tradition dates the first games to 776 BCE. Wars were supposed to pause, and the prize was an olive wreath, not money."},{"q":"What is the capital city of Greece?","a":"Athens","o":["Athens","Vatican City","Sarajevo","London"],"f":"Athens is the capital of Greece.","kind":"capital"},{"q":"Which of these flags belongs to Greece?","a":"GRC","o":["GRC","DNK","MKD","BGR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Greece.","kind":"flag"}],"hard":[{"q":"The Antikythera mechanism, found in a shipwreck, is an ancient device for what?","a":"Predicting astronomical positions","o":["Predicting astronomical positions","Grinding grain","Printing books","Navigating by sonar"],"f":"Gears inside a bronze box modeled the motion of the sun and moon. It dates from around the 100s BCE."},{"q":"Which theater at Epidaurus is still used for plays because of its acoustics?","a":"The theater of Epidaurus","o":["The theater of Epidaurus","The Colosseum","The Globe","Ephesus only"],"f":"The stone seats of the 300s BCE hold thousands. A coin dropped on the stage can be heard at the top."},{"q":"The Minoan palace of Knossos on Crete is tied to which legend of a monster in a maze?","a":"The Minotaur","o":["The Minotaur","The Hydra","The Sphinx","Medusa"],"f":"Arthur Evans excavated Knossos in the early 1900s. The labyrinth story is older than his reconstruction."},{"q":"Which of these cities is the capital of Greece?","a":"Athens","o":["Athens","Thessaloniki","Patras","Heraklion"],"f":"Athens is the capital of Greece.","kind":"capital"},{"q":"Which flag is the flag of Greece?","a":"GRC","o":["GRC","KGZ","BDI","IRL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Greece.","kind":"flag"}]}},{"id":"GRD","name":"Grenada","cont":"North America","emoji":"🇬🇩","latlng":[12.11666666,-61.66666666],"q":{"easy":[{"q":"Which spice, the island's nickname, is the seed covering of a tropical tree?","a":"Nutmeg","o":["Nutmeg","Cinnamon","Clove","Allspice"],"f":"Grenada is the Spice Isle. Nutmeg and mace, the seed's red aril, are the main exports of that tree."},{"q":"Which underwater sculpture park sits in the bay of the capital?","a":"Molinere Underwater Sculpture Park","o":["Molinere Underwater Sculpture Park","The Blue Hole","A ship reef only","The Atlantis story"],"f":"Jason deCaires Taylor installed figures on the seabed in 2006. Coral has grown over them."},{"q":"Which chocolate from local cacao is a revived farm product?","a":"Tree-to-bar cocoa","o":["Tree-to-bar cocoa","Sugar only","Coffee only","Vanilla"],"f":"Cacao was an old crop. Small estates now ferment beans and make bars on the island."},{"q":"Which city is the capital of Grenada?","a":"St. George's","o":["St. George's","Ramallah","Thimphu","Lima"],"f":"St. George's is the capital of Grenada.","kind":"capital"},{"q":"Which flag belongs to Grenada?","a":"GRD","o":["GRD","SWE","KHM","NRU"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Grenada.","kind":"flag"}],"medium":[{"q":"Which sprinter, born in Gouyave, won Olympic 400-meter gold in 2012, the country's first Olympic title?","a":"Kirani James","o":["Kirani James","Usain Bolt","Shaunae Miller-Uibo","Michael Johnson"],"f":"He was 19 when he won in London. Bolt is Jamaican, Miller-Uibo is Bahamian, and Johnson is American."},{"q":"Nutmeg and mace, Grenada's signature spices, are two products of one fruit. Mace is which part?","a":"The red lacy covering of the seed","o":["The red lacy covering of the seed","The tree's root","The flower's pollen","The bark"],"f":"The seed itself is nutmeg. One fruit therefore yields two spices, which is why Grenada is nicknamed the Spice Isle."},{"q":"Oil down, often called the national dish, is a one-pot stew of salted meat, coconut milk, and which starchy fruit?","a":"Breadfruit","o":["Breadfruit","Plantain only","Mango","Ackee"],"f":"Everything cooks in one pot until the liquid is absorbed, or down. Dumplings and callaloo often go in too."},{"q":"What is the capital city of Grenada?","a":"St. George's","o":["St. George's","Nassau","Mexico City","Basseterre"],"f":"St. George's is the capital of Grenada.","kind":"capital"},{"q":"Which of these flags belongs to Grenada?","a":"GRD","o":["GRD","CRI","BRB","KNA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Grenada.","kind":"flag"}],"hard":[{"q":"Which hurricane in 2004 damaged most of the island's buildings and the nutmeg trees?","a":"Hurricane Ivan","o":["Hurricane Ivan","Irma","Maria","Katrina"],"f":"Ivan passed directly over Grenada. Nutmeg trees take years to bear, so the crop recovered slowly."},{"q":"The Grand Anse beach and the capital's horseshoe harbor face which sea?","a":"The Caribbean Sea","o":["The Caribbean Sea","The Atlantic only","The Pacific","The Gulf of Mexico"],"f":"St. George's wraps a crater harbor. Grand Anse is the long beach to the south."},{"q":"Which oil-down stew of breadfruit, coconut milk, and salted meat is the national dish?","a":"Oil down","o":["Oil down","Callaloo","Pepperpot","Rundown"],"f":"Everything is cooked in one pot in coconut milk until the liquid is absorbed. It is a Sunday and festival dish."},{"q":"Which of these cities is the capital of Grenada?","a":"St. George's","o":["St. George's","Gouyave","Grenville","Sauteurs"],"f":"St. George's is the capital of Grenada.","kind":"capital"},{"q":"Which flag is the flag of Grenada?","a":"GRD","o":["GRD","PAK","STP","ESP"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Grenada.","kind":"flag"}]}},{"id":"GTM","name":"Guatemala","cont":"North America","emoji":"🇬🇹","latlng":[15.5,-90.25],"q":{"easy":[{"q":"Which Maya city of tall temples in the Peten forest is a UNESCO site?","a":"Tikal","o":["Tikal","Calakmul","Copan","Palenque"],"f":"Tikal's Temple IV rises above the canopy. It was a major Classic Maya capital and a rival of Calakmul."},{"q":"Which black-bean breakfast with eggs and plantain is eaten everywhere?","a":"Huevos con frijoles","o":["Huevos con frijoles","Pupusas","Gallo pinto","Arepas"],"f":"Black beans are the daily protein. Tortillas, eggs, and fried plantain make a typical plate."},{"q":"Which volcanic lake in a crater, with three cones, is a famous highland view?","a":"Lake Atitlan","o":["Lake Atitlan","Lake Izabal","Lake Peten Itza","Amatitlan"],"f":"Volcanoes ring Atitlan. Maya towns with distinct weaving traditions sit on its shores."},{"q":"Which city is the capital of Guatemala?","a":"Guatemala City","o":["Guatemala City","Helsinki","Rabat","Port Moresby"],"f":"Guatemala City is the capital of Guatemala.","kind":"capital"},{"q":"Which flag belongs to Guatemala?","a":"GTM","o":["GTM","BEL","MNE","LIE"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Guatemala.","kind":"flag"}],"medium":[{"q":"Which K'iche' activist, born in Chimel, won the 1992 Nobel Peace Prize for defending Indigenous rights?","a":"Rigoberta Menchu","o":["Rigoberta Menchu","Malala Yousafzai","Wangari Maathai","Oscar Arias"],"f":"Her prize drew attention to the civil war's violence against Maya communities. She has remained a public advocate since."},{"q":"Tikal's temples rise above the Peten forest. In the Classic period this Maya city was a rival of which other great Maya power, in Mexico?","a":"Calakmul","o":["Calakmul","Cuzco","Tenochtitlan","Chan Chan"],"f":"Tikal's tallest temple, Temple IV, is over 60 meters high. Its carved stelae record wars and accessions of kings."},{"q":"The resplendent quetzal, with long green tail plumes, was sacred to the Maya as a symbol of what?","a":"Freedom and preciousness","o":["Freedom and preciousness","The underworld ocean","Winter storms","Desert winds"],"f":"Tail feathers were used in royal costume and could not be bought cheaply. The bird still lives in cloud forests, and its name was given to the currency."},{"q":"What is the capital city of Guatemala?","a":"Guatemala City","o":["Guatemala City","Port of Spain","San José","Mexico City"],"f":"Guatemala City is the capital of Guatemala.","kind":"capital"},{"q":"Which of these flags belongs to Guatemala?","a":"GTM","o":["GTM","VCT","CAN","ATG"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Guatemala.","kind":"flag"}],"hard":[{"q":"Which K'iche' capital in the highlands was burned by Spanish forces in 1524?","a":"Q'umarkaj","o":["Q'umarkaj","Tikal","Copan","Chichen Itza"],"f":"Q'umarkaj, also called Utatlan, sat on a plateau. Its ruins are near Santa Cruz del Quiche."},{"q":"Asturias, a novelist, won the Nobel literature prize. His work draws on which stories?","a":"Maya myth and dictatorship","o":["Maya myth and dictatorship","Only French realism","Norse sagas","The Popol Vuh is a source"],"f":"Miguel Angel Asturias used legends from the Popol Vuh and the experience of dictatorship. He won the prize in 1967."},{"q":"The Popol Vuh, written down in the 1500s, is the creation epic of which people?","a":"The K'iche' Maya","o":["The K'iche' Maya","The Aztecs","The Inca","The Nahua only"],"f":"It tells of the hero twins and the making of humans from maize. A friar's copy preserved the text."},{"q":"Which of these cities is the capital of Guatemala?","a":"Guatemala City","o":["Guatemala City","Antigua Guatemala","Quetzaltenango","Flores"],"f":"Guatemala City is the capital of Guatemala.","kind":"capital"},{"q":"Which flag is the flag of Guatemala?","a":"GTM","o":["GTM","SLV","NIC","HND"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Guatemala.","kind":"flag"}]}},{"id":"GUY","name":"Guyana","cont":"South America","emoji":"🇬🇾","latlng":[5,-59],"q":{"easy":[{"q":"Which huge waterfall on the Potaro River drops off a sandstone table?","a":"Kaieteur Falls","o":["Kaieteur Falls","Angel Falls","Victoria Falls","Iguazu"],"f":"Kaieteur plunges from the Potaro into the gorge below. It is the country's most famous natural sight."},{"q":"Which Christmas stew is preserved with cassareep from cassava?","a":"Pepperpot","o":["Pepperpot","Callaloo","Oil down","Jollof"],"f":"Cassareep, boiled cassava juice, preserves the meat. The pot can be reheated over days."},{"q":"Which wooden Gothic cathedral and a seawall define the capital's old center?","a":"St. George's Cathedral","o":["St. George's Cathedral","The Red Fort","Christ Church","The basilica"],"f":"St. George's in Georgetown is among the tallest wooden buildings. The Dutch-era seawall holds back the Atlantic."},{"q":"Which city is the capital of Guyana?","a":"Georgetown","o":["Georgetown","Victoria","Thimphu","Astana"],"f":"Georgetown is the capital of Guyana.","kind":"capital"},{"q":"Which flag belongs to Guyana?","a":"GUY","o":["GUY","RUS","LBR","KEN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Guyana.","kind":"flag"}],"medium":[{"q":"Which writer, born in Georgetown, told of teaching in a tough London school in the memoir To Sir, With Love?","a":"E. R. Braithwaite","o":["E. R. Braithwaite","V. S. Naipaul","Derek Walcott","Chinua Achebe"],"f":"He later served as a diplomat. The book became a well-known film, but the classroom story began with his own life."},{"q":"Kaieteur Falls, on the Potaro River, is famous for a single enormous drop surrounded by what kind of forest?","a":"Rainforest","o":["Rainforest","Mangrove swamp only","Pine taiga","Date-palm oasis"],"f":"The Potaro drops about 226 meters in one plunge. Swifts nest behind the sheet of water."},{"q":"Schools and courts in Guyana work mainly in which language, unlike in Brazil or Suriname?","a":"English","o":["English","Dutch","Portuguese","French"],"f":"The country was British Guiana until independence in 1966. Suriname uses Dutch, and French Guiana is part of France, not a separate country."},{"q":"What is the capital city of Guyana?","a":"Georgetown","o":["Georgetown","Buenos Aires","Montevideo","Santiago"],"f":"Georgetown is the capital of Guyana.","kind":"capital"},{"q":"Which of these flags belongs to Guyana?","a":"GUY","o":["GUY","CHL","URY","ECU"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Guyana.","kind":"flag"}],"hard":[{"q":"The Rupununi savannas and the Iwokrama forest lie in the lands of which people?","a":"The Makushi and other nations","o":["The Makushi and other nations","The Inca","The Maya","The Aztecs"],"f":"Indigenous nations hold titled villages in the interior. Ecotourism and cattle share the savanna."},{"q":"Which brown crystal sugar is named for a colonial river county?","a":"Demerara sugar","o":["Demerara sugar","Essequibo","Berbice","Courantyne"],"f":"The Dutch and then the British planted cane on the coast. The sugar's name stayed in British kitchens."},{"q":"Which novelist, born in 1921, opened the Guyana Quartet with Palace of the Peacock?","a":"Wilson Harris","o":["Wilson Harris","Edgar Mittelholzer","Jan Carew","Martin Carter"],"f":"Harris had surveyed the interior before he turned to fiction. The book follows a crew traveling up a river."},{"q":"Which of these cities is the capital of Guyana?","a":"Georgetown","o":["Georgetown","Linden","New Amsterdam","Bartica"],"f":"Georgetown is the capital of Guyana.","kind":"capital"},{"q":"Which flag is the flag of Guyana?","a":"GUY","o":["GUY","MDA","MAR","SEN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Guyana.","kind":"flag"}]}},{"id":"HND","name":"Honduras","cont":"North America","emoji":"🇭🇳","latlng":[15,-86.5],"q":{"easy":[{"q":"Which Maya city with a huge ball court and macaw sculptures is a UNESCO site?","a":"Copan","o":["Copan","Tikal","Caracol","Quirigua"],"f":"Copan's sculptures of kings are among the finest Maya stonework. The site is near the Guatemalan border, inside Honduras."},{"q":"Which baleada, a flour tortilla folded over beans and cheese, is street food?","a":"A baleada","o":["A baleada","A pupusa","An arepa","A taco"],"f":"Baleadas are the everyday snack. Cream and eggs are common extras."},{"q":"Which bay islands of reefs and a pirate past lie off the north coast?","a":"The Bay Islands","o":["The Bay Islands","The Corn Islands","San Blas","The Caymans"],"f":"Roatan, Utila, and Guanaja sit on the Mesoamerican Reef. English is widely spoken from an old island settlement."},{"q":"Which city is the capital of Honduras?","a":"Tegucigalpa","o":["Tegucigalpa","Luanda","Pyongyang","Minsk"],"f":"Tegucigalpa is the capital of Honduras.","kind":"capital"},{"q":"Which flag belongs to Honduras?","a":"HND","o":["HND","CHL","CMR","MNG"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Honduras.","kind":"flag"}],"medium":[{"q":"Which 19th-century leader, born in Tegucigalpa, tried to reunite the countries of Central America and is a national hero?","a":"Francisco Morazan","o":["Francisco Morazan","Simon Bolivar","Jose de San Martin","Benito Juarez"],"f":"He was the last president of the Federal Republic of Central America and was executed in Costa Rica in 1842. His birthday is a holiday."},{"q":"Copan, a Maya city near the Guatemalan border, is especially famous for sculpture and for a staircase covered in what?","a":"Hieroglyphs","o":["Hieroglyphs","Gold leaf","Roman mosaics","Chinese porcelain"],"f":"The Hieroglyphic Stairway has the longest known Maya inscription. Copan's kings also raised finely carved stelae of themselves."},{"q":"The Bay Islands, including Roatan and Utila, sit on which reef system?","a":"The Mesoamerican Reef","o":["The Mesoamerican Reef","The Great Barrier Reef","The Red Sea reef","The Maldives atolls"],"f":"English is widely spoken on the islands because of British settlement and later English-speaking islanders. Utila is a well-known scuba stop."},{"q":"What is the capital city of Honduras?","a":"Tegucigalpa","o":["Tegucigalpa","San Salvador","Managua","Roseau"],"f":"Tegucigalpa is the capital of Honduras.","kind":"capital"},{"q":"Which of these flags belongs to Honduras?","a":"HND","o":["HND","BLZ","KNA","CUB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Honduras.","kind":"flag"}],"hard":[{"q":"Which silver mining town in the mountains was a Spanish colonial center?","a":"Tegucigalpa's neighbor Yuscaran or Santa Lucia","o":["Tegucigalpa's neighbor Yuscaran or Santa Lucia","Potosi","Taxco","Guanajuato"],"f":"Small colonial mining towns such as Yuscaran still have cobbled streets and a church on the square."},{"q":"The Mosquito Coast, or La Moskitia, is a rainforest region of which people?","a":"The Miskito","o":["The Miskito","The Maya","The Garifuna only","The Lenca"],"f":"The Miskito people live along the rivers near the Nicaraguan border. The pine savanna and the rainforest meet there."},{"q":"Which bird with a long tail, the national bird, is the turquoise-browed motmot?","a":"The motmot","o":["The motmot","The quetzal","The macaw","The toucan"],"f":"The motmot is called the torogoz. It nests in tunnels in banks and appears on souvenirs."},{"q":"Which of these cities is the capital of Honduras?","a":"Tegucigalpa","o":["Tegucigalpa","San Pedro Sula","La Ceiba","Comayagua"],"f":"Tegucigalpa is the capital of Honduras.","kind":"capital"},{"q":"Which flag is the flag of Honduras?","a":"HND","o":["HND","NIC","SLV","GTM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Honduras.","kind":"flag"}]}},{"id":"HRV","name":"Croatia","cont":"Europe","emoji":"🇭🇷","latlng":[45.16666666,15.5],"q":{"easy":[{"q":"Which stepped lakes and waterfalls in the interior are a famous national park?","a":"Plitvice Lakes","o":["Plitvice Lakes","Lake Bled","The Blue Lagoon","Pamukkale"],"f":"Plitvice's lakes spill over travertine barriers. Boardwalks cross the water."},{"q":"Which necktie, a knotted cloth, takes its European name from a Croatian regiment?","a":"A cravat","o":["A cravat","A bolo tie","A scarf","A stole"],"f":"French speakers saw Croatian soldiers' neck cloths in the 1600s. Cravate became the word for a tie."},{"q":"Which coastal defensive town of marble streets was long an independent republic?","a":"Dubrovnik","o":["Dubrovnik","Venice","Ragusa is the old name","Split"],"f":"Dubrovnik's walls face the Adriatic. It traded as a city-republic for centuries."},{"q":"Which city is the capital of Croatia?","a":"Zagreb","o":["Zagreb","Bishkek","St. George's","Castries"],"f":"Zagreb is the capital of Croatia.","kind":"capital"},{"q":"Which flag belongs to Croatia?","a":"HRV","o":["HRV","MRT","MEX","TKM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Croatia.","kind":"flag"}],"medium":[{"q":"Which inventor, born in Smiljan in 1856, pioneered alternating-current electricity and the induction motor?","a":"Nikola Tesla","o":["Nikola Tesla","Thomas Edison","Guglielmo Marconi","Michael Faraday"],"f":"He was an ethnic Serb born in the Austrian Empire, in the village that is now in Croatia, and later worked in the United States. His ashes are kept in Belgrade."},{"q":"The modern necktie traces back to 17th-century soldiers from this region serving in France. The French word cravate comes from their name. What did they wear?","a":"A knotted neckerchief","o":["A knotted neckerchief","A feathered helmet","A tartan kilt","A metal gorget only"],"f":"Louis XIV's court copied the style. The soldiers were called Croats, and cravate is the French reshaping of that word."},{"q":"Dubrovnik's stone walls, a UNESCO site, enclosed a republic that rivaled Venice in the Adriatic. For most of its golden age that republic was called what?","a":"Ragusa","o":["Ragusa","Spalato","Zadar","Kotor"],"f":"Ragusa paid tribute at times but kept its own senate and ships. The old name survives in the word argosy, a rich merchant vessel, from Ragusa."},{"q":"What is the capital city of Croatia?","a":"Zagreb","o":["Zagreb","Reykjavík","Sofia","Berlin"],"f":"Zagreb is the capital of Croatia.","kind":"capital"},{"q":"Which of these flags belongs to Croatia?","a":"HRV","o":["HRV","BEL","ITA","ROU"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Croatia.","kind":"flag"}],"hard":[{"q":"The Arena of Pula is a standing Roman building used today for what?","a":"Concerts and film","o":["Concerts and film","Gladiators still","Parliament","A train station"],"f":"The elliptical amphitheater survived in the port of Pula. Stages are set inside in summer."},{"q":"Which lace from an Adriatic island is made with a needle, not bobbins, and is UNESCO-listed?","a":"Pag lace","o":["Pag lace","Bruges lace","Chantilly","Honiton"],"f":"Lepoglava, Hvar, and Pag each have a lace tradition. Pag's is made with an agave-fiber thread."},{"q":"The Glagolitic alphabet was used for centuries in church books along which coast?","a":"The Dalmatian coast","o":["The Dalmatian coast","The Baltic","The Black Sea","The North Sea"],"f":"Priests wrote Croatian in Glagolitic, a Slavic script older than Cyrillic in this use, into early modern times."},{"q":"Which of these cities is the capital of Croatia?","a":"Zagreb","o":["Zagreb","Split","Rijeka","Dubrovnik"],"f":"Zagreb is the capital of Croatia.","kind":"capital"},{"q":"Which flag is the flag of Croatia?","a":"HRV","o":["HRV","SVN","PRY","SVK"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Croatia.","kind":"flag"}]}},{"id":"HTI","name":"Haiti","cont":"North America","emoji":"🇭🇹","latlng":[19,-72.41666666],"q":{"easy":[{"q":"Which citadel in the north, built after independence, is a UNESCO fortress?","a":"The Citadelle Laferriere","o":["The Citadelle Laferriere","Fort Jacques","Sans-Souci is the palace below","The Ozama"],"f":"King Henri Christophe built the citadel on a mountaintop. It was meant to resist a French return."},{"q":"Which squash soup, served on New Year's Day, is a national dish?","a":"Soup joumou","o":["Soup joumou","Pumpkin soup of only Halloween","Callaloo","Sancocho"],"f":"Soup joumou was once reserved for slaveholders. Eating it on 1 January marks independence in 1804."},{"q":"Which painterly style of bright markets and vodou scenes is a national art?","a":"Naive market paintings","o":["Naive market paintings","Muralism of Mexico","Abstract expressionism","Impressionism"],"f":"Artists of the Centre d'Art in the 1940s painted daily life and spirits in flat, vivid color."},{"q":"Which city is the capital of Haiti?","a":"Port-au-Prince","o":["Port-au-Prince","Rabat","Nouakchott","Port Louis"],"f":"Port-au-Prince is the capital of Haiti.","kind":"capital"},{"q":"Which flag belongs to Haiti?","a":"HTI","o":["HTI","ZMB","CHN","GHA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Haiti.","kind":"flag"}],"medium":[{"q":"Which leader of the Haitian Revolution, born enslaved on Saint-Domingue, died in a French prison in 1803?","a":"Toussaint Louverture","o":["Toussaint Louverture","Henri Christophe","Jean-Jacques Dessalines","Simon Bolivar"],"f":"He had turned the slave uprising into a disciplined army and forced France to abolish slavery on the island. Napoleon had him seized during negotiations."},{"q":"The Citadelle Laferriere, a huge hilltop fort and UNESCO site, was built under which early king?","a":"Henri Christophe","o":["Henri Christophe","Louis XIV","Henry VIII","Kamehameha I"],"f":"It was meant to resist a French attempt to restore slavery. Tens of thousands of workers hauled cannon and stone up the mountain after independence."},{"q":"On 1 January 1804 Haiti declared independence. It is remembered as the first nation born from which kind of successful uprising?","a":"A revolution of enslaved people","o":["A revolution of enslaved people","A gold rush","A peasant revolt in Europe","A sailors' mutiny"],"f":"The army defeated French forces sent by Napoleon. The new state was the first Black-led republic in the modern world."},{"q":"What is the capital city of Haiti?","a":"Port-au-Prince","o":["Port-au-Prince","Managua","Ottawa","Roseau"],"f":"Port-au-Prince is the capital of Haiti.","kind":"capital"},{"q":"Which of these flags belongs to Haiti?","a":"HTI","o":["HTI","BLZ","JAM","SLV"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Haiti.","kind":"flag"}],"hard":[{"q":"Which painter and Vodou priest, who died in 1948, became the most famous of the early naive artists?","a":"Hector Hyppolite","o":["Hector Hyppolite","Philome Obin","Rigaud Benoit","Wilson Bigaud"],"f":"Hyppolite painted spirits with house paint. Andre Breton championed the pictures in the 1940s."},{"q":"The 1804 independence made Haiti the first state born of which kind of revolt?","a":"A successful revolt of enslaved people","o":["A successful revolt of enslaved people","A settler tax revolt","A royal coup","A merchant strike"],"f":"The revolution defeated French, Spanish, and British forces. Independence was declared on 1 January 1804."},{"q":"Kompa music, the dance-band sound, was shaped in the 1950s by which bandleader?","a":"Nemours Jean-Baptiste","o":["Nemours Jean-Baptiste","Tabou Combo later","Boukman Eksperyans","Wyclef"],"f":"Nemours slowed the merengue into konpa direk. The two-step still fills dance halls."},{"q":"Which of these cities is the capital of Haiti?","a":"Port-au-Prince","o":["Port-au-Prince","Cap-Haïtien","Gonaïves","Jacmel"],"f":"Port-au-Prince is the capital of Haiti.","kind":"capital"},{"q":"Which flag is the flag of Haiti?","a":"HTI","o":["HTI","SGP","GUY","LBN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Haiti.","kind":"flag"}]}},{"id":"HUN","name":"Hungary","cont":"Europe","emoji":"🇭🇺","latlng":[47,20],"q":{"easy":[{"q":"Which river separates the hilly side and the flat side of the capital?","a":"The Danube","o":["The Danube","The Tisza","The Rhine","The Volga"],"f":"Buda and Pest were united in 1873. Bridges across the Danube joined the two towns."},{"q":"Which paprika stew of meat and vegetables is the national dish?","a":"Goulash","o":["Goulash","Borscht","Paella","Ratatouille"],"f":"Goulash, or gulyas, began as a herdsman's kettle. Paprika gives it the red color."},{"q":"Which pianist and composer of Hungarian rhapsodies was born in 1811?","a":"Franz Liszt","o":["Franz Liszt","Chopin","Brahms","Bartok"],"f":"Liszt was born in Raiding, then in the Kingdom of Hungary. He became the great piano virtuoso of his age."},{"q":"Which city is the capital of Hungary?","a":"Budapest","o":["Budapest","Moroni","Majuro","Juba"],"f":"Budapest is the capital of Hungary.","kind":"capital"},{"q":"Which flag belongs to Hungary?","a":"HUN","o":["HUN","NZL","ERI","UGA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Hungary.","kind":"flag"}],"medium":[{"q":"Which designer, born in Budapest, invented a twisting cube puzzle in 1974?","a":"Erno Rubik","o":["Erno Rubik","Laszlo Biro","Harry Houdini","John von Neumann"],"f":"He was a professor of architecture and built the cube to teach three-dimensional movement. It became a worldwide craze after 1980. Houdini and von Neumann were also born in Budapest."},{"q":"Laszlo Biro, born in Budapest, patented a pen that writes with a tiny ball. What does the ball do?","a":"It rolls ink onto the paper","o":["It rolls ink onto the paper","It erases graphite","It punches Braille","It sprays perfume"],"f":"He and his brother developed it in the 1930s after noticing newspaper ink dried fast. Production later took off in Argentina, where Biro had fled the war."},{"q":"Goulash, the national stew, is flavored above all by which ground red spice?","a":"Paprika","o":["Paprika","Saffron","Turmeric","Cinnamon"],"f":"Paprika is dried pepper, brought from the Americas and later grown on the Hungarian plain. A proper goulash is soupier than many foreign versions."},{"q":"What is the capital city of Hungary?","a":"Budapest","o":["Budapest","Nicosia","Minsk","Vatican City"],"f":"Budapest is the capital of Hungary.","kind":"capital"},{"q":"Which of these flags belongs to Hungary?","a":"HUN","o":["HUN","FIN","PRT","BIH"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Hungary.","kind":"flag"}],"hard":[{"q":"Which thermal lake at Heviz, near the western end of the lake country, is a famous bath?","a":"Lake Heviz","o":["Lake Heviz","Lake Balaton","Lake Geneva","The Blue Lagoon"],"f":"Heviz is a warm crater lake. People have bathed there since Roman times and under later Hungarian kings."},{"q":"The conquest of the Carpathian Basin by Magyar tribes is traditionally dated to which year?","a":"895","o":["895","1066","1492","476"],"f":"The seven tribes under Arpad entered the basin at the end of the 800s. The date is traditional."},{"q":"Which embroidery of the Matyo community, with bright flowers, is a UNESCO craft?","a":"Matyo embroidery","o":["Matyo embroidery","Kente","Cross-stitch of only England","Batik"],"f":"Women in Mezokovesd stitched dense floral patterns on costumes and cloth for the home."},{"q":"Which of these cities is the capital of Hungary?","a":"Budapest","o":["Budapest","Debrecen","Szeged","Pécs"],"f":"Budapest is the capital of Hungary.","kind":"capital"},{"q":"Which flag is the flag of Hungary?","a":"HUN","o":["HUN","BGR","IRN","TJK"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Hungary.","kind":"flag"}]}},{"id":"IDN","name":"Indonesia","cont":"Asia","emoji":"🇮🇩","latlng":[-5,120],"q":{"easy":[{"q":"Which volcano in East Java rises from a sea of sand and is a famous sunrise hike?","a":"Mount Bromo","o":["Mount Bromo","Krakatoa","Merapi","Fuji"],"f":"Bromo sits in the Tengger caldera. Visitors cross the sand sea before dawn."},{"q":"Which fried rice with sweet soy, egg, and chicken is everyday food?","a":"Nasi goreng","o":["Nasi goreng","Sushi","Paella","Biryani"],"f":"Nasi goreng is leftover rice fried with kecap manis. It is eaten at breakfast and at night."},{"q":"Which shadow-puppet theater, with a lamp and a screen, tells Hindu epics in Java?","a":"Wayang kulit","o":["Wayang kulit","Kabuki","Noh","Opera"],"f":"The dalang moves leather puppets and speaks every part. A gamelan orchestra plays beside the screen."},{"q":"Which city is the capital of Indonesia?","a":"Jakarta","o":["Jakarta","Dublin","Belmopan","Dodoma"],"f":"Jakarta is the capital of Indonesia.","kind":"capital"},{"q":"Which flag belongs to Indonesia?","a":"IDN","o":["IDN","GUY","EST","BEN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Indonesia.","kind":"flag"}],"medium":[{"q":"Borobudur, a huge 9th-century monument in Java, is a stepped pyramid of which religion?","a":"Buddhism","o":["Buddhism","Hinduism","Islam","Christianity"],"f":"It was buried under volcanic ash and jungle until the 19th century. Pilgrims walk clockwise up the terraces toward a central stupa."},{"q":"The Komodo dragon, the largest living lizard, lives wild only on a few islands here. Besides teeth, its bite delivers what?","a":"Venom","o":["Venom","A constricting tail","Electric shock","A spray of acid"],"f":"For years the dangerous bite was blamed only on bacteria in the saliva. Researchers later found venom glands. A dragon can take down deer and water buffalo."},{"q":"In 1883 a volcano in the Sunda Strait exploded, darkened skies worldwide, and killed tens of thousands. What was it called?","a":"Krakatoa","o":["Krakatoa","Tambora","Merapi","Fuji"],"f":"Most deaths came from the tsunamis, not the ash. Tambora, in 1815, was an even larger eruption on a different island."},{"q":"What is the capital city of Indonesia?","a":"Jakarta","o":["Jakarta","Yerevan","Tashkent","Sana'a"],"f":"Jakarta is the capital of Indonesia.","kind":"capital"},{"q":"Which of these flags belongs to Indonesia?","a":"IDN","o":["IDN","KOR","PHL","VNM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Indonesia.","kind":"flag"}],"hard":[{"q":"Which islands, the Moluccas, were once called the Spice Islands for cloves and nutmeg?","a":"The Maluku Islands","o":["The Maluku Islands","The Azores","The Canaries","Zanzibar only"],"f":"Cloves and nutmeg grew almost nowhere else. European powers fought over the islands from the 1500s."},{"q":"Which wax-resist dyeing uses a canting pen and copper stamps?","a":"Batik","o":["Batik","Ikat","Songket","Kente"],"f":"Motifs can name a region. The craft is especially deep in the court cities of the center island."},{"q":"The Majapahit kingdom of the 1300s was centered on which island?","a":"Java","o":["Java","Bali","Sumatra","Sulawesi"],"f":"Majapahit influenced much of the archipelago. Its capital was near modern Trowulan in East Java."},{"q":"Which of these cities is the capital of Indonesia?","a":"Jakarta","o":["Jakarta","Surabaya","Bandung","Medan"],"f":"Jakarta is the capital of Indonesia.","kind":"capital"},{"q":"Which flag is the flag of Indonesia?","a":"IDN","o":["IDN","POL","SGP","MCO"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Indonesia.","kind":"flag"}]}},{"id":"IND","name":"India","cont":"Asia","emoji":"🇮🇳","latlng":[20,77],"q":{"easy":[{"q":"Which riverside city of ghats and temples on the Ganges is a major pilgrimage site?","a":"Varanasi","o":["Varanasi","Haridwar","Kolkata","Ujjain"],"f":"Varanasi, also called Banaras, is one of the oldest living cities. Pilgrims bathe at the stone steps."},{"q":"Which thin crisp pancake of rice and lentils, served with chutney, is a southern breakfast?","a":"Dosa","o":["Dosa","Naan","Crepe","Injera"],"f":"A dosa is fermented batter spread on a hot griddle. Masala dosa holds a potato filling."},{"q":"Which leader, called Mahatma, led nonviolent campaigns against British rule and was killed in 1948?","a":"Mohandas Gandhi","o":["Mohandas Gandhi","Nehru","Jinnah","Ambedkar"],"f":"Gandhi was born in Porbandar in 1869. He was assassinated in Delhi on 30 January 1948."},{"q":"Which city is the capital of India?","a":"New Delhi","o":["New Delhi","Sarajevo","Apia","Freetown"],"f":"New Delhi is the capital of India.","kind":"capital"},{"q":"Which flag belongs to India?","a":"IND","o":["IND","GNQ","BGR","COG"],"f":"Compare the colors and symbols. One of these four flags is the national flag of India.","kind":"flag"}],"medium":[{"q":"Which physicist, born in Tiruchirappalli, won the 1930 Nobel Prize for showing how light changes color when it scatters?","a":"C. V. Raman","o":["C. V. Raman","Satyendra Nath Bose","Homi Bhabha","Abdus Salam"],"f":"The color of the sea and the sky helped lead him to the effect now called Raman scattering. Bose, of Bose-Einstein statistics, never received that prize."},{"q":"The Taj Mahal was built in the 17th century by Shah Jahan as a tomb for whom?","a":"His wife Mumtaz Mahal","o":["His wife Mumtaz Mahal","His mother Nur Jahan","A Hindu saint","A Persian poet"],"f":"It took about 20 years and white marble from Makrana. The four minarets lean slightly outward so that in an earthquake they would fall away from the dome."},{"q":"The game of chess developed from an Indian strategy game played with four armies. What was that game called?","a":"Chaturanga","o":["Chaturanga","Go","Mancala","Pachisi"],"f":"Chaturanga means four limbs, matching the pieces of an ancient army: infantry, cavalry, elephants, and chariots. It passed through Persia, where it became shatranj."},{"q":"What is the capital city of India?","a":"New Delhi","o":["New Delhi","Abu Dhabi","Islamabad","Bishkek"],"f":"New Delhi is the capital of India.","kind":"capital"},{"q":"Which of these flags belongs to India?","a":"IND","o":["IND","MYS","AZE","GEO"],"f":"Compare the colors and symbols. One of these four flags is the national flag of India.","kind":"flag"}],"hard":[{"q":"Which emperor's edicts, carved on pillars and rocks in the 200s BCE, preach dhamma after a bloody war?","a":"Ashoka","o":["Ashoka","Akbar","Chandragupta","Harsha"],"f":"Ashoka of the Maurya dynasty renounced conquest after Kalinga. His lion capital became the national emblem."},{"q":"Which classical dance of Tamil Nadu uses fixed hand gestures called mudras?","a":"Bharatanatyam","o":["Bharatanatyam","Kathak","Odissi","Kathakali"],"f":"Bharatanatyam was shaped in the temples and courts of the south. It revived on the modern stage in the 20th century."},{"q":"The Iron Pillar of Delhi, from about the 400s, is famous for resisting what?","a":"Rust","o":["Rust","Lightning","Earthquakes","Paint"],"f":"The pillar, probably moved from central India, has barely corroded. Its high-phosphorus iron forms a protective film."},{"q":"Which of these cities is the capital of India?","a":"New Delhi","o":["New Delhi","Mumbai","Kolkata","Chennai"],"f":"New Delhi is the capital of India.","kind":"capital"},{"q":"Which flag is the flag of India?","a":"IND","o":["IND","ZMB","FJI","SYC"],"f":"Compare the colors and symbols. One of these four flags is the national flag of India.","kind":"flag"}]}},{"id":"IRL","name":"Ireland","cont":"Europe","emoji":"🇮🇪","latlng":[53,-8],"q":{"easy":[{"q":"Which cliffs of dark rock face the Atlantic in County Clare?","a":"The Cliffs of Moher","o":["The Cliffs of Moher","Etretat","The White Cliffs","The Twelve Apostles"],"f":"The Cliffs of Moher rise above the sea near Doolin. On a clear day the Aran Islands are visible."},{"q":"Which round loaf of flour, buttermilk, and baking soda is a home bread?","a":"Soda bread","o":["Soda bread","Baguette","Rye","Pita"],"f":"Soda bread rose on buttermilk and baking soda when yeast was scarce. A cross is often cut in the top."},{"q":"Which frame drum, played with a short stick, sits in a traditional music session?","a":"The bodhran","o":["The bodhran","The djembe","The taiko","The timpani"],"f":"The bodhran is held against the body and struck with a tipper. It keeps time for fiddles and flutes."},{"q":"Which city is the capital of Ireland?","a":"Dublin","o":["Dublin","Mbabane","Port Moresby","Astana"],"f":"Dublin is the capital of Ireland.","kind":"capital"},{"q":"Which flag belongs to Ireland?","a":"IRL","o":["IRL","FJI","PNG","MLI"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Ireland.","kind":"flag"}],"medium":[{"q":"Which scientist, born at Lismore Castle in 1627, showed that the pressure of a gas rises as its volume shrinks?","a":"Robert Boyle","o":["Robert Boyle","Isaac Newton","Robert Hooke","Antoine Lavoisier"],"f":"Boyle's law is that relationship, when temperature stays the same. He also helped found the Royal Society in London and argued for careful experiments."},{"q":"Newgrange, a passage tomb in the Boyne Valley, is older than the pyramids at Giza. About when was it built?","a":"Around 3200 BCE","o":["Around 3200 BCE","Around 1200 BCE","Around 500 BCE","Around 800 CE"],"f":"At midwinter sunrise a beam of light enters the passage and lights the chamber. The carvings of spirals on the kerbstones are older than any writing in Ireland."},{"q":"From 1845 to about 1852 a blight destroyed the crop that poor families depended on, and a million people died. Which crop?","a":"The potato","o":["The potato","Wheat","Oats","Flax"],"f":"The blight was a microorganism, Phytophthora infestans. Death and emigration cut the island's population sharply, and the politics of the famine are still debated."},{"q":"What is the capital city of Ireland?","a":"Dublin","o":["Dublin","Rome","Nicosia","Belgrade"],"f":"Dublin is the capital of Ireland.","kind":"capital"},{"q":"Which of these flags belongs to Ireland?","a":"IRL","o":["IRL","BEL","AUT","NLD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Ireland.","kind":"flag"}],"hard":[{"q":"The Book of Kells, an illuminated gospel, was made by monks and is kept at which university?","a":"Trinity College Dublin","o":["Trinity College Dublin","Oxford","The Sorbonne","Uppsala"],"f":"The book dates from around 800. Its carpet pages of spirals are a high point of Insular art."},{"q":"Skellig Michael, a steep island, holds what kind of early medieval ruins?","a":"Beehive monastic cells","o":["Beehive monastic cells","A Viking ship","A Roman fort","A lighthouse only"],"f":"Monks lived in stone huts on the rock between the 500s and the 1200s. Steps still climb to the monastery."},{"q":"Hurling, the fast field sport, is played with a stick called what?","a":"A hurley","o":["A hurley","A shinty","A mallet","A bat"],"f":"Players hit a small ball, the sliotar, with a flat ash stick. The game is older than written Irish history."},{"q":"Which of these cities is the capital of Ireland?","a":"Dublin","o":["Dublin","Cork","Galway","Limerick"],"f":"Dublin is the capital of Ireland.","kind":"capital"},{"q":"Which flag is the flag of Ireland?","a":"IRL","o":["IRL","MEX","ITA","CIV"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Ireland.","kind":"flag"}]}},{"id":"IRN","name":"Iran","cont":"Asia","emoji":"🇮🇷","latlng":[32,53],"q":{"easy":[{"q":"Which huge square in Isfahan is framed by a palace, a bazaar, and two mosques?","a":"Naqsh-e Jahan Square","o":["Naqsh-e Jahan Square","Red Square","Tiananmen","The Registan"],"f":"Shah Abbas laid out the square in the early 1600s. It is also called Imam Square."},{"q":"Which skewered meat with saffron rice is a restaurant classic?","a":"Chelo kebab","o":["Chelo kebab","Shish tawook","Souvlaki","Satay"],"f":"Chelo is steamed rice with a crisp crust, the tahdig. Kebab-e koobideh is the minced version."},{"q":"Which poet of the late 900s wrote the Shahnameh, the epic of the kings?","a":"Ferdowsi","o":["Ferdowsi","Hafez","Rumi","Saadi"],"f":"Ferdowsi composed about 50,000 couplets in New Persian. His tomb is in Tus, near Mashhad."},{"q":"Which city is the capital of Iran?","a":"Tehran","o":["Tehran","Port Louis","Honiara","Libreville"],"f":"Tehran is the capital of Iran.","kind":"capital"},{"q":"Which flag belongs to Iran?","a":"IRN","o":["IRN","MCO","TUN","ARG"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Iran.","kind":"flag"}],"medium":[{"q":"Which mathematician, born in Tehran, in 2014 became the first woman to win the Fields Medal?","a":"Maryam Mirzakhani","o":["Maryam Mirzakhani","Emmy Noether","Hypatia","Tu Youyou"],"f":"She worked on the geometry of surfaces and died in 2017 at 40. The Fields Medal is often described as the highest prize in mathematics."},{"q":"Persepolis, burned after Alexander's invasion, was the ceremonial seat of which empire?","a":"The Achaemenid Empire","o":["The Achaemenid Empire","The Sassanian Empire","The Ottoman Empire","The Parthian Empire"],"f":"Darius I began the great terrace in the 6th century BCE. Reliefs of gift-bearers from many lands line the stairways."},{"q":"Nowruz, the new year marked at the spring equinox, is kept with a table of seven items whose names begin with the letter S. The festival is older than which religion that later adopted it?","a":"Islam","o":["Islam","Zoroastrianism","Buddhism","Christianity"],"f":"It was already a major feast under the Achaemenids and is linked to Zoroastrian tradition. Families still grow sabzeh, sprouted greens, for the table."},{"q":"What is the capital city of Iran?","a":"Tehran","o":["Tehran","Tokyo","Seoul","Baghdad"],"f":"Tehran is the capital of Iran.","kind":"capital"},{"q":"Which of these flags belongs to Iran?","a":"IRN","o":["IRN","KWT","JPN","ISR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Iran.","kind":"flag"}],"hard":[{"q":"Windcatchers, or badgirs, cool houses in which desert city famous for them?","a":"Yazd","o":["Yazd","Isfahan","Tabriz","Rasht"],"f":"A badgir funnels breeze down into a basement pool. Yazd's old town is full of them, beside qanats and clay lanes."},{"q":"Miniature painting of the Safavid court illustrated which books?","a":"Epic and poetic manuscripts","o":["Epic and poetic manuscripts","Newspapers","Scientific journals","Maps only"],"f":"Painters such as Behzad set finely detailed scenes inside the pages of the Shahnameh and love poems."},{"q":"Nowruz, the new year at the spring equinox, is marked by a table of objects called what?","a":"The haft-seen","o":["The haft-seen","A Christmas tree","A menorah","A shrine"],"f":"Seven items starting with the letter S are set out, plus sprouts grown for the holiday."},{"q":"Which of these cities is the capital of Iran?","a":"Tehran","o":["Tehran","Isfahan","Shiraz","Tabriz"],"f":"Tehran is the capital of Iran.","kind":"capital"},{"q":"Which flag is the flag of Iran?","a":"IRN","o":["IRN","HUN","BGR","TJK"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Iran.","kind":"flag"}]}},{"id":"IRQ","name":"Iraq","cont":"Asia","emoji":"🇮🇶","latlng":[33,44],"q":{"easy":[{"q":"Which ancient city on the Euphrates was the capital of Hammurabi?","a":"Babylon","o":["Babylon","Ur","Nineveh","Assur"],"f":"Hammurabi's law code was issued in the 1700s BCE. The city's ruins lie near modern Hillah."},{"q":"Which grilled river fish, opened and cooked over a wood fire, is a Baghdad specialty?","a":"Masgouf","o":["Masgouf","Sushi","Ceviche","Fish and chips"],"f":"Masgouf is usually carp, marinated and staked beside the flame. It is a restaurant ritual on the Tigris."},{"q":"Which wetlands of reeds in the south are home to the Marsh Arabs, or Ma'dan?","a":"The Mesopotamian marshes","o":["The Mesopotamian marshes","The Sudd","The Everglades","The Okavango"],"f":"The marshes between the Tigris and Euphrates were drained in recent decades and partly reflooded. Reed houses are a traditional dwelling."},{"q":"Which city is the capital of Iraq?","a":"Baghdad","o":["Baghdad","Apia","Funafuti","Sofia"],"f":"Baghdad is the capital of Iraq.","kind":"capital"},{"q":"Which flag belongs to Iraq?","a":"IRQ","o":["IRQ","BIH","PLW","GRD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Iraq.","kind":"flag"}],"medium":[{"q":"Which architect, born in Baghdad in 1950, became famous for sweeping concrete curves such as the Guangzhou Opera House?","a":"Zaha Hadid","o":["Zaha Hadid","Ieoh Ming Pei","Tadao Ando","Frank Gehry"],"f":"She was the first woman to win the Pritzker Prize, in 2004. She died in 2016, and many of her buildings opened only after her death."},{"q":"In southern Mesopotamia, Sumerian scribes pressed signs into wet clay. That writing system is called what?","a":"Cuneiform","o":["Cuneiform","Hieroglyphs","Linear B","Devanagari"],"f":"The name means wedge-shaped, from the mark of a reed stylus. It began as pictures for trade around 3400 BCE and later recorded laws and poems."},{"q":"The Ziggurat of Ur, partly restored, was a stepped temple platform in the city of the moon god. Which god?","a":"Nanna, or Sin","o":["Nanna, or Sin","Marduk","Enlil","Ishtar"],"f":"Ur was a Sumerian capital on the Euphrates. The brick core is ancient, and the lower facing was rebuilt in the 20th century."},{"q":"What is the capital city of Iraq?","a":"Baghdad","o":["Baghdad","Doha","Kabul","Beijing"],"f":"Baghdad is the capital of Iraq.","kind":"capital"},{"q":"Which of these flags belongs to Iraq?","a":"IRQ","o":["IRQ","TJK","CHN","KHM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Iraq.","kind":"flag"}],"hard":[{"q":"The Ishtar Gate of Babylon, now rebuilt in a Berlin museum, was glazed in which color?","a":"Blue","o":["Blue","Red","Green","White"],"f":"Nebuchadnezzar II dedicated the gate to Ishtar. Lions and dragons in glazed brick covered the walls."},{"q":"Which stringed instrument, a pear-shaped lute, is central to Iraqi classical music?","a":"The oud","o":["The oud","The sitar","The kora","The banjo"],"f":"The Iraqi oud school of Baghdad and Mosul was famous in the 20th century. The munir or sharqi style sang with it."},{"q":"The ziggurat of Ur, rebuilt in part in the 20th century, honored which moon god?","a":"Nanna","o":["Nanna","Marduk","Assur","Enlil"],"f":"The great ziggurat at Tell al-Muqayyar dates from the third millennium BCE. A temple to Nanna stood on top."},{"q":"Which of these cities is the capital of Iraq?","a":"Baghdad","o":["Baghdad","Basra","Mosul","Erbil"],"f":"Baghdad is the capital of Iraq.","kind":"capital"},{"q":"Which flag is the flag of Iraq?","a":"IRQ","o":["IRQ","EGY","SYR","YEM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Iraq.","kind":"flag"}]}},{"id":"ISL","name":"Iceland","cont":"Europe","emoji":"🇮🇸","latlng":[65,-18],"q":{"easy":[{"q":"Which hot spring area gave the English language the word geyser?","a":"Geysir","o":["Geysir","Yellowstone","Rotorua","Pamukkale"],"f":"The Great Geysir has often been quiet, while nearby Strokkur erupts every few minutes."},{"q":"Which thick cultured dairy food is eaten at breakfast?","a":"Skyr","o":["Skyr","Yogurt of Bulgaria only","Feta","Butter"],"f":"Skyr is a soft cheese eaten like yogurt. It has been made on the island for centuries."},{"q":"Which lights, caused by solar particles, color the winter sky?","a":"The aurora borealis","o":["The aurora borealis","The milky way","Lightning","Ball lightning"],"f":"The northern lights are common on clear nights away from town lamps. Green is the usual color."},{"q":"Which city is the capital of Iceland?","a":"Reykjavík","o":["Reykjavík","Sana'a","Vientiane","Addis Ababa"],"f":"Reykjavík is the capital of Iceland.","kind":"capital"},{"q":"Which flag belongs to Iceland?","a":"ISL","o":["ISL","SLE","KIR","VUT"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Iceland.","kind":"flag"}],"medium":[{"q":"Which novelist, born in Reykjavik, won the 1955 Nobel Prize and wrote Independent People?","a":"Halldor Laxness","o":["Halldor Laxness","Sigrid Undset","Knut Hamsun","Sjón"],"f":"Independent People follows a stubborn sheep farmer. Laxness wrote in Icelandic and argued that a small language could still hold a world literature."},{"q":"The Althing, founded around 930 at Thingvellir, is one of the oldest surviving what?","a":"Parliaments","o":["Parliaments","Universities","Stock exchanges","Navies"],"f":"Chiefs met in the open rift valley, where the Eurasian and North American plates pull apart. The modern parliament in Reykjavik still uses the old name."},{"q":"The island of Surtsey rose from the sea in eruptions that began in which year?","a":"1963","o":["1963","1947","1973","1996"],"f":"Scientists kept the new island almost free of visitors so they could watch life arrive on bare lava. Moss and birds colonized it within a few years."},{"q":"What is the capital city of Iceland?","a":"Reykjavík","o":["Reykjavík","Vienna","Ljubljana","Bratislava"],"f":"Reykjavík is the capital of Iceland.","kind":"capital"},{"q":"Which of these flags belongs to Iceland?","a":"ISL","o":["ISL","MLT","LVA","SVK"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Iceland.","kind":"flag"}],"hard":[{"q":"The Althing, often called the oldest parliament, first met at which lava site?","a":"Thingvellir","o":["Thingvellir","Reykholt","Akureyri","Vik"],"f":"Chiefs gathered at Thingvellir from 930. The rift valley is now a national park and a UNESCO site."},{"q":"Which 13th-century prose tales of farmers and feuds are the island's classic literature?","a":"The sagas","o":["The sagas","The Kalevala","The Eddas only of gods","Beowulf"],"f":"Njals saga and Egil's saga were written in Icelandic. They are still read as both history and story."},{"q":"The Krafla and Reykjanes fields supply electricity and heat from what?","a":"Geothermal steam","o":["Geothermal steam","Coal","Imported oil only","Nuclear plants"],"f":"Boreholes tap volcanic heat. Much of the country's electricity and home heating comes from it."},{"q":"Which of these cities is the capital of Iceland?","a":"Reykjavík","o":["Reykjavík","Akureyri","Keflavík","Selfoss"],"f":"Reykjavík is the capital of Iceland.","kind":"capital"},{"q":"Which flag is the flag of Iceland?","a":"ISL","o":["ISL","SWE","NOR","DNK"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Iceland.","kind":"flag"}]}},{"id":"ISR","name":"Israel","cont":"Asia","emoji":"🇮🇱","latlng":[31.47,35.13],"q":{"easy":[{"q":"Which ancient limestone wall in Jerusalem is a Jewish place of prayer?","a":"The Western Wall","o":["The Western Wall","The Temple Mount platform","Masada","The Dome only"],"f":"The Western Wall is a retaining wall of the Temple Mount platform. People place written prayers in its cracks."},{"q":"Which deep-fried chickpea balls in pita are a street food across the region?","a":"Falafel","o":["Falafel","Hummus only","Sabich","Shawarma"],"f":"Falafel is ground chickpeas, herbed and fried. It is eaten standing up, with salad and tahini."},{"q":"Which crusader city on the coast has a famous underground refectory and sea walls?","a":"Acre","o":["Acre","Jaffa","Haifa","Caesarea"],"f":"Akko's old city is a UNESCO site. The Knights Hospitaller left huge halls under the streets."},{"q":"Where do the Knesset and the Supreme Court of Israel sit?","a":"Jerusalem","o":["Jerusalem","Tunis","San Marino","Lima"],"f":"The Knesset and the Supreme Court sit in Jerusalem. Many embassies are in Tel Aviv.","kind":"capital"},{"q":"Which flag belongs to Israel?","a":"ISR","o":["ISR","MNE","DOM","LBY"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Israel.","kind":"flag"}],"medium":[{"q":"Which violinist, born in Tel Aviv in 1945, became a celebrated soloist after a childhood bout of polio?","a":"Itzhak Perlman","o":["Itzhak Perlman","Jascha Heifetz","Pinchas Zukerman","Yehudi Menuhin"],"f":"He uses crutches or a scooter to reach the chair and then plays seated. Heifetz and Menuhin were born in the Russian Empire and in New York."},{"q":"The Dead Sea shore is the lowest dry land on Earth. Its water is famous for being so salty that a swimmer does what?","a":"Floats with little effort","o":["Floats with little effort","Sinks faster than in the ocean","Can drink it safely","Sees it freeze in summer"],"f":"The salt is several times that of the ocean, so the water is dense. The surface has been falling as rivers are diverted and minerals are extracted."},{"q":"In 73 or 74 CE, after a Roman siege, the last defenders of a desert fortress killed themselves rather than be enslaved. Which fortress?","a":"Masada","o":["Masada","Herodium","Megiddo","Beersheba"],"f":"The story comes mainly from the historian Josephus. Archaeologists found the Roman ramp still leaning against the cliff."},{"q":"Which city is home to the Knesset and the Supreme Court of Israel?","a":"Jerusalem","o":["Jerusalem","Bishkek","Beirut","Dhaka"],"f":"The Knesset and the Supreme Court sit in Jerusalem. Many embassies are in Tel Aviv.","kind":"capital"},{"q":"Which of these flags belongs to Israel?","a":"ISR","o":["ISR","SAU","THA","SGP"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Israel.","kind":"flag"}],"hard":[{"q":"Which valley of ancient copper mines in the southern desert is a park of red pillars?","a":"Timna","o":["Timna","Ein Gedi","Qumran","The Galilee caves"],"f":"Timna holds shafts and smelting sites from several ancient periods. A natural arch and a small Egyptian shrine stand in the park."},{"q":"Hummus, a paste of chickpeas and tahini, is eaten with which sauce of ground sesame?","a":"Tahini is in it","o":["Tahini is in it","Amba","Zhug","Schug only"],"f":"Chickpeas, tahini, lemon, and garlic are the base. Olive oil is poured on top."},{"q":"The Hebrew revival of the late 1800s turned a liturgical language into daily speech largely through whose efforts?","a":"Eliezer Ben-Yehuda","o":["Eliezer Ben-Yehuda","Theodor Herzl","Maimonides","Rashi"],"f":"Ben-Yehuda compiled a dictionary and raised his son in Hebrew. The project was part of a wider cultural movement."},{"q":"Which of these cities holds the Knesset and the Supreme Court of Israel?","a":"Jerusalem","o":["Jerusalem","Tel Aviv","Haifa","Beersheba"],"f":"The Knesset and the Supreme Court sit in Jerusalem. Many embassies are in Tel Aviv.","kind":"capital"},{"q":"Which flag is the flag of Israel?","a":"ISR","o":["ISR","UKR","ALB","IRL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Israel.","kind":"flag"}]}},{"id":"ITA","name":"Italy","cont":"Europe","emoji":"🇮🇹","latlng":[42.83333333,12.83333333],"q":{"easy":[{"q":"Which ancient amphitheater in Rome hosted gladiator shows and could be flooded for naval games?","a":"The Colosseum","o":["The Colosseum","The Circus Maximus","The Pantheon","The Forum"],"f":"The Colosseum opened in 80 CE under the Flavian emperors. Much of its stone was later reused in other buildings."},{"q":"Which dough of flour and egg, cut into shapes and boiled, is a national staple?","a":"Pasta","o":["Pasta","Rice","Bread only","Polenta only"],"f":"Dried pasta of durum wheat travels well. Regions argue over shapes and sauces."},{"q":"Which artist painted the Mona Lisa and designed machines in notebooks?","a":"Leonardo da Vinci","o":["Leonardo da Vinci","Michelangelo","Raphael","Caravaggio"],"f":"Leonardo was born in Vinci in 1452. He worked in Florence, Milan, and finally France."},{"q":"Which city is the capital of Italy?","a":"Rome","o":["Rome","Algiers","Kabul","Dodoma"],"f":"Rome is the capital of Italy.","kind":"capital"},{"q":"Which flag belongs to Italy?","a":"ITA","o":["ITA","IDN","CRI","VUT"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Italy.","kind":"flag"}],"medium":[{"q":"Which scientist, born in Pisa in 1564, used a telescope to see Jupiter's moons and defended the idea that Earth moves around the Sun?","a":"Galileo Galilei","o":["Galileo Galilei","Nicolaus Copernicus","Johannes Kepler","Giordano Bruno"],"f":"Copernicus was Polish and Kepler German; Galileo brought the new astronomy into public view in Italian. The Inquisition forced him to recant in 1633, and he spent his last years under house arrest."},{"q":"In 79 CE Mount Vesuvius buried Pompeii under a surge of hot gas and stone. The city was a Roman town near which modern city?","a":"Naples","o":["Naples","Rome","Florence","Venice"],"f":"Ash preserved bakeries, graffiti, and the holes where bodies had been. Plaster casts made from those holes show people as they fell."},{"q":"Modern Italy became a single kingdom in 1861, but Rome joined only in 1870. Before that, the peninsula was what?","a":"A patchwork of separate states","o":["A patchwork of separate states","One empire ruled from Constantinople","A French province","A single republic since ancient times"],"f":"Piedmont-Sardinia led the unification, with Garibaldi's volunteers in the south. The pope lost Rome and did not recognize the new state until the Lateran Treaty of 1929."},{"q":"What is the capital city of Italy?","a":"Rome","o":["Rome","Amsterdam","Bucharest","Copenhagen"],"f":"Rome is the capital of Italy.","kind":"capital"},{"q":"Which of these flags belongs to Italy?","a":"ITA","o":["ITA","MNE","LUX","NOR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Italy.","kind":"flag"}],"hard":[{"q":"The Leaning Tower stands beside the cathedral of which Tuscan city?","a":"Pisa","o":["Pisa","Florence","Siena","Lucca"],"f":"The bell tower began to lean during construction in the 1100s because the ground is soft clay."},{"q":"Which volcano on Sicily is the highest and most active in Europe?","a":"Mount Etna","o":["Mount Etna","Vesuvius","Stromboli","Fuji"],"f":"Etna erupts often. Its lava soils grow pistachios, vines, and citrus on the lower slopes."},{"q":"The commedia dell'arte used stock characters and which face covering?","a":"Masks","o":["Masks","Helmets","Veils","Crowns"],"f":"Troupes improvised from scenarios. Characters such as Arlecchino wore leather masks."},{"q":"Which of these cities is the capital of Italy?","a":"Rome","o":["Rome","Milan","Naples","Florence"],"f":"Rome is the capital of Italy.","kind":"capital"},{"q":"Which flag is the flag of Italy?","a":"ITA","o":["ITA","CIV","IRL","MEX"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Italy.","kind":"flag"}]}},{"id":"JAM","name":"Jamaica","cont":"North America","emoji":"🇯🇲","latlng":[18.25,-77.5],"q":{"easy":[{"q":"Which coffee and a famous seasoned grilled chicken are national flavors?","a":"Jerk chicken","o":["Jerk chicken","Ackee is the other","Curry goat","Festival"],"f":"Jerk is meat rubbed with allspice and scotch bonnet and smoked over pimento wood."},{"q":"Which genre, with an offbeat guitar chop, grew in Kingston in the 1960s?","a":"Reggae","o":["Reggae","Ska only earlier","Dancehall later","Calypso"],"f":"Reggae slowed rocksteady. Bob Marley and the Wailers carried it worldwide in the 1970s."},{"q":"Which blue-green mountain range rises behind the capital?","a":"The Blue Mountains","o":["The Blue Mountains","The John Crow","The Cockpit Country","The Santa Cruz"],"f":"Blue Mountain coffee grows on the cool slopes. The main peak is the island's highest."},{"q":"Which city is the capital of Jamaica?","a":"Kingston","o":["Kingston","Gaborone","Yaren","Podgorica"],"f":"Kingston is the capital of Jamaica.","kind":"capital"},{"q":"Which flag belongs to Jamaica?","a":"JAM","o":["JAM","CYP","IND","IRL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Jamaica.","kind":"flag"}],"medium":[{"q":"Which organizer, born in St. Ann's Bay in 1887, founded the Universal Negro Improvement Association?","a":"Marcus Garvey","o":["Marcus Garvey","Martin Luther King Jr.","W. E. B. Du Bois","Nelson Mandela"],"f":"He urged people of African descent worldwide to take pride in their history and build their own institutions. Jamaica named him its first national hero."},{"q":"Blue Mountain coffee is grown on steep slopes in the east of the island. The range is named for the blue haze, and the beans are known for what?","a":"A mild flavor and high price","o":["A mild flavor and high price","Being naturally caffeine-free","Growing under snow","A bitter smoked taste"],"f":"Cool mist and rich soil slow the ripening of the cherries. Japan has long been one of the biggest buyers of the certified beans."},{"q":"In the 1700s communities of escaped enslaved people, the Maroons, forced Britain to sign peace treaties. Which Maroon leader is a national hero?","a":"Queen Nanny","o":["Queen Nanny","Nzinga","Harriet Tubman","Yaa Asantewaa"],"f":"Nanny Town, in the Blue Mountains, was a Maroon stronghold. The treaties gave the Maroons land and a degree of self-rule."},{"q":"What is the capital city of Jamaica?","a":"Kingston","o":["Kingston","Santo Domingo","Roseau","Ottawa"],"f":"Kingston is the capital of Jamaica.","kind":"capital"},{"q":"Which of these flags belongs to Jamaica?","a":"JAM","o":["JAM","GTM","NIC","HTI"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Jamaica.","kind":"flag"}],"hard":[{"q":"Which nurse, born in Kingston in 1805, cared for soldiers during the Crimean War?","a":"Mary Seacole","o":["Mary Seacole","Florence Nightingale","Clara Barton","Edith Cavell"],"f":"Mary Seacole traveled at her own expense and ran a British Hotel near the front. Her memoir appeared in 1857."},{"q":"The Maroons, escaped enslaved communities, signed treaties in the 1700s from which mountain villages?","a":"Accompong and Moore Town","o":["Accompong and Moore Town","Kingston","Montego Bay","Port Royal"],"f":"The treaties recognized Maroon land. Moore Town's drumming and Kromanti language are a UNESCO heritage."},{"q":"Port Royal, once a pirate capital, sank in which 1692 disaster?","a":"An earthquake","o":["An earthquake","A hurricane only","A volcanic eruption","A tidal wave from Lisbon"],"f":"Much of the town slid into the harbor. It had been the busiest English port in the Caribbean."},{"q":"Which of these cities is the capital of Jamaica?","a":"Kingston","o":["Kingston","Montego Bay","Spanish Town","Mandeville"],"f":"Kingston is the capital of Jamaica.","kind":"capital"},{"q":"Which flag is the flag of Jamaica?","a":"JAM","o":["JAM","TUR","LBN","GEO"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Jamaica.","kind":"flag"}]}},{"id":"JOR","name":"Jordan","cont":"Asia","emoji":"🇯🇴","latlng":[31,36],"q":{"easy":[{"q":"Which Roman city of colonnaded streets and an oval plaza is north of Amman?","a":"Jerash","o":["Jerash","Petra","Philadelphia","Palmyra"],"f":"Jerash, ancient Gerasa, is one of the best-preserved Roman cities of the region. Chariot ruts mark the stones."},{"q":"Which lamb cooked in fermented dried yogurt, served with rice, is the national dish?","a":"Mansaf","o":["Mansaf","Maqluba","Kabsa","Ouzi"],"f":"Mansaf is the dish of hospitality. The yogurt sauce, jameed, is sharp and rich."},{"q":"Which salty lake on the western border is the lowest land surface on Earth?","a":"The Dead Sea","o":["The Dead Sea","The Caspian","Lake Assal","The Sea of Galilee"],"f":"The Dead Sea is shared with Israel and the West Bank. Swimmers float because the water is extremely salty."},{"q":"Which city is the capital of Jordan?","a":"Amman","o":["Amman","Sarajevo","Amsterdam","Maseru"],"f":"Amman is the capital of Jordan.","kind":"capital"},{"q":"Which flag belongs to Jordan?","a":"JOR","o":["JOR","BEL","BDI","MEX"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Jordan.","kind":"flag"}],"medium":[{"q":"Petra's most famous facade, Al-Khazneh, was carved from the cliff by which ancient people?","a":"The Nabataeans","o":["The Nabataeans","The Romans","The Pharaohs","The Persians"],"f":"They grew rich taxing the incense caravans. The name Treasury is a later legend about a pharaoh's gold, not the building's real use."},{"q":"In 1812 a Swiss traveler entered Petra disguised as a pilgrim and became the first European in centuries to describe it. Who was he?","a":"Johann Ludwig Burckhardt","o":["Johann Ludwig Burckhardt","Richard Burton","Ibn Battuta","Gertrude Bell"],"f":"He had learned Arabic and traveled as Sheikh Ibrahim. His notes revealed the city to European scholars, though local people had never forgotten it."},{"q":"Wadi Rum is a desert of sandstone mountains. Film crews use it because the red sand and cliffs can stand in for what?","a":"The surface of Mars","o":["The surface of Mars","The Amazon rainforest","The Alps","A coral reef"],"f":"Scenes in The Martian and earlier films were shot there. The valley is also full of ancient rock carvings and Bedouin camps."},{"q":"What is the capital city of Jordan?","a":"Amman","o":["Amman","Bandar Seri Begawan","Kabul","Jakarta"],"f":"Amman is the capital of Jordan.","kind":"capital"},{"q":"Which of these flags belongs to Jordan?","a":"JOR","o":["JOR","TLS","TUR","AFG"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Jordan.","kind":"flag"}],"hard":[{"q":"Which rose-red Nabataean city is carved into sandstone cliffs?","a":"Petra","o":["Petra","Hegra","Palmyra","Baalbek"],"f":"Petra was the Nabataean capital. The Treasury facade is a tomb cut from the cliff."},{"q":"A UNESCO reserve of desert wilderness and rock bridges south of the capital region is called what?","a":"Wadi Rum","o":["Wadi Rum","The Empty Quarter","The Negev","Sinai"],"f":"Wadi Rum's sandstone mountains were a route for caravans. T. E. Lawrence wrote about passing through."},{"q":"Which black iris is the national flower?","a":"The black iris","o":["The black iris","The tulip","The rose","The lotus"],"f":"Iris nigricans grows in the hills in spring. It appears in art and on stamps."},{"q":"Which of these cities is the capital of Jordan?","a":"Amman","o":["Amman","Zarqa","Irbid","Aqaba"],"f":"Amman is the capital of Jordan.","kind":"capital"},{"q":"Which flag is the flag of Jordan?","a":"JOR","o":["JOR","SDN","PSE","KWT"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Jordan.","kind":"flag"}]}},{"id":"JPN","name":"Japan","cont":"Asia","emoji":"🇯🇵","latlng":[36,138],"q":{"easy":[{"q":"Which pink blossoms are watched in parks each spring in a custom called hanami?","a":"Cherry blossoms","o":["Cherry blossoms","Plum blossoms only","Lotus","Wisteria"],"f":"Hanami picnics sit under sakura trees. Forecasts track the bloom from south to north."},{"q":"Which vinegared rice with fish or vegetables is a national dish known worldwide?","a":"Sushi","o":["Sushi","Sashimi only","Tempura","Ramen"],"f":"Sushi refers to the seasoned rice. Nigiri places a slice of fish on a small rice block."},{"q":"Which high-speed trains, begun in 1964 between Tokyo and Osaka, are a national symbol?","a":"The shinkansen","o":["The shinkansen","The TGV","The ICE","The maglev only"],"f":"The first line opened for the Tokyo Olympics. Trains are famous for punctuality."},{"q":"Which city is the capital of Japan?","a":"Tokyo","o":["Tokyo","South Tarawa","San Marino","Gitega"],"f":"Tokyo is the capital of Japan.","kind":"capital"},{"q":"Which flag belongs to Japan?","a":"JPN","o":["JPN","BIH","VEN","GMB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Japan.","kind":"flag"}],"medium":[{"q":"Which physicist, born in Tokyo, predicted a particle later called the meson and won the 1949 Nobel Prize?","a":"Hideki Yukawa","o":["Hideki Yukawa","Shinichiro Tomonaga","Leo Esaki","Richard Feynman"],"f":"He proposed the particle in 1935 to explain how the nucleus holds together. Tomonaga, also Japanese, shared a later Nobel for other work in physics."},{"q":"Mount Fuji, a cone visible from far across the Kanto plain, last erupted in which year?","a":"1707","o":["1707","1868","1923","1945"],"f":"The Hoei eruption threw ash as far as Edo, now Tokyo. The mountain is a sacred site in both Shinto and Buddhist tradition, and a UNESCO cultural site."},{"q":"In 1868 the Tokugawa shogunate fell and the emperor was restored to the center of politics. That change is called what?","a":"The Meiji Restoration","o":["The Meiji Restoration","The Taisho Democracy","The Genpei War","The Boshin War"],"f":"Meiji means enlightened rule. The Boshin War was the civil war fought during the change, not the name of the new order. Within decades the government built railways, a conscript army, and a constitution."},{"q":"What is the capital city of Japan?","a":"Tokyo","o":["Tokyo","Baku","Kathmandu","Beijing"],"f":"Tokyo is the capital of Japan.","kind":"capital"},{"q":"Which of these flags belongs to Japan?","a":"JPN","o":["JPN","SGP","THA","SYR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Japan.","kind":"flag"}],"hard":[{"q":"Which novel of the early 1000s, by Murasaki Shikibu, is often called the world's first novel?","a":"The Tale of Genji","o":["The Tale of Genji","The Pillow Book","The Manyoshu","Heike"],"f":"The Tale of Genji follows court life in the Heian period. It was written by a lady-in-waiting."},{"q":"The tea ceremony, chanoyu, uses which powdered green tea?","a":"Matcha","o":["Matcha","Sencha","Hojicha","Bancha"],"f":"Whisked matcha is served in a quiet room with set gestures. Sen no Rikyu shaped the form in the 1500s."},{"q":"Which castle on Shikoku, rebuilt several times, has a famous white keep over the sea?","a":"Matsuyama Castle","o":["Matsuyama Castle","Himeji","Osaka","Nagoya"],"f":"Matsuyama's hill castle looks over the city and the Seto Inland Sea. Himeji, the white heron, is the most famous keep."},{"q":"Which of these cities is the capital of Japan?","a":"Tokyo","o":["Tokyo","Osaka","Kyoto","Hiroshima"],"f":"Tokyo is the capital of Japan.","kind":"capital"},{"q":"Which flag is the flag of Japan?","a":"JPN","o":["JPN","BGD","PLW","LAO"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Japan.","kind":"flag"}]}},{"id":"KAZ","name":"Kazakhstan","cont":"Asia","emoji":"🇰🇿","latlng":[48,68],"q":{"easy":[{"q":"Which red-rock canyon east of Almaty is a famous hiking landscape?","a":"Charyn Canyon","o":["Charyn Canyon","The Grand Canyon","Tara","Fish River"],"f":"Charyn's Valley of Castles is a maze of sedimentary towers. A river runs at the bottom."},{"q":"Which dish of boiled meat and noodles, eaten with the hand, is a national meal?","a":"Beshbarmak","o":["Beshbarmak","Plov","Laghman","Manti"],"f":"Beshbarmak means five fingers. Horse or mutton is served over wide noodles."},{"q":"Which fermented mare's milk is the traditional drink of the steppe?","a":"Kumis","o":["Kumis","Ayran","Kefir","Ay ran"],"f":"Kumis is slightly sour and mildly fizzy. It is passed at feasts in a bowl."},{"q":"Which city is the capital of Kazakhstan?","a":"Astana","o":["Astana","Tripoli","Paramaribo","Djibouti"],"f":"Astana is the capital. Almaty was the capital until 1997, and the city was called Nur-Sultan from 2019 to 2022.","kind":"capital"},{"q":"Which flag belongs to Kazakhstan?","a":"KAZ","o":["KAZ","VUT","LUX","IRL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Kazakhstan.","kind":"flag"}],"medium":[{"q":"Wild apple forests in the Tian Shan are the main ancestor of the apples sold in supermarkets. Botanists call that wild apple what?","a":"Malus sieversii","o":["Malus sieversii","Malus sylvestris","Pyrus communis","Prunus armeniaca"],"f":"Malus sieversii still grows in the mountains of the southeast. Genetic studies show that domestic apples descend chiefly from it. Malus sylvestris is the European crab apple, a lesser contributor."},{"q":"Yuri Gagarin's 1961 flight left Earth from a cosmodrome on the steppe that is leased to Russia. What is the site called?","a":"Baikonur","o":["Baikonur","Plesetsk","Cape Canaveral","Jiuquan"],"f":"The town of Baikonur was a decoy name; the pads are nearer the settlement once called Leninsk. The lease to Russia runs well into the 21st century."},{"q":"A burial found at Issyk in 1969 held a young warrior covered in thousands of gold pieces. The figure is known as what?","a":"The Golden Man","o":["The Golden Man","The Golden Fleece","The Amber Prince","The Jade Emperor"],"f":"The costume is Saka, from the Iron Age nomads of the steppe. A copy of the tall headdress became a national symbol."},{"q":"What is the capital city of Kazakhstan?","a":"Astana","o":["Astana","Amman","Doha","Naypyidaw"],"f":"Astana is the capital. Almaty was the capital until 1997, and the city was called Nur-Sultan from 2019 to 2022.","kind":"capital"},{"q":"Which of these flags belongs to Kazakhstan?","a":"KAZ","o":["KAZ","IND","KGZ","SAU"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Kazakhstan.","kind":"flag"}],"hard":[{"q":"The Golden Man, a Scythian or Saka burial, was found in 1969 in which kind of grave?","a":"A kurgan mound","o":["A kurgan mound","A pyramid","A ship","A cave"],"f":"The Issyk kurgan held a young person in a suit of gold plaques. The find became a national symbol."},{"q":"Which two-string lute accompanies epic songs and instrumental kui?","a":"The dombra","o":["The dombra","The komuz","The saz","The oud"],"f":"The dombra is played with the fingers. Singers recite long poems to it, and short instrumental pieces are called kui."},{"q":"Apple forests around Almaty hold wild ancestors of which fruit?","a":"The domestic apple","o":["The domestic apple","The orange","The banana","The mango"],"f":"Malus sieversii in the Tian Shan is a wild apple. Genetic studies tie it to the fruit grown worldwide."},{"q":"Which of these cities is the capital of Kazakhstan?","a":"Astana","o":["Astana","Almaty","Shymkent","Karaganda"],"f":"Astana is the capital. Almaty was the capital until 1997, and the city was called Nur-Sultan from 2019 to 2022.","kind":"capital"},{"q":"Which flag is the flag of Kazakhstan?","a":"KAZ","o":["KAZ","UKR","SWE","KEN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Kazakhstan.","kind":"flag"}]}},{"id":"KEN","name":"Kenya","cont":"Africa","emoji":"🇰🇪","latlng":[1,38],"q":{"easy":[{"q":"Which famous reserve of lions and wildebeest lies along the Tanzanian border in southwestern Kenya?","a":"The Maasai Mara","o":["The Maasai Mara","Kruger","Etosha","The Serengeti"],"f":"The Maasai Mara is the northern continuation of the Serengeti ecosystem. The great migration crosses into it."},{"q":"Which stiff maize porridge is eaten daily across Kenya?","a":"Ugali","o":["Ugali","Sushi","Risotto","Fondue"],"f":"Ugali is maize flour stirred into a firm dough. It is pinched off and used to scoop stew."},{"q":"Which lake in the Rift Valley is known for huge flocks of flamingos?","a":"Lake Nakuru","o":["Lake Nakuru","Lake Baikal","Lake Superior","Lake Geneva"],"f":"Algae in the alkaline water feed lesser flamingos. Their pink flocks cover the shallows in good years."},{"q":"Which city is the capital of Kenya?","a":"Nairobi","o":["Nairobi","Quito","Chișinău","Vienna"],"f":"Nairobi is the capital of Kenya.","kind":"capital"},{"q":"Which flag belongs to Kenya?","a":"KEN","o":["KEN","QAT","KWT","ARE"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Kenya.","kind":"flag"}],"medium":[{"q":"Which environmentalist, born in Nyeri in 1940, founded the Green Belt Movement and won the Nobel Peace Prize in 2004?","a":"Wangarĩ Maathai","o":["Wangarĩ Maathai","Rigoberta Menchú","Shirin Ebadi","Malala Yousafzai"],"f":"Rural women planted trees against erosion and defended public forests. Menchú, Ebadi, and Yousafzai are laureates from Guatemala, Iran, and Pakistan."},{"q":"The second-highest peak in Africa, after Kilimanjaro, stands in this country. It is an old what?","a":"Volcano","o":["Volcano","Sandstone fold","Meteor crater","Coral plateau"],"f":"The highest summit is Batian, on Mount Kenya. Glaciers there have been shrinking, so this question does not ask you to count them. Kilimanjaro is across the border in Tanzania."},{"q":"A 1950s revolt against British rule and land losses, strongest among Kikuyu fighters, is known as what?","a":"The Mau Mau uprising","o":["The Mau Mau uprising","The Maji Maji war","The Herero war","The Anglo-Zulu war"],"f":"The British held many people in camps. Independence came in 1963 under Jomo Kenyatta. Maji Maji was in German East Africa, and the Herero war was in German South West Africa."},{"q":"What is the capital city of Kenya?","a":"Nairobi","o":["Nairobi","Libreville","Gitega","Asmara"],"f":"Nairobi is the capital of Kenya.","kind":"capital"},{"q":"Which of these flags belongs to Kenya?","a":"KEN","o":["KEN","GNB","BDI","SDN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Kenya.","kind":"flag"}],"hard":[{"q":"The Kikuyu, the largest community, call the fig and highland forest sacred in which traditional belief?","a":"A world of ancestral spirits","o":["A world of ancestral spirits","Shinto kami of Japan","Norse gods","Olympian gods"],"f":"Mugumo fig trees were shrines. Many people now also belong to Christian churches."},{"q":"Which Indian Ocean port, with an old town of carved doors, was a Swahili trading city?","a":"Mombasa","o":["Mombasa","Dakar","Casablanca","Cape Town"],"f":"Mombasa's Old Town and Fort Jesus recall centuries of Indian Ocean trade in ivory, gold, and cloves."},{"q":"Long-distance running became a national passion. The training camps in the Rift are especially around which town?","a":"Iten","o":["Iten","Mombasa","Kisumu","Garissa"],"f":"Iten sits high above the Rift. Runners train on its dirt roads and at St. Patrick's school."},{"q":"Which of these cities is the capital of Kenya?","a":"Nairobi","o":["Nairobi","Mombasa","Kisumu","Nakuru"],"f":"Nairobi is the capital of Kenya.","kind":"capital"},{"q":"Which flag is the flag of Kenya?","a":"KEN","o":["KEN","BRN","CMR","TLS"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Kenya.","kind":"flag"}]}},{"id":"KGZ","name":"Kyrgyzstan","cont":"Asia","emoji":"🇰🇬","latlng":[41,75],"q":{"easy":[{"q":"Which mountain range, the Celestial Mountains, forms much of the country's spine?","a":"The Tian Shan","o":["The Tian Shan","The Pamirs only","The Altai","The Urals"],"f":"The Tian Shan holds Peak Pobeda and Khan Tengri. Glaciers feed the rivers of the valleys."},{"q":"Which hand-pulled noodles with pepper and meat are a daily dish?","a":"Laghman","o":["Laghman","Ramen","Pho","Spaghetti"],"f":"Laghman is boiled noodles with a stir-fried topping. It is shared across Central Asian kitchens."},{"q":"Which felt carpet with a spiral or horn pattern is a Kyrgyz craft?","a":"The shyrdak","o":["The shyrdak","The kilim","Persian Tabriz","A Navajo rug"],"f":"Two layers of felt are cut and pressed so the pattern shows on both sides. Shyrdaks cover the yurt floor."},{"q":"Which city is the capital of Kyrgyzstan?","a":"Bishkek","o":["Bishkek","Malabo","Skopje","Roseau"],"f":"Bishkek is the capital of Kyrgyzstan.","kind":"capital"},{"q":"Which flag belongs to Kyrgyzstan?","a":"KGZ","o":["KGZ","PRY","MLI","AUT"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Kyrgyzstan.","kind":"flag"}],"medium":[{"q":"Which novelist, born in Sheker, wrote Jamila and The Day Lasts More Than a Hundred Years?","a":"Chingiz Aitmatov","o":["Chingiz Aitmatov","Leo Tolstoy","Orhan Pamuk","Naguib Mahfouz"],"f":"He wrote in both Kyrgyz and Russian and brought nomadic life to readers abroad. Jamila, a love story set in a wartime village, was praised by Louis Aragon."},{"q":"The Manas epic, recited by specialist bards, tells of a hero who unites the tribes. Those bards are called what?","a":"Manaschi","o":["Manaschi","Akyns","Ashiks","Griots"],"f":"A full recitation can last many hours, and some versions run to hundreds of thousands of lines. UNESCO lists the epic as intangible heritage."},{"q":"Issyk-Kul is a huge mountain lake that rarely freezes. The main reason is that the water is what?","a":"Slightly salty","o":["Slightly salty","Heated by a volcano","Covered in oil","Stirred by ships"],"f":"The name means hot lake, though the water is cold. It has no outlet, so minerals stay behind as water evaporates."},{"q":"What is the capital city of Kyrgyzstan?","a":"Bishkek","o":["Bishkek","Jakarta","Thimphu","Singapore"],"f":"Bishkek is the capital of Kyrgyzstan.","kind":"capital"},{"q":"Which of these flags belongs to Kyrgyzstan?","a":"KGZ","o":["KGZ","BGD","TKM","NPL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Kyrgyzstan.","kind":"flag"}],"hard":[{"q":"The epic of Manas is recited by a singer called what?","a":"A manaschi","o":["A manaschi","A griot","An ashik","A bard of only Wales"],"f":"Manaschi memorize tens of thousands of lines. The epic tells of a hero who unites the Kyrgyz."},{"q":"Which large mountain lake in the northeast is slightly salty and never freezes over completely?","a":"Issyk-Kul","o":["Issyk-Kul","Balkhash","Karakul","The Aral"],"f":"Issyk-Kul means warm lake. Hot springs and depth keep parts of it open in winter."},{"q":"Eagle hunting on horseback, a winter hunt for foxes, is practiced in which mountain tradition?","a":"Berkutchy","o":["Berkutchy","Falconry of only Arabia","Hawking in England","Coursing"],"f":"A berkutchi trains a golden eagle. The hunt is a living craft in the high valleys."},{"q":"Which of these cities is the capital of Kyrgyzstan?","a":"Bishkek","o":["Bishkek","Osh","Jalal-Abad","Karakol"],"f":"Bishkek is the capital of Kyrgyzstan.","kind":"capital"},{"q":"Which flag is the flag of Kyrgyzstan?","a":"KGZ","o":["KGZ","MHL","DNK","FRA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Kyrgyzstan.","kind":"flag"}]}},{"id":"KHM","name":"Cambodia","cont":"Asia","emoji":"🇰🇭","latlng":[13,105],"q":{"easy":[{"q":"Which great lake expands and shrinks with the monsoon and feeds a huge fishery?","a":"Tonle Sap","o":["Tonle Sap","The Aral Sea","Lake Baikal","Inle Lake"],"f":"The Tonle Sap river reverses when the Mekong floods, filling the lake. Floating villages move with the water."},{"q":"Which steamed fish curry in banana leaf is a national dish?","a":"Fish amok","o":["Fish amok","Tom yum","Pho","Sushi"],"f":"Amok is coconut fish steamed until it sets. It is served in the leaf with rice."},{"q":"Which royal pagoda in the capital is famous for a floor of silver tiles?","a":"The Silver Pagoda","o":["The Silver Pagoda","Shwedagon","The Temple of the Emerald Buddha","Wat Arun"],"f":"The Silver Pagoda stands inside the Royal Palace grounds. Its floor is covered with silver tiles."},{"q":"Which city is the capital of Cambodia?","a":"Phnom Penh","o":["Phnom Penh","St. George's","Yamoussoukro","Canberra"],"f":"Phnom Penh is the capital of Cambodia.","kind":"capital"},{"q":"Which flag belongs to Cambodia?","a":"KHM","o":["KHM","GTM","VCT","NAM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Cambodia.","kind":"flag"}],"medium":[{"q":"Angkor Wat was built in the 12th century as a temple to Vishnu and later became a Buddhist shrine. Which king began it?","a":"Suryavarman II","o":["Suryavarman II","Jayavarman VII","Norodom Sihanouk","Yasovarman I"],"f":"Jayavarman VII, a later king, built the nearby city of Angkor Thom and the faces of the Bayon. Angkor Wat itself remains the largest religious monument on Earth."},{"q":"Between 1975 and 1979 the Khmer Rouge emptied the cities and renamed the country Democratic Kampuchea. Their leader was who?","a":"Pol Pot","o":["Pol Pot","Norodom Sihanouk","Lon Nol","Hun Sen"],"f":"About a quarter of the population died from execution, hunger, and overwork. The Tuol Sleng prison and the killing fields are now memorials."},{"q":"Classical dancers bend the hands back and tell stories of spirits and kings. That court dance is called what?","a":"Apsara dance","o":["Apsara dance","Kecak","Kathak","Legong"],"f":"The poses copy carvings of heavenly dancers on the temples of Angkor. The tradition was nearly wiped out in the 1970s and later rebuilt by surviving teachers."},{"q":"What is the capital city of Cambodia?","a":"Phnom Penh","o":["Phnom Penh","Tbilisi","Hanoi","Kuala Lumpur"],"f":"Phnom Penh is the capital of Cambodia.","kind":"capital"},{"q":"Which of these flags belongs to Cambodia?","a":"KHM","o":["KHM","IRN","JOR","KOR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Cambodia.","kind":"flag"}],"hard":[{"q":"The temple of Angkor Wat was built in the 1100s as a representation of which mythical mountain?","a":"Mount Meru","o":["Mount Meru","Olympus","Fuji","Sinai"],"f":"The five towers stand for the peaks of Meru, the center of the Hindu cosmos. A moat is the ocean around it."},{"q":"Apsara dancers bend hands and feet in a style carved on which temple walls?","a":"Angkor's bas-reliefs","o":["Angkor's bas-reliefs","Borobudur","The Parthenon","Petra"],"f":"The carvings show celestial dancers. The modern classical dance revived those poses in the 20th century."},{"q":"Which pepper from Kampot, on the coast, is a protected crop with a famous aroma?","a":"Kampot pepper","o":["Kampot pepper","Sichuan pepper","Black pepper of Malabar only","Pink peppercorns"],"f":"Kampot pepper grows on vines near the sea. Its name is legally protected, like a wine region."},{"q":"Which of these cities is the capital of Cambodia?","a":"Phnom Penh","o":["Phnom Penh","Siem Reap","Battambang","Sihanoukville"],"f":"Phnom Penh is the capital of Cambodia.","kind":"capital"},{"q":"Which flag is the flag of Cambodia?","a":"KHM","o":["KHM","CHN","TON","TKM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Cambodia.","kind":"flag"}]}},{"id":"KIR","name":"Kiribati","cont":"Oceania","emoji":"🇰🇮","latlng":[1.41666666,173],"q":{"easy":[{"q":"Which island chain crosses the equator and the date line?","a":"The Gilbert, Phoenix, and Line islands","o":["The Gilbert, Phoenix, and Line islands","The Marshalls","The Carolines","The Cooks"],"f":"Kiribati is the Gilberts plus the Phoenix and Line groups. The country spans all four hemispheres."},{"q":"Which toddy from a cut flower stalk is a daily drink?","a":"Coconut toddy","o":["Coconut toddy","Kava","Beer","Juice"],"f":"Fresh toddy is sweet. Fermented, it becomes sour. It is collected from the coconut palm."},{"q":"Which traditional meeting house is the center of village life?","a":"The maneaba","o":["The maneaba","The bai","The fale","The longhouse"],"f":"The maneaba is a large open hall. Clans have seats along the sides, and decisions are talked through there."},{"q":"Which city is the capital of Kiribati?","a":"South Tarawa","o":["South Tarawa","Lomé","Islamabad","Panama City"],"f":"South Tarawa is the capital of Kiribati.","kind":"capital"},{"q":"Which flag belongs to Kiribati?","a":"KIR","o":["KIR","SEN","SDN","SLV"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Kiribati.","kind":"flag"}],"medium":[{"q":"Kiribati is the only country whose own islands lie in all four of what?","a":"Hemispheres","o":["Hemispheres","Oceans","Climate zones","Continental plates"],"f":"The Gilbert, Phoenix, and Line Islands straddle both the equator and the 180th meridian."},{"q":"The country's name is the local pronunciation of which earlier European name?","a":"The Gilberts","o":["The Gilberts","The Solomons","The Marshalls","The Carolines"],"f":"It is pronounced Kiri-bass. Britain once joined these islands with the Ellice Islands, which later became Tuvalu."},{"q":"Village decisions in Kiribati are debated in an open meeting house called a what?","a":"Maneaba","o":["Maneaba","Bai","Haus tambaran","Langi"],"f":"Where you sit in a maneaba shows your family's role. Speaking out of turn is a serious breach of custom."},{"q":"What is the capital city of Kiribati?","a":"South Tarawa","o":["South Tarawa","Honiara","Palikir","Apia"],"f":"South Tarawa is the capital of Kiribati.","kind":"capital"},{"q":"Which of these flags belongs to Kiribati?","a":"KIR","o":["KIR","VUT","FJI","NRU"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Kiribati.","kind":"flag"}],"hard":[{"q":"Which atoll was mined for phosphate until the deposits were exhausted?","a":"Banaba","o":["Banaba","Tarawa","Kiritimati","Abaiang"],"f":"Banaba, or Ocean Island, was stripped for phosphate in the 20th century. Many Banabans were resettled on Rabi in Fiji."},{"q":"The stick chart, a teaching map of shells and sticks, showed what?","a":"Swells and islands","o":["Swells and islands","The stars only","The winds only","Fishing rights"],"f":"Navigators learned how ocean swells bounce off islands. The charts were memory tools, not carried on every voyage."},{"q":"Tarawa saw a major battle in 1943 between which forces?","a":"The United States and Japan","o":["The United States and Japan","Britain and Germany","Australia and Japan only at Kokoda","New Zealand and Japan"],"f":"The landing at Betio was one of the bloodiest of the Pacific war. Wrecks remain on the reef."},{"q":"Which of these cities is the capital of Kiribati?","a":"South Tarawa","o":["South Tarawa","Betio","Bairiki","Abaiang"],"f":"South Tarawa is the capital of Kiribati.","kind":"capital"},{"q":"Which flag is the flag of Kiribati?","a":"KIR","o":["KIR","UGA","ZWE","MWI"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Kiribati.","kind":"flag"}]}},{"id":"KNA","name":"Saint Kitts and Nevis","cont":"North America","emoji":"🇰🇳","latlng":[17.33333333,-62.75],"q":{"easy":[{"q":"Which railway, built to move sugar, is now a scenic tourist ride around the main island?","a":"The St. Kitts Scenic Railway","o":["The St. Kitts Scenic Railway","The Panama Railway","The Demerara railway","A funicular"],"f":"The narrow-gauge line circles the island. A tourist train uses the old cane route."},{"q":"Which Sunday plate stews salted cod with a Pacific fruit?","a":"Saltfish and breadfruit","o":["Saltfish and breadfruit","Ackee","Fungee","Cou-cou"],"f":"Salt cod, tomatoes, and peppers are stewed and served with boiled breadfruit or dumplings."},{"q":"Which fortress on a hill above the capital harbor was a British stronghold?","a":"Brimstone Hill","o":["Brimstone Hill","Shirley Heights","The Citadelle","Nelson's Dockyard"],"f":"Brimstone Hill is a UNESCO fortress of black volcanic stone. It was called the Gibraltar of the West Indies."},{"q":"Which city is the capital of Saint Kitts and Nevis?","a":"Basseterre","o":["Basseterre","Oslo","Vatican City","Ashgabat"],"f":"Basseterre is the capital of Saint Kitts and Nevis.","kind":"capital"},{"q":"Which flag belongs to Saint Kitts and Nevis?","a":"KNA","o":["KNA","KOR","RUS","PER"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Saint Kitts and Nevis.","kind":"flag"}],"medium":[{"q":"Which singer and guitarist, born in Basseterre in 1950, moved to England as a child and wrote Love and Affection?","a":"Joan Armatrading","o":["Joan Armatrading","Tracy Chapman","Nina Simone","Miriam Makeba"],"f":"She was seven when the family settled in Birmingham. Her self-titled 1976 album made her an international songwriter."},{"q":"Brimstone Hill Fortress, a UNESCO site, was built by enslaved Africans to British designs. It guarded which island?","a":"St. Kitts","o":["St. Kitts","Barbados","Jamaica","Bermuda"],"f":"The citadel sits about 230 meters up a volcanic hill. France captured it once, in 1782, and Britain took it back the next year."},{"q":"St. Kitts, settled by the English in 1623, is often called the mother colony of which empire's Caribbean?","a":"The British Empire","o":["The British Empire","The Dutch Empire","The Portuguese Empire","The Swedish Empire"],"f":"From here, English settlers went on to other islands. France also colonized part of St. Kitts until the 1713 Treaty of Utrecht."},{"q":"What is the capital city of Saint Kitts and Nevis?","a":"Basseterre","o":["Basseterre","Washington, D.C.","Managua","Belmopan"],"f":"Basseterre is the capital of Saint Kitts and Nevis.","kind":"capital"},{"q":"Which of these flags belongs to Saint Kitts and Nevis?","a":"KNA","o":["KNA","ATG","CRI","HTI"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Saint Kitts and Nevis.","kind":"flag"}],"hard":[{"q":"Which smaller island, with a volcanic peak and a quiet town at Charlestown, shares the federation?","a":"The smaller island of the pair","o":["The smaller island of the pair","Barbuda","Anguilla","Montserrat"],"f":"It has its own island assembly. A bathhouse from the 1700s recalls a brief spa fashion."},{"q":"The Battle of Frigate Bay in 1782 was fought between which two empires?","a":"Britain and France","o":["Britain and France","Spain and the Dutch","The United States and Spain","Portugal and Britain"],"f":"France besieged Brimstone Hill and took it, then returned the islands in the postwar peace."},{"q":"Which sugar windmills, now roofless towers, dot the cane fields?","a":"Stone windmill towers","o":["Stone windmill towers","Dutch polders","Aqueducts","Lighthouses only"],"f":"Plantations crushed cane with wind power. The towers remain after the industry faded."},{"q":"Which of these cities is the capital of Saint Kitts and Nevis?","a":"Basseterre","o":["Basseterre","Charlestown","Cayon","Dieppe Bay"],"f":"Basseterre is the capital of Saint Kitts and Nevis.","kind":"capital"},{"q":"Which flag is the flag of Saint Kitts and Nevis?","a":"KNA","o":["KNA","ZMB","LKA","LBY"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Saint Kitts and Nevis.","kind":"flag"}]}},{"id":"KOR","name":"South Korea","cont":"Asia","emoji":"🇰🇷","latlng":[37,127.5],"q":{"easy":[{"q":"Which sweet-soy beef barbecue is a restaurant favorite?","a":"Bulgogi","o":["Bulgogi","Galbi","Samgyeopsal","Japchae"],"f":"Bulgogi is thinly sliced beef marinated with soy, sugar, and pear, then grilled."},{"q":"Which volcanic island of women divers and basalt cliffs lies south of the peninsula?","a":"Jeju","o":["Jeju","Ulleung","Ganghwa","Geoje"],"f":"Jeju's haenyeo dive for shellfish. The island's basalt tube, Manjanggul, is a UNESCO site along with the divers."},{"q":"Which traditional dress of a jacket and high skirt, or a vest and trousers, is worn on holidays?","a":"The hanbok","o":["The hanbok","The kimono","The ao dai","The sari"],"f":"A hanbok uses bright silk and a ribbon tie. Modern versions appear at weddings and New Year."},{"q":"Which city is the capital of South Korea?","a":"Seoul","o":["Seoul","Chișinău","Nairobi","Harare"],"f":"Seoul is the capital of South Korea.","kind":"capital"},{"q":"Which flag belongs to South Korea?","a":"KOR","o":["KOR","CHE","MOZ","ZWE"],"f":"Compare the colors and symbols. One of these four flags is the national flag of South Korea.","kind":"flag"}],"medium":[{"q":"King Sejong's scholars announced a simple phonetic alphabet in 1446 so that ordinary people could read. What is it called?","a":"Hangul","o":["Hangul","Hanja","Kana","Katakana"],"f":"Before Hangul, writing used Chinese characters, which took years to learn. The shapes of Hangul were designed from how the mouth makes each sound."},{"q":"In 1377 monks at Heungdeok Temple printed a Buddhist book with movable metal type. It is older than Gutenberg's Bible. What is the book called?","a":"Jikji","o":["Jikji","The Tripitaka Koreana","The Diamond Sutra of Dunhuang","The Analects"],"f":"The surviving volume is kept in Paris. The Tripitaka Koreana, carved on wooden blocks at Haeinsa, is a different and also famous project."},{"q":"Admiral Yi Sun-sin, born in Seoul in 1545, defended the coast with armored ships nicknamed what?","a":"Turtle ships","o":["Turtle ships","Dragon ships","Fire ships","Junks"],"f":"During the Japanese invasions of the 1590s his fleets won battles even when badly outnumbered. He was killed at the moment of victory in 1598."},{"q":"What is the capital city of South Korea?","a":"Seoul","o":["Seoul","Tehran","Bandar Seri Begawan","Doha"],"f":"Seoul is the capital of South Korea.","kind":"capital"},{"q":"Which of these flags belongs to South Korea?","a":"KOR","o":["KOR","KGZ","CHN","AFG"],"f":"Compare the colors and symbols. One of these four flags is the national flag of South Korea.","kind":"flag"}],"hard":[{"q":"Ondol heating runs hot smoke through channels under what?","a":"The floor","o":["The floor","The roof","The walls only","A stove in the center"],"f":"Rooms stay warm from the floor up. The system shaped the custom of sitting and sleeping low."},{"q":"Pansori is a long narrative song performed by a singer and which drummer?","a":"A buk drummer","o":["A buk drummer","A full orchestra","A piano","A gayageum only"],"f":"A pansori singer may perform for hours. The drummer calls out encouragement. UNESCO lists the form."},{"q":"The Seokguram grotto and Bulguksa temple, from the 700s, stand near which city?","a":"Gyeongju","o":["Gyeongju","Seoul","Busan","Jeonju"],"f":"Gyeongju was the capital of Silla. The granite Buddha of Seokguram looks out from a cave of fitted stone."},{"q":"Which of these cities is the capital of South Korea?","a":"Seoul","o":["Seoul","Busan","Incheon","Daegu"],"f":"Seoul is the capital of South Korea.","kind":"capital"},{"q":"Which flag is the flag of South Korea?","a":"KOR","o":["KOR","AND","PAK","MRT"],"f":"Compare the colors and symbols. One of these four flags is the national flag of South Korea.","kind":"flag"}]}},{"id":"KWT","name":"Kuwait","cont":"Asia","emoji":"🇰🇼","latlng":[29.5,45.75],"q":{"easy":[{"q":"Which spiced rice with meat and dried lime is the celebration dish?","a":"Machboos","o":["Machboos","Mansaf","Harees","Tharid"],"f":"Machboos is rice cooked with meat, onion, and dried black lime. It is the dish families serve for guests."},{"q":"Which wooden lateen-sailed ship carried gulf trade and pearling crews?","a":"A boom dhow","o":["A boom dhow","A junk","A felucca","A longship"],"f":"Shipwrights built these boats by eye from teak. The lateen sail still appears in heritage races."},{"q":"Which old market lane in the capital grew up around the town wells?","a":"Mubarakiya","o":["Mubarakiya","Mutrah","Khan el-Khalili","The Grand Bazaar"],"f":"Souq Al-Mubarakiya still sells spices, sweets, and cloth in the lanes of the old town."},{"q":"Which city is the capital of Kuwait?","a":"Kuwait City","o":["Kuwait City","Bissau","Paris","Dublin"],"f":"Kuwait City is the capital of Kuwait.","kind":"capital"},{"q":"Which flag belongs to Kuwait?","a":"KWT","o":["KWT","ETH","BLZ","VEN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Kuwait.","kind":"flag"}],"medium":[{"q":"Bronze Age ruins and a later Greek settlement called Ikaros have been excavated on which island in the bay?","a":"Failaka","o":["Failaka","Bubiyan","Tarout","Sir Bani Yas"],"f":"Failaka sat on the old Dilmun trade routes. Alexander's successors left a small fort and temples there. Tarout is a Saudi island, and Sir Bani Yas is in Abu Dhabi."},{"q":"In August 1990 a neighboring army occupied the country and was driven out seven months later. Which state invaded?","a":"Iraq","o":["Iraq","Iran","Saudi Arabia","Oman"],"f":"The occupation lasted until February 1991, when a US-led coalition expelled the Iraqi army. Oil wells were set alight during the retreat."},{"q":"Before oil, divers went down on one breath for months each season to gather what?","a":"Pearls","o":["Pearls","Sponges","Ambergris","Coral for jewelry"],"f":"A stone weight pulled the diver down and a nose clip kept the water out. Japanese cultured pearls crashed the old market in the 1930s."},{"q":"What is the capital city of Kuwait?","a":"Kuwait City","o":["Kuwait City","Naypyidaw","Thimphu","Ramallah"],"f":"Kuwait City is the capital of Kuwait.","kind":"capital"},{"q":"Which of these flags belongs to Kuwait?","a":"KWT","o":["KWT","LAO","AZE","KGZ"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Kuwait.","kind":"flag"}],"hard":[{"q":"Which seafront palace, named for a sword, has a tiled watchtower?","a":"Seif Palace","o":["Seif Palace","The Alhambra","Topkapi","The Potala"],"f":"Seif Palace stands in the old town beside the water. The blue-tiled tower is a landmark of that shore."},{"q":"After the 1991 war, crews from many countries worked for months to cap what?","a":"Burning oil wells","o":["Burning oil wells","Date groves","Pearl beds","Desalination plants"],"f":"Wells had been set alight. The last fires were capped in November 1991."},{"q":"Which Bedouin weaving, done on a ground loom, makes patterned tent bands?","a":"Sadu weaving","o":["Sadu weaving","Ikat","Kente","Tartan"],"f":"Sadu uses sheep wool and geometric patterns. A workshop in the old town still teaches the craft."},{"q":"Which of these cities is the capital of Kuwait?","a":"Kuwait City","o":["Kuwait City","Hawalli","Ahmadi","Jahra"],"f":"Kuwait City is the capital of Kuwait.","kind":"capital"},{"q":"Which flag is the flag of Kuwait?","a":"KWT","o":["KWT","SDN","PSE","JOR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Kuwait.","kind":"flag"}]}},{"id":"LAO","name":"Laos","cont":"Asia","emoji":"🇱🇦","latlng":[18,105],"q":{"easy":[{"q":"Which town of temples on a peninsula of the Mekong is a UNESCO city?","a":"Luang Prabang","o":["Luang Prabang","Vientiane","Pakse","Savannakhet"],"f":"Luang Prabang's monasteries and colonial houses sit between the Mekong and the Nam Khan."},{"q":"Which minced-meat salad with lime, chili, and herbs is eaten across the country?","a":"Larb","o":["Larb","Som tam","Pho","Amok"],"f":"Larb is meat or fish tossed with toasted rice powder, fish sauce, and herbs."},{"q":"Which turquoise waterfall near Luang Prabang drops in tiers through the forest?","a":"Kuang Si","o":["Kuang Si","Niagara","Iguazu","Detian"],"f":"Kuang Si's pools are a pale blue from minerals. A bear rescue center sits beside the park."},{"q":"Which city is the capital of Laos?","a":"Vientiane","o":["Vientiane","N'Djamena","Ouagadougou","Moroni"],"f":"Vientiane is the capital of Laos.","kind":"capital"},{"q":"Which flag belongs to Laos?","a":"LAO","o":["LAO","SLB","GNB","CZE"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Laos.","kind":"flag"}],"medium":[{"q":"Thousands of giant stone vessels on the Xieng Khouang plateau, mostly Iron Age, are known as what?","a":"The Plain of Jars","o":["The Plain of Jars","The Plain of Temples","The Stone Forest","The Valley of Stupas"],"f":"Burials found nearby suggest the jars once held bodies or bones. Many sites are still dangerous because of unexploded bombs from the wars of the 1960s and 1970s."},{"q":"Luang Prabang's old town of monasteries sits where the Mekong meets which river?","a":"The Nam Khan","o":["The Nam Khan","The Nam Ou","The Mun","The Chao Phraya"],"f":"At dawn, monks walk the peninsula collecting alms. The whole old town is a UNESCO site. The Chao Phraya is the river of Bangkok, not of this confluence."},{"q":"From 1964 to 1973, while officially neutral, the country was heavily bombed in a covert conflict often called what?","a":"The Secret War","o":["The Secret War","The Tet Offensive","The Malayan Emergency","The Indonesian Confrontation"],"f":"Clearance teams still find cluster bomblets in fields. The Tet Offensive was fought in Vietnam. The Malayan Emergency and the Indonesian Confrontation were other Southeast Asian conflicts."},{"q":"What is the capital city of Laos?","a":"Vientiane","o":["Vientiane","Beijing","Ulaanbaatar","Pyongyang"],"f":"Vientiane is the capital of Laos.","kind":"capital"},{"q":"Which of these flags belongs to Laos?","a":"LAO","o":["LAO","BTN","IRQ","YEM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Laos.","kind":"flag"}],"hard":[{"q":"Which great gilded stupa is the national symbol?","a":"Pha That Luang","o":["Pha That Luang","Wat Xieng Thong","Wat Arun","The Shwedagon"],"f":"The stupa in the capital has been ruined and rebuilt more than once. Legend says a relic of the Buddha lies inside."},{"q":"The khene, a bamboo mouth organ, is the main instrument of which traditional music?","a":"Lam","o":["Lam","Gamelan","Gagaku","Pansori"],"f":"Lam singers trade poetic lines while the khene drones. The style is the heart of Lao folk song."},{"q":"Sticky rice, eaten with the hand, is steamed in which basket?","a":"A bamboo huad or tiered basket","o":["A bamboo huad or tiered basket","A rice cooker only","A tagine","A banana leaf only"],"f":"Glutinous rice is soaked and steamed. A small basket, the tip khao, keeps it at the table."},{"q":"Which of these cities is the capital of Laos?","a":"Vientiane","o":["Vientiane","Luang Prabang","Pakse","Savannakhet"],"f":"Vientiane is the capital of Laos.","kind":"capital"},{"q":"Which flag is the flag of Laos?","a":"LAO","o":["LAO","BGD","JPN","PLW"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Laos.","kind":"flag"}]}},{"id":"LBN","name":"Lebanon","cont":"Asia","emoji":"🇱🇧","latlng":[33.83333333,35.83333333],"q":{"easy":[{"q":"Which Roman temple complex in the Beqaa Valley has enormous columns?","a":"Baalbek","o":["Baalbek","Byblos","Tyre","Palmyra"],"f":"Baalbek's temples of Jupiter and Bacchus were built on a much older tell. The stones are among the largest ever moved."},{"q":"Which cracked wheat and meat ovals, fried or raw, are a national dish?","a":"Kibbeh","o":["Kibbeh","Falafel","Kofta","Meatballs"],"f":"Kibbeh nayyeh is raw lamb with bulgur. Fried kibbeh are stuffed balls."},{"q":"Which ancient grove near Bsharri is a remnant of the mountain's famous trees?","a":"The cedar grove at Bsharri","o":["The cedar grove at Bsharri","The baobab","The redwood","The olive"],"f":"The cedar is on the flag. The grove at the Cedars of God near Bsharri is a protected remnant."},{"q":"Which city is the capital of Lebanon?","a":"Beirut","o":["Beirut","Asunción","San Marino","Porto-Novo"],"f":"Beirut is the capital of Lebanon.","kind":"capital"},{"q":"Which flag belongs to Lebanon?","a":"LBN","o":["LBN","SOM","NER","ITA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Lebanon.","kind":"flag"}],"medium":[{"q":"Which poet and painter, born in Bsharri in 1883, wrote The Prophet?","a":"Khalil Gibran","o":["Khalil Gibran","Mahmoud Darwish","Nizar Qabbani","Adonis"],"f":"He emigrated to the United States as a boy and wrote much of his English work in New York. Darwish was Palestinian. Qabbani and Adonis were Syrian."},{"q":"Ancient shipbuilders prized the timber of which mountain tree, now rare and kept in highland groves?","a":"The cedar","o":["The cedar","The olive","The date palm","The carob"],"f":"Egyptian records ask for this timber from the coast. A stylized cedar is the national emblem. Most of the old forests were cut centuries ago."},{"q":"The Greek word for book comes from an ancient port here, because papyrus was shipped through it. Which port?","a":"Byblos","o":["Byblos","Tyre","Sidon","Ugarit"],"f":"Byblos has been lived in for thousands of years. Ugarit, where an early alphabet was found, is on the Syrian coast. Tyre and Sidon were the other great ports of this shore."},{"q":"What is the capital city of Lebanon?","a":"Beirut","o":["Beirut","Ankara","Singapore","Kathmandu"],"f":"Beirut is the capital of Lebanon.","kind":"capital"},{"q":"Which of these flags belongs to Lebanon?","a":"LBN","o":["LBN","ISR","GEO","PHL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Lebanon.","kind":"flag"}],"hard":[{"q":"Byblos, one of the oldest continuously lived ports, gave Greek a word for what?","a":"A book, from its papyrus trade","o":["A book, from its papyrus trade","A ship","A god","A coin"],"f":"Greeks bought papyrus at Byblos. The town's name became the word biblos, a book."},{"q":"Which singer, born Nouhad Haddad, became famous with the Rahbani brothers' musicals?","a":"Fairuz","o":["Fairuz","Umm Kulthum","Asmahan","Majida El Roumi"],"f":"Fairuz's songs defined popular music from the 1950s on. She is widely heard across the Arab world."},{"q":"Dabke, a line dance of the Levant, is led by a dancer who does what?","a":"Sets the steps with a handkerchief or stick","o":["Sets the steps with a handkerchief or stick","Plays the oud","Sings alone","Spins like a dervish"],"f":"The leader improvises jumps while the line holds a rhythm. Weddings still open the floor with dabke."},{"q":"Which of these cities is the capital of Lebanon?","a":"Beirut","o":["Beirut","Tripoli","Sidon","Byblos"],"f":"Beirut is the capital of Lebanon.","kind":"capital"},{"q":"Which flag is the flag of Lebanon?","a":"LBN","o":["LBN","PER","AUT","LVA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Lebanon.","kind":"flag"}]}},{"id":"LBR","name":"Liberia","cont":"Africa","emoji":"🇱🇷","latlng":[6.5,-9.5],"q":{"easy":[{"q":"Which old settlement of freed people from the Americas gave Liberia its name and its capital's history?","a":"The colony of freed settlers","o":["The colony of freed settlers","A Viking camp","A Roman fort","An Inca road"],"f":"In the 1820s the American Colonization Society landed freed African Americans at Providence Island. The name Liberia means land of the free."},{"q":"Which rice dish cooked in one pot with greens and meat is a home classic?","a":"Jollof rice and palm butter","o":["Jollof rice and palm butter","Sushi","Poutine","Ceviche"],"f":"Palm butter sauces and jollof-style rice are everyday favorites. Cassava leaf stew is another."},{"q":"Which beach and forest park east of Monrovia is a well-known nature stop?","a":"Sapo National Park","o":["Sapo National Park","Kruger","Yellowstone","Banff"],"f":"Sapo protects rainforest and forest elephants in the southeast, the country's largest park."},{"q":"Which city is the capital of Liberia?","a":"Monrovia","o":["Monrovia","Paris","Minsk","Roseau"],"f":"Monrovia is the capital of Liberia.","kind":"capital"},{"q":"Which flag belongs to Liberia?","a":"LBR","o":["LBR","JOR","BEL","BRB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Liberia.","kind":"flag"}],"medium":[{"q":"Settlers who founded the republic, independent in 1847, were mainly who?","a":"Freed African Americans","o":["Freed African Americans","Portuguese convicts","Dutch farmers","British convicts"],"f":"The American Colonization Society began settlements in the 1820s. The state was not a colony of a European empire, which is why the date is so early. The main city's name honors U.S. president James Monroe."},{"q":"Who, elected in 2005 and sworn in in 2006, was the first woman elected head of state in Africa?","a":"Ellen Johnson Sirleaf","o":["Ellen Johnson Sirleaf","Wangarĩ Maathai","Winnie Madikizela-Mandela","Ruth Perry"],"f":"She shared the 2011 Nobel Peace Prize and served two terms. Ruth Perry had chaired a transitional council in the 1990s, but she was not chosen in a national election. Maathai and Madikizela-Mandela did not hold this office."},{"q":"In 1926 the Firestone company took a huge concession to plant which crop?","a":"Rubber","o":["Rubber","Cocoa","Cloves","Tea"],"f":"The deal lasted for most of the century and tied farms to American tire making. Cocoa built the economies of Ghana and Ivory Coast. Cloves built Zanzibar."},{"q":"What is the capital city of Liberia?","a":"Monrovia","o":["Monrovia","Abuja","Tunis","Niamey"],"f":"Monrovia is the capital of Liberia.","kind":"capital"},{"q":"Which of these flags belongs to Liberia?","a":"LBR","o":["LBR","NGA","SEN","SYC"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Liberia.","kind":"flag"}],"hard":[{"q":"The True Whig Party dominated politics for a century. It mainly represented which community?","a":"Settler families from the Americas","o":["Settler families from the Americas","The Maasai","The Tuareg","The Zulu"],"f":"Settler families from the Americas and their descendants ran the state until the 1980 coup."},{"q":"Which company built a huge rubber plantation at Harbel in the 1920s?","a":"Firestone","o":["Firestone","Toyota","Nestle","Shell"],"f":"The plantation at Harbel became one of the world's largest rubber estates."},{"q":"The Vai people developed a famous local writing system in the 1800s. It is written in which direction?","a":"Left to right in syllables","o":["Left to right in syllables","Only in hieroglyphs","In Norse runes","In Inca quipu knots"],"f":"The Vai syllabary was invented around 1833. It is one of the few scripts created in West Africa in that century."},{"q":"Which of these cities is the capital of Liberia?","a":"Monrovia","o":["Monrovia","Gbarnga","Buchanan","Harper"],"f":"Monrovia is the capital of Liberia.","kind":"capital"},{"q":"Which flag is the flag of Liberia?","a":"LBR","o":["LBR","MYS","USA","QAT"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Liberia.","kind":"flag"}]}},{"id":"LBY","name":"Libya","cont":"Africa","emoji":"🇱🇾","latlng":[25,17],"q":{"easy":[{"q":"Which ruined Greek city in the eastern hills was founded by settlers in the 600s BCE?","a":"Cyrene","o":["Cyrene","Leptis Magna","Carthage","Alexandria"],"f":"Cyrene's temple of Zeus and the sanctuary of Apollo stand above the coastal plain. It was the leading city of a Greek pentapolis."},{"q":"Which stuffed pastry and spicy soup are Ramadan favorites in Libya?","a":"Sharba and bureek","o":["Sharba and bureek","Sushi","Poutine","Arepa"],"f":"Sharba is a spicy soup. Bureek are fried pastries filled with meat or egg."},{"q":"Which vast sea of sand in the southwest is one of the Sahara's great dune fields?","a":"The Ubari Sand Sea","o":["The Ubari Sand Sea","The Gobi","The Namib","The Kalahari"],"f":"The Ubari, or Idehan Ubari, holds dunes and a few palm lakes called gueltas."},{"q":"Which city is the capital of Libya?","a":"Tripoli","o":["Tripoli","Ngerulmud","Beijing","Prague"],"f":"Tripoli is the capital of Libya.","kind":"capital"},{"q":"Which flag belongs to Libya?","a":"LBY","o":["LBY","HRV","NPL","NLD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Libya.","kind":"flag"}],"medium":[{"q":"Who led resistance to the Italian occupation in Cyrenaica and was executed in 1931?","a":"Omar Mukhtar","o":["Omar Mukhtar","Abd el-Kader","Samori Touré","Muhammad Ahmad"],"f":"He was called the Lion of the Desert. Abd el-Kader fought France in Algeria, Samori Touré fought the French in West Africa, and Muhammad Ahmad was the Mahdi in Sudan."},{"q":"The Roman emperor Septimius Severus, who ruled from 193, was born in which city on this coast?","a":"Leptis Magna","o":["Leptis Magna","Carthage","Alexandria","Cyrene"],"f":"He adorned his hometown with a forum, a basilica, and arches that still stand. Carthage is in Tunisia and Alexandria in Egypt. Cyrene is a Greek city on this same coast, but it is not his birthplace."},{"q":"The Tadrart Acacus, a UNESCO landscape in the southwest, is famous for what on the rock?","a":"Prehistoric paintings of people and animals","o":["Prehistoric paintings of people and animals","Roman mosaics","Phoenician shipping logs","Medieval icons"],"f":"The pictures run from a wetter Sahara into the desert age and show cattle and giraffes where it is now extremely dry. They are paintings, not Roman floors."},{"q":"What is the capital city of Libya?","a":"Tripoli","o":["Tripoli","Accra","Mbabane","Niamey"],"f":"Tripoli is the capital of Libya.","kind":"capital"},{"q":"Which of these flags belongs to Libya?","a":"LBY","o":["LBY","NAM","EGY","GNQ"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Libya.","kind":"flag"}],"hard":[{"q":"The Sanusi order, a Sufi movement, had its stronghold in which eastern region?","a":"Cyrenaica","o":["Cyrenaica","Andalusia","Tuscany","Brittany"],"f":"The Sanusi led resistance to Italian conquest from oasis towns such as Jaghbub and Kufra."},{"q":"Rock art in the Acacus Mountains, a UNESCO site, shows what from a wetter Sahara?","a":"People, cattle, and chariots","o":["People, cattle, and chariots","Only spaceships","Viking ships","Maya stelae"],"f":"Paintings and engravings in the Tadrart Acacus record thousands of years of Saharan life."},{"q":"The Garamantes built underground water tunnels in the Fezzan. Those tunnels are called what?","a":"Foggara","o":["Foggara","Qanats of only Iran","Aqueducts of Rome","Stepwells of India"],"f":"Foggara, like Persian qanats, move groundwater to oasis fields. The Garamantian kingdom depended on them."},{"q":"Which of these cities is the capital of Libya?","a":"Tripoli","o":["Tripoli","Benghazi","Misrata","Sabha"],"f":"Tripoli is the capital of Libya.","kind":"capital"},{"q":"Which flag is the flag of Libya?","a":"LBY","o":["LBY","AZE","MNG","ARE"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Libya.","kind":"flag"}]}},{"id":"LCA","name":"Saint Lucia","cont":"North America","emoji":"🇱🇨","latlng":[13.88333333,-60.96666666],"q":{"easy":[{"q":"Which two volcanic plugs rise from the sea near Soufriere?","a":"The Pitons","o":["The Pitons","The Pitons are the answer","Diamond Rock","Morne Diablotin"],"f":"Gros Piton and Petit Piton are a UNESCO site. They are volcanic plugs clothed in forest."},{"q":"Which coal-pot stew of salted meat and green banana in one pot is the national dish?","a":"Green fig and saltfish","o":["Green fig and saltfish","Oil down","Pepperpot","Callaloo"],"f":"Green fig means green banana. It is boiled and served with a salt-cod stew."},{"q":"Which drive-through volcano and sulfur springs are a famous stop?","a":"Sulphur Springs","o":["Sulphur Springs","The Boiling Lake","Irazu","Poas"],"f":"The springs sit in a caldera above Soufriere. Visitors can walk on a formed crust and see the steam."},{"q":"Which city is the capital of Saint Lucia?","a":"Castries","o":["Castries","Bishkek","Seoul","Banjul"],"f":"Castries is the capital of Saint Lucia.","kind":"capital"},{"q":"Which flag belongs to Saint Lucia?","a":"LCA","o":["LCA","TCD","KAZ","LIE"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Saint Lucia.","kind":"flag"}],"medium":[{"q":"Which poet, born in Castries, won the 1992 Nobel Prize in Literature?","a":"Derek Walcott","o":["Derek Walcott","V. S. Naipaul","Seamus Heaney","Wole Soyinka"],"f":"His long poem Omeros sets Homeric themes in the Caribbean. He also founded the Trinidad Theatre Workshop."},{"q":"The Pitons, a UNESCO site, are two volcanic plugs rising straight from the sea. What are their usual names?","a":"Gros Piton and Petit Piton","o":["Gros Piton and Petit Piton","Mount Pelée and Soufriere","Pico Duarte and La Selle","Blue Mountain and Catherine"],"f":"Gros Piton is the broader one, Petit Piton the steeper. Coral reefs at their feet are part of the same World Heritage area."},{"q":"France and Britain captured St. Lucia from each other more than a dozen times. That history earned it which nickname?","a":"The Helen of the West Indies","o":["The Helen of the West Indies","The Pearl of the Antilles","The Spice Isle","The Nature Isle"],"f":"Like Helen of Troy, the island was fought over for its beauty and its harbors. Britain finally kept it in 1814, and independence came in 1979."},{"q":"What is the capital city of Saint Lucia?","a":"Castries","o":["Castries","Mexico City","San Salvador","Basseterre"],"f":"Castries is the capital of Saint Lucia.","kind":"capital"},{"q":"Which of these flags belongs to Saint Lucia?","a":"LCA","o":["LCA","CRI","USA","ATG"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Saint Lucia.","kind":"flag"}],"hard":[{"q":"Which folk singer, born in 1914, was later honored as the island's Queen of Culture?","a":"Sesenne Descartes","o":["Sesenne Descartes","Calypso Rose","The Mighty Sparrow","Denyse Plummer"],"f":"Sesenne Descartes sang traditional kweyol songs for decades and kept the older repertoire alive."},{"q":"The island changed hands between Britain and France so often that the local language is what?","a":"A French-based Creole","o":["A French-based Creole","Spanish","Dutch","Portuguese"],"f":"Kweyol is the everyday speech. English is the official language from the final British period."},{"q":"Which chocolate from hillside cacao has become a small-batch export?","a":"Tree-to-bar cocoa","o":["Tree-to-bar cocoa","Nutmeg","Sugar only","Bananas only"],"f":"Estates ferment cacao in the old valleys. The bean was grown here long before the recent revival."},{"q":"Which of these cities is the capital of Saint Lucia?","a":"Castries","o":["Castries","Vieux Fort","Soufrière","Gros Islet"],"f":"Castries is the capital of Saint Lucia.","kind":"capital"},{"q":"Which flag is the flag of Saint Lucia?","a":"LCA","o":["LCA","ETH","JOR","GAB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Saint Lucia.","kind":"flag"}]}},{"id":"LIE","name":"Liechtenstein","cont":"Europe","emoji":"🇱🇮","latlng":[47.26666666,9.53333333],"q":{"easy":[{"q":"Which cheese-and-pasta bake is the best-known local dish?","a":"Kasknopfle","o":["Kasknopfle","Fondue","Raclette","Pizza"],"f":"Kasknopfle are small dumplings with cheese and fried onions, close to spaetzle."},{"q":"Which river forms the western border with Switzerland?","a":"The Alpine Rhine","o":["The Alpine Rhine","The Danube","The Rhone","The Inn"],"f":"The Rhine leaves the Alps along the country's lowland. Vineyards cover some of the slopes above it."},{"q":"Which small printed squares for collectors were long a famous export?","a":"Postage stamps","o":["Postage stamps","Coins of gold","Tea","Spices"],"f":"A small population and pretty designs made the stamps a collector's item and a source of revenue."},{"q":"Which city is the capital of Liechtenstein?","a":"Vaduz","o":["Vaduz","Dushanbe","Kampala","Jerusalem"],"f":"Vaduz is the capital of Liechtenstein.","kind":"capital"},{"q":"Which flag belongs to Liechtenstein?","a":"LIE","o":["LIE","MOZ","DOM","MMR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Liechtenstein.","kind":"flag"}],"medium":[{"q":"In a 1984 referendum, Liechtenstein became the last country in Europe to grant women what?","a":"The vote in national elections","o":["The vote in national elections","The right to own land","Access to university","Passports of their own"],"f":"Only men voted, and the yes side won by 119 votes. Women first used the national vote in 1986, when Emma Eigenmann entered parliament."},{"q":"Only one other country is surrounded solely by countries that themselves have no seacoast. Which is it?","a":"Uzbekistan","o":["Uzbekistan","Switzerland","Austria","Luxembourg"],"f":"Switzerland and Austria border Liechtenstein, and neither touches the sea, so a traveler crosses two countries to reach the ocean. Geographers call that doubly landlocked."},{"q":"The principality takes its name from a noble family that, in 1719, bought land so they could have a seat in the empire. Where was that family originally based?","a":"Lower Austria, near Vienna","o":["Lower Austria, near Vienna","Brittany","Sicily","Bohemia only"],"f":"Emperor Charles VI united the county of Vaduz and the lordship of Schellenberg and raised them to a principality. The princes did not live there full time for many generations."},{"q":"What is the capital city of Liechtenstein?","a":"Vaduz","o":["Vaduz","Tallinn","Dublin","Minsk"],"f":"Vaduz is the capital of Liechtenstein.","kind":"capital"},{"q":"Which of these flags belongs to Liechtenstein?","a":"LIE","o":["LIE","AUT","GBR","SWE"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Liechtenstein.","kind":"flag"}],"hard":[{"q":"The princely family bought the domain in 1719 and took their name from which earlier estate?","a":"A castle in Lower Austria","o":["A castle in Lower Austria","A palace in Paris","A fort in Spain","A manor in England"],"f":"The Liechtenstein name comes from a castle south of Vienna. The family later acquired this Alpine county."},{"q":"Which trail network and the Eschnerberg are used for what weekend activity?","a":"Hiking","o":["Hiking","Desert camel treks","Reef diving","Glacier skiing only"],"f":"Marked paths cross vineyards, forest, and the three communities of the upper hill."},{"q":"The 1868 constitution and later votes kept the prince's role while adding what?","a":"A parliament","o":["A parliament","A military junta","A colonial governor","A caliph"],"f":"Men received the vote in the 1800s. Women gained the national vote in 1984, after a long debate."},{"q":"Which of these cities is the capital of Liechtenstein?","a":"Vaduz","o":["Vaduz","Schaan","Balzers","Triesen"],"f":"Vaduz is the capital of Liechtenstein.","kind":"capital"},{"q":"Which flag is the flag of Liechtenstein?","a":"LIE","o":["LIE","MNE","BLZ","LBR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Liechtenstein.","kind":"flag"}]}},{"id":"LKA","name":"Sri Lanka","cont":"Asia","emoji":"🇱🇰","latlng":[7,81],"q":{"easy":[{"q":"Which temple in Kandy is said to hold a tooth relic of the Buddha?","a":"The Temple of the Tooth","o":["The Temple of the Tooth","Sigiriya","Dambulla","Polonnaruwa"],"f":"The relic is kept in a golden casket. A perahera procession honors it each year."},{"q":"Which bowl-shaped pancakes of fermented rice batter are a breakfast food?","a":"Hoppers","o":["Hoppers","Dosa","Injera","Crepes"],"f":"A hopper, or appa, is cooked in a small curved pan. An egg hopper holds an egg in the middle."},{"q":"Which national park in the southeast is known for leopards?","a":"Yala","o":["Yala","Wilpattu","Horton Plains","Udawalawe"],"f":"Yala's dry scrub holds one of the higher densities of leopards studied anywhere. Elephants and sloth bears live there too."},{"q":"Which city is the official capital of Sri Lanka?","a":"Sri Jayawardenepura Kotte","o":["Sri Jayawardenepura Kotte","Podgorica","Castries","Basseterre"],"f":"Sri Jayawardenepura Kotte is the official capital. Colombo is the commercial capital.","kind":"capital"},{"q":"Which flag belongs to Sri Lanka?","a":"LKA","o":["LKA","CAF","AGO","CHE"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Sri Lanka.","kind":"flag"}],"medium":[{"q":"Which novelist, born in Colombo in 1943, wrote The English Patient?","a":"Michael Ondaatje","o":["Michael Ondaatje","Salman Rushdie","Arundhati Roy","Kazuo Ishiguro"],"f":"He moved to Canada as a teenager. Rushdie was born in Bombay, Roy in Meghalaya, and Ishiguro in Nagasaki. Arthur C. Clarke lived on this island for years but was born in England."},{"q":"A 5th-century king built a palace on a sheer rock, with frescoes on the cliff below. What is the site called?","a":"Sigiriya","o":["Sigiriya","Polonnaruwa","Dambulla","Anuradhapura"],"f":"King Kashyapa ruled from the rock in the late 400s. Visitors scratched poems on the mirror wall under the paintings. The other three are famous cities or cave temples, but not this rock."},{"q":"After a fungus wiped out highland coffee in the 19th century, who planted the estate tea that replaced it?","a":"James Taylor, a British planter","o":["James Taylor, a British planter","A medieval Sinhalese king","Dutch cinnamon merchants","Chinese monks in the 8th century"],"f":"Taylor planted tea at Loolecondera in 1867. The drink sold as Ceylon tea is a crop of the colonial century, not an ancient one."},{"q":"What is the official capital city of Sri Lanka?","a":"Sri Jayawardenepura Kotte","o":["Sri Jayawardenepura Kotte","Tehran","Bishkek","Damascus"],"f":"Sri Jayawardenepura Kotte is the official capital. Colombo is the commercial capital.","kind":"capital"},{"q":"Which of these flags belongs to Sri Lanka?","a":"LKA","o":["LKA","TUR","IRQ","LBN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Sri Lanka.","kind":"flag"}],"hard":[{"q":"The rock fortress of Sigiriya is famous for frescoes and for what engineering?","a":"A palace on a magma plug with gardens and a moat","o":["A palace on a magma plug with gardens and a moat","A Roman camp","A mud mosque","A timber fort"],"f":"King Kashyapa built a palace on the rock in the 400s. The lion's paws still mark the stair."},{"q":"Cinnamon from the island's bark was a prize of which ocean trade?","a":"The Indian Ocean spice trade","o":["The Indian Ocean spice trade","The Silk Road only by land","The fur trade","The Atlantic slave trade"],"f":"Peelers still cut the inner bark of shoots. The quills are a historic export."},{"q":"Which tea, planted widely from the 1800s, replaced coffee after a leaf disease?","a":"Black tea","o":["Black tea","Yerba mate","Cocoa","Rubber"],"f":"James Taylor and others opened estates in the highlands. Tea became the main plantation crop."},{"q":"Which of these cities is the official capital of Sri Lanka?","a":"Sri Jayawardenepura Kotte","o":["Sri Jayawardenepura Kotte","Colombo","Kandy","Galle"],"f":"Sri Jayawardenepura Kotte is the official capital. Colombo is the commercial capital.","kind":"capital"},{"q":"Which flag is the flag of Sri Lanka?","a":"LKA","o":["LKA","PRK","IRQ","TON"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Sri Lanka.","kind":"flag"}]}},{"id":"LSO","name":"Lesotho","cont":"Africa","emoji":"🇱🇸","latlng":[-29.5,28.5],"q":{"easy":[{"q":"Which highland range covers this kingdom that is entirely surrounded by South Africa?","a":"The Maloti Mountains","o":["The Maloti Mountains","The Alps","The Andes","The Himalaya"],"f":"Lesotho sits in the Maloti and Drakensberg highlands. Snow falls on the peaks in winter."},{"q":"Which stew of corn, beans, and sorghum is a daily meal?","a":"Nyekoe","o":["Nyekoe","Sushi","Paella","Poutine"],"f":"Nyekoe simmers maize and beans. Papa, a maize porridge, is the other everyday starch."},{"q":"The mokorotlo, a conical straw hat, appears on the flag and recalls which rural building?","a":"A herder's shelter","o":["A herder's shelter","A pagoda","An igloo","A teepee"],"f":"The hat's shape echoes a grass shelter used in the mountains. It became a national emblem."},{"q":"Which city is the capital of Lesotho?","a":"Maseru","o":["Maseru","Budapest","Ashgabat","Nicosia"],"f":"Maseru is the capital of Lesotho.","kind":"capital"},{"q":"Which flag belongs to Lesotho?","a":"LSO","o":["LSO","HUN","LIE","JOR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Lesotho.","kind":"flag"}],"medium":[{"q":"Which 19th-century leader gathered people at Thaba Bosiu and is remembered as the founder of the Basotho nation?","a":"Moshoeshoe I","o":["Moshoeshoe I","Shaka","Mzilikazi","Cetshwayo"],"f":"He mixed defense with diplomacy and invited missionaries. Shaka and Cetshwayo led the Zulu, and Mzilikazi led the Ndebele. None of them founded this kingdom."},{"q":"A conical woven hat, echoing a hill near Thaba Bosiu, is worn with a patterned blanket. What is the hat called?","a":"A mokorotlo","o":["A mokorotlo","A fez","A kufi","A keffiyeh"],"f":"The hill is Qiloane. The blanket became everyday dress in the 19th century and works as a coat in a cold highland winter. A fez, a kufi, and a keffiyeh are caps from other regions."},{"q":"This is the only independent country whose whole territory lies above which elevation?","a":"1,000 meters","o":["1,000 meters","100 meters","5,000 meters","Sea level"],"f":"The lowest point is about 1,400 meters, where rivers meet the border. The Maloti and the Drakensberg make the rest higher. No other independent state is entirely above 1,000 meters."},{"q":"What is the capital city of Lesotho?","a":"Maseru","o":["Maseru","Monrovia","Bamako","Yaoundé"],"f":"Maseru is the capital of Lesotho.","kind":"capital"},{"q":"Which of these flags belongs to Lesotho?","a":"LSO","o":["LSO","MOZ","AGO","MDG"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Lesotho.","kind":"flag"}],"hard":[{"q":"King Moshoeshoe I gathered clans at which flat-topped mountain fortress in the 1800s?","a":"Thaba Bosiu","o":["Thaba Bosiu","Table Mountain","Uluru","Aconcagua"],"f":"Thaba Bosiu means mountain of the night. Raiders struggled to take the stronghold, and the kingdom grew around it."},{"q":"Which warm wrap blanket, often worn pinned at the shoulder, is everyday dress in the cold highlands?","a":"The Basotho blanket","o":["The Basotho blanket","The kimono","The sari","The poncho of the Andes only"],"f":"Wool blankets from mills became a national dress in the late 1800s. Patterns mark status and taste."},{"q":"Pony trekking is a classic way to see the mountains because villages long relied on what animal?","a":"Horses","o":["Horses","Camels","Reindeer","Llamas"],"f":"Small Basotho ponies carry riders and packs on steep paths where carts cannot go."},{"q":"Which of these cities is the capital of Lesotho?","a":"Maseru","o":["Maseru","Teyateyaneng","Mafeteng","Hlotse"],"f":"Maseru is the capital of Lesotho.","kind":"capital"},{"q":"Which flag is the flag of Lesotho?","a":"LSO","o":["LSO","IRL","SWE","DOM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Lesotho.","kind":"flag"}]}},{"id":"LTU","name":"Lithuania","cont":"Europe","emoji":"🇱🇹","latlng":[56,24],"q":{"easy":[{"q":"Which red-brick island castle stands in a lake west of Vilnius?","a":"Trakai Island Castle","o":["Trakai Island Castle","Malbork","Mir Castle","Neuschwanstein"],"f":"Trakai was a stronghold of the Grand Duchy. The castle sits on an island reached by a bridge."},{"q":"Which potato dumplings stuffed with meat are the national dish?","a":"Cepelinai","o":["Cepelinai","Gnocchi","Pierogi","Ravioli"],"f":"Cepelinai are named for zeppelins because of their shape. They are served with sour cream and bacon."},{"q":"Which team sport is a national passion, with outdoor courts in many yards?","a":"Basketball","o":["Basketball","Cricket","Baseball","Rugby"],"f":"Lithuania's national team has been a European power. The sport took root between the world wars."},{"q":"Which city is the capital of Lithuania?","a":"Vilnius","o":["Vilnius","Santiago","Malé","Monrovia"],"f":"Vilnius is the capital of Lithuania.","kind":"capital"},{"q":"Which flag belongs to Lithuania?","a":"LTU","o":["LTU","SLE","MLI","KAZ"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Lithuania.","kind":"flag"}],"medium":[{"q":"Which painter and composer, born in 1875, filled pictures with glowing mythical figures and wrote music for them?","a":"Mikalojus Konstantinas Ciurlionis","o":["Mikalojus Konstantinas Ciurlionis","Marc Chagall","Arvo Part","Jean Sibelius"],"f":"He died at 35, in 1911, leaving hundreds of paintings and many musical scores. A museum in Kaunas keeps the largest collection."},{"q":"The Hill of Crosses near Siauliai is a pilgrimage mound covered with tens of thousands of what?","a":"Crosses left by visitors","o":["Crosses left by visitors","Soviet statues","Wind turbines","Burial mounds of kings"],"f":"Authorities bulldozed it more than once in the Soviet period, and people rebuilt it. It became a symbol of quiet resistance and of prayer."},{"q":"At its greatest extent in the 15th century, the Grand Duchy of Lithuania stretched from the Baltic toward which sea?","a":"The Black Sea","o":["The Black Sea","The Caspian Sea","The North Sea","The Mediterranean"],"f":"It was a multiethnic state of Lithuanians, Ruthenians, and others, later joined with Poland. Its size is why Lithuanian is not a Slavic language even though the old realm covered Slavic lands."},{"q":"What is the capital city of Lithuania?","a":"Vilnius","o":["Vilnius","Helsinki","Sarajevo","Belgrade"],"f":"Vilnius is the capital of Lithuania.","kind":"capital"},{"q":"Which of these flags belongs to Lithuania?","a":"LTU","o":["LTU","LVA","HRV","POL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Lithuania.","kind":"flag"}],"hard":[{"q":"The Grand Duchy, joined with Poland in 1569, had its statutes written in which language of the chancery?","a":"Ruthenian, then Polish","o":["Ruthenian, then Polish","Only Latin","Only German","Swedish"],"f":"The Lithuanian Statutes were a famous law code. The court language shifted over the centuries."},{"q":"Which amber and linen crafts are traditional along the coast and in villages?","a":"Amber jewelry and linen cloth","o":["Amber jewelry and linen cloth","Silk","Cotton","Wool tartan"],"f":"Flax fields once covered the country. Linen costumes and amber beads appear at festivals."},{"q":"Rasu hill and other castle mounds are remains of what?","a":"Wooden hillforts","o":["Wooden hillforts","Roman camps","Inca terraces","Viking ship graves"],"f":"Early dukes lived in timber forts on steep mounds. Many are now grassy hills with a view."},{"q":"Which of these cities is the capital of Lithuania?","a":"Vilnius","o":["Vilnius","Kaunas","Klaipėda","Šiauliai"],"f":"Vilnius is the capital of Lithuania.","kind":"capital"},{"q":"Which flag is the flag of Lithuania?","a":"LTU","o":["LTU","MWI","BHR","LKA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Lithuania.","kind":"flag"}]}},{"id":"LUX","name":"Luxembourg","cont":"Europe","emoji":"🇱🇺","latlng":[49.75,6.16666666],"q":{"easy":[{"q":"Which smoked pork collar served with broad beans is the national dish?","a":"Judd mat Gaardebounen","o":["Judd mat Gaardebounen","Choucroute","Cassoulet","Paella"],"f":"The pork is smoked and boiled, then plated with beans in a wine sauce. It is a winter classic."},{"q":"Which sandstone ravine country is nicknamed Little Switzerland?","a":"The Mullerthal","o":["The Mullerthal","The Black Forest","The Ardennes only","The Jura"],"f":"Trails in the Mullerthal pass mossy gorges and small waterfalls east of the capital."},{"q":"Which sparkling wine is made along the Moselle by the traditional bottle method?","a":"Cremant","o":["Cremant","Champagne of only France","Cava","Prosecco"],"f":"Luxembourgish cremant is a protected sparkling wine. Vineyards line the river toward Germany."},{"q":"Which city is the capital of Luxembourg?","a":"Luxembourg City","o":["Luxembourg City","Yaoundé","Ulaanbaatar","Cairo"],"f":"Luxembourg City is the capital of Luxembourg.","kind":"capital"},{"q":"Which flag belongs to Luxembourg?","a":"LUX","o":["LUX","CUB","KIR","SYC"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Luxembourg.","kind":"flag"}],"medium":[{"q":"Which statesman, born in Luxembourg City in 1886, later became French foreign minister and proposed the coal and steel pool that led toward the European Union?","a":"Robert Schuman","o":["Robert Schuman","Jean Monnet","Konrad Adenauer","Alcide De Gasperi"],"f":"He was born a German subject in Luxembourg and became a French citizen. Monnet drafted much of the 1950 plan, but the public proposal is called the Schuman Declaration."},{"q":"In 1985 five countries signed an agreement in a Moselle wine village to drop passport checks. What was the village?","a":"Schengen","o":["Schengen","Echternach","Vianden","Clervaux"],"f":"The Schengen Area later grew to most of Europe. The name of a Luxembourg village became the word for border-free travel."},{"q":"The Bock casemates are kilometers of tunnels cut into the rock under Luxembourg City. They were built mainly as what?","a":"Military defenses","o":["Military defenses","Wine cellars","A Roman aqueduct","A salt mine"],"f":"The fortress was so strong that the city was called the Gibraltar of the North. The tunnels were partly destroyed after 1867, when the fortress was dismantled by treaty."},{"q":"What is the capital city of Luxembourg?","a":"Luxembourg City","o":["Luxembourg City","Copenhagen","Vatican City","Bucharest"],"f":"Luxembourg City is the capital of Luxembourg.","kind":"capital"},{"q":"Which of these flags belongs to Luxembourg?","a":"LUX","o":["LUX","SVK","MDA","BEL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Luxembourg.","kind":"flag"}],"hard":[{"q":"Which 1950s plan by a Luxembourg-born statesman proposed pooling coal and steel?","a":"The Schuman Plan","o":["The Schuman Plan","The Marshall Plan","The Truman Doctrine","The Molotov Plan"],"f":"Robert Schuman's 1950 declaration led to the European Coal and Steel Community, a root of the European Union."},{"q":"The Bock casemates are underground passages cut for what?","a":"Defense of the fortress","o":["Defense of the fortress","Wine storage only","A metro","A canal"],"f":"The rock under the old town was honeycombed with tunnels. The fortress was dismantled in the 1860s, but galleries remain."},{"q":"Which radio and television company, broadcasting in several languages, was long based here?","a":"RTL","o":["RTL","The BBC","RAI","NHK"],"f":"CLT, later RTL, used the country's location and laws to broadcast across borders."},{"q":"Which of these cities is the capital of Luxembourg?","a":"Luxembourg City","o":["Luxembourg City","Esch-sur-Alzette","Differdange","Dudelange"],"f":"Luxembourg City is the capital of Luxembourg.","kind":"capital"},{"q":"Which flag is the flag of Luxembourg?","a":"LUX","o":["LUX","FRA","RUS","NLD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Luxembourg.","kind":"flag"}]}},{"id":"LVA","name":"Latvia","cont":"Europe","emoji":"🇱🇻","latlng":[57,25],"q":{"easy":[{"q":"Which resin from the Baltic Sea is polished into jewelry?","a":"Amber","o":["Amber","Jet","Coral","Pearl"],"f":"Amber is fossil tree resin. Storms wash it onto Latvian beaches, and Riga has long traded it."},{"q":"Which stewed legumes with bacon are a Christmas dish?","a":"Grey peas","o":["Grey peas","Lentils","Sushi","Grits"],"f":"Grey peas are stewed until soft and served with smoked meat and sour cream."},{"q":"Which song festival, held every five years, fills a huge choir shell?","a":"The five-year choir festival","o":["The five-year choir festival","Eurovision","The Proms","Laulupidu of Estonia only"],"f":"The Dziesmu svetki began in 1873. Choirs were central to the independence movement."},{"q":"Which city is the capital of Latvia?","a":"Riga","o":["Riga","Jerusalem","Algiers","Damascus"],"f":"Riga is the capital of Latvia.","kind":"capital"},{"q":"Which flag belongs to Latvia?","a":"LVA","o":["LVA","MUS","BGD","GUY"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Latvia.","kind":"flag"}],"medium":[{"q":"Which painter, born in Daugavpils in 1903, later became famous in America for large fields of color?","a":"Mark Rothko","o":["Mark Rothko","Marc Chagall","Jackson Pollock","Wassily Kandinsky"],"f":"His family emigrated when he was ten, and he grew up as Marcus Rothkowitz. The city was then called Dvinsk, in the Russian Empire."},{"q":"Riga has one of Europe's richest collections of buildings in which decorative style of about 1900?","a":"Art Nouveau","o":["Art Nouveau","Gothic only","Bauhaus","Neoclassical temples"],"f":"Alberta Street and Elizabetes Street are lined with sculpted faces, peacocks, and flowing stone. The old town beside them is medieval and Hanseatic."},{"q":"Jani, the midsummer festival, is celebrated with bonfires, wreaths, and a search for a mythical fern flower. It marks the shortest what?","a":"Night of the year","o":["Night of the year","Day of the year","Lent","Harvest moon"],"f":"Herbal cheeses and songs go with the fires. The holiday is a public festival, not only a folk revival."},{"q":"What is the capital city of Latvia?","a":"Riga","o":["Riga","Valletta","Amsterdam","Vilnius"],"f":"Riga is the capital of Latvia.","kind":"capital"},{"q":"Which of these flags belongs to Latvia?","a":"LVA","o":["LVA","MLT","AND","CZE"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Latvia.","kind":"flag"}],"hard":[{"q":"The Livonian Order of crusading knights ruled from castles along which river?","a":"The Daugava","o":["The Daugava","The Volga","The Danube","The Rhine"],"f":"Stone castles such as Cesis controlled the trade route from the Baltic inland."},{"q":"Which wooden farmsteads and a palace park at Rundale show 18th-century life?","a":"Rundale Palace","o":["Rundale Palace","Versailles","Peterhof","Schonbrunn"],"f":"Bartolomeo Rastrelli, who worked in St. Petersburg, designed Rundale for the Duke of Courland."},{"q":"Jani, the midsummer festival, is celebrated with wreaths and what?","a":"Bonfires and cheese","o":["Bonfires and cheese","Fireworks only","A fast","A silence"],"f":"On Jani, people stay up, sing, and eat caraway cheese. Meadows are said to hold special power that night."},{"q":"Which of these cities is the capital of Latvia?","a":"Riga","o":["Riga","Daugavpils","Liepāja","Jelgava"],"f":"Riga is the capital of Latvia.","kind":"capital"},{"q":"Which flag is the flag of Latvia?","a":"LVA","o":["LVA","AUT","PER","LBN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Latvia.","kind":"flag"}]}},{"id":"MAR","name":"Morocco","cont":"Africa","emoji":"🇲🇦","latlng":[32,-5],"q":{"easy":[{"q":"Which walled old city of tanneries and mosques is the historic heart of Fes?","a":"The medina of Fes","o":["The medina of Fes","The Casbah of Algiers","Stone Town","Mdina"],"f":"Fes el-Bali is one of the largest car-free medieval cities still lived in. Its dye pits are famous."},{"q":"Which slow-cooked clay pot of meat, fruit, and spices is a national dish?","a":"Tagine","o":["Tagine","Sushi","Paella","Poutine"],"f":"A tagine is both the stew and the conical pot. It simmers on a charcoal brazier."},{"q":"Which blue-washed mountain town in the Rif is famous for its painted lanes?","a":"Chefchaouen","o":["Chefchaouen","Marrakesh","Casablanca","Tangier"],"f":"Chefchaouen, in the Rif Mountains, is known for streets washed in blue and white."},{"q":"Which city is the capital of Morocco?","a":"Rabat","o":["Rabat","San José","Amman","Kyiv"],"f":"Rabat is the capital of Morocco.","kind":"capital"},{"q":"Which flag belongs to Morocco?","a":"MAR","o":["MAR","FSM","KNA","MNE"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Morocco.","kind":"flag"}],"medium":[{"q":"Which traveler, born in Tangier in 1304, dictated a famous account after nearly 30 years on the road?","a":"Ibn Battuta","o":["Ibn Battuta","Ibn Khaldun","Leo Africanus","Ibn Jubayr"],"f":"The Rihla describes journeys from West Africa to China. Ibn Khaldun, born in Tunis, wrote a theory of history. Leo Africanus grew up in Fez but was born in Granada. Ibn Jubayr was an earlier traveler from al-Andalus."},{"q":"Aït Benhaddou, a UNESCO village of earthen towers, stands on an old caravan road into which mountains?","a":"The Atlas","o":["The Atlas","The Alps","The Drakensberg","The Simien"],"f":"Caravans used it between the Sahara and Marrakech. The towers are rammed earth, repaired after rains. Film crews borrow the ksar because the shape reads clearly on camera."},{"q":"Volubilis, near Meknes, still shows mosaics from its time as a city of which empire?","a":"The Roman Empire","o":["The Roman Empire","The Ottoman Empire","The Songhai Empire","The Aksumite Empire"],"f":"It began as a town of Mauretanian kings and became a Roman center. A mosaic of the labors of Hercules is still there. Juba II, a local king educated in Rome, belongs to the same story."},{"q":"What is the capital city of Morocco?","a":"Rabat","o":["Rabat","Porto-Novo","Antananarivo","Accra"],"f":"Rabat is the capital of Morocco.","kind":"capital"},{"q":"Which of these flags belongs to Morocco?","a":"MAR","o":["MAR","ERI","LSO","SSD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Morocco.","kind":"flag"}],"hard":[{"q":"The Almoravid and Almohad dynasties of the Middle Ages came from which desert people?","a":"The Berber, or Amazigh, tribes","o":["The Berber, or Amazigh, tribes","The Vikings","The Inca","The Maori"],"f":"Amazigh reformers built empires that ruled Morocco and much of Spain."},{"q":"Which tiled garden courtyard and religious school, built in the 1300s, is a jewel of Fes?","a":"The Bou Inania Madrasa","o":["The Bou Inania Madrasa","The Alhambra","The Topkapi","The Forbidden City"],"f":"Marinid sultans endowed madrasas with carved cedar, tile, and plaster."},{"q":"The fantasia, a festival charge of horsemen, ends with what?","a":"A volley of gunpowder","o":["A volley of gunpowder","A polo goal","A bullfight","A boat race"],"f":"Riders in embroidered saddles gallop in line and fire muskets together."},{"q":"Which of these cities is the capital of Morocco?","a":"Rabat","o":["Rabat","Casablanca","Marrakesh","Fes"],"f":"Rabat is the capital of Morocco.","kind":"capital"},{"q":"Which flag is the flag of Morocco?","a":"MAR","o":["MAR","VNM","CHN","AUS"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Morocco.","kind":"flag"}]}},{"id":"MCO","name":"Monaco","cont":"Europe","emoji":"🇲🇨","latlng":[43.73333333,7.4],"q":{"easy":[{"q":"Which belle epoque casino is the landmark of Monte Carlo?","a":"The Casino de Monte-Carlo","o":["The Casino de Monte-Carlo","The Venetian","Baden-Baden","The Hippodrome"],"f":"The casino opened in the 1860s and funded the principality's growth. Its opera house sits in the same building."},{"q":"Which fried pastry filled with greens or pumpkin is a local snack?","a":"Barbagiuan","o":["Barbagiuan","Samosa","Pastizz","Empanada"],"f":"Barbagiuan means uncle John. The pastry is sold at festivals and bakeries."},{"q":"Which cliffside garden of cacti looks over the Mediterranean?","a":"The Jardin Exotique","o":["The Jardin Exotique","The Boboli","Kew","The Alhambra"],"f":"The exotic garden clings to a rock face. Caves of stalactites open underneath it."},{"q":"Which city is the capital of Monaco?","a":"Monaco","o":["Monaco","Malé","Islamabad","Castries"],"f":"Monaco is the capital of Monaco.","kind":"capital"},{"q":"Which flag belongs to Monaco?","a":"MCO","o":["MCO","TUR","GTM","SSD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Monaco.","kind":"flag"}],"medium":[{"q":"In 1297 Francois Grimaldi seized the rock of Monaco disguised as what?","a":"A Franciscan friar","o":["A Franciscan friar","A Venetian admiral","A Turkish merchant","A papal legate"],"f":"He and his cousins hid soldiers under monks' robes. The Grimaldi family still rules, and the coat of arms shows two friars with swords."},{"q":"The Monaco Grand Prix, first held in 1929, is unusual among major races because the track is made of what?","a":"Closed city streets","o":["Closed city streets","An oval of banked concrete","A desert salt flat","A frozen lake"],"f":"Cars pass within centimeters of barriers, harbor, and apartment blocks. The tunnel and the hairpin by the grand hotel are the famous corners."},{"q":"The Oceanographic Museum, on the cliff above the harbor, was directed for many years by which underwater explorer?","a":"Jacques Cousteau","o":["Jacques Cousteau","Thor Heyerdahl","Sylvia Earle","Robert Ballard"],"f":"Prince Albert I, a serious ocean scientist, founded the museum in 1910. Cousteau led it from 1957 to 1988."},{"q":"What is the capital city of Monaco?","a":"Monaco","o":["Monaco","Copenhagen","San Marino","Podgorica"],"f":"Monaco is the capital of Monaco.","kind":"capital"},{"q":"Which of these flags belongs to Monaco?","a":"MCO","o":["MCO","SVN","GBR","LVA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Monaco.","kind":"flag"}],"hard":[{"q":"The ruling family, the Grimaldi, bought the rock in 1297 by a legend of entering in what disguise?","a":"Franciscan friars","o":["Franciscan friars","Viking traders","Ottoman envoys","Masked carnival goers"],"f":"Francois Grimaldi, called the Malicious, is said to have seized the fortress dressed as a friar."},{"q":"Which ocean museum on the rock was long directed by a famous undersea explorer?","a":"The Oceanographic Museum","o":["The Oceanographic Museum","The Louvre","The Prado","The British Museum"],"f":"Prince Albert I, a scientist-prince, founded the museum. Jacques Cousteau later directed it for years."},{"q":"The rally and the tennis tournament are modern events, but the harbor's transformation in the 1900s added land by what method?","a":"Filling the sea","o":["Filling the sea","Draining a lake","Cutting a canal","Moving a river"],"f":"Fontvieille and parts of Larvotto sit on reclaimed ground. The principality grew without conquering a neighbor."},{"q":"Which of these cities is the capital of Monaco?","a":"Monaco","o":["Monaco","Nice","Menton","Cannes"],"f":"Monaco is the capital of Monaco.","kind":"capital"},{"q":"Which flag is the flag of Monaco?","a":"MCO","o":["MCO","IDN","POL","SGP"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Monaco.","kind":"flag"}]}},{"id":"MDA","name":"Moldova","cont":"Europe","emoji":"🇲🇩","latlng":[47,29],"q":{"easy":[{"q":"Which cave monastery and river bend is a famous open-air historic site?","a":"Orheiul Vechi","o":["Orheiul Vechi","Lavra of Kyiv","Meteora","Cappadocia"],"f":"A monastery is cut into a limestone cliff above the Raut. Earlier fortresses stood on the ridge."},{"q":"Which cornmeal porridge, similar to polenta, is the daily starch?","a":"Mamaliga","o":["Mamaliga","Risotto","Pasta","Bread only"],"f":"Mamaliga is served with cheese, sour cream, or stew. It is shared with Romania next door."},{"q":"Which mile-long wine cellars, dug in limestone, store millions of bottles?","a":"Cricova or Milestii Mici","o":["Cricova or Milestii Mici","Tokaj","Porto's lodges","Champagne caves"],"f":"Underground galleries near the capital hold national collections. Some tunnels are driven like streets."},{"q":"Which city is the capital of Moldova?","a":"Chișinău","o":["Chișinău","Ulaanbaatar","Jerusalem","Kuala Lumpur"],"f":"Chișinău is the capital of Moldova.","kind":"capital"},{"q":"Which flag belongs to Moldova?","a":"MDA","o":["MDA","VUT","IND","TJK"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Moldova.","kind":"flag"}],"medium":[{"q":"Milestii Mici stores wine in tunnels that were originally dug as what?","a":"Limestone mines","o":["Limestone mines","Salt mines","Metro lines","Air-raid shelters only"],"f":"The galleries run for hundreds of kilometers, and only a fraction holds bottles. Cricova, nearer Chisinau, is another underground cellar of the same kind."},{"q":"Orheiul Vechi is a cliff monastery and cave complex above a bend in which river?","a":"The Raut","o":["The Raut","The Danube","The Dniester","The Prut"],"f":"Monks carved cells into the limestone. Below them are traces of Geto-Dacian and Tatar settlements, so the bend has been lived in for more than two thousand years."},{"q":"Stephen the Great ruled Moldavia in the late 1400s and fought to keep it from which expanding empire?","a":"The Ottoman Empire","o":["The Ottoman Empire","The Spanish Empire","The British Empire","The Mughal Empire"],"f":"His realm included present-day Moldova and part of Romania. He built a church after many of his battles, and several of those painted churches survive."},{"q":"What is the capital city of Moldova?","a":"Chișinău","o":["Chișinău","Amsterdam","Madrid","Sarajevo"],"f":"Chișinău is the capital of Moldova.","kind":"capital"},{"q":"Which of these flags belongs to Moldova?","a":"MDA","o":["MDA","LIE","BIH","CYP"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Moldova.","kind":"flag"}],"hard":[{"q":"Which traditional carpet, with geometric flowers, is woven in villages and listed by UNESCO?","a":"The village flower carpet","o":["The village flower carpet","Persian Tabriz","Navajo rugs","Aubusson"],"f":"Village carpets covered benches and walls. Brides brought them as part of a dowry."},{"q":"The Soroca fortress on the Dniester was rebuilt in the 1500s against which raiders?","a":"Crimean Tatar raids","o":["Crimean Tatar raids","The Vikings","The Normans","The Inca"],"f":"Round stone towers guard a crossing. The fort was part of Moldavia's northern defense."},{"q":"Martisor, on the first of March, is marked by wearing what?","a":"A red-and-white thread","o":["A red-and-white thread","A mask","A crown","A black armband"],"f":"The little cord, a martisor, is given as a sign of spring. It is worn for several days."},{"q":"Which of these cities is the capital of Moldova?","a":"Chișinău","o":["Chișinău","Bălți","Cahul","Orhei"],"f":"Chișinău is the capital of Moldova.","kind":"capital"},{"q":"Which flag is the flag of Moldova?","a":"MDA","o":["MDA","AND","ROU","TCD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Moldova.","kind":"flag"}]}},{"id":"MDG","name":"Madagascar","cont":"Africa","emoji":"🇲🇬","latlng":[-20,47],"q":{"easy":[{"q":"Which famous avenue of giant baobabs stands near Morondava on the west coast?","a":"The Avenue of the Baobabs","o":["The Avenue of the Baobabs","The Champs-Elysees","The Appian Way","The Silk Road"],"f":"Grandidier's baobabs line a dirt road. They are among the widest trees on Earth."},{"q":"Which rice dish with beef or chicken, cooked in one pot, is Sunday food?","a":"Romazava's companion vary","o":["Romazava's companion vary","Sushi","Poutine","Ceviche"],"f":"Rice, called vary, is the staple. Romazava is a meat and greens stew served over it."},{"q":"Which lemurs with black and white coats and loud calls live only in Madagascar?","a":"Indri","o":["Indri","Koalas","Pandas","Sloths"],"f":"The indri is the largest living lemur. Its song carries through the eastern rainforest."},{"q":"Which city is the capital of Madagascar?","a":"Antananarivo","o":["Antananarivo","Seoul","Sana'a","Belgrade"],"f":"Antananarivo is the capital of Madagascar.","kind":"capital"},{"q":"Which flag belongs to Madagascar?","a":"MDG","o":["MDG","BOL","PER","QAT"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Madagascar.","kind":"flag"}],"medium":[{"q":"The island's main language is Austronesian. Its closest relatives are spoken where?","a":"Borneo","o":["Borneo","The Arabian Peninsula","The Andes","Southern Africa's click-language region"],"f":"Settlers from the Indonesian archipelago arrived, probably in the first millennium, before Bantu-speaking Africans. Genes and words both point across the Indian Ocean."},{"q":"Tsingy de Bemaraha, a UNESCO park, is a maze of what?","a":"Needle-sharp limestone pinnacles","o":["Needle-sharp limestone pinnacles","Granite domes","Sand dunes","Coral atolls"],"f":"Tsingy means a place where one cannot walk barefoot. Caves cut through the stone, and lemurs live in the pockets of forest on top."},{"q":"The Avenue of the Baobabs near Morondava is a row of which trees, left standing when fields replaced the forest?","a":"Grandidier's baobabs","o":["Grandidier's baobabs","Dragon blood trees","Joshua trees","Quiver trees"],"f":"Six of the world's baobab species grow only on this island. One African species and one Australian species live elsewhere. Dragon blood trees are the umbrellas of Socotra."},{"q":"What is the capital city of Madagascar?","a":"Antananarivo","o":["Antananarivo","Tripoli","Lilongwe","Gitega"],"f":"Antananarivo is the capital of Madagascar.","kind":"capital"},{"q":"Which of these flags belongs to Madagascar?","a":"MDG","o":["MDG","KEN","CMR","CIV"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Madagascar.","kind":"flag"}],"hard":[{"q":"Malagasy, the national language, is closest to languages of which distant region?","a":"Borneo in Southeast Asia","o":["Borneo in Southeast Asia","Iceland","The Andes","West Africa only"],"f":"Sailors from the Indonesian archipelago settled the island over a thousand years ago and brought their language."},{"q":"Which kingdom united much of the island from the highlands in the 1800s?","a":"The Merina kingdom","o":["The Merina kingdom","The Sakalava kingdom","The Betsimisaraka league","The Merina only of the coast"],"f":"Andrianampoinimerina and his son Radama expanded highland rule across much of the island."},{"q":"Famadihana, a highland custom, means families do what with ancestors?","a":"Rebury them in fresh cloth","o":["Rebury them in fresh cloth","Burn them at sea","Leave them on platforms","Mummify them in ice"],"f":"Every few years a family may open a tomb, rewrap the dead in new silk, and feast. Not every community practices it."},{"q":"Which of these cities is the capital of Madagascar?","a":"Antananarivo","o":["Antananarivo","Toamasina","Antsirabe","Fianarantsoa"],"f":"Antananarivo is the capital of Madagascar.","kind":"capital"},{"q":"Which flag is the flag of Madagascar?","a":"MDG","o":["MDG","NOR","SAU","NGA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Madagascar.","kind":"flag"}]}},{"id":"MDV","name":"Maldives","cont":"Asia","emoji":"🇲🇻","latlng":[3.25,73],"q":{"easy":[{"q":"Which traditional wooden boat with a square stern is the island workhorse?","a":"The dhoni","o":["The dhoni","The dhow","The junk","The luzzu"],"f":"A dhoni carries people and fish between islands. Modern ones often have a diesel engine."},{"q":"Which clear fish soup with lime and chili is home cooking?","a":"Garudhiya","o":["Garudhiya","Tom yum","Bouillabaisse","Ceviche"],"f":"Garudhiya is tuna or reef fish boiled with salt and spices. Rice and lime come with it."},{"q":"Which coral rings with a lagoon inside make up the country's geography?","a":"Atolls","o":["Atolls","Volcanic cones","Deltas","Fjords"],"f":"About 1,200 islands sit on 26 atolls. Many are only a meter or two above the sea."},{"q":"Which city is the capital of Maldives?","a":"Malé","o":["Malé","Port Louis","Lisbon","Brussels"],"f":"Malé is the capital of Maldives.","kind":"capital"},{"q":"Which flag belongs to Maldives?","a":"MDV","o":["MDV","AUT","MDG","PLW"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Maldives.","kind":"flag"}],"medium":[{"q":"For centuries, small white shells from these atolls were shipped as far as Africa and used as money. What are they called?","a":"Cowries","o":["Cowries","Conches","Nautiluses","Abalone"],"f":"The money cowrie was light and hard to fake. West African markets were still counting the shells long after the islands had moved on to other trade."},{"q":"These coral islands have almost no hills. Their average ground sits about how far above the sea?","a":"One to two meters","o":["One to two meters","About 50 meters","About 200 meters","About 1,000 meters"],"f":"There are no rivers. Fresh water sits in thin lenses under the sand, which is why a higher sea threatens the whole country."},{"q":"Grated coconut, onion, chili, and smoked tuna, eaten at breakfast with flatbread, is called what?","a":"Mas huni","o":["Mas huni","Garudhiya","Hoppers","Nasi lemak"],"f":"Garudhiya is the clear tuna broth served with rice, a different dish. Skipjack has always been the fish these islands depend on."},{"q":"What is the capital city of Maldives?","a":"Malé","o":["Malé","Thimphu","Kuwait City","Bishkek"],"f":"Malé is the capital of Maldives.","kind":"capital"},{"q":"Which of these flags belongs to Maldives?","a":"MDV","o":["MDV","JPN","IDN","PSE"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Maldives.","kind":"flag"}],"hard":[{"q":"Cowrie shells from these islands were once used across Africa and Asia as what?","a":"Money","o":["Money","Food","Dye","Medicine only"],"f":"Cypraea shells were light and durable. Traders carried them as far as West Africa."},{"q":"Boduberu drumming and which Islamic calendar of festivals shape island culture?","a":"The Islamic year and drum dances","o":["The Islamic year and drum dances","Carnival","Diwali","Songkran"],"f":"The islands became Muslim through Indian Ocean trade. Boduberu drums still play at celebrations."},{"q":"Tuna, caught by pole and line, is the main export fish. The method is used to limit what?","a":"Bycatch of other species","o":["Bycatch of other species","The size of the boat","The price","The spice"],"f":"Pole-and-line boats flick water and catch tuna one by one, which avoids some of the waste of large nets."},{"q":"Which of these cities is the capital of Maldives?","a":"Malé","o":["Malé","Addu City","Fuvahmulah","Kulhudhuffushi"],"f":"Malé is the capital of Maldives.","kind":"capital"},{"q":"Which flag is the flag of Maldives?","a":"MDV","o":["MDV","PSE","LAO","THA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Maldives.","kind":"flag"}]}},{"id":"MEX","name":"Mexico","cont":"North America","emoji":"🇲🇽","latlng":[23,-102],"q":{"easy":[{"q":"Which ancient city of the Pyramid of the Sun stands northeast of the capital?","a":"Teotihuacan","o":["Teotihuacan","Chichen Itza","Palenque","Tenochtitlan"],"f":"Teotihuacan flourished around the 400s. Its broad avenue is called the Street of the Dead."},{"q":"Which sauce of chili and chocolate, and a flatbread, define the kitchen?","a":"Mole and tortillas","o":["Mole and tortillas","Tacos only","Ceviche","Pupusas"],"f":"Mole poblano combines chilies, spices, and a little chocolate. Corn tortillas are the daily bread."},{"q":"Which painter of epic murals, married to Frida Kahlo, covered public walls in the 20th century?","a":"Diego Rivera","o":["Diego Rivera","Orozco","Siqueiros","Tamayo"],"f":"Rivera painted the history of Mexico on ministry walls. Kahlo's self-portraits made her equally famous."},{"q":"Which city is the capital of Mexico?","a":"Mexico City","o":["Mexico City","Warsaw","Dublin","Palikir"],"f":"Mexico City is the capital of Mexico.","kind":"capital"},{"q":"Which flag belongs to Mexico?","a":"MEX","o":["MEX","NRU","ALB","GBR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Mexico.","kind":"flag"}],"medium":[{"q":"Which chemist, born in Tepic, first synthesized norethindrone in 1951, a key step toward the oral contraceptive?","a":"Luis Miramontes","o":["Luis Miramontes","Alexander Fleming","Percy Julian","Selman Waksman"],"f":"He was in his twenties, working in Mexico City with Carl Djerassi and Jorge Rosenkranz. The compound was made from chemicals drawn from Mexican yams."},{"q":"Teotihuacan, with the Pyramids of the Sun and Moon, was already abandoned when which later people gave it that name?","a":"The Aztecs","o":["The Aztecs","The Inca","The Olmecs","The Spanish"],"f":"The name means the place where the gods were created. The city's own builders left almost no readable writing, so their name for it is unknown."},{"q":"Nixtamalization, developed in ancient Mesoamerica, soaks dried corn in water mixed with what?","a":"Lime or wood ash","o":["Lime or wood ash","Sea salt","Honey","Chili oil"],"f":"The alkaline bath unlocks niacin and makes the protein easier to use, which prevented pellagra. The same process produces masa for tortillas."},{"q":"What is the capital city of Mexico?","a":"Mexico City","o":["Mexico City","San José","Guatemala City","Santo Domingo"],"f":"Mexico City is the capital of Mexico.","kind":"capital"},{"q":"Which of these flags belongs to Mexico?","a":"MEX","o":["MEX","JAM","NIC","GTM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Mexico.","kind":"flag"}],"hard":[{"q":"Which 1810 parish cry in Dolores began the war of independence?","a":"The Grito de Dolores","o":["The Grito de Dolores","The Plan of Iguala","The Constitution of 1917","The Reform War"],"f":"Miguel Hidalgo rang the church bell on 16 September 1810. Independence Day repeats the cry."},{"q":"The Day of the Dead altars set out marigolds and which sweet bread?","a":"Pan de muerto","o":["Pan de muerto","Rosca de reyes","Conchas","Bolillo"],"f":"Families remember the dead at the start of November. Sugar skulls and pan de muerto go on the altar."},{"q":"Which silver city in the mountains has a baroque church and tunnel streets?","a":"Guanajuato","o":["Guanajuato","Taxco","Zacatecas","San Miguel"],"f":"Guanajuato grew rich on silver. Its alley, the Callejon del Beso, is a tourist legend."},{"q":"Which of these cities is the capital of Mexico?","a":"Mexico City","o":["Mexico City","Guadalajara","Monterrey","Cancún"],"f":"Mexico City is the capital of Mexico.","kind":"capital"},{"q":"Which flag is the flag of Mexico?","a":"MEX","o":["MEX","CIV","ITA","IRL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Mexico.","kind":"flag"}]}},{"id":"MHL","name":"Marshall Islands","cont":"Oceania","emoji":"🇲🇭","latlng":[9,168],"q":{"easy":[{"q":"Which low coral islands and a huge lagoon define the country?","a":"Atolls","o":["Atolls","Volcanic peaks","High islands","Canyons"],"f":"The Marshall Islands are two chains of atolls, the Ratak and the Ralik. Land sits only a few meters above the sea."},{"q":"Which raw fish with coconut and a baked breadfruit are island food?","a":"Fish and breadfruit","o":["Fish and breadfruit","Spam only","Rice only","Taro only"],"f":"Reef fish is eaten raw with lime or cooked in coconut cream. Breadfruit is roasted in a pit."},{"q":"Which stick charts and outrigger canoes were the old tools of travel?","a":"Navigation charts and canoes","o":["Navigation charts and canoes","Steamships","Compasses only","Planes"],"f":"Canoes linked the atolls. Knowledge of stars and swells was a specialist craft."},{"q":"Which city is the capital of Marshall Islands?","a":"Majuro","o":["Majuro","Madrid","Yamoussoukro","Bissau"],"f":"Majuro is the capital of Marshall Islands.","kind":"capital"},{"q":"Which flag belongs to Marshall Islands?","a":"MHL","o":["MHL","KNA","MNG","CAF"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Marshall Islands.","kind":"flag"}],"medium":[{"q":"From 1946 to 1958 the United States tested nuclear weapons at which atoll after moving its people away?","a":"Bikini Atoll","o":["Bikini Atoll","Chuuk Lagoon","Funafuti","Tarawa"],"f":"The swimsuit was named after the tests. Fallout and relocation meant many Bikinians could not safely return home."},{"q":"Marshallese stick charts were teaching tools for what, rather than maps carried on a voyage?","a":"Ocean swell patterns","o":["Ocean swell patterns","Star brightness","Bird migration dates","Coral species"],"f":"Shells stood for islands and curved sticks for reflected swells. Sailors memorized the lesson, then crossed the ocean without the chart."},{"q":"Kwajalein surrounds one of the world's largest lagoons. An atoll is mainly a ring of what?","a":"Low coral islets","o":["Low coral islets","Granite peaks","River deltas","Sandstone cliffs"],"f":"Reefs grow around a sinking volcano. When the volcano is gone, the reef and its islets remain around a lagoon."},{"q":"What is the capital city of Marshall Islands?","a":"Majuro","o":["Majuro","Canberra","Yaren","Honiara"],"f":"Majuro is the capital of Marshall Islands.","kind":"capital"},{"q":"Which of these flags belongs to Marshall Islands?","a":"MHL","o":["MHL","KIR","NZL","TON"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Marshall Islands.","kind":"flag"}],"hard":[{"q":"Which large outrigger sailing canoe was the traditional craft for voyages between atolls?","a":"The walap","o":["The walap","The Fijian drua","The Maori waka","A Chinese junk"],"f":"A walap was lashed with coconut fiber and could carry people across open water. Navigators read the swell."},{"q":"Kwajalein atoll hosts which kind of modern installation?","a":"A missile test range","o":["A missile test range","A space elevator","A naval museum only","A phosphate mine"],"f":"The United States tests missiles into the lagoon under a compact of free association. Islanders live on Ebeye nearby."},{"q":"Which large land crab is a prized food?","a":"The coconut crab","o":["The coconut crab","The lobster","The mantis shrimp","The horseshoe crab"],"f":"Coconut crabs climb palms and crack nuts. They are the largest land arthropods and are now protected in places."},{"q":"Which of these cities is the capital of Marshall Islands?","a":"Majuro","o":["Majuro","Ebeye","Jaluit","Wotje"],"f":"Majuro is the capital of Marshall Islands.","kind":"capital"},{"q":"Which flag is the flag of Marshall Islands?","a":"MHL","o":["MHL","CPV","ITA","PLW"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Marshall Islands.","kind":"flag"}]}},{"id":"MKD","name":"North Macedonia","cont":"Europe","emoji":"🇲🇰","latlng":[41.83333333,22],"q":{"easy":[{"q":"Which lake town of early churches and a fortress is a UNESCO site?","a":"Ohrid","o":["Ohrid","Bitola","Prilep","Struga"],"f":"Ohrid's medieval churches hold icons and frescoes. The lake is shared with Albania."},{"q":"Which baked beans in a clay pot are a national dish?","a":"Tavce gravce","o":["Tavce gravce","Fasolada","Cassoulet","Chili"],"f":"Tavce gravce is beans baked with paprika and onion. It is served in the clay dish it cooked in."},{"q":"Which stone bridge in Skopje's old bazaar crosses the Vardar?","a":"The Stone Bridge","o":["The Stone Bridge","Stari Most","Charles Bridge","The Rialto"],"f":"The Stone Bridge linked the bazaar and the fortress. It has been rebuilt several times after floods and quakes."},{"q":"Which city is the capital of North Macedonia?","a":"Skopje","o":["Skopje","Ramallah","Amman","Lilongwe"],"f":"Skopje is the capital of North Macedonia.","kind":"capital"},{"q":"Which flag belongs to North Macedonia?","a":"MKD","o":["MKD","GHA","KOR","TCD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of North Macedonia.","kind":"flag"}],"medium":[{"q":"Lake Ohrid is often called Europe's oldest lake. It is also unusual for the number of species that live where?","a":"Only in this lake","o":["Only in this lake","Only in the open ocean","Only on glaciers","Only in the Sahara"],"f":"Snails, trout, and other animals evolved in isolation over hundreds of thousands of years. The town of Ohrid, with its medieval churches, shares the UNESCO listing."},{"q":"Under an agreement with Greece, the country officially became North Macedonia in which year?","a":"2019","o":["2019","1991","2001","2018"],"f":"The Prespa Agreement settled a long dispute over the name Macedonia. The change took effect on 12 February 2019 and opened the door to closer ties with NATO and the European Union."},{"q":"Ohrid was once known as the Jerusalem of the Balkans because of how many of which buildings it had?","a":"Churches","o":["Churches","Lighthouses","Minarets only","Synagogues"],"f":"A medieval saying claimed it had 365 churches, one for each day. The real number was smaller, but the old town is still dense with monasteries and frescoed chapels."},{"q":"What is the capital city of North Macedonia?","a":"Skopje","o":["Skopje","Chișinău","Madrid","Moscow"],"f":"Skopje is the capital of North Macedonia.","kind":"capital"},{"q":"Which of these flags belongs to North Macedonia?","a":"MKD","o":["MKD","RUS","CHE","ITA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of North Macedonia.","kind":"flag"}],"hard":[{"q":"The Kokino ridge holds Bronze Age stones aligned for what?","a":"Watching the sun and moon","o":["Watching the sun and moon","A Roman road","A medieval fair","A ski jump"],"f":"Archaeologists describe Kokino as a megalithic observatory. The claim is studied, not a fantasy of aliens."},{"q":"Which embroidery and folk costumes of the villages are worn at weddings?","a":"Embroidered shirts and vests","o":["Embroidered shirts and vests","Kimonos","Kente","Tartan"],"f":"Red and black embroidery marks regional dress. Dance troupes keep the costumes on stage."},{"q":"Saint Clement of Ohrid, a student of Cyril and Methodius, founded a school famous for what?","a":"The Cyrillic tradition","o":["The Cyrillic tradition","The Latin alphabet","Glagolitic only in Croatia","Runes"],"f":"Clement's school at Ohrid taught Slavic clergy. The town became a literary center of the First Bulgarian Empire's culture."},{"q":"Which of these cities is the capital of North Macedonia?","a":"Skopje","o":["Skopje","Bitola","Ohrid","Kumanovo"],"f":"Skopje is the capital of North Macedonia.","kind":"capital"},{"q":"Which flag is the flag of North Macedonia?","a":"MKD","o":["MKD","UZB","MMR","IDN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of North Macedonia.","kind":"flag"}]}},{"id":"MLI","name":"Mali","cont":"Africa","emoji":"🇲🇱","latlng":[17,-4],"q":{"easy":[{"q":"Which ancient city of mud mosques and manuscripts stands on the edge of the Sahara?","a":"Timbuktu","o":["Timbuktu","Marrakesh","Fez","Cairo"],"f":"Timbuktu's Sankore mosque and libraries made it a center of Islamic learning under the Songhai and before them."},{"q":"Which peanut sauce with rice is a common family meal?","a":"Tigadegena","o":["Tigadegena","Sushi","Paella","Poutine"],"f":"Groundnut sauce, often with meat or greens, is poured over rice or millet."},{"q":"The Bandiagara cliffs are the homeland of which people famous for masked dances and villages on the rock?","a":"The Dogon","o":["The Dogon","The Maasai","The Zulu","The Berbers"],"f":"Dogon villages cling to the escarpment. Their masks come out at the dama ceremonies."},{"q":"Which city is the capital of Mali?","a":"Bamako","o":["Bamako","Vilnius","Reykjavík","Naypyidaw"],"f":"Bamako is the capital of Mali.","kind":"capital"},{"q":"Which flag belongs to Mali?","a":"MLI","o":["MLI","SLB","MDA","FRA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Mali.","kind":"flag"}],"medium":[{"q":"Mansa Musa of the Mali Empire made a famous pilgrimage to Mecca in which year?","a":"1324","o":["1324","1066","1453","1591"],"f":"His party carried so much gold that Cairo prices were said to sag for years. A Moroccan army took Timbuktu in 1591, long after his reign. He inherited the empire; he did not found it."},{"q":"The Great Mosque of Djenné is widely called the largest mud-brick building. The one standing now was rebuilt in which year?","a":"1907","o":["1907","1324","800","1960"],"f":"Older mosques stood on the site for centuries. Residents still replaster the walls in a yearly festival. The building you photograph is not an untouched medieval original."},{"q":"From the 14th century, Timbuktu was famous across the Islamic world especially as a center of what?","a":"Scholarship and manuscript libraries","o":["Scholarship and manuscript libraries","Atlantic shipbuilding","Coal mining","Porcelain export"],"f":"Sankore gathered teachers and students. Families hid manuscripts in private libraries that conservators still catalog. The city was a university town on the desert edge, not a seaport."},{"q":"What is the capital city of Mali?","a":"Bamako","o":["Bamako","Rabat","Mogadishu","Juba"],"f":"Bamako is the capital of Mali.","kind":"capital"},{"q":"Which of these flags belongs to Mali?","a":"MLI","o":["MLI","CMR","GMB","SSD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Mali.","kind":"flag"}],"hard":[{"q":"Mansa Musa of Mali made a famous pilgrimage in 1324 to which city?","a":"Mecca","o":["Mecca","Rome","Jerusalem only as a side trip","Lhasa"],"f":"His caravan crossed the Sahara with so much gold that prices in Cairo were said to fall."},{"q":"The Great Mosque of Djenne, rebuilt in 1907 on an older plan, is made of what?","a":"Mud brick","o":["Mud brick","Marble","Concrete and glass","Timber only"],"f":"Each year residents replaster the mosque in a festival. Wooden beams stick out as permanent scaffolding."},{"q":"The griot's 21-string harp-lute is called what?","a":"The kora","o":["The kora","The sitar","The banjo","The oud"],"f":"Griots sing the Sunjata epic and family histories with the kora. The instrument is shared across the Manding world."},{"q":"Which of these cities is the capital of Mali?","a":"Bamako","o":["Bamako","Timbuktu","Sikasso","Ségou"],"f":"Bamako is the capital of Mali.","kind":"capital"},{"q":"Which flag is the flag of Mali?","a":"MLI","o":["MLI","GNB","SEN","GIN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Mali.","kind":"flag"}]}},{"id":"MLT","name":"Malta","cont":"Europe","emoji":"🇲🇹","latlng":[35.83333333,14.58333333],"q":{"easy":[{"q":"Which flaky pastry filled with ricotta or peas is a street snack?","a":"Pastizzi","o":["Pastizzi","Samosa","Empanada","Croissant"],"f":"Pastizzi are sold from small shops. The ricotta filling is called a pastizz tal-irkotta."},{"q":"Which fishing boats are painted in bright bands with an eye on the bow?","a":"Luzzu","o":["Luzzu","Gondolas","Dhows","Junks"],"f":"The eye of Osiris, or Horus, is said to protect the boat. Colors once marked the home village."},{"q":"Which limestone temples, older than the pyramids of Giza, stand on the islands?","a":"The megalithic temples","o":["The megalithic temples","Stonehenge","The Parthenon","Carnac only"],"f":"Ggantija, Hagar Qim, and Mnajdra were built between about 3600 and 2500 BCE."},{"q":"Which city is the capital of Malta?","a":"Valletta","o":["Valletta","Abuja","Freetown","Luanda"],"f":"Valletta is the capital of Malta.","kind":"capital"},{"q":"Which flag belongs to Malta?","a":"MLT","o":["MLT","SGP","BGD","CIV"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Malta.","kind":"flag"}],"medium":[{"q":"The Ggantija temples on Gozo were built around 3600 BCE, which makes them older than what?","a":"The Great Pyramid of Giza","o":["The Great Pyramid of Giza","The cave paintings of Lascaux","The city of Jericho","Gobekli Tepe"],"f":"They are among the oldest free-standing stone buildings still standing. Lascaux, Jericho, and Gobekli Tepe are older, which is why the pyramid is the right comparison."},{"q":"In 1565 the Ottoman Empire besieged Malta and failed to take it from which knights?","a":"The Knights of St. John","o":["The Knights of St. John","The Templars","The Teutonic Knights","The Knights of the Garter"],"f":"The Great Siege ended in September when a relief force arrived. The knights then built Valletta, named for their grand master Jean de Valette."},{"q":"In 1942 King George VI awarded the George Cross for collective bravery to the people of Malta. It recognized their endurance of what?","a":"Axis bombing and siege","o":["Axis bombing and siege","A volcanic eruption","A famine of 1848","A pirate raid in 1565"],"f":"Malta sat on the supply route to North Africa, and the islands were among the most bombed places of the war. The cross still appears on the national flag."},{"q":"What is the capital city of Malta?","a":"Valletta","o":["Valletta","Luxembourg City","Copenhagen","Tirana"],"f":"Valletta is the capital of Malta.","kind":"capital"},{"q":"Which of these flags belongs to Malta?","a":"MLT","o":["MLT","ITA","LIE","CZE"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Malta.","kind":"flag"}],"hard":[{"q":"The Knights of St John moved their headquarters here in 1530 after leaving which island?","a":"Rhodes","o":["Rhodes","Cyprus","Crete","Malta was the first"],"f":"Charles V granted Malta to the Order. They built Valletta after the Great Siege of 1565."},{"q":"Which golden limestone, cut from local quarries, colors the cities?","a":"Globigerina limestone","o":["Globigerina limestone","Marble","Granite","Basalt"],"f":"The soft stone weathers to a honey color. It is easy to carve into balconies and baroque scrolls."},{"q":"The Mdina, the old inland capital, is nicknamed what because of its quiet nights?","a":"The Silent City","o":["The Silent City","The White City","The Eternal City","The Big Apple"],"f":"Mdina's narrow streets are largely closed to cars. It was the capital before the Knights built Valletta."},{"q":"Which of these cities is the capital of Malta?","a":"Valletta","o":["Valletta","Mdina","Sliema","Birgu"],"f":"Valletta is the capital of Malta.","kind":"capital"},{"q":"Which flag is the flag of Malta?","a":"MLT","o":["MLT","SLE","PAK","FSM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Malta.","kind":"flag"}]}},{"id":"MMR","name":"Myanmar","cont":"Asia","emoji":"🇲🇲","latlng":[22,98],"q":{"easy":[{"q":"Which gilded pagoda in Yangon is the country's most famous Buddhist site?","a":"The Shwedagon Pagoda","o":["The Shwedagon Pagoda","Bagan","The Mahamuni","Kyaiktiyo"],"f":"The Shwedagon is said to hold relics of the Buddha. Its stupa is covered in gold."},{"q":"Which fish noodle soup, eaten at breakfast, is the national dish?","a":"Mohinga","o":["Mohinga","Pho","Ramen","Laksa"],"f":"Mohinga is rice noodles in a fish broth with lemongrass and banana stem. Stalls serve it in the morning."},{"q":"Which lake of stilt villages and leg-rowing fishermen is in the Shan hills?","a":"Inle Lake","o":["Inle Lake","Tonle Sap","The Dead Sea","Lake Toba"],"f":"Inle's gardens float on mats of vegetation. Fishermen row with one leg to keep their hands free."},{"q":"Which city is the capital of Myanmar?","a":"Naypyidaw","o":["Naypyidaw","Moscow","Skopje","Zagreb"],"f":"Naypyidaw became the capital in 2005. Yangon was the capital until then and is still the largest city.","kind":"capital"},{"q":"Which flag belongs to Myanmar?","a":"MMR","o":["MMR","GNQ","EGY","CAF"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Myanmar.","kind":"flag"}],"medium":[{"q":"Who, born in Pantanaw in 1909, was secretary-general of the United Nations from 1961 to 1971?","a":"U Thant","o":["U Thant","Dag Hammarskjöld","Kurt Waldheim","Boutros Boutros-Ghali"],"f":"He took office after Dag Hammarskjold died in a plane crash. U is a title of respect; he had no family surname in the Western sense. Waldheim and Boutros-Ghali held the post later."},{"q":"More than two thousand Buddhist temples still stand on a plain by the Irrawaddy, mostly from the 11th to 13th centuries. What is that plain called?","a":"Bagan","o":["Bagan","Mandalay","Sukhothai","Ayutthaya"],"f":"Bagan was the seat of the first Burmese empire. A 1975 earthquake damaged many monuments, and UNESCO listed the area in 2019. Sukhothai and Ayutthaya are in Thailand."},{"q":"The long 19th-century footbridge at Amarapura is built mainly of which wood?","a":"Teak","o":["Teak","Bamboo","Ebony","Pine"],"f":"U Bein is said to have used posts from a deserted royal palace. The bridge runs about 1.2 kilometers and is often called one of the longest teak footbridges."},{"q":"What is the capital city of Myanmar?","a":"Naypyidaw","o":["Naypyidaw","Jakarta","Kuala Lumpur","Seoul"],"f":"Naypyidaw became the capital in 2005. Yangon was the capital until then and is still the largest city.","kind":"capital"},{"q":"Which of these flags belongs to Myanmar?","a":"MMR","o":["MMR","ARE","QAT","ISR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Myanmar.","kind":"flag"}],"hard":[{"q":"Which pilgrimage site is a small pagoda perched on a gilded boulder?","a":"The golden rock","o":["The golden rock","The Shwedagon","Mount Popa","Mandalay Hill"],"f":"Pilgrims press gold leaf onto the boulder. The site, Kyaiktiyo, stands in the hills of the southeast."},{"q":"The chinlone game keeps a rattan ball in the air with what?","a":"Feet and knees, not hands","o":["Feet and knees, not hands","Only the head","Rackets","Sticks"],"f":"Chinlone is a circle of players who pass a woven ball with graceful kicks. It is more dance than contest."},{"q":"Thanaka, a yellow paste worn on the face, is ground from what?","a":"Tree bark","o":["Tree bark","Turmeric only","Clay","Rice powder"],"f":"The bark of the thanaka tree is ground on a stone with water. The paste is a cosmetic and a sunscreen."},{"q":"Which of these cities is the capital of Myanmar?","a":"Naypyidaw","o":["Naypyidaw","Yangon","Mandalay","Bagan"],"f":"Naypyidaw became the capital in 2005. Yangon was the capital until then and is still the largest city.","kind":"capital"},{"q":"Which flag is the flag of Myanmar?","a":"MMR","o":["MMR","ECU","ALB","MYS"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Myanmar.","kind":"flag"}]}},{"id":"MNE","name":"Montenegro","cont":"Europe","emoji":"🇲🇪","latlng":[42.5,19.3],"q":{"easy":[{"q":"Which winding bay of medieval towns is the country's most famous landscape?","a":"The Bay of Kotor","o":["The Bay of Kotor","The Bosphorus","The Amalfi Coast","The fjords of Norway"],"f":"Kotor's walls climb the cliff above a drowned river valley. Perast and its island church sit farther out."},{"q":"Which smoked ham of the Njegusi plateau is a national product?","a":"Njeguski prsut","o":["Njeguski prsut","Jamón","Prosciutto of Parma","Speck"],"f":"The ham is cured in the mountain air above Kotor. It is served with cheese and wine."},{"q":"Which cliff monastery, reached by a mountain road, is a major pilgrimage site?","a":"Ostrog","o":["Ostrog","Rila","Studenica","Athos"],"f":"Ostrog is built into a vertical rock. It honors Saint Basil of Ostrog and draws visitors of several faiths."},{"q":"Which city is the capital of Montenegro?","a":"Podgorica","o":["Podgorica","Asmara","Manama","Santo Domingo"],"f":"Podgorica is the capital of Montenegro.","kind":"capital"},{"q":"Which flag belongs to Montenegro?","a":"MNE","o":["MNE","SLE","NAM","KOR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Montenegro.","kind":"flag"}],"medium":[{"q":"Which prince-bishop and poet, born in Njegusi, wrote The Mountain Wreath?","a":"Petar II Petrovic-Njegos","o":["Petar II Petrovic-Njegos","Ivo Andric","Vuk Karadzic","Djura Jaksic"],"f":"He ruled Montenegro in the 1830s and 1840s and is buried on Mount Lovcen. The poem is about honor, faith, and the struggle with the Ottomans."},{"q":"The Bay of Kotor looks like a fjord but is actually a drowned river canyon. It opens into which sea?","a":"The Adriatic","o":["The Adriatic","The Black Sea","The Aegean","The Tyrrhenian"],"f":"Medieval towns such as Kotor and Perast climb its cliffs. The whole region is a UNESCO cultural landscape."},{"q":"The country's name, Montenegro in Italian and Crna Gora in the local language, means what?","a":"Black mountain","o":["Black mountain","Silver coast","High lake","Old bridge"],"f":"Venetian sailors saw dark forests on the mountains above the coast. Crna Gora is the same name in the South Slavic language."},{"q":"What is the capital city of Montenegro?","a":"Podgorica","o":["Podgorica","Oslo","Minsk","Bern"],"f":"Podgorica is the capital of Montenegro.","kind":"capital"},{"q":"Which of these flags belongs to Montenegro?","a":"MNE","o":["MNE","LVA","NLD","SWE"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Montenegro.","kind":"flag"}],"hard":[{"q":"The name of the country refers to forests so dark they looked black. Which range carries that name inland?","a":"The Lovcen and inland ranges","o":["The Lovcen and inland ranges","The Alps","The Caucasus","The Pindus"],"f":"Venetian maps called the hinterland the black mountain. The coast was once separate, under various rulers."},{"q":"Which deep canyon of green water, popular with rafters, is cut by a tributary of the Drina?","a":"The Tara Canyon","o":["The Tara Canyon","The Grand Canyon","Samaria Gorge","The Verdon"],"f":"The Tara Canyon is among the deepest in Europe. Its water is a cold green between limestone walls."},{"q":"Which old royal capital in the hills still holds palaces and embassies from the principality era?","a":"Cetinje","o":["Cetinje","Podgorica","Kotor","Niksic"],"f":"Cetinje was the capital of the prince-bishops and later of the kingdom. Museums and embassies still line its streets."},{"q":"Which of these cities is the capital of Montenegro?","a":"Podgorica","o":["Podgorica","Nikšić","Kotor","Budva"],"f":"Podgorica is the capital of Montenegro.","kind":"capital"},{"q":"Which flag is the flag of Montenegro?","a":"MNE","o":["MNE","GRC","BEL","HUN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Montenegro.","kind":"flag"}]}},{"id":"MNG","name":"Mongolia","cont":"Asia","emoji":"🇲🇳","latlng":[46,105],"q":{"easy":[{"q":"Which cold desert of dinosaurs fossils and sand dunes fills the south?","a":"The Gobi","o":["The Gobi","The Sahara","The Namib","The Taklamakan only"],"f":"The Gobi stretches into China. Flaming Cliffs have yielded famous dinosaur eggs."},{"q":"Which steamed dumplings filled with meat are a winter staple?","a":"Buuz","o":["Buuz","Momo","Mandu","Pierogi"],"f":"Buuz are pinched at the top and steamed. They are essential at the lunar new year, Tsagaan Sar."},{"q":"Which overtone singing produces two notes at once?","a":"Khoomei","o":["Khoomei","Yodeling","Throat singing of only Tuva","Rap"],"f":"A singer holds a drone and shapes a whistle-like melody above it. Regional styles have different names."},{"q":"Which city is the capital of Mongolia?","a":"Ulaanbaatar","o":["Ulaanbaatar","Helsinki","Harare","Lusaka"],"f":"Ulaanbaatar is the capital of Mongolia.","kind":"capital"},{"q":"Which flag belongs to Mongolia?","a":"MNG","o":["MNG","LBY","LBR","UKR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Mongolia.","kind":"flag"}],"medium":[{"q":"Temujin, later called Genghis Khan, was born in the 1160s beside which river, according to the Mongol chronicle?","a":"The Onon","o":["The Onon","The Yellow River","The Volga","The Amu Darya"],"f":"In 1206 he took the title Genghis Khan after uniting the steppe tribes. The empire his family built became the largest contiguous land empire in history."},{"q":"The midsummer festival Naadam is built around which three sports?","a":"Wrestling, archery, and horse racing","o":["Wrestling, archery, and horse racing","Falconry, polo, and shooting","Sumo, judo, and kendo","Polo, buzkashi, and tent pegging"],"f":"Child jockeys race for many kilometers across open steppe. A winning wrestler earns a title that can grow with later victories."},{"q":"Herders call their round felt tent what in Mongolian?","a":"A ger","o":["A ger","A teepee","A lavvu","A chum"],"f":"Turkic speakers call the same tent a yurt. The roof ring lets out smoke and lets in light, and a family can pack the whole frame onto animals in an afternoon."},{"q":"What is the capital city of Mongolia?","a":"Ulaanbaatar","o":["Ulaanbaatar","Jakarta","Tokyo","Dili"],"f":"Ulaanbaatar is the capital of Mongolia.","kind":"capital"},{"q":"Which of these flags belongs to Mongolia?","a":"MNG","o":["MNG","IND","PSE","UZB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Mongolia.","kind":"flag"}],"hard":[{"q":"Naadam, the national festival, crowns winners in wrestling, archery, and which third sport?","a":"Horse racing","o":["Horse racing","Falconry","Polo","Skating"],"f":"Child jockeys race horses across the steppe. Wrestling has no weight classes and no time limit."},{"q":"The classical vertical script, still used beside Cyrillic, was adapted from which older alphabet?","a":"The Old Uyghur script","o":["The Old Uyghur script","Chinese characters","The Arabic script","The Latin alphabet"],"f":"In the 1200s scribes took up a script based on Old Uyghur. It is written in vertical columns and remains in ceremonial use."},{"q":"The Orkhon inscriptions of the 700s are the oldest long texts in which language family?","a":"Turkic","o":["Turkic","Chinese","Mongolian of the classical script only","Tibetan"],"f":"The stones honor the Gokturk khans. They stand in the Orkhon valley, a later Mongol heartland."},{"q":"Which of these cities is the capital of Mongolia?","a":"Ulaanbaatar","o":["Ulaanbaatar","Erdenet","Darkhan","Khovd"],"f":"Ulaanbaatar is the capital of Mongolia.","kind":"capital"},{"q":"Which flag is the flag of Mongolia?","a":"MNG","o":["MNG","DEU","NAM","LSO"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Mongolia.","kind":"flag"}]}},{"id":"MOZ","name":"Mozambique","cont":"Africa","emoji":"🇲🇿","latlng":[-18.25,35],"q":{"easy":[{"q":"Which island city of stone palaces and chapels was a Portuguese Indian-Ocean capital?","a":"The stone island town","o":["The stone island town","Zanzibar","Goree","Mombasa"],"f":"The Island of Mozambique, a UNESCO site, has a stone town and a fort facing the mainland by a bridge."},{"q":"Which stew of cassava leaves, peanuts, and coconut is a national side dish?","a":"Matapa","o":["Matapa","Moambe chicken","Callaloo","Sukuma wiki"],"f":"The leaves are pounded and simmered, often with shrimp. Rice or a maize porridge comes alongside."},{"q":"Which vast dune and lagoon coast in the south is a famous beach wilderness?","a":"Bazaruto and Tofo","o":["Bazaruto and Tofo","The French Riviera","Copacabana","Bondi"],"f":"The Inhambane coast and the Bazaruto islands draw divers and dhows."},{"q":"Which city is the capital of Mozambique?","a":"Maputo","o":["Maputo","San Marino","Abu Dhabi","Panama City"],"f":"Maputo is the capital of Mozambique.","kind":"capital"},{"q":"Which flag belongs to Mozambique?","a":"MOZ","o":["MOZ","BOL","PRK","URY"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Mozambique.","kind":"flag"}],"medium":[{"q":"Which writer, born in Beira in 1955, wrote Sleepwalking Land in Portuguese?","a":"Mia Couto","o":["Mia Couto","José Craveirinha","Paulina Chiziane","Pepetela"],"f":"He trained as a journalist and a biologist. Craveirinha and Chiziane are major writers from this country, of other books. Pepetela is Angolan."},{"q":"Ilha de Moçambique, a UNESCO island of stone chapels and a fort, was built up by which European power?","a":"Portugal","o":["Portugal","Britain","The Netherlands","Oman"],"f":"The chapel of Nossa Senhora de Baluarte, begun in the 1520s, is among the oldest European buildings in the southern hemisphere. The administration later moved south toward today's Maputo. Oman was the power in Zanzibar."},{"q":"A fiery chili sauce and chicken, spread through Portuguese kitchens from this coast, is called what?","a":"Piri-piri","o":["Piri-piri","Berbere","Harissa","Jerk"],"f":"The chili came from the Americas on Portuguese ships. This coast made it a signature sauce. Berbere is Ethiopian, harissa is Tunisian, and jerk is Jamaican."},{"q":"What is the capital city of Mozambique?","a":"Maputo","o":["Maputo","Niamey","Algiers","Lilongwe"],"f":"Maputo is the capital of Mozambique.","kind":"capital"},{"q":"Which of these flags belongs to Mozambique?","a":"MOZ","o":["MOZ","NGA","SEN","GIN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Mozambique.","kind":"flag"}],"hard":[{"q":"The Makonde people of the north carve which dark wood into helmet masks and family trees?","a":"Ebony or African blackwood","o":["Ebony or African blackwood","Pine","Balsa","Bamboo"],"f":"Mapiko helmet masks are danced at initiations. Modern family-tree sculptures became a studio art."},{"q":"Which 15th-century stone trading town on the coast dealt in gold and cloth before the Portuguese?","a":"Sofala","o":["Sofala","Elmina","Calicut","Malacca"],"f":"Sofala linked Zimbabwe's goldfields to the Indian Ocean. The site later silted and declined."},{"q":"Which dance music of the south mixes local guitars with urban rhythms?","a":"Marrabenta","o":["Marrabenta","Kizomba","Highlife","Soukous"],"f":"The style grew in the southern port suburbs in the mid-20th century."},{"q":"Which of these cities is the capital of Mozambique?","a":"Maputo","o":["Maputo","Beira","Nampula","Matola"],"f":"Maputo is the capital of Mozambique.","kind":"capital"},{"q":"Which flag is the flag of Mozambique?","a":"MOZ","o":["MOZ","CAN","MLI","MHL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Mozambique.","kind":"flag"}]}},{"id":"MRT","name":"Mauritania","cont":"Africa","emoji":"🇲🇷","latlng":[20,-12],"q":{"easy":[{"q":"Which iron-ore train, one of the longest freight trains, runs from the desert mines to the Atlantic?","a":"The Zouerat to Nouadhibou train","o":["The Zouerat to Nouadhibou train","The Orient Express","The Shinkansen","The Trans-Siberian"],"f":"The ore train can stretch for kilometers. Travelers sometimes ride in the open wagons."},{"q":"Which millet couscous with dried meat is a desert staple?","a":"Couscous with goat","o":["Couscous with goat","Sushi","Poutine","Arepa"],"f":"Meals center on millet or rice, camel or goat, and sweet mint tea poured from a height."},{"q":"Which holy city of seven libraries holds thousands of old Islamic manuscripts?","a":"Chinguetti","o":["Chinguetti","Timbuktu","Fez","Kairouan"],"f":"Chinguetti was a stop on the pilgrimage road. Families still keep medieval books in wooden chests."},{"q":"Which city is the capital of Mauritania?","a":"Nouakchott","o":["Nouakchott","Bangkok","St. George's","Paris"],"f":"Nouakchott is the capital of Mauritania.","kind":"capital"},{"q":"Which flag belongs to Mauritania?","a":"MRT","o":["MRT","HND","PRY","TJK"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Mauritania.","kind":"flag"}],"medium":[{"q":"Chinguetti, Ouadane, Tichitt, and Oualata are UNESCO caravan towns still known for libraries of what?","a":"Medieval manuscripts","o":["Medieval manuscripts","Roman mosaics","Printed Bibles from Mainz","Cuneiform tablets"],"f":"Families kept Qurans and books of law in desert houses. Sand is covering streets in Chinguetti. These were stops on the routes, not Roman colonies."},{"q":"The Richat Structure, rings in the desert nicknamed the Eye of the Sahara, is what?","a":"An eroded dome of rock","o":["An eroded dome of rock","A meteor crater","A volcanic caldera","A dried coral atoll"],"f":"Layers wear away at different speeds and leave circles about 40 kilometers across. The impact-crater idea was popular and is wrong. It is geology, not a bullseye someone built."},{"q":"Independence from France came in which year?","a":"1960","o":["1960","1945","1975","1991"],"f":"Moktar Ould Daddah became the first president. The state kept ties to both the Arab world and West Africa. 1975 was the year of the Portuguese colonies, not this one."},{"q":"What is the capital city of Mauritania?","a":"Nouakchott","o":["Nouakchott","N'Djamena","Bamako","Khartoum"],"f":"Nouakchott is the capital of Mauritania.","kind":"capital"},{"q":"Which of these flags belongs to Mauritania?","a":"MRT","o":["MRT","GMB","RWA","LSO"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Mauritania.","kind":"flag"}],"hard":[{"q":"The Moorish society divides traditionally between warrior and scholarly lineages and which craft groups?","a":"Artisan castes","o":["Artisan castes","Samurai","Knights Templar","Janissaries"],"f":"Smiths, griots, and other specialists had inherited roles. Modern law rejects discrimination, but the history remains sensitive."},{"q":"Which cold Atlantic current keeps the coast dry and foggy?","a":"The Canary Current","o":["The Canary Current","The Gulf Stream","The Kuroshio","The Agulhas"],"f":"The Canary Current cools the air. Rain is scarce, and the Sahara reaches the beach."},{"q":"Imraguen fishers of the Banc d'Arguin have a tradition of cooperating with which wild animal to find fish?","a":"Dolphins","o":["Dolphins","Eagles","Camels","Penguins"],"f":"Dolphins herd mullet toward the nets. The national park protects this coast and huge bird flocks."},{"q":"Which of these cities is the capital of Mauritania?","a":"Nouakchott","o":["Nouakchott","Nouadhibou","Rosso","Kaédi"],"f":"Nouakchott is the capital of Mauritania.","kind":"capital"},{"q":"Which flag is the flag of Mauritania?","a":"MRT","o":["MRT","IND","SVK","BEN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Mauritania.","kind":"flag"}]}},{"id":"MUS","name":"Mauritius","cont":"Africa","emoji":"🇲🇺","latlng":[-20.28333333,57.55],"q":{"easy":[{"q":"Which extinct flightless bird, gone by the late 1600s, is the island's most famous animal?","a":"The dodo","o":["The dodo","The moa","The great auk","The passenger pigeon"],"f":"Dutch sailors found dodos on Mauritius. Within decades hunting and introduced animals wiped them out."},{"q":"Which Indian-ocean stew of spices, often with meat, reflects the island's mixed kitchens?","a":"A curry","o":["A curry","Sushi","Poutine","Fondue"],"f":"Mauritian curries, dholl puri, and Chinese noodles share the table. Sugar plantations brought many of the ancestors."},{"q":"Which colored-earth dunes in the southwest are a famous small landscape?","a":"The Seven Coloured Earths","o":["The Seven Coloured Earths","The Painted Desert","Zhangye","The Vinicunca rainbow"],"f":"Chamarel's volcanic soils form stripes of red, brown, and purple. A waterfall drops nearby."},{"q":"Which city is the capital of Mauritius?","a":"Port Louis","o":["Port Louis","Kabul","Panama City","Baghdad"],"f":"Port Louis is the capital of Mauritius.","kind":"capital"},{"q":"Which flag belongs to Mauritius?","a":"MUS","o":["MUS","SGP","CHE","BTN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Mauritius.","kind":"flag"}],"medium":[{"q":"The dodo lived only here and was extinct by the end of which century?","a":"The 17th century","o":["The 17th century","The 12th century","The 19th century","The 20th century"],"f":"Dutch sailors described it in the 1590s. A 1662 report is the last sighting most historians accept. The bird had no fear of people because no one had lived on the island."},{"q":"Le Morne, a UNESCO mountain, is honored as a refuge of whom?","a":"Maroons who had escaped slavery","o":["Maroons who had escaped slavery","Dutch governors","Exiled Napoleonic officers","Shipwrecked Vikings"],"f":"Communities hid on the rock. A story says some leaped from the cliffs when a party bringing news of freedom was mistaken for a raid. The site remembers resistance."},{"q":"Sega, the Creole dance, is typically sung in which language of the islands?","a":"Mauritian Creole","o":["Mauritian Creole","Dutch","Classical Arabic","Mandarin"],"f":"Enslaved Africans shaped the drums and the dance, and Indian and European influences joined later. The sega tambour of Rodrigues, specifically, is the form UNESCO listed. Hindi is widely spoken, but the lyrics are usually Creole."},{"q":"What is the capital city of Mauritius?","a":"Port Louis","o":["Port Louis","Antananarivo","Gitega","Niamey"],"f":"Port Louis is the capital of Mauritius.","kind":"capital"},{"q":"Which of these flags belongs to Mauritius?","a":"MUS","o":["MUS","ETH","GNQ","SDN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Mauritius.","kind":"flag"}],"hard":[{"q":"Enslaved people who escaped into the hills were called maroons. Their leader among the best known is who?","a":"A community rather than one king","o":["A community rather than one king","Shaka","Mansa Musa","Sunjata"],"f":"Le Morne mountain sheltered maroons. UNESCO lists the cultural landscape of that refuge."},{"q":"Sega music, with swaying hips and a goatskin drum, grew on the plantations. The drum is called what?","a":"The ravanne","o":["The ravanne","The taiko","The bodhran","The djembe"],"f":"The ravanne is a wide frame drum heated over a fire before it is played."},{"q":"Which crop, planted by the French and later the British, shaped the whole economy?","a":"Sugar cane","o":["Sugar cane","Rubber","Cocoa","Tea only"],"f":"Sugar estates covered the lowlands. Indentured workers from India arrived after slavery ended in 1835."},{"q":"Which of these cities is the capital of Mauritius?","a":"Port Louis","o":["Port Louis","Curepipe","Quatre Bornes","Mahébourg"],"f":"Port Louis is the capital of Mauritius.","kind":"capital"},{"q":"Which flag is the flag of Mauritius?","a":"MUS","o":["MUS","GEO","LAO","SEN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Mauritius.","kind":"flag"}]}},{"id":"MWI","name":"Malawi","cont":"Africa","emoji":"🇲🇼","latlng":[-13.5,34],"q":{"easy":[{"q":"Lake Malawi holds hundreds of species of which colorful fish?","a":"Cichlids","o":["Cichlids","Salmon","Cod","Tuna"],"f":"The lake is famous for endemic cichlids. Many aquarium fish were bred from these species."},{"q":"Which maize porridge is eaten at almost every meal?","a":"Nsima","o":["Nsima","Sushi","Risotto","Fondue"],"f":"Nsima is thick maize dough. Relishes of fish, beans, or greens are spooned beside it."},{"q":"Which Scottish explorer reached the lake in 1859 and called it Lake Nyasa?","a":"David Livingstone","o":["David Livingstone","James Cook","Marco Polo","Ibn Battuta"],"f":"Livingstone traveled from the Zambezi. Nyasa means lake in local speech, so the old name doubled the word."},{"q":"Which city is the capital of Malawi?","a":"Lilongwe","o":["Lilongwe","Luxembourg City","Managua","Reykjavík"],"f":"Lilongwe is the capital of Malawi.","kind":"capital"},{"q":"Which flag belongs to Malawi?","a":"MWI","o":["MWI","SGP","DEU","BRN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Malawi.","kind":"flag"}],"medium":[{"q":"A teenager at Masitala built a windmill from scrap and a textbook, later told in The Boy Who Harnessed the Wind. Who was he?","a":"William Kamkwamba","o":["William Kamkwamba","Richard Turere","Kelvin Doe","Lewis Latimer"],"f":"The windmill powered lights and a pump. Turere invented lion lights in Kenya, and Doe built a generator from scrap in Sierra Leone. Latimer was a 19th-century American inventor."},{"q":"David Livingstone called Lake Malawi, with its fishing lights, by what name?","a":"The Lake of Stars","o":["The Lake of Stars","The smoke that thunders","The Mountains of the Moon","Victoria Nyanza"],"f":"Lamps on the boats looked like a sky on the water. The lake also holds hundreds of cichlid species found nowhere else, a famous case for how fast new species can form. The smoke that thunders is Victoria Falls."},{"q":"The colony of Nyasaland became independent, under a new name, in which year?","a":"1964","o":["1964","1957","1963","1994"],"f":"Hastings Kamuzu Banda became the first president and ruled for decades. 1963 was Kenya. Zambia also became independent in 1964. Nyasa is a word for a lake."},{"q":"What is the capital city of Malawi?","a":"Lilongwe","o":["Lilongwe","Tripoli","N'Djamena","Porto-Novo"],"f":"Lilongwe is the capital of Malawi.","kind":"capital"},{"q":"Which of these flags belongs to Malawi?","a":"MWI","o":["MWI","GMB","GAB","ZAF"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Malawi.","kind":"flag"}],"hard":[{"q":"The Chewa people dance which masked society at funerals and initiations?","a":"The Gule Wamkulu","o":["The Gule Wamkulu","The haka","Kabuki","Ballet"],"f":"Gule Wamkulu, the great dance, brings out masked spirits of the nyau society. UNESCO lists it."},{"q":"Which high granite massif in the southeast is known for a rare cedar?","a":"Mount Mulanje","o":["Mount Mulanje","Kilimanjaro","Table Mountain","Mount Kenya"],"f":"The Mulanje cedar grows on the mountain's plateaus. Deforestation has made it scarce."},{"q":"The Maravi kingdom of the 1500s and 1600s gave a form of its name to the modern country. Its heartland was which shore?","a":"The southwest lakeshore","o":["The southwest lakeshore","The Cape of Good Hope","The Gulf of Guinea","The Red Sea"],"f":"Maravi chiefs controlled ivory and later clashed with Portuguese traders from the Zambezi."},{"q":"Which of these cities is the capital of Malawi?","a":"Lilongwe","o":["Lilongwe","Blantyre","Mzuzu","Zomba"],"f":"Lilongwe is the capital of Malawi.","kind":"capital"},{"q":"Which flag is the flag of Malawi?","a":"MWI","o":["MWI","ECU","JAM","ZMB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Malawi.","kind":"flag"}]}},{"id":"MYS","name":"Malaysia","cont":"Asia","emoji":"🇲🇾","latlng":[2.5,112.5],"q":{"easy":[{"q":"Which coconut rice with sambal, anchovies, and egg is the national breakfast?","a":"Nasi lemak","o":["Nasi lemak","Nasi goreng","Laksa","Hainanese chicken rice"],"f":"Nasi lemak is rice cooked in coconut milk, served with chili sambal and peanuts."},{"q":"Which great apes live in the rainforests of Borneo, including the Malaysian states there?","a":"Orangutans","o":["Orangutans","Gorillas","Chimpanzees","Gibbons only"],"f":"Orangutans swing through the canopy of Sabah and Sarawak. Rehabilitation centers care for orphans."},{"q":"Which hill stations of the peninsula are famous for tea estates?","a":"The Cameron Highlands","o":["The Cameron Highlands","Darjeeling","Nuwara Eliya","Munnar"],"f":"British planters opened tea and vegetable farms in the cool hills. Tea is still picked by hand."},{"q":"Which city is the official capital of Malaysia?","a":"Kuala Lumpur","o":["Kuala Lumpur","Tripoli","Kampala","Lomé"],"f":"Kuala Lumpur is the official capital. Putrajaya is the administrative center.","kind":"capital"},{"q":"Which flag belongs to Malaysia?","a":"MYS","o":["MYS","CMR","SOM","SYC"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Malaysia.","kind":"flag"}],"medium":[{"q":"Which actress, born in Ipoh in 1962, won the Academy Award for best actress for Everything Everywhere All at Once?","a":"Michelle Yeoh","o":["Michelle Yeoh","Gong Li","Maggie Cheung","Zhang Ziyi"],"f":"She trained as a ballet dancer and first became famous in Hong Kong action films. Gong Li was born in Shenyang, Zhang Ziyi in Beijing, and Maggie Cheung in Hong Kong."},{"q":"The Petronas Towers were the world's tallest buildings from 1998 until 2004. Which building took that title from them?","a":"Taipei 101","o":["Taipei 101","The Burj Khalifa","The Empire State Building","The Shanghai Tower"],"f":"The towers stand 451.9 meters to their tips and are linked by a skybridge. The Burj Khalifa, in Dubai, took the record only in 2010. The Shanghai Tower came later still."},{"q":"Malaya became independent from Britain in which year?","a":"1957","o":["1957","1945","1963","1965"],"f":"The wider federation called Malaysia, adding Sabah and Sarawak, was formed in 1963. Singapore left that federation in 1965. 1945 was the end of the Japanese occupation, not independence."},{"q":"What is the official capital city of Malaysia?","a":"Kuala Lumpur","o":["Kuala Lumpur","Tehran","Sri Jayawardenepura Kotte","Beirut"],"f":"Kuala Lumpur is the official capital. Putrajaya is the administrative center.","kind":"capital"},{"q":"Which of these flags belongs to Malaysia?","a":"MYS","o":["MYS","ARM","PRK","VNM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Malaysia.","kind":"flag"}],"hard":[{"q":"The Strait of Malacca, between the peninsula and Sumatra, has long been a route for what?","a":"Spice and oil shipping","o":["Spice and oil shipping","Only local fishing","Overland silk","Arctic convoys"],"f":"The strait is one of the busiest sea lanes. Melaka was a sultanate that taxed that trade."},{"q":"Which wax-and-dye cloth is a shared craft of Malaysia and Indonesia?","a":"Batik","o":["Batik","Songket","Ikat only","Kente"],"f":"Malaysian batik often uses floral motifs and brighter stamps. It is worn as formal shirts."},{"q":"The orang asli and the Dayak peoples include longhouse communities on which island?","a":"Borneo","o":["Borneo","Sumatra","The peninsula only","Java"],"f":"Dayak longhouses in Sarawak house many families under one roof, each with a door onto a common veranda."},{"q":"Which of these cities is the official capital of Malaysia?","a":"Kuala Lumpur","o":["Kuala Lumpur","Putrajaya","George Town","Johor Bahru"],"f":"Kuala Lumpur is the official capital. Putrajaya is the administrative center.","kind":"capital"},{"q":"Which flag is the flag of Malaysia?","a":"MYS","o":["MYS","USA","LBR","SVN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Malaysia.","kind":"flag"}]}},{"id":"NAM","name":"Namibia","cont":"Africa","emoji":"🇳🇦","latlng":[-22,17],"q":{"easy":[{"q":"Which huge red dunes face the Atlantic at Sossusvlei?","a":"The Namib dunes","o":["The Namib dunes","The Sahara","The Gobi","The Atacama"],"f":"Some dunes at Sossusvlei are among the tallest in the world. A white clay pan sits among them."},{"q":"Which grilled meat, from game or beef, is the center of a social meal?","a":"Braai","o":["Braai","Sushi","Fondue","Poutine"],"f":"A braai is a barbecue. It is as much a gathering as a way of cooking."},{"q":"Which coastal skeleton of shipwrecks gave a stretch of shore its grim nickname?","a":"The Skeleton Coast","o":["The Skeleton Coast","The Gold Coast","The Ivory Coast","The Cape of Good Hope"],"f":"Fog, currents, and rocks wrecked ships. Whale bones and rusted hulls remain on the sand."},{"q":"Which city is the capital of Namibia?","a":"Windhoek","o":["Windhoek","Damascus","Vaduz","Bucharest"],"f":"Windhoek is the capital of Namibia.","kind":"capital"},{"q":"Which flag belongs to Namibia?","a":"NAM","o":["NAM","TUV","GEO","KWT"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Namibia.","kind":"flag"}],"medium":[{"q":"Deadvlei, a white clay pan among the Namib dunes, is famous for what standing on the floor?","a":"Dead camel thorn trees","o":["Dead camel thorn trees","Petrified Roman columns","Living mangroves","Nesting penguins"],"f":"The trees died centuries ago when dunes cut off the water, and the dry air kept the wood. Sossusvlei's red dunes rise next door. The pan is not a ruined city."},{"q":"German forces drove the Herero and the Nama into the desert and camps in 1904-1908. Germany officially called those crimes a genocide in which year?","a":"2021","o":["2021","1918","1948","1990"],"f":"Tens of thousands died. Von Trotha's 1904 order against the Herero is a central document. Independence from South Africa came in 1990. The official recognition was not made in 1918 or 1948."},{"q":"Himba women mix butterfat and red ochre to cover skin and hair. What is that mixture called?","a":"Otjize","o":["Otjize","Thanaka","Kohl","Henna"],"f":"It protects skin in a hot dry climate and is a mark of beauty. Thanaka is the yellow bark paste of Myanmar. The Himba live mainly in the northwest."},{"q":"What is the capital city of Namibia?","a":"Windhoek","o":["Windhoek","Rabat","Abuja","Pretoria"],"f":"Windhoek is the capital of Namibia.","kind":"capital"},{"q":"Which of these flags belongs to Namibia?","a":"NAM","o":["NAM","COD","TUN","GIN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Namibia.","kind":"flag"}],"hard":[{"q":"Which strange plant of the Namib lives for centuries on only two leaves?","a":"Welwitschia","o":["Welwitschia","The baobab","The quiver tree","The dragon's blood tree"],"f":"The two leaves split into long straps. Fog helps the plant survive in the desert, and some are thought to be over a thousand years old."},{"q":"Which German colonial war of 1904 to 1908 against the Herero and Nama is studied as an early genocide?","a":"The Herero and Nama war","o":["The Herero and Nama war","The Boer War","The Zulu War","The Ashanti War"],"f":"German forces drove people into the desert and ran camps. Namibia and Germany have negotiated recognition and aid."},{"q":"Twyfelfontein, a UNESCO site, is a hillside of what?","a":"Ancient rock engravings","o":["Ancient rock engravings","A Roman theater","A Buddhist stupa","A Viking ship"],"f":"Hunters engraved animals and footprints on the sandstone thousands of years ago."},{"q":"Which of these cities is the capital of Namibia?","a":"Windhoek","o":["Windhoek","Walvis Bay","Swakopmund","Rundu"],"f":"Windhoek is the capital of Namibia.","kind":"capital"},{"q":"Which flag is the flag of Namibia?","a":"NAM","o":["NAM","YEM","HRV","GTM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Namibia.","kind":"flag"}]}},{"id":"NER","name":"Niger","cont":"Africa","emoji":"🇳🇪","latlng":[16,8],"q":{"easy":[{"q":"Which huge mud mosque in Agadez, with a tall spiked tower, is a symbol of the Sahara?","a":"The Agadez Mosque","o":["The Agadez Mosque","The Great Mosque of Djenne","The Hassan II Mosque","The Blue Mosque"],"f":"The minaret of Agadez is built of mud brick and wooden stakes. It has been rebuilt many times since the 1500s."},{"q":"Which millet porridge with sauce is the daily meal?","a":"Fura or pate","o":["Fura or pate","Sushi","Paella","Poutine"],"f":"Millet is pounded and cooked into a stiff paste. Sauces of leaves, baobab, or meat go with it."},{"q":"Which UNESCO historic center of a trans-Saharan town is known for its cross-shaped silver jewelry?","a":"Agadez","o":["Agadez","Timbuktu","Ghadames","Chinguetti"],"f":"The Agadez Cross is a Tuareg pendant. Styles vary by region and were once a form of wealth."},{"q":"Which city is the capital of Niger?","a":"Niamey","o":["Niamey","Minsk","San José","Luxembourg City"],"f":"Niamey is the capital of Niger.","kind":"capital"},{"q":"Which flag belongs to Niger?","a":"NER","o":["NER","GRC","ISR","AZE"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Niger.","kind":"flag"}],"medium":[{"q":"The historic mosque of Agadez, in a UNESCO old town, is known above all for what?","a":"A tall mud-brick minaret","o":["A tall mud-brick minaret","A glass spire","A marble Ottoman dome","A steel radio mast"],"f":"Timbers stud the tower so it can be replastered, as on other Sahelian mosques. Agadez was a crossroads of Saharan caravans. The tower's present form is often linked to the 16th century, with many later repairs."},{"q":"At the Gerewol, Wodaabe men dance for days in makeup and ornaments. Young women are mainly judging what?","a":"Their beauty","o":["Their beauty","A camel race","A recitation contest","A millet harvest"],"f":"The dance prizes teeth and the whites of the eyes. It happens in the rainy season, when the herds are together. It is not a race."},{"q":"Fossils of Jobaria and Suchomimus were dug at Gadoufaoua, in the Ténéré. Those rocks record a Sahara that was once what?","a":"A wetter land of rivers","o":["A wetter land of rivers","A single ice sheet","Open ocean over a trench","A coral reef at the pole"],"f":"Teams led by Paul Sereno excavated there in the 1990s. Suchomimus had a crocodile-like snout for fish. The dunes on top are young compared with the bones."},{"q":"What is the capital city of Niger?","a":"Niamey","o":["Niamey","Monrovia","Asmara","Port Louis"],"f":"Niamey is the capital of Niger.","kind":"capital"},{"q":"Which of these flags belongs to Niger?","a":"NER","o":["NER","RWA","CMR","MRT"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Niger.","kind":"flag"}],"hard":[{"q":"The Tuareg of the Air Mountains hold an annual gathering of nomads called what?","a":"The Cure Salee","o":["The Cure Salee","The Hajj","Carnival","Oktoberfest"],"f":"The Cure Salee, at Ingall, is a festival of salt cure for livestock, courtship, and politics."},{"q":"Which medieval empire along the Niger, with a capital at Gao, ruled this region in the 1400s?","a":"Songhai","o":["Songhai","The Inca","Rome","Mali only in the 800s"],"f":"Songhai controlled the bend of the Niger and the Saharan trade until a Moroccan army defeated it in 1591."},{"q":"Hausa city life in the south shares language and trade with which large neighbor?","a":"The large neighbor to the south","o":["The large neighbor to the south","Morocco","Egypt","South Africa"],"f":"Hausa is spoken on both sides of that border. Markets in Maradi and Zinder face Kano."},{"q":"Which of these cities is the capital of Niger?","a":"Niamey","o":["Niamey","Zinder","Maradi","Agadez"],"f":"Niamey is the capital of Niger.","kind":"capital"},{"q":"Which flag is the flag of Niger?","a":"NER","o":["NER","PLW","ARG","MKD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Niger.","kind":"flag"}]}},{"id":"NGA","name":"Nigeria","cont":"Africa","emoji":"🇳🇬","latlng":[10,8],"q":{"easy":[{"q":"Which huge rock stands near Abuja and appears in many photographs of the country?","a":"Zuma Rock","o":["Zuma Rock","Uluru","Table Mountain","El Capitan"],"f":"Zuma Rock is a monolith on the road between Abuja and Kaduna. It has been printed on currency."},{"q":"Which one-pot tomato rice, shared with neighbors and fiercely debated, is a party dish?","a":"Jollof rice","o":["Jollof rice","Sushi","Paella","Risotto"],"f":"Jollof is rice cooked in a pepper and tomato sauce. Nigeria and Ghana both claim the best version."},{"q":"Which film industry, based largely in Lagos, became one of the most productive in the world?","a":"Nollywood","o":["Nollywood","Hollywood","Bollywood","Anime"],"f":"Nollywood grew from video films in the 1990s. Stories are often shot fast and sold on disc and online."},{"q":"Which city is the capital of Nigeria?","a":"Abuja","o":["Abuja","Ngerulmud","Bogotá","San Marino"],"f":"Abuja is the capital of Nigeria.","kind":"capital"},{"q":"Which flag belongs to Nigeria?","a":"NGA","o":["NGA","BRN","HND","VEN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Nigeria.","kind":"flag"}],"medium":[{"q":"Which playwright, born in Abeokuta in 1934, won the Nobel Prize in Literature in 1986?","a":"Wole Soyinka","o":["Wole Soyinka","Chinua Achebe","Ngũgĩ wa Thiong'o","Nadine Gordimer"],"f":"He was imprisoned during the civil war of 1967-1970. Achebe, also from this country, did not receive the Nobel. Ngũgĩ is Kenyan, and Gordimer was South African."},{"q":"Which novelist, born in Ogidi in 1930, wrote Things Fall Apart?","a":"Chinua Achebe","o":["Chinua Achebe","Wole Soyinka","Ben Okri","Buchi Emecheta"],"f":"The 1958 novel follows Okonkwo as British rule arrives. Okri and Emecheta are major novelists connected to this country, but not the author of that book."},{"q":"Fela Kuti, born in Abeokuta in 1938, named a style Afrobeat. His shows were built around what?","a":"Long songs, a big band, and political words","o":["Long songs, a big band, and political words","Solo piano recitals","Gregorian chant","Italian opera"],"f":"He led Africa 70 and later Egypt 80 from the Kalakuta compound in Lagos. Afrobeats, with an s, is a later pop label. It is not the style he named in the 1970s."},{"q":"What is the capital city of Nigeria?","a":"Abuja","o":["Abuja","Maputo","Moroni","Lilongwe"],"f":"Abuja is the capital of Nigeria.","kind":"capital"},{"q":"Which of these flags belongs to Nigeria?","a":"NGA","o":["NGA","SEN","BDI","SDN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Nigeria.","kind":"flag"}],"hard":[{"q":"The Benin Kingdom, in today's Edo State, cast famous plaques and heads in which metal?","a":"Brass and bronze","o":["Brass and bronze","Platinum","Aluminum","Tin only"],"f":"The Benin Bronzes decorated the palace in Benin City. A British force looted many of them in 1897."},{"q":"Which Yoruba talking drum imitates the tones of speech?","a":"The dundun","o":["The dundun","The bodhran","The taiko","The timpani"],"f":"The dundun is squeezed under the arm so the pitch slides. Master drummers can suggest words."},{"q":"The Kano dye pits, still in use, color cloth with which deep blue?","a":"Indigo","o":["Indigo","Saffron","Cochineal","Woad only in Europe"],"f":"Kofar Mata pits in Kano have produced indigo cloth for centuries. The city was a Sahel trading capital."},{"q":"Which of these cities is the capital of Nigeria?","a":"Abuja","o":["Abuja","Lagos","Kano","Ibadan"],"f":"Abuja is the capital of Nigeria.","kind":"capital"},{"q":"Which flag is the flag of Nigeria?","a":"NGA","o":["NGA","DEU","CAF","LBN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Nigeria.","kind":"flag"}]}},{"id":"NIC","name":"Nicaragua","cont":"North America","emoji":"🇳🇮","latlng":[13,-85],"q":{"easy":[{"q":"Which colonial city at the foot of a volcano has a famous yellow cathedral?","a":"Leon","o":["Leon","Granada","Managua","Masaya"],"f":"Leon's cathedral is a UNESCO site. Ruben Dario is buried there."},{"q":"Which corn cake with cheese, the nacatamal, is a Sunday breakfast?","a":"A nacatamal","o":["A nacatamal","A pupusa","An arepa","A tamale of only Mexico"],"f":"Nacatamales are corn dough stuffed with meat and wrapped in plantain leaves, then steamed."},{"q":"Which lake with freshwater sharks, or a story of them, is the great inland sea?","a":"The great freshwater lake","o":["The great freshwater lake","Lake Managua","The Gulf of Fonseca","Pearl Lagoon"],"f":"Bull sharks were long known to enter the lake from the Caribbean by the San Juan River. Sightings are now rare."},{"q":"Which city is the capital of Nicaragua?","a":"Managua","o":["Managua","Sarajevo","Bangkok","Phnom Penh"],"f":"Managua is the capital of Nicaragua.","kind":"capital"},{"q":"Which flag belongs to Nicaragua?","a":"NIC","o":["NIC","MKD","MDA","ARE"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Nicaragua.","kind":"flag"}],"medium":[{"q":"Which poet, born in Metapa in 1867, launched the Spanish-language modernismo movement with the book Azul?","a":"Ruben Dario","o":["Ruben Dario","Pablo Neruda","Octavio Paz","Jorge Luis Borges"],"f":"Azul appeared in 1888 and reshaped Spanish poetry on both sides of the Atlantic. His birthplace was later renamed Ciudad Dario."},{"q":"Ometepe, an island of the volcanoes Concepcion and Maderas, takes its Nahuatl name from which meaning?","a":"Two mountains","o":["Two mountains","Sacred water","Place of reeds","Fire island"],"f":"The island sits in the great lake of the country, and petroglyphs are scattered across the slopes. Bull sharks have reached that lake from the Caribbean, but that is a separate story."},{"q":"In 1856 an American adventurer seized Nicaragua, made himself president, and re-legalized slavery. Who was he?","a":"William Walker","o":["William Walker","Sam Houston","Davy Crockett","John C. Fremont"],"f":"Armies from across Central America drove him out. He was executed in Honduras in 1860, and Nicaragua remembers the fight as the National War."},{"q":"What is the capital city of Nicaragua?","a":"Managua","o":["Managua","Belmopan","Ottawa","Roseau"],"f":"Managua is the capital of Nicaragua.","kind":"capital"},{"q":"Which of these flags belongs to Nicaragua?","a":"NIC","o":["NIC","USA","KNA","GRD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Nicaragua.","kind":"flag"}],"hard":[{"q":"Which priest and poet, born in Granada in 1925, wrote the long poem Cosmic Canticle?","a":"Ernesto Cardenal","o":["Ernesto Cardenal","Ruben Dario","Gioconda Belli","Claribel Alegria"],"f":"Cardenal founded an arts community at Solentiname and later served as minister of culture."},{"q":"Granada, founded in 1524, looks over which volcano and a scatter of isletas?","a":"Mombacho and the isletas","o":["Mombacho and the isletas","Lake Atitlan","Lake Titicaca","The Bay of Fonseca"],"f":"The city was a rival of Leon. Its colorful streets face the isletas, small islands of an old lava flow."},{"q":"Which revolutionary front won power in 1979 and gives its initials to a later party?","a":"The Sandinista front","o":["The Sandinista front","The Contras","The Somocistas","The Liberals of the 1800s"],"f":"The FSLN overthrew Anastasio Somoza. The name honors Augusto Cesar Sandino, killed in 1934."},{"q":"Which of these cities is the capital of Nicaragua?","a":"Managua","o":["Managua","León","Granada","Matagalpa"],"f":"Managua is the capital of Nicaragua.","kind":"capital"},{"q":"Which flag is the flag of Nicaragua?","a":"NIC","o":["NIC","SLV","HND","GTM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Nicaragua.","kind":"flag"}]}},{"id":"NLD","name":"Netherlands","cont":"Europe","emoji":"🇳🇱","latlng":[52.5,5.75],"q":{"easy":[{"q":"Which wind-powered machines drained lakes and ground grain for centuries?","a":"Windmills","o":["Windmills","Watermills only","Steam engines","Treadwheels"],"f":"Stone and wood mills still stand at Kinderdijk and Zaanse Schans. Many pumped polders dry."},{"q":"Which thin syrup waffle is a common souvenir and snack?","a":"A stroopwafel","o":["A stroopwafel","A Belgian waffle","A crepe","A biscuit"],"f":"A stroopwafel is two cookie layers with caramel syrup between them. It is often set over a hot cup so the filling softens."},{"q":"Which painter of The Night Watch worked in Amsterdam's golden age?","a":"Rembrandt van Rijn","o":["Rembrandt van Rijn","Vermeer","Van Gogh","Hals"],"f":"Rembrandt lived from 1606 to 1669. The Night Watch is a civic-guard portrait in the Rijksmuseum."},{"q":"Which city is the constitutional capital of the Netherlands?","a":"Amsterdam","o":["Amsterdam","Majuro","Port of Spain","Apia"],"f":"Amsterdam is the constitutional capital. The government and the king sit in The Hague.","kind":"capital"},{"q":"Which flag belongs to Netherlands?","a":"NLD","o":["NLD","CAF","ERI","AUS"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Netherlands.","kind":"flag"}],"medium":[{"q":"Which painter, born in Zundert in 1853, sold almost nothing in his lifetime and painted Sunflowers and The Starry Night?","a":"Vincent van Gogh","o":["Vincent van Gogh","Rembrandt van Rijn","Johannes Vermeer","Piet Mondrian"],"f":"The Starry Night was painted in France, but he was Dutch by birth. Rembrandt and Vermeer belong to the 17th century, two hundred years earlier."},{"q":"Antonie van Leeuwenhoek, a cloth merchant born in Delft, ground single lenses and became the first person to see what?","a":"Bacteria and other microbes","o":["Bacteria and other microbes","The moons of Jupiter","X-rays","The structure of DNA"],"f":"He called them animalcules and wrote careful letters to the Royal Society in London. He never published a book, but his microscopes were the best of the 1670s."},{"q":"A polder is farmland made by draining a lake or a piece of seabed and keeping the water out with what?","a":"Dikes and pumps","o":["Dikes and pumps","Terraces of stone","Canals that raise the land","Glass greenhouses"],"f":"Much of the country is at or below sea level. Windmills once did the pumping, and electric stations do it now."},{"q":"What is the constitutional capital city of the Netherlands?","a":"Amsterdam","o":["Amsterdam","Sarajevo","Budapest","Luxembourg City"],"f":"Amsterdam is the constitutional capital. The government and the king sit in The Hague.","kind":"capital"},{"q":"Which of these flags belongs to Netherlands?","a":"NLD","o":["NLD","UKR","MNE","MCO"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Netherlands.","kind":"flag"}],"hard":[{"q":"Which legal scholar, born in Delft in 1583, wrote the early modern case for freedom of the seas?","a":"Hugo Grotius","o":["Hugo Grotius","Erasmus","Spinoza","Descartes"],"f":"Grotius argued that the ocean could not be owned. The idea shaped later maritime law."},{"q":"Delftware, the blue-and-white pottery, imitated porcelain from which country?","a":"China","o":["China","Japan only","Persia","Turkey"],"f":"Dutch traders brought Chinese porcelain. Delft potters painted tin-glazed earthenware in a similar blue."},{"q":"The Eleven Cities skating race crosses frozen canals of which province when the ice is thick enough?","a":"Friesland","o":["Friesland","Holland","Limburg","Zeeland"],"f":"The Elfstedentocht is rare because the canals seldom freeze hard enough. Towns along the route prepare for years."},{"q":"Which of these cities is the constitutional capital of the Netherlands?","a":"Amsterdam","o":["Amsterdam","The Hague","Rotterdam","Utrecht"],"f":"Amsterdam is the constitutional capital. The government and the king sit in The Hague.","kind":"capital"},{"q":"Which flag is the flag of Netherlands?","a":"NLD","o":["NLD","FRA","RUS","LUX"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Netherlands.","kind":"flag"}]}},{"id":"NOR","name":"Norway","cont":"Europe","emoji":"🇳🇴","latlng":[62,10],"q":{"easy":[{"q":"Which deep sea inlets between steep mountains define the west coast?","a":"Fjords","o":["Fjords","Rias","Estuaries","Lagoons"],"f":"Fjords are drowned glacial valleys. Sognefjord and Geirangerfjord are among the best known."},{"q":"Which brown whey cheese is sliced onto bread?","a":"Brunost","o":["Brunost","Cheddar","Brie","Feta"],"f":"Brunost is made by boiling whey until the sugars caramelize. It tastes sweet, not like a typical cheese."},{"q":"Which two Viking ships, the Oseberg and the Gokstad, were buried and later dug up?","a":"The Oseberg and Gokstad ships","o":["The Oseberg and Gokstad ships","The Vasa","The Skuldelev ships","The Mary Rose"],"f":"The Oseberg ship, around 820, was a burial for two women. It is displayed in Oslo's ship museum."},{"q":"Which city is the capital of Norway?","a":"Oslo","o":["Oslo","Phnom Penh","Antananarivo","Tripoli"],"f":"Oslo is the capital of Norway.","kind":"capital"},{"q":"Which flag belongs to Norway?","a":"NOR","o":["NOR","PRY","USA","UZB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Norway.","kind":"flag"}],"medium":[{"q":"Which painter, born in 1863, made The Scream, a figure on a bridge under a blood-red sky?","a":"Edvard Munch","o":["Edvard Munch","Edvard Grieg","Henrik Ibsen","Gustav Vigeland"],"f":"He painted several versions. He wrote that he had felt a great scream pass through nature while walking near Oslo, then called Christiania."},{"q":"Norway's famous narrow inlets, with steep walls falling into deep water, were carved mainly by what?","a":"Glaciers","o":["Glaciers","Rivers alone","Volcanic rifts","Coral growth"],"f":"Ice Age glaciers overdeepened river valleys, and the sea flooded them when the ice melted. Sognefjord is the longest and deepest."},{"q":"Roald Amundsen, born near Fredrikstad, led the first expedition to reach which point in December 1911?","a":"The South Pole","o":["The South Pole","The North Pole by land","The summit of Everest","The source of the Nile"],"f":"He used skis and sled dogs and beat Robert Falcon Scott by about a month. Earlier he had been the first to sail the Northwest Passage."},{"q":"What is the capital city of Norway?","a":"Oslo","o":["Oslo","Bern","Bratislava","Tallinn"],"f":"Oslo is the capital of Norway.","kind":"capital"},{"q":"Which of these flags belongs to Norway?","a":"NOR","o":["NOR","ROU","ITA","DEU"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Norway.","kind":"flag"}],"hard":[{"q":"Which explorer reached the South Pole in December 1911, ahead of Scott?","a":"Roald Amundsen","o":["Roald Amundsen","Nansen","Heyerdahl","Shackleton"],"f":"Amundsen used skis and dogs. Scott's party arrived a month later and died on the return."},{"q":"The stave churches, built of wood in the Middle Ages, are famous for what construction?","a":"Post-and-beam wooden frames","o":["Post-and-beam wooden frames","Stone vaults","Mud brick","Ice blocks"],"f":"Borgund and a few dozen others survive. Dragons on the gables echo Viking carving."},{"q":"Which Nobel peace prize is awarded in Oslo, unlike the other Nobel prizes?","a":"The Peace Prize","o":["The Peace Prize","The Physics Prize","The Literature Prize","All of them"],"f":"Alfred Nobel's will gave the peace prize to a Norwegian committee. The ceremony is in Oslo City Hall."},{"q":"Which of these cities is the capital of Norway?","a":"Oslo","o":["Oslo","Bergen","Trondheim","Stavanger"],"f":"Oslo is the capital of Norway.","kind":"capital"},{"q":"Which flag is the flag of Norway?","a":"NOR","o":["NOR","SWE","DNK","ISL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Norway.","kind":"flag"}]}},{"id":"NPL","name":"Nepal","cont":"Asia","emoji":"🇳🇵","latlng":[28,84],"q":{"easy":[{"q":"Which dumplings, steamed or fried, are eaten with chili sauce on every street?","a":"Momos","o":["Momos","Buuz","Gyoza","Pierogi"],"f":"Momos are filled with buffalo, chicken, or vegetables. They came into the hills with Tibetan and Newar kitchens."},{"q":"Which lowland park is famous for one-horned rhinoceroses?","a":"Chitwan National Park","o":["Chitwan National Park","Sagarmatha","Bardia only","Kaziranga"],"f":"Chitwan protects rhinos, tigers, and elephants in the Terai. It is a UNESCO site."},{"q":"Which palace squares of Newar kings stand in Kathmandu, Patan, and Bhaktapur?","a":"The Durbar Squares","o":["The Durbar Squares","Red Fort","The Forbidden City","The Grand Palace"],"f":"The durbar squares hold temples and palace courts. The 2015 earthquake damaged many of them."},{"q":"Which city is the capital of Nepal?","a":"Kathmandu","o":["Kathmandu","Podgorica","Yaoundé","Andorra la Vella"],"f":"Kathmandu is the capital of Nepal.","kind":"capital"},{"q":"Which flag belongs to Nepal?","a":"NPL","o":["NPL","DEU","HUN","COL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Nepal.","kind":"flag"}],"medium":[{"q":"Lumbini, a garden on the southern plains, is honored as the birthplace of whom?","a":"Siddhartha Gautama, the Buddha","o":["Siddhartha Gautama, the Buddha","Mahavira","Guru Nanak","Laozi"],"f":"He was born there, traditionally in the 6th or 5th century BCE, when the place was part of the Shakya lands. Ashoka left a pillar in the 3rd century BCE. Mahavira, Nanak, and Laozi are other teachers, not of this garden."},{"q":"Sagarmatha, the world's highest peak, stands on the border with China. What is its usual English name?","a":"Mount Everest","o":["Mount Everest","K2","Kangchenjunga","Annapurna"],"f":"The Nepali name is Sagarmatha and the Tibetan name is Chomolungma. Climbers on this side start in the Khumbu. The mountain is shared with China; it is not wholly inside one country. Kangchenjunga is a different border peak."},{"q":"A war with Britain in 1814-1816 ended by treaty, and the kingdom was never made a colony of which empire?","a":"The British Empire","o":["The British Empire","The Mughal Empire","The Qing Empire","The Portuguese Empire"],"f":"The Treaty of Sugauli kept the kingdom independent. Britain later recruited Gurkha soldiers from the hills. Unequal pressure was real, but there was no colonial government here."},{"q":"What is the capital city of Nepal?","a":"Kathmandu","o":["Kathmandu","Kabul","Sri Jayawardenepura Kotte","Riyadh"],"f":"Kathmandu is the capital of Nepal.","kind":"capital"},{"q":"Which of these flags belongs to Nepal?","a":"NPL","o":["NPL","IND","LBN","PRK"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Nepal.","kind":"flag"}],"hard":[{"q":"Which millet beer of the eastern hills is sipped through a bamboo straw?","a":"Tongba","o":["Tongba","Sake","Soju","Chhang from barley only"],"f":"Hot water is poured over fermented millet in a pot. The drink is a Limbu specialty."},{"q":"The living goddess Kumari lives in a palace of which kind of square?","a":"The old palace square","o":["The old palace square","A modern mall","A Roman forum","A harbor"],"f":"A Kumari is chosen from a Newar Buddhist family and lives in a palace on the durbar square until she reaches puberty."},{"q":"Which hill kingdom conquered the valley towns in the 1760s and founded the modern state?","a":"The Gorkha kingdom","o":["The Gorkha kingdom","The Malla city-states","The Licchavi realm","The Magadha empire"],"f":"Prithvi Narayan Shah of Gorkha took the valley and united the hills. His dynasty ruled until the monarchy ended in 2008."},{"q":"Which of these cities is the capital of Nepal?","a":"Kathmandu","o":["Kathmandu","Pokhara","Lalitpur","Biratnagar"],"f":"Kathmandu is the capital of Nepal.","kind":"capital"},{"q":"Which flag is the flag of Nepal?","a":"NPL","o":["NPL","CIV","MUS","TKM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Nepal.","kind":"flag"}]}},{"id":"NRU","name":"Nauru","cont":"Oceania","emoji":"🇳🇷","latlng":[-0.53333333,166.91666666],"q":{"easy":[{"q":"Which seabird nests in the remaining trees along the coastal terrace?","a":"The black noddy","o":["The black noddy","The emperor penguin","The wandering albatross","The Atlantic puffin"],"f":"Black noddies nest in coastal trees. Mining removed much of the inland forest they might once have used."},{"q":"Which raw fish in coconut milk is a common plate?","a":"Coconut fish","o":["Coconut fish","Sashimi","Ceviche","Poke"],"f":"Reef fish is marinated with coconut and lime. It is a shared Pacific dish with local names."},{"q":"Which Australian camp, opened in the 2000s, held people seeking asylum?","a":"The offshore processing center","o":["The offshore processing center","A university","A naval college","A hospital only"],"f":"Nauru hosted an Australian regional processing center. The policy was widely debated."},{"q":"Government offices of Nauru sit in which district?","a":"Yaren","o":["Yaren","Tegucigalpa","Tokyo","Brussels"],"f":"Nauru has no official capital. Government offices sit in Yaren.","kind":"capital"},{"q":"Which flag belongs to Nauru?","a":"NRU","o":["NRU","BEL","SOM","GEO"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Nauru.","kind":"flag"}],"medium":[{"q":"Mining of which mineral, formed largely from ancient seabird droppings, stripped most of Nauru's interior?","a":"Phosphate","o":["Phosphate","Bauxite","Diamonds","Copper"],"f":"The plateau left behind is a field of sharp coral pinnacles. Phosphate briefly made the tiny republic wealthy, then the easy deposits ran out."},{"q":"Nauru is generally recognized as the world's smallest what?","a":"Island republic","o":["Island republic","Continent","Archipelago nation","Landlocked state"],"f":"Only Vatican City and Monaco are smaller countries, and neither is a republic. Nauru is a single island of about 21 square kilometers."},{"q":"In World War II, Nauru was occupied by which country's forces?","a":"Japan","o":["Japan","Germany","Italy","Spain"],"f":"Phosphate was the prize. Hundreds of Nauruans were deported to Truk for forced labor, and many did not survive."},{"q":"In which district are the government offices of Nauru?","a":"Yaren","o":["Yaren","Nuku'alofa","Palikir","Ngerulmud"],"f":"Nauru has no official capital. Government offices sit in Yaren.","kind":"capital"},{"q":"Which of these flags belongs to Nauru?","a":"NRU","o":["NRU","VUT","SLB","TON"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Nauru.","kind":"flag"}],"hard":[{"q":"The island's phosphate came from which natural source, compacted over ages?","a":"Seabird droppings","o":["Seabird droppings","Volcanic ash","River silt","Coral sand only"],"f":"Guano reacted with the limestone to form phosphate rock. Mining began under a colonial mandate."},{"q":"Which railway once carried the ore from the plateau to the coast?","a":"A narrow-gauge phosphate line","o":["A narrow-gauge phosphate line","A bullet train","A cable car","A canal"],"f":"Cantilever loaders dumped the rock into ships. The workings are now mostly silent."},{"q":"The national game of the region, played hard on the island, is which football code?","a":"Australian rules football","o":["Australian rules football","Soccer only","Rugby league only","Cricket"],"f":"Australian rules took root through the phosphate years and the Australian connection. Local leagues are fierce."},{"q":"Which of these districts holds the government offices of Nauru?","a":"Yaren","o":["Yaren","Denigomodu","Aiwo","Meneng"],"f":"Nauru has no official capital. Government offices sit in Yaren.","kind":"capital"},{"q":"Which flag is the flag of Nauru?","a":"NRU","o":["NRU","MNG","GNQ","SVN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Nauru.","kind":"flag"}]}},{"id":"NZL","name":"New Zealand","cont":"Oceania","emoji":"🇳🇿","latlng":[-41,174],"q":{"easy":[{"q":"Which flightless bird with hair-like feathers is a national symbol?","a":"The kiwi","o":["The kiwi","The kakapo","The moa","The weka"],"f":"The kiwi hunts insects at night. Its nostril is at the tip of a long beak."},{"q":"Which Maori challenge, with a protruding tongue and a weapon, opens ceremonies?","a":"The haka","o":["The haka","The poi","The waiata","The moko"],"f":"The All Blacks perform a haka before matches. Many haka are older ceremonial dances."},{"q":"Which fjorded southwest coast of mountains and rain is a UNESCO wilderness?","a":"Fiordland","o":["Fiordland","The Bay of Islands","The Coromandel","Taranaki"],"f":"Milford Sound and Doubtful Sound cut into the mountains. Rainforest grows to the water."},{"q":"Which city is the capital of New Zealand?","a":"Wellington","o":["Wellington","Castries","Moroni","Tripoli"],"f":"Wellington is the capital of New Zealand.","kind":"capital"},{"q":"Which flag belongs to New Zealand?","a":"NZL","o":["NZL","COD","CMR","KGZ"],"f":"Compare the colors and symbols. One of these four flags is the national flag of New Zealand.","kind":"flag"}],"medium":[{"q":"Which physicist, born in Brightwater, is called a father of nuclear physics for revealing the atomic nucleus?","a":"Ernest Rutherford","o":["Ernest Rutherford","Niels Bohr","Marie Curie","Enrico Fermi"],"f":"He won the 1908 Nobel Prize in chemistry and later led Cambridge's Cavendish Laboratory. Element 104, rutherfordium, honors him."},{"q":"In 1840 many Maori chiefs and the British Crown signed which agreement?","a":"The Treaty of Waitangi","o":["The Treaty of Waitangi","The Antarctic Treaty","The Treaty of Versailles","The Schengen Agreement"],"f":"The English and Maori texts do not match perfectly on sovereignty. That gap is still central to New Zealand law and politics."},{"q":"A hangi cooks food with steam in an earth oven. Which people developed this method in New Zealand?","a":"The Maori","o":["The Maori","The Anangu","The Inuit","The Sami"],"f":"Hot stones and leaves keep soil off the food. A hangi is still the center of many gatherings and welcomes."},{"q":"What is the capital city of New Zealand?","a":"Wellington","o":["Wellington","Yaren","Suva","Nuku'alofa"],"f":"Wellington is the capital of New Zealand.","kind":"capital"},{"q":"Which of these flags belongs to New Zealand?","a":"NZL","o":["NZL","PLW","KIR","SLB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of New Zealand.","kind":"flag"}],"hard":[{"q":"The Treaty of Waitangi in 1840 was signed by the British crown and which leaders?","a":"Maori chiefs","o":["Maori chiefs","Australian governors","The king of Tonga","French settlers"],"f":"The treaty's English and Maori texts do not match perfectly. It remains the founding document and a source of claims."},{"q":"Which geothermal valley of geysers and mud pools is a classic North Island sight?","a":"Rotorua","o":["Rotorua","Taupo","White Island","Hanmer"],"f":"Rotorua's Whakarewarewa terraces and geysers sit in a Maori village landscape. The smell of sulfur is part of the visit."},{"q":"The moa, a giant bird, was hunted to extinction after which arrival?","a":"Polynesian settlement","o":["Polynesian settlement","European settlement only","The ice age ending","Australian colonization"],"f":"Moa were gone within centuries of the first Pacific voyagers. The Haast's eagle that hunted them vanished too."},{"q":"Which of these cities is the capital of New Zealand?","a":"Wellington","o":["Wellington","Auckland","Christchurch","Queenstown"],"f":"Wellington is the capital of New Zealand.","kind":"capital"},{"q":"Which flag is the flag of New Zealand?","a":"NZL","o":["NZL","AUS","FJI","TUV"],"f":"Compare the colors and symbols. One of these four flags is the national flag of New Zealand.","kind":"flag"}]}},{"id":"OMN","name":"Oman","cont":"Asia","emoji":"🇴🇲","latlng":[21,57],"q":{"easy":[{"q":"Which desert of orange dunes inland from the coast is a classic landscape?","a":"The Wahiba Sands","o":["The Wahiba Sands","The Empty Quarter only","The Gobi","The Negev"],"f":"The Sharqiya, or Wahiba, Sands lie east of the mountains. Camps and date villages edge the dunes."},{"q":"Which meat, wrapped and cooked for many hours in an underground pit, is a festival dish?","a":"Shuwa","o":["Shuwa","Mandi","Kabsa","Harees"],"f":"Shuwa is lamb or goat marinated with spices and buried over hot stones. It is served at Eid."},{"q":"Which old port souq under a wooden gallery faces the harbor of the capital?","a":"Mutrah Souq","o":["Mutrah Souq","The Grand Bazaar","Khan el-Khalili","The Gold Souq of Dubai"],"f":"Mutrah's lanes sell frankincense, silver, and textiles beside the corniche and the fort."},{"q":"Which city is the capital of Oman?","a":"Muscat","o":["Muscat","Brasília","Zagreb","Mexico City"],"f":"Muscat is the capital of Oman.","kind":"capital"},{"q":"Which flag belongs to Oman?","a":"OMN","o":["OMN","FIN","SRB","ALB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Oman.","kind":"flag"}],"medium":[{"q":"The Dhofar hills produce the resin of Boswellia sacra, once shipped to Rome and Egypt. What is that resin?","a":"Frankincense","o":["Frankincense","Myrrh","Ambergris","Camphor"],"f":"The best groves drink the summer monsoon mist. UNESCO lists the frankincense sites of Dhofar. Myrrh comes from a related but different tree."},{"q":"Channels that split spring water among farms, still running in mountain villages, are called what?","a":"Aflaj","o":["Aflaj","Qanats","Roman aqueducts","Shadufs"],"f":"UNESCO inscribed five of these systems in 2006. A sundial or a watch tower can divide the flow by time. Iranian qanats are a cousin idea, usually dug underground."},{"q":"Each summer a monsoon greens the hills around Salalah while the rest of Arabia bakes. What is that season called?","a":"The khareef","o":["The khareef","The shamal","The harmattan","The kaskazi"],"f":"Mist drips from the frankincense trees, and waterfalls appear that do not exist in other months. The shamal is a dry north wind, and the harmattan is the dusty wind of West Africa."},{"q":"What is the capital city of Oman?","a":"Muscat","o":["Muscat","Jerusalem","Dhaka","Jakarta"],"f":"Muscat is the capital of Oman.","kind":"capital"},{"q":"Which of these flags belongs to Oman?","a":"OMN","o":["OMN","ARM","TLS","SAU"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Oman.","kind":"flag"}],"hard":[{"q":"Frankincense resin comes from trees in which landscape?","a":"The southern frankincense hills","o":["The southern frankincense hills","The northern fjords","The inland dunes only","The capital coast"],"f":"Boswellia trees grow in the Dhofar hills. The resin was a treasure of ancient trade."},{"q":"Which huge round-tower fort, built in the 1600s, guards an interior market town?","a":"Nizwa Fort","o":["Nizwa Fort","Bahla Fort","Nakhal Fort","Jabreen Castle"],"f":"The tower was packed with earth and stone to resist cannon fire. The souq still sits at its foot."},{"q":"Which eastern port has long built wooden ships for ocean trade?","a":"The port of Sur","o":["The port of Sur","Salalah","Duqm","Khasab"],"f":"Yards in Sur turned out vessels that sailed to East Africa and India. A few still build in wood."},{"q":"Which of these cities is the capital of Oman?","a":"Muscat","o":["Muscat","Salalah","Sohar","Nizwa"],"f":"Muscat is the capital of Oman.","kind":"capital"},{"q":"Which flag is the flag of Oman?","a":"OMN","o":["OMN","NPL","KOR","SVN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Oman.","kind":"flag"}]}},{"id":"PAK","name":"Pakistan","cont":"Asia","emoji":"🇵🇰","latlng":[30,70],"q":{"easy":[{"q":"Which huge Mughal mosque of red sandstone stands in Lahore?","a":"The Badshahi Mosque","o":["The Badshahi Mosque","The Faisal Mosque","The Grand Jamia","The Wazir Khan only"],"f":"Aurangzeb ordered the Badshahi Mosque in the 1670s. It faces the Lahore Fort across the square."},{"q":"Which slow-cooked beef or lamb stew, eaten at breakfast, is a city classic?","a":"Nihari","o":["Nihari","Biryani","Haleem","Karahi"],"f":"Nihari simmers overnight with marrow and spices. It is a traditional weekend breakfast in Karachi and Lahore."},{"q":"Which brightly painted trucks, covered in poetry and flowers, are a moving folk art?","a":"Decorated trucks","o":["Decorated trucks","Rickshaws only","Auto rickshaws of Bangkok","Jeepneys"],"f":"Truck artists paint every panel. The style is a recognized popular art."},{"q":"Which city is the capital of Pakistan?","a":"Islamabad","o":["Islamabad","Podgorica","Sucre","Yamoussoukro"],"f":"Islamabad is the capital of Pakistan.","kind":"capital"},{"q":"Which flag belongs to Pakistan?","a":"PAK","o":["PAK","ROU","GAB","MCO"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Pakistan.","kind":"flag"}],"medium":[{"q":"Which physicist, born in Jhang in 1926, shared the 1979 Nobel Prize for uniting electromagnetism with the weak force?","a":"Abdus Salam","o":["Abdus Salam","C. V. Raman","Satyendra Nath Bose","Homi Bhabha"],"f":"He shared the prize with Sheldon Glashow and Steven Weinberg. Raman, Bose, and Bhabha were major physicists from India, and none of them received that 1979 prize."},{"q":"Mohenjo-daro, a UNESCO city of fired-brick streets and covered drains, belonged to which ancient civilization?","a":"The Indus Valley","o":["The Indus Valley","Mesopotamia","The Olmecs","Ancient Egypt"],"f":"Its mature age was roughly 2500 to 1900 BCE. The Great Bath is the most famous structure. The Indus script is still unread, so we know the engineering better than the politics."},{"q":"K2, the world's second-highest peak, stands on the border with China in which range?","a":"The Karakoram","o":["The Karakoram","The Himalaya","The Hindu Kush","The Pamir"],"f":"It had no widely used local name, so the survey label K2 stuck. It is a harder climb, climber for climber, than Everest, and it is not in the Himalaya proper."},{"q":"What is the capital city of Pakistan?","a":"Islamabad","o":["Islamabad","Dushanbe","Ulaanbaatar","Sri Jayawardenepura Kotte"],"f":"Islamabad is the capital of Pakistan.","kind":"capital"},{"q":"Which of these flags belongs to Pakistan?","a":"PAK","o":["PAK","TLS","KAZ","NPL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Pakistan.","kind":"flag"}],"hard":[{"q":"Which mountain pass between Peshawar and Kabul has been a route of armies and traders?","a":"The Khyber Pass","o":["The Khyber Pass","The Lowari Pass","Bolan","Khunjerab"],"f":"The Khyber cuts through the Spin Ghar mountains. Caravans and armies have used it for thousands of years."},{"q":"The Indus Valley cities of Harappa and Mohenjo-daro had which notable urban feature?","a":"Planned streets and drains","o":["Planned streets and drains","Pyramids","Ziggurats","Colosseums"],"f":"The cities, more than 4,000 years old, laid out brick houses on a grid with covered drains."},{"q":"Which poet and philosopher, born in Sialkot in 1877, wrote in Urdu and Persian and died in 1938?","a":"Muhammad Iqbal","o":["Muhammad Iqbal","Ghalib","Faiz","Rumi"],"f":"Iqbal's poems urged a spiritual and political renewal. He is honored as the national poet."},{"q":"Which of these cities is the capital of Pakistan?","a":"Islamabad","o":["Islamabad","Karachi","Lahore","Peshawar"],"f":"Islamabad is the capital of Pakistan.","kind":"capital"},{"q":"Which flag is the flag of Pakistan?","a":"PAK","o":["PAK","TUR","DZA","TUN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Pakistan.","kind":"flag"}]}},{"id":"PAN","name":"Panama","cont":"North America","emoji":"🇵🇦","latlng":[9,-80],"q":{"easy":[{"q":"Which lock canal, opened in 1914, links the Atlantic and the Pacific?","a":"The lock canal between the oceans","o":["The lock canal between the oceans","The Suez","The Erie","The Corinth"],"f":"Locks lift ships over the continental divide at Gatun Lake. An expanded set of locks opened in 2016."},{"q":"Which fried corn cake and a sancocho stew are home food?","a":"Tortillas and sancocho","o":["Tortillas and sancocho","Pupusas","Arepas","Ceviche only"],"f":"Sancocho is a chicken or meat soup with root vegetables. Arepas and patacones are common sides."},{"q":"Which Caribbean islands of the Kuna, or Guna, people fly their own flag inside the country?","a":"Guna Yala","o":["Guna Yala","The Pearl Islands","Bocas del Toro","Coiba"],"f":"The Guna run a comarca, a self-governing territory, along the San Blas coast. Molas are their reverse-appliqué cloth."},{"q":"Which city is the capital of Panama?","a":"Panama City","o":["Panama City","Bangkok","Malabo","Kabul"],"f":"Panama City is the capital of Panama.","kind":"capital"},{"q":"Which flag belongs to Panama?","a":"PAN","o":["PAN","PRK","AUT","AZE"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Panama.","kind":"flag"}],"medium":[{"q":"Which salsa singer and songwriter, born in Panama City, later served as minister of tourism?","a":"Ruben Blades","o":["Ruben Blades","Willie Colon","Tito Puente","Celia Cruz"],"f":"His 1978 album Siembra, made with Willie Colon, became one of salsa's bestsellers. Colon and Puente were born in the United States, and Cruz was born in Cuba."},{"q":"The Panama Canal, opened in 1914, raises ships with locks onto which artificial lake?","a":"Gatun Lake","o":["Gatun Lake","Lake Nicaragua","Lake Atitlan","Lake Managua"],"f":"The canal is not a sea-level ditch. Locks lift ships about 26 meters to the lake, then lower them to the other ocean. A larger set of locks opened in 2016."},{"q":"Treaties signed in 1977 transferred the canal from the United States to Panama at noon on which date?","a":"31 December 1999","o":["31 December 1999","15 August 1914","4 July 1977","1 January 2005"],"f":"They are the Torrijos-Carter Treaties. The Canal Zone, a strip the United States had controlled since construction, came to an end that day."},{"q":"What is the capital city of Panama?","a":"Panama City","o":["Panama City","St. John's","Basseterre","Port-au-Prince"],"f":"Panama City is the capital of Panama.","kind":"capital"},{"q":"Which of these flags belongs to Panama?","a":"PAN","o":["PAN","DOM","DMA","BHS"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Panama.","kind":"flag"}],"hard":[{"q":"Which toquilla-palm hat, woven in Ecuador and shipped through this isthmus, took the country's name abroad?","a":"A misnamed palm hat","o":["A misnamed palm hat","The sombrero vueltiao","The cowboy hat","The bowler"],"f":"Toquilla-palm hats from Montecristi were shipped through Panama to California and Europe. The name stuck."},{"q":"Which brightly painted former school buses became a folk art of the capital streets?","a":"Diablos rojos","o":["Diablos rojos","Jeepneys","Chicken buses","Matatus"],"f":"The red devils were American school buses covered in paintings and slogans. A metro and newer buses have replaced many of them."},{"q":"Coiba Island, a former penal colony, is now a national park known for what?","a":"Marine life and a prison history","o":["Marine life and a prison history","Skiing","A Maya capital","A gold rush"],"f":"The island held a prison for decades. Its reefs and forests are now protected."},{"q":"Which of these cities is the capital of Panama?","a":"Panama City","o":["Panama City","Colón","David","Santiago"],"f":"Panama City is the capital of Panama.","kind":"capital"},{"q":"Which flag is the flag of Panama?","a":"PAN","o":["PAN","TTO","TZA","SYR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Panama.","kind":"flag"}]}},{"id":"PER","name":"Peru","cont":"South America","emoji":"🇵🇪","latlng":[-10,-76],"q":{"easy":[{"q":"Which Inca city in the clouds was revealed to the world by Hiram Bingham in 1911?","a":"Machu Picchu","o":["Machu Picchu","Cusco","Ollantaytambo","Choquequirao"],"f":"Machu Picchu sits above the Urubamba. It was a royal estate of the 1400s, abandoned and later overgrown."},{"q":"Which citrus-cured fish, the national dish of the coast, is a lunch classic?","a":"Ceviche","o":["Ceviche","Tiradito","Lomo saltado","Aji de gallina"],"f":"Ceviche marinates fish in lime with onion and chili. It is served with sweet potato and corn."},{"q":"Which lake, the highest large lake, is shared with Bolivia?","a":"Lake Titicaca","o":["Lake Titicaca","Lake Junin","Lake Titicaca is shared","Arapa"],"f":"Reed islands of the Uros float near Puno. The lake was sacred to Inca origin stories."},{"q":"Which city is the capital of Peru?","a":"Lima","o":["Lima","Djibouti","Vilnius","Athens"],"f":"Lima is the capital of Peru.","kind":"capital"},{"q":"Which flag belongs to Peru?","a":"PER","o":["PER","TUR","MLI","MNG"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Peru.","kind":"flag"}],"medium":[{"q":"Which writer, born in Arequipa, won the 2010 Nobel Prize in Literature?","a":"Mario Vargas Llosa","o":["Mario Vargas Llosa","Gabriel Garcia Marquez","Jorge Luis Borges","Pablo Neruda"],"f":"Novels such as The Time of the Hero and The Feast of the Goat examine power and corruption. He later also became a Spanish citizen."},{"q":"The Inca estate of Machu Picchu sits on a ridge above which river's cloud-forest canyon?","a":"The Urubamba","o":["The Urubamba","The Amazon","The Orinoco","The Parana"],"f":"The royal estate was abandoned in the 1500s and became widely known after Hiram Bingham's 1911 visit. Its dry-stone terraces still grip the ridge."},{"q":"Giant figures made by clearing dark stones, some hundreds of meters across, lie on a dry coastal plateau. Which culture made them?","a":"The Nazca","o":["The Nazca","The Moche","The Chimu","The Wari"],"f":"The lines are easiest to see from above, yet they were laid out long before airplanes, by careful measurement on the ground."},{"q":"What is the capital city of Peru?","a":"Lima","o":["Lima","Santiago","Paramaribo","Georgetown"],"f":"Lima is the capital of Peru.","kind":"capital"},{"q":"Which of these flags belongs to Peru?","a":"PER","o":["PER","COL","VEN","URY"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Peru.","kind":"flag"}],"hard":[{"q":"Which lines in the desert near Nazca were made by moving stones aside?","a":"The Nazca Lines","o":["The Nazca Lines","The Sajama lines","Geoglyphs of only Chile","Runways"],"f":"The figures of animals and lines are best seen from the air. They date from about 200 BCE to 600 CE."},{"q":"The potato was domesticated in the Andes. How many species does the region still grow?","a":"Thousands of varieties","o":["Thousands of varieties","Only three","Only the sweet potato","None now"],"f":"Farmers keep a huge range of colors and shapes. The International Potato Center in Lima stores many of them."},{"q":"Which round terraces in the Sacred Valley are often explained as a place for testing crops?","a":"Moray","o":["Moray","Pisac","Tipon","Winay Wayna"],"f":"The rings drop into a bowl, and the air is warmer toward the bottom. The crop-laboratory idea is a common explanation, not a proven record."},{"q":"Which of these cities is the capital of Peru?","a":"Lima","o":["Lima","Cusco","Arequipa","Trujillo"],"f":"Lima is the capital of Peru.","kind":"capital"},{"q":"Which flag is the flag of Peru?","a":"PER","o":["PER","AUT","LBN","LVA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Peru.","kind":"flag"}]}},{"id":"PHL","name":"Philippines","cont":"Asia","emoji":"🇵🇭","latlng":[13,122],"q":{"easy":[{"q":"Which rice noodles with broth, or a sour stew called sinigang, share the table with which sour pork?","a":"Adobo","o":["Adobo","Sushi","Pho","Ramen"],"f":"Adobo simmers pork or chicken in vinegar, soy, and garlic. It is often called the national dish."},{"q":"Which terraced mountains of the Cordilleras, a UNESCO landscape, were built for rice?","a":"The Ifugao rice terraces","o":["The Ifugao rice terraces","The terraces of Yuanyang","Andenes","Banaue is part of them"],"f":"Ifugao communities carved terraces over many centuries. Some are still planted with rice."},{"q":"Which decorated minibuses, originally surplus jeeps, are the everyday city ride?","a":"Jeepneys","o":["Jeepneys","Tuk-tuks","Matatus","Dolmus"],"f":"Jeepneys were rebuilt from military jeeps after World War II. They are painted with names and chrome."},{"q":"Which city is the capital of Philippines?","a":"Manila","o":["Manila","Bratislava","Accra","Zagreb"],"f":"Manila is the capital of Philippines.","kind":"capital"},{"q":"Which flag belongs to Philippines?","a":"PHL","o":["PHL","FIN","BRA","MUS"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Philippines.","kind":"flag"}],"medium":[{"q":"Which novelist and doctor, born in Calamba in 1861, wrote Noli Me Tangere and was executed in 1896?","a":"José Rizal","o":["José Rizal","Andres Bonifacio","Emilio Aguinaldo","Apolinario Mabini"],"f":"His novels attacked the power of the Spanish friars. Bonifacio led the Katipunan revolt, Aguinaldo headed the revolutionary government, and Mabini was its adviser. None of them wrote Noli."},{"q":"The Ifugao rice terraces of the Cordillera, a UNESCO landscape, were built on what?","a":"Steep mountain slopes","o":["Steep mountain slopes","A river delta","A coral atoll","The floor of a crater"],"f":"Farmers still repair the stone walls and the irrigation. They are a living landscape, not an empty ruin, and claims about their exact age are debated."},{"q":"After the Second World War, surplus American military vehicles were stretched into a loud, painted form of public transport. What is it called?","a":"A jeepney","o":["A jeepney","A tuk-tuk","A rickshaw","A tram"],"f":"The word blends jeep and jitney. Chrome, slogans, and painted scenes cover a traditional jeepney. A tuk-tuk is the three-wheeler of Thailand and its neighbors."},{"q":"What is the capital city of Philippines?","a":"Manila","o":["Manila","Damascus","Amman","Baku"],"f":"Manila is the capital of Philippines.","kind":"capital"},{"q":"Which of these flags belongs to Philippines?","a":"PHL","o":["PHL","IRN","MDV","CHN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Philippines.","kind":"flag"}],"hard":[{"q":"Which hero and novelist, author of Noli Me Tangere, was executed in 1896?","a":"Jose Rizal","o":["Jose Rizal","Bonifacio","Aguinaldo","Mabini"],"f":"Rizal's novels attacked colonial abuses. He was shot at Bagumbayan, now Luneta, in Manila."},{"q":"The hudhud chants of the Ifugao are sung during what work?","a":"Rice harvest and funerals","o":["Rice harvest and funerals","War only","Fishing","Metal forging"],"f":"The hudhud is a long narrative song. UNESCO lists it. Women traditionally lead the chant."},{"q":"Which volcano in Albay has a famous perfect cone?","a":"Mayon","o":["Mayon","Pinatubo","Taal","Fuji"],"f":"Mayon has erupted many times. Its slopes are a symbol of the Bicol region."},{"q":"Which of these cities is the capital of Philippines?","a":"Manila","o":["Manila","Cebu City","Davao City","Quezon City"],"f":"Manila is the capital of Philippines.","kind":"capital"},{"q":"Which flag is the flag of Philippines?","a":"PHL","o":["PHL","ZMB","MDG","OMN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Philippines.","kind":"flag"}]}},{"id":"PLW","name":"Palau","cont":"Oceania","emoji":"🇵🇼","latlng":[7.5,134.5],"q":{"easy":[{"q":"Which limestone islands of a famous lagoon are a UNESCO site?","a":"The Rock Islands","o":["The Rock Islands","The Seventy Islands","Chuuk","The Yasawas"],"f":"The Rock Islands Southern Lagoon has mushroom-shaped islets and marine lakes. Jellyfish Lake is the best known."},{"q":"Which swamp root, grown in flooded patches, is the prestige starch?","a":"Taro","o":["Taro","Breadfruit","Rice","Yam only"],"f":"Taro patches are tended with care. A feast is incomplete without the root."},{"q":"Which traditional meeting house with decorated beams is the community hall?","a":"The bai","o":["The bai","The maneaba","The fale","The ger"],"f":"A bai's gables are painted with stories. It is the place of council, not a private home."},{"q":"Which city is the capital of Palau?","a":"Ngerulmud","o":["Ngerulmud","Malé","Lisbon","Rome"],"f":"Ngerulmud is the capital of Palau.","kind":"capital"},{"q":"Which flag belongs to Palau?","a":"PLW","o":["PLW","SEN","AFG","GEO"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Palau.","kind":"flag"}],"medium":[{"q":"Jellyfish Lake in the Rock Islands is famous for golden jellyfish that have mostly lost their what?","a":"Sting","o":["Sting","Color","Bell","Ability to swim"],"f":"Cut off from the sea and short of predators, their stings faded. Each day the jellyfish migrate across the lake following the sun."},{"q":"Palau's Rock Islands look like mushrooms because erosion cuts the limestone most strongly at which level?","a":"The waterline","o":["The waterline","The summit","The reef crest","The beach dune"],"f":"Waves and boring organisms undercut the rock, leaving a cap of forest on a narrow stone neck."},{"q":"A traditional Palauan meeting house, with a carved gable telling village stories, is called a what?","a":"Bai","o":["Bai","Maneaba","Fale","Langi"],"f":"Men historically gathered in the bai, while women often held real authority over family land and titles."},{"q":"What is the capital city of Palau?","a":"Ngerulmud","o":["Ngerulmud","Port Vila","Majuro","Funafuti"],"f":"Ngerulmud is the capital of Palau.","kind":"capital"},{"q":"Which of these flags belongs to Palau?","a":"PLW","o":["PLW","NRU","PNG","FJI"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Palau.","kind":"flag"}],"hard":[{"q":"The islands were a German, then Japanese, then American trust territory. Compact free association began in which decade?","a":"The 1990s","o":["The 1990s","The 1960s","The 1940s","The 2010s"],"f":"Palau approved a compact with the United States and became fully self-governing in 1994."},{"q":"Which marine-lake jellyfish have lost their sting?","a":"Golden jellyfish","o":["Golden jellyfish","Box jellyfish","Irukandji","Portuguese men-of-war"],"f":"Mastigias jellyfish in Jellyfish Lake live without a strong sting. Snorkelers swim among them."},{"q":"The stone faces and terraces of which islands show old village sites?","a":"The Rock Islands and Babeldaob","o":["The Rock Islands and Babeldaob","Only Yap","Only Nan Madol","Only Leluh"],"f":"Terraces and monoliths on Babeldaob are among the older earthworks in Oceania."},{"q":"Which of these cities is the capital of Palau?","a":"Ngerulmud","o":["Ngerulmud","Koror","Airai","Ngardmau"],"f":"Ngerulmud is the capital of Palau.","kind":"capital"},{"q":"Which flag is the flag of Palau?","a":"PLW","o":["PLW","LAO","BGD","JPN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Palau.","kind":"flag"}]}},{"id":"PNG","name":"Papua New Guinea","cont":"Oceania","emoji":"🇵🇬","latlng":[-6,147],"q":{"easy":[{"q":"Which birds of elaborate plumes are a national symbol and a highland treasure?","a":"Birds of paradise","o":["Birds of paradise","Cassowaries","Hornbills","Parrots"],"f":"More than 30 kinds of birds of paradise live on the island. Highland headdresses use their feathers."},{"q":"Which roasted pork and sweet potato are the highland feast?","a":"Mumu pork and kau kau","o":["Mumu pork and kau kau","Sago","Rice","Fish and chips"],"f":"A mumu is an earth oven of hot stones. Sweet potato, kau kau, is the daily staple of the highlands."},{"q":"Which volcano buried much of the old island town of Rabaul in 1994?","a":"Tavurvur","o":["Tavurvur","Lamington","Ulawun","Krakatoa"],"f":"Ash from Tavurvur and a second vent covered the town that September. The provincial capital then moved to Kokopo."},{"q":"Which city is the capital of Papua New Guinea?","a":"Port Moresby","o":["Port Moresby","Ottawa","Harare","Mbabane"],"f":"Port Moresby is the capital of Papua New Guinea.","kind":"capital"},{"q":"Which flag belongs to Papua New Guinea?","a":"PNG","o":["PNG","DZA","BEL","JAM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Papua New Guinea.","kind":"flag"}],"medium":[{"q":"Papua New Guinea has more living languages than any other country. About how many are there?","a":"More than 800","o":["More than 800","About 40","About 120","About 300"],"f":"Many are spoken by only a few hundred people. Tok Pisin, an English-based creole, is the language strangers most often share."},{"q":"In 1942 Australian troops fought Japanese forces along which muddy mountain path toward Port Moresby?","a":"The Kokoda Track","o":["The Kokoda Track","The Burma Road","The Ho Chi Minh Trail","The Inca Trail"],"f":"The Owen Stanley Range campaign stopped a Japanese advance on Port Moresby. It became a defining Australian war story."},{"q":"Male birds of paradise, most of which live on New Guinea, are famous for what?","a":"Elaborate courtship dances","o":["Elaborate courtship dances","Building clay nests","Migrating to Antarctica","Singing underwater"],"f":"Some clear a patch of forest floor and dance for hours. Bright plumes evolved because females choose the most impressive males."},{"q":"What is the capital city of Papua New Guinea?","a":"Port Moresby","o":["Port Moresby","Majuro","Wellington","Canberra"],"f":"Port Moresby is the capital of Papua New Guinea.","kind":"capital"},{"q":"Which of these flags belongs to Papua New Guinea?","a":"PNG","o":["PNG","AUS","FSM","VUT"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Papua New Guinea.","kind":"flag"}],"hard":[{"q":"The national currency takes its name from which traditional valuable?","a":"A gold-lip pearl shell","o":["A gold-lip pearl shell","A stone disk","A cocoa bean","A Spanish gold coin"],"f":"Highland trade used the gold-lip shell called a kina. The modern currency, introduced at independence, took that name."},{"q":"The Sepik River is famous for which carved art?","a":"Spirit masks and hooks","o":["Spirit masks and hooks","Jade","Bronze","Marble"],"f":"Men's houses store ancestor figures. Crocodile-scarification and yam cults belong to the same river culture."},{"q":"Which highland festival of painted bodies and headdresses is held at Mount Hagen?","a":"The singsing","o":["The singsing","The haka","Intore","A powwow"],"f":"Groups dance in bilas, body decoration of paint, shells, and feathers. The show grew in the 1960s."},{"q":"Which of these cities is the capital of Papua New Guinea?","a":"Port Moresby","o":["Port Moresby","Lae","Madang","Mount Hagen"],"f":"Port Moresby is the capital of Papua New Guinea.","kind":"capital"},{"q":"Which flag is the flag of Papua New Guinea?","a":"PNG","o":["PNG","DZA","URY","GTM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Papua New Guinea.","kind":"flag"}]}},{"id":"POL","name":"Poland","cont":"Europe","emoji":"🇵🇱","latlng":[52,20],"q":{"easy":[{"q":"Which dumplings with potato, cheese, or meat are a national comfort food?","a":"Pierogi","o":["Pierogi","Ravioli","Gyoza","Manti"],"f":"Pierogi are boiled and sometimes fried. Sour cream and onions are the usual company."},{"q":"Which red-brick castle of the Teutonic Order on the Nogat River is one of the largest?","a":"Malbork Castle","o":["Malbork Castle","Wawel","The Kremlin","Neuschwanstein"],"f":"Malbork was the Teutonic headquarters. It is a huge UNESCO fortress of brick halls and towers."},{"q":"Which composer of piano mazurkas and nocturnes was born in Zelazowa Wola in 1810?","a":"Frederic Chopin","o":["Frederic Chopin","Liszt","Schumann","Paderewski"],"f":"Chopin left for Paris but wrote dances drawn from Polish folk rhythms. His heart is entombed in Warsaw."},{"q":"Which city is the capital of Poland?","a":"Warsaw","o":["Warsaw","Maseru","Tbilisi","Sana'a"],"f":"Warsaw is the capital of Poland.","kind":"capital"},{"q":"Which flag belongs to Poland?","a":"POL","o":["POL","UGA","KNA","GEO"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Poland.","kind":"flag"}],"medium":[{"q":"Which astronomer, born in Torun in 1473, argued that Earth orbits the Sun?","a":"Nicolaus Copernicus","o":["Nicolaus Copernicus","Galileo Galilei","Johannes Kepler","Tycho Brahe"],"f":"His book On the Revolutions of the Heavenly Spheres appeared in 1543, the year he died. He had worked as a church canon in Frombork, on the Baltic."},{"q":"The Wieliczka salt mine, near Krakow, has chapels and chandeliers carved entirely from what?","a":"Rock salt","o":["Rock salt","Marble","Amber","Ice"],"f":"Miners worked there from the 13th century until the 1990s. The Chapel of St. Kinga, far underground, is the showpiece of the UNESCO site."},{"q":"In 1980 striking workers at the Gdansk shipyard formed a union that the government later banned. What was it called?","a":"Solidarity","o":["Solidarity","The Prague Spring","Charter 77","The Orange Alternative"],"f":"Lech Walesa, an electrician, became its face. The movement returned in 1989 and helped end one-party rule. Walesa was elected president in 1990."},{"q":"What is the capital city of Poland?","a":"Warsaw","o":["Warsaw","Moscow","Luxembourg City","Zagreb"],"f":"Warsaw is the capital of Poland.","kind":"capital"},{"q":"Which of these flags belongs to Poland?","a":"POL","o":["POL","GRC","SVN","NLD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Poland.","kind":"flag"}],"hard":[{"q":"Which salt mine near Krakow has chapels carved underground?","a":"Wieliczka","o":["Wieliczka","Bochnia only","Hallstatt","Cardona"],"f":"Miners at Wieliczka carved altars and a famous chapel from salt. The tunnels are a UNESCO site."},{"q":"The Constitution of 3 May 1791 was a landmark document of which state?","a":"The Polish-Lithuanian Commonwealth","o":["The Polish-Lithuanian Commonwealth","The Russian Empire","Prussia","Austria"],"f":"It was one of the first modern written constitutions in Europe. Neighbors partitioned the state soon after."},{"q":"Which Christmas Eve supper has no meat and sets an extra place?","a":"Wigilia","o":["Wigilia","Easter breakfast","A harvest feast","Carnival"],"f":"Wigilia begins when the first star appears. Beet soup, carp, and pierogi are typical, and hay is sometimes laid under the cloth."},{"q":"Which of these cities is the capital of Poland?","a":"Warsaw","o":["Warsaw","Kraków","Gdańsk","Wrocław"],"f":"Warsaw is the capital of Poland.","kind":"capital"},{"q":"Which flag is the flag of Poland?","a":"POL","o":["POL","SGP","MCO","IDN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Poland.","kind":"flag"}]}},{"id":"PRK","name":"North Korea","cont":"Asia","emoji":"🇰🇵","latlng":[40,127],"q":{"easy":[{"q":"Which historic city near the southern border was a capital of the Goryeo kingdom?","a":"Kaesong","o":["Kaesong","Pyongyang","Hamhung","Sinuiju"],"f":"Kaesong holds Goryeo royal tombs and an old Confucian academy. It sits near the demilitarized zone."},{"q":"Which pickled cabbage, seasoned with chili, is eaten with meals?","a":"Kimchi","o":["Kimchi","Sauerkraut","Tsukemono","Achar"],"f":"Kimchi is cabbage or radish fermented with chili and garlic. It is a staple on both sides of the peninsula."},{"q":"Which river runs through the capital to the Yellow Sea?","a":"The Taedong","o":["The Taedong","The Yalu","The Han","The Nakdong"],"f":"The Taedong passes Pyongyang. A famous tower, the Juche Tower, stands on its bank."},{"q":"Which city is the capital of North Korea?","a":"Pyongyang","o":["Pyongyang","Bogotá","Tallinn","Cairo"],"f":"Pyongyang is the capital of North Korea.","kind":"capital"},{"q":"Which flag belongs to North Korea?","a":"PRK","o":["PRK","SRB","NLD","HUN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of North Korea.","kind":"flag"}],"medium":[{"q":"Fighting in the Korean War stopped in 1953 with an agreement signed at Panmunjom. What kind of agreement was it?","a":"An armistice, not a peace treaty","o":["An armistice, not a peace treaty","A peace treaty that formally ended the war","A royal marriage alliance","A trade pact and nothing more"],"f":"The fighting began in June 1950. The armistice drew a line near the 38th parallel and created a demilitarized zone. No peace treaty has replaced it."},{"q":"The highest mountain on the Korean peninsula, a volcano with a crater lake, stands on the border with China. What is it called?","a":"Mount Paektu","o":["Mount Paektu","Mount Halla","Mount Kumgang","Mount Seorak"],"f":"Koreans call the lake Heaven Lake. Old foundation myths place the origin of the Korean people on this mountain. Hallasan is on Jeju, in the south, and Kumgang and Seorak are different ranges."},{"q":"Pyongyang is famous for cold buckwheat noodles served in an icy broth. What is that dish called?","a":"Raengmyon","o":["Raengmyon","Japchae","Tteokbokki","Kimchi jjigae"],"f":"In the south the same family of noodles is called naengmyeon. The broth is meant to be icy and the noodles chewy. Japchae is a stir-fried glass-noodle dish, served warm."},{"q":"What is the capital city of North Korea?","a":"Pyongyang","o":["Pyongyang","Phnom Penh","Vientiane","Bishkek"],"f":"Pyongyang is the capital of North Korea.","kind":"capital"},{"q":"Which of these flags belongs to North Korea?","a":"PRK","o":["PRK","MYS","KHM","NPL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of North Korea.","kind":"flag"}],"hard":[{"q":"The Korean War of 1950 to 1953 ended with which kind of agreement, not a peace treaty?","a":"An armistice","o":["An armistice","A surrender","A royal marriage","A United Nations membership vote"],"f":"The armistice was signed at Panmunjom. A formal peace treaty was never concluded."},{"q":"Mount Paektu, a volcano on the Chinese border, holds which crater lake?","a":"Heaven Lake","o":["Heaven Lake","Crater Lake of Oregon","Lake Toba","Baikal"],"f":"Heaven Lake straddles the border. Korean tradition ties the mountain to the origin of kingdoms."},{"q":"Which ancient kingdom's painted tombs near the capital are a UNESCO site?","a":"Goguryeo","o":["Goguryeo","Silla","Baekje","Goryeo"],"f":"Goguryeo ruled the north in the early centuries CE. Murals in the tombs show daily life, processions, and mythical animals."},{"q":"Which of these cities is the capital of North Korea?","a":"Pyongyang","o":["Pyongyang","Hamhung","Kaesong","Chongjin"],"f":"Pyongyang is the capital of North Korea.","kind":"capital"},{"q":"Which flag is the flag of North Korea?","a":"PRK","o":["PRK","ZMB","HND","SVK"],"f":"Compare the colors and symbols. One of these four flags is the national flag of North Korea.","kind":"flag"}]}},{"id":"PRT","name":"Portugal","cont":"Europe","emoji":"🇵🇹","latlng":[39.5,-8],"q":{"easy":[{"q":"Which custard tarts from a Lisbon monastery shop are a national sweet?","a":"Pastel de nata","o":["Pastel de nata","Baklava","Cannoli","Creme brulee"],"f":"Pastel de nata are baked in very hot ovens so the tops blister. The Belem shop claims the old recipe."},{"q":"Which tower and monastery at the mouth of the Tagus mark the age of exploration?","a":"The Belem Tower and Jeronimos","o":["The Belem Tower and Jeronimos","The Eiffel Tower","The Monument to the Discoveries only","Sagres only"],"f":"Belem Tower guarded the river. Jeronimos Monastery was built with profits from the spice trade."},{"q":"Which captain reached India by sea in 1498?","a":"Vasco da Gama","o":["Vasco da Gama","Columbus","Magellan","Dias"],"f":"Da Gama rounded the Cape and crossed to Calicut. The voyage opened a Portuguese route into the Indian Ocean."},{"q":"Which city is the capital of Portugal?","a":"Lisbon","o":["Lisbon","Doha","Bridgetown","Bishkek"],"f":"Lisbon is the capital of Portugal.","kind":"capital"},{"q":"Which flag belongs to Portugal?","a":"PRT","o":["PRT","UGA","JPN","LKA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Portugal.","kind":"flag"}],"medium":[{"q":"Which poet, born in Lisbon, wrote under dozens of invented names, which he called heteronyms?","a":"Fernando Pessoa","o":["Fernando Pessoa","Luis de Camoes","Jose Saramago","Eca de Queiros"],"f":"Alberto Caeiro, Ricardo Reis, and Alvaro de Campos were his most famous imaginary authors, each with a style of his own. The Book of Disquiet was pieced together after his death."},{"q":"On 1 November 1755 a huge earthquake, fires, and a tsunami destroyed much of Lisbon. The disaster pushed European thinkers to argue about what?","a":"How a good God could allow such suffering","o":["How a good God could allow such suffering","Whether the Earth was flat","How to invent the steam engine","Whether to ban all churches"],"f":"Voltaire used the quake in Candide. The Marquis of Pombal rebuilt the downtown on a grid, one of the first planned city centers in Europe."},{"q":"Fado, a UNESCO-listed song tradition, is typically a voice accompanied by which guitar?","a":"The Portuguese guitar","o":["The Portuguese guitar","The flamenco guitar","The oud","The balalaika"],"f":"The Portuguese guitar has a pear-shaped body and twelve steel strings. Classic fado dwells on saudade, a homesick longing."},{"q":"What is the capital city of Portugal?","a":"Lisbon","o":["Lisbon","Athens","Amsterdam","Budapest"],"f":"Lisbon is the capital of Portugal.","kind":"capital"},{"q":"Which of these flags belongs to Portugal?","a":"PRT","o":["PRT","ITA","GBR","DEU"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Portugal.","kind":"flag"}],"hard":[{"q":"Azulejo tiles cover churches and stations. The word comes from Arabic for what?","a":"A polished stone","o":["A polished stone","A brush","A kiln","A sail"],"f":"The blue-and-white panels tell stories. A famous hall of tiles stands in the National Tile Museum."},{"q":"Which sad urban song, with a Portuguese guitar, grew in Lisbon neighborhoods?","a":"Fado","o":["Fado","Flamenco","Tango","Rebetiko"],"f":"Fado singers perform fate and longing. Amalia Rodrigues made it famous in the 20th century."},{"q":"The 1755 earthquake and fire destroyed much of Lisbon and shook which philosophical debate?","a":"How a good world could suffer","o":["How a good world could suffer","The divine right of kings","The heliocentric model","The age of the Earth"],"f":"Voltaire used the disaster in Candide. The Marquis of Pombal rebuilt the Baixa on a grid."},{"q":"Which of these cities is the capital of Portugal?","a":"Lisbon","o":["Lisbon","Porto","Coimbra","Faro"],"f":"Lisbon is the capital of Portugal.","kind":"capital"},{"q":"Which flag is the flag of Portugal?","a":"PRT","o":["PRT","BLZ","ISR","SSD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Portugal.","kind":"flag"}]}},{"id":"PRY","name":"Paraguay","cont":"South America","emoji":"🇵🇾","latlng":[-23,-58],"q":{"easy":[{"q":"Which herbal tea, drunk cold from a gourd or hot, is a national habit?","a":"Terere and mate","o":["Terere and mate","Coffee","Cocoa","Guarana"],"f":"Terere is yerba mate with ice water and herbs. It is passed among friends all day."},{"q":"Which harp music of the countryside accompanies polkas and galopas?","a":"The folk harp","o":["The folk harp","The charango","The guitar of only Spain","The bandoneon"],"f":"The harp has a light sound and a fast bass. It is the national instrument."},{"q":"Which huge dam, shared with Brazil, floods a branch of the Parana?","a":"Itaipu","o":["Itaipu","Yacyreta","Salto Grande","Three Gorges"],"f":"Itaipu, finished in the 1980s, was long the largest hydroelectric plant by output. The lake covers the old Guaira falls."},{"q":"Which city is the capital of Paraguay?","a":"Asunción","o":["Asunción","Ottawa","Nassau","Yamoussoukro"],"f":"Asunción is the capital of Paraguay.","kind":"capital"},{"q":"Which flag belongs to Paraguay?","a":"PRY","o":["PRY","KWT","HTI","MDV"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Paraguay.","kind":"flag"}],"medium":[{"q":"Which novelist, born in Asuncion, wrote I, the Supreme about a 19th-century dictator?","a":"Augusto Roa Bastos","o":["Augusto Roa Bastos","Gabriel Garcia Marquez","Mario Vargas Llosa","Isabel Allende"],"f":"The novel portrays Jose Gaspar Rodriguez de Francia, who ruled Paraguay in isolation after independence. Roa Bastos spent years in exile."},{"q":"UNESCO sites at Trinidad and Jesus de Tavarangue preserve ruins of settlements built by which religious order?","a":"The Jesuits","o":["The Jesuits","The Benedictines","The Franciscans","The Dominicans"],"f":"In these 17th- and 18th-century missions, Guarani communities and Jesuit priests built churches, workshops, and orchards."},{"q":"From 1864 to 1870 Paraguay fought Argentina, Brazil, and Uruguay in which devastating conflict?","a":"The War of the Triple Alliance","o":["The War of the Triple Alliance","The War of the Pacific","The Chaco War","The Paraguayan War of Independence"],"f":"Paraguay's population fell drastically, though historians still debate the exact toll. Recovery took generations."},{"q":"What is the capital city of Paraguay?","a":"Asunción","o":["Asunción","Santiago","Buenos Aires","Sucre"],"f":"Asunción is the capital of Paraguay.","kind":"capital"},{"q":"Which of these flags belongs to Paraguay?","a":"PRY","o":["PRY","URY","ARG","SUR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Paraguay.","kind":"flag"}],"hard":[{"q":"The War of the Triple Alliance, from 1864 to 1870, set Paraguay against which three neighbors?","a":"Brazil, Argentina, and Uruguay","o":["Brazil, Argentina, and Uruguay","Chile, Bolivia, and Peru","The United States, Britain, and France","Spain, Portugal, and Britain"],"f":"The war killed a huge share of the population. It remains the central trauma of 19th-century history."},{"q":"Which lace, woven by hand in the town of Itauguá, is a national craft?","a":"Ñanduti","o":["Ñanduti","Bobbin lace of Bruges","Filet","Crochet only"],"f":"Nanduti means spider web. Women stitch circular sunburst patterns on a frame."},{"q":"The Jesuit missions among the Guarani left ruins at which UNESCO towns?","a":"Trinidad and Jesus","o":["Trinidad and Jesus","San Ignacio Mini","Cordoba","Asuncion"],"f":"The reductions of Trinidad and Jesus preserve baroque stone churches from the 1700s."},{"q":"Which of these cities is the capital of Paraguay?","a":"Asunción","o":["Asunción","Ciudad del Este","Encarnación","Concepción"],"f":"Asunción is the capital of Paraguay.","kind":"capital"},{"q":"Which flag is the flag of Paraguay?","a":"PRY","o":["PRY","SVK","HRV","SVN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Paraguay.","kind":"flag"}]}},{"id":"PSE","name":"Palestine","cont":"Asia","emoji":"🇵🇸","latlng":[31.9,35.2],"q":{"easy":[{"q":"Which church in Bethlehem is built over the grotto tradition calls the birthplace of Jesus?","a":"The Church of the Nativity","o":["The Church of the Nativity","The Holy Sepulchre","The Annunciation","The Nativity in Nazareth"],"f":"The basilica dates from the 300s, rebuilt in the 500s. A silver star marks the grotto."},{"q":"Which sumac chicken and onion pie on bread is a festive dish?","a":"Musakhan","o":["Musakhan","Maqluba","Mansaf","Kabsa"],"f":"Musakhan bakes chicken on taboon bread with onions and sumac. It is a harvest and celebration dish."},{"q":"Which trees on the hills have been pressed for oil for centuries?","a":"Olive trees","o":["Olive trees","Cedars","Date palms only","Citrus"],"f":"The olive harvest in autumn is a family event. Oil, soap, and wood are the old products."},{"q":"The Palestinian Authority's main government offices are in which city?","a":"Ramallah","o":["Ramallah","Vaduz","Guatemala City","Kampala"],"f":"Ramallah is the administrative center. Jerusalem is claimed as a capital.","kind":"capital"},{"q":"Which flag belongs to Palestine?","a":"PSE","o":["PSE","HND","BWA","MNE"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Palestine.","kind":"flag"}],"medium":[{"q":"Which poet, born in al-Birwa in 1941, wrote Identity Card and became the best-known voice of Palestinian letters?","a":"Mahmoud Darwish","o":["Mahmoud Darwish","Khalil Gibran","Nizar Qabbani","Adonis"],"f":"His family left al-Birwa in 1948. He later lived in exile and in Ramallah, and died in 2008. Gibran was Lebanese, and Qabbani and Adonis were Syrian."},{"q":"Cross-stitch on village dresses, whose patterns once signaled a woman's home region, was inscribed by UNESCO in 2021. What is it called?","a":"Tatreez","o":["Tatreez","Kantha","Sashiko","Kente"],"f":"A dress from Ramallah does not look like one from Hebron or Gaza. The stitches are counted on the cloth, so the motifs stay geometric. Kantha, sashiko, and kente are textile traditions of Bengal, Japan, and Ghana."},{"q":"A pot of rice, meat, and fried vegetables is flipped onto a platter so the rice lands on top. What is that dish called?","a":"Maqluba","o":["Maqluba","Mansaf","Musakhan","Mandi"],"f":"The name means upside down. Cauliflower, eggplant, and chicken are a common filling. Mansaf is lamb with fermented dried yogurt, musakhan is chicken with sumac and onions, and mandi is a spiced rice cooked in a buried pot."},{"q":"Which city holds the Palestinian Authority's main government offices?","a":"Ramallah","o":["Ramallah","Muscat","Bishkek","Kathmandu"],"f":"Ramallah is the administrative center. Jerusalem is claimed as a capital.","kind":"capital"},{"q":"Which of these flags belongs to Palestine?","a":"PSE","o":["PSE","SAU","IDN","IRQ"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Palestine.","kind":"flag"}],"hard":[{"q":"Tatreez, the cross-stitch of geometric patterns, was traditionally sewn on what?","a":"Village dresses","o":["Village dresses","Sails","Tents","Carpets only"],"f":"Each area had motifs. Women still stitch tatreez on clothing and panels as a living craft."},{"q":"Which hill town is known for hand-blown glass in blue and green?","a":"Hebron","o":["Hebron","Nablus","Jericho","Bethlehem"],"f":"Glassblowers melt recycled glass and shape it by hand. The craft is centuries old and is still sold in the old city."},{"q":"The old city of Hebron holds the tomb tradition links to which biblical figures?","a":"Abraham and his family","o":["Abraham and his family","David","Solomon","Moses"],"f":"The Ibrahimi Mosque, or Cave of the Patriarchs, is sacred to Muslims and Jews. It is a place of pilgrimage and of strict division."},{"q":"Which of these cities holds the Palestinian Authority's main government offices?","a":"Ramallah","o":["Ramallah","Nablus","Hebron","Jericho"],"f":"Ramallah is the administrative center. Jerusalem is claimed as a capital.","kind":"capital"},{"q":"Which flag is the flag of Palestine?","a":"PSE","o":["PSE","SDN","KWT","JOR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Palestine.","kind":"flag"}]}},{"id":"QAT","name":"Qatar","cont":"Asia","emoji":"🇶🇦","latlng":[25.5,51.25],"q":{"easy":[{"q":"Which museum of Islamic art, designed by I. M. Pei, stands on a harbor island?","a":"The Museum of Islamic Art","o":["The Museum of Islamic Art","The Louvre Abu Dhabi","The Guggenheim","The British Museum"],"f":"The building opened in 2008 on a purpose-built island in Doha Bay. Its collection spans many centuries."},{"q":"Which spiced rice with lamb is the everyday feast dish?","a":"Machboos","o":["Machboos","Kabsa is similar","Mandi","Harees"],"f":"Machboos cooks rice in meat broth with dried lime. It is the Gulf's shared comfort food."},{"q":"Which tidal inlet where dunes meet the sea is a famous southern landscape?","a":"Khor Al Adaid","o":["Khor Al Adaid","The Empty Quarter's far side","Liwa","The Dead Sea"],"f":"Khor Al Adaid, the Inland Sea, is a creek of seawater inside the dunes on the Saudi border."},{"q":"Which city is the capital of Qatar?","a":"Doha","o":["Doha","Belgrade","London","Tallinn"],"f":"Doha is the capital of Qatar.","kind":"capital"},{"q":"Which flag belongs to Qatar?","a":"QAT","o":["QAT","BOL","BEN","DJI"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Qatar.","kind":"flag"}],"medium":[{"q":"The old pearling trade on the peninsula collapsed in the 1930s mainly because of what?","a":"Japanese cultured pearls","o":["Japanese cultured pearls","A ban on diving","The opening of the Suez Canal","The invention of nylon"],"f":"Cultured pearls flooded the market and the price of natural pearls crashed. Families who had crewed the dhows later moved into oil, and then into gas. The Suez Canal had opened much earlier, in 1869."},{"q":"In 2022 the men's football World Cup was played here, the first World Cup hosted in which part of the world?","a":"The Arab world","o":["The Arab world","South America","East Asia","West Africa"],"f":"Matches were scheduled in winter because the summer heat is extreme. South America, East Asia, and Africa had all hosted the tournament in earlier years."},{"q":"A satellite news network that changed Arabic-language broadcasting was founded in Doha in 1996. What is it called?","a":"Al Jazeera","o":["Al Jazeera","Al Arabiya","BBC Arabic","France 24"],"f":"It quickly drew viewers across the Arab world. Al Arabiya, based in Dubai, was launched later, in 2003. BBC Arabic is much older as a radio service and is not based in Doha."},{"q":"What is the capital city of Qatar?","a":"Doha","o":["Doha","Jerusalem","Kabul","Singapore"],"f":"Doha is the capital of Qatar.","kind":"capital"},{"q":"Which of these flags belongs to Qatar?","a":"QAT","o":["QAT","MYS","PHL","OMN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Qatar.","kind":"flag"}],"hard":[{"q":"Pearl diving was the main livelihood before which mid-20th-century change?","a":"Oil exports and cultured pearls","o":["Oil exports and cultured pearls","Tourism only","Fishing bans","A gold rush"],"f":"Japanese cultured pearls and then oil ended the old diving economy. Families still keep the songs."},{"q":"Which UNESCO merchant town of the 1700s preserves a fort and a ruined souq?","a":"Al Zubarah","o":["Al Zubarah","Souq Waqif","Barzan towers","Al Wakrah fort"],"f":"Al Zubarah was a pearling and trading town in the 1700s and 1800s. Its ruins are protected."},{"q":"Falconry, practiced across the Gulf, trains birds to hunt which classic quarry?","a":"Houbara bustards","o":["Houbara bustards","Fish","Camels","Snakes"],"f":"Falcons are flown at houbara and other birds. The practice is a UNESCO heritage shared by several countries."},{"q":"Which of these cities is the capital of Qatar?","a":"Doha","o":["Doha","Al Wakrah","Al Khor","Lusail"],"f":"Doha is the capital of Qatar.","kind":"capital"},{"q":"Which flag is the flag of Qatar?","a":"QAT","o":["QAT","BHR","DNK","NRU"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Qatar.","kind":"flag"}]}},{"id":"ROU","name":"Romania","cont":"Europe","emoji":"🇷🇴","latlng":[46,25],"q":{"easy":[{"q":"Which wetland where a great river meets the Black Sea is a UNESCO reserve of birds?","a":"The Danube Delta","o":["The Danube Delta","The Camargue","The Wadden Sea","The Volga Delta"],"f":"The Danube splits into channels among reeds. Pelicans and fishermen's villages share the water."},{"q":"Which cabbage rolls stuffed with meat and rice are a holiday and everyday dish?","a":"Sarmale","o":["Sarmale","Dolma","Golabki","Holubtsi"],"f":"Sarmale are simmered with smoked meat and served with polenta, called mamaliga."},{"q":"Which high paved road crosses the Fagaras Mountains in dramatic switchbacks?","a":"The Transfagarasan","o":["The Transfagarasan","The Stelvio","The Gotthard","The Dalton"],"f":"The Transfagarasan was built in the 1970s. It climbs past glacial lakes between sheer slopes."},{"q":"Which city is the capital of Romania?","a":"Bucharest","o":["Bucharest","Muscat","Suva","Niamey"],"f":"Bucharest is the capital of Romania.","kind":"capital"},{"q":"Which flag belongs to Romania?","a":"ROU","o":["ROU","QAT","KOR","YEM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Romania.","kind":"flag"}],"medium":[{"q":"Which sculptor, born in Hobita, carved endlessly simplified birds and columns and worked mostly in Paris?","a":"Constantin Brancusi","o":["Constantin Brancusi","Auguste Rodin","Henry Moore","Alberto Giacometti"],"f":"The Endless Column and the Table of Silence stand in Targu Jiu, a public memorial to soldiers of the First World War. He had briefly been Rodin's assistant and then rejected that style."},{"q":"The painted monasteries of Bucovina, a UNESCO group, are famous because their frescoes cover what?","a":"The outside walls","o":["The outside walls","Only underground crypts","Stained-glass windows","Wooden ceilings alone"],"f":"Voronet blue and the ladders of souls at Sucevita were painted in the 15th and 16th centuries. The pictures taught Bible stories to people who could not read."},{"q":"Vlad III, ruler of Wallachia in the 15th century, inspired a later novel. What did Bram Stoker invent that Vlad was not?","a":"A vampire count living in a Transylvanian castle","o":["A vampire count living in a Transylvanian castle","A prince who fought the Ottomans","A ruler who impaled enemies","A member of the Draculesti family"],"f":"Vlad did impale captives and his father was called Dracul, so the nickname Dracula has a historical root. Bran Castle's link to him is mostly modern tourism."},{"q":"What is the capital city of Romania?","a":"Bucharest","o":["Bucharest","San Marino","Helsinki","Brussels"],"f":"Bucharest is the capital of Romania.","kind":"capital"},{"q":"Which of these flags belongs to Romania?","a":"ROU","o":["ROU","LVA","BEL","ISL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Romania.","kind":"flag"}],"hard":[{"q":"Which painted monasteries of Bucovina keep frescoes on the outside walls?","a":"Voronet, Sucevita, and Moldovita","o":["Voronet, Sucevita, and Moldovita","The Sistine Chapel","Rila","The Troodos churches"],"f":"The paint has survived centuries of weather. Voronet blue is especially famous."},{"q":"Which poet of the Romantic age, Mihai Eminescu, is honored with a national day on which date of his birth?","a":"15 January","o":["15 January","1 December","24 January","8 March"],"f":"Eminescu's poem Luceafarul is a national classic. He died in 1889."},{"q":"The Dacian fortresses of the Orastie Mountains resisted which empire before 106 CE?","a":"Rome","o":["Rome","The Ottomans","The Mongols","Austria"],"f":"Trajan's column in Rome shows the Dacian wars. Sarmizegetusa was the Dacian capital."},{"q":"Which of these cities is the capital of Romania?","a":"Bucharest","o":["Bucharest","Cluj-Napoca","Timișoara","Iași"],"f":"Bucharest is the capital of Romania.","kind":"capital"},{"q":"Which flag is the flag of Romania?","a":"ROU","o":["ROU","MDA","AND","TCD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Romania.","kind":"flag"}]}},{"id":"RUS","name":"Russia","cont":"Europe","emoji":"🇷🇺","latlng":[60,100],"q":{"easy":[{"q":"Which cathedral on Red Square has swirling colored domes?","a":"Saint Basil's Cathedral","o":["Saint Basil's Cathedral","The Hermitage","The Kremlin wall","Saint Sophia"],"f":"Ivan the Terrible ordered the cathedral after a victory in 1552. Each chapel has a different dome."},{"q":"Which beet soup with sour cream is a widely eaten bowl?","a":"Borscht","o":["Borscht","Gazpacho","Pho","Miso"],"f":"Borscht is cooked across Eastern Europe, with many family recipes. Beet gives the red color."},{"q":"Which novelist wrote War and Peace and Anna Karenina?","a":"Leo Tolstoy","o":["Leo Tolstoy","Dostoevsky","Chekhov","Turgenev"],"f":"Tolstoy's estate at Yasnaya Polyana is a museum. He died in 1910 after leaving home by train."},{"q":"Which city is the capital of Russia?","a":"Moscow","o":["Moscow","Dushanbe","Santiago","San José"],"f":"Moscow is the capital of Russia.","kind":"capital"},{"q":"Which flag belongs to Russia?","a":"RUS","o":["RUS","LBR","WSM","CAN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Russia.","kind":"flag"}],"medium":[{"q":"Which chemist, born in Tobolsk, published the periodic table in 1869 and left gaps for elements not yet found?","a":"Dmitri Mendeleev","o":["Dmitri Mendeleev","Antoine Lavoisier","Marie Curie","John Dalton"],"f":"He arranged elements by atomic weight and by repeating properties. Several of the gaps were filled in his lifetime, which persuaded other scientists he was right."},{"q":"Lake Baikal, in Siberia, is the world's deepest lake and holds about what share of Earth's unfrozen surface fresh water?","a":"About one fifth","o":["About one fifth","About one hundredth","About half","Nearly all of it"],"f":"It is also one of the oldest lakes, and most of its species, including the nerpa seal, live nowhere else. The lake is a UNESCO natural site."},{"q":"Yuri Gagarin, born in Klushino, became the first person to orbit Earth on 12 April of which year?","a":"1961","o":["1961","1957","1969","1975"],"f":"His flight, Vostok 1, lasted 108 minutes. 1957 was Sputnik, the first satellite, and 1969 was the first Moon landing."},{"q":"What is the capital city of Russia?","a":"Moscow","o":["Moscow","Brussels","Chișinău","Sarajevo"],"f":"Moscow is the capital of Russia.","kind":"capital"},{"q":"Which of these flags belongs to Russia?","a":"RUS","o":["RUS","EST","BIH","UKR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Russia.","kind":"flag"}],"hard":[{"q":"Which ballet company, founded in the 1700s, performs in a famous Moscow theater?","a":"The Bolshoi","o":["The Bolshoi","The Mariinsky only","The Royal Ballet","La Scala"],"f":"Bolshoi means big. The company shares the classical repertory with St. Petersburg's Mariinsky."},{"q":"The Trans-Siberian Railway, begun in the 1890s, links Moscow with which ocean's coast?","a":"The Pacific","o":["The Pacific","The Arctic only","The Atlantic","The Indian"],"f":"The line reaches Vladivostok. Building it tied the empire's far east to the capital by rail."},{"q":"Which wooden churches of Kizhi island were built without nails in the 1700s?","a":"The Kizhi churches","o":["The Kizhi churches","Stave churches of Norway","The Suzdal kremlin","The Novgorod kremlin"],"f":"The Transfiguration church has twenty-two domes. It stands on an island in Lake Onega."},{"q":"Which of these cities is the capital of Russia?","a":"Moscow","o":["Moscow","Saint Petersburg","Novosibirsk","Kazan"],"f":"Moscow is the capital of Russia.","kind":"capital"},{"q":"Which flag is the flag of Russia?","a":"RUS","o":["RUS","FRA","NLD","LUX"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Russia.","kind":"flag"}]}},{"id":"RWA","name":"Rwanda","cont":"Africa","emoji":"🇷🇼","latlng":[-2,30],"q":{"easy":[{"q":"Which great apes live in the volcanoes of the northwest?","a":"Mountain gorillas","o":["Mountain gorillas","Orangutans","Chimpanzees of the savanna only","Baboons"],"f":"Volcanoes National Park protects gorillas on the Virunga slopes. Permits fund the park."},{"q":"Which maize or cassava dough with beans or meat is a daily plate?","a":"Ugali and isombe","o":["Ugali and isombe","Sushi","Poutine","Fondue"],"f":"Isombe is cassava leaves. Ugali or boiled plantain fills the rest of the plate."},{"q":"Which traditional dance with high leaps and a drum line is performed at weddings?","a":"Intore","o":["Intore","The haka","Ballet","Kabuki"],"f":"Intore dancers leap and sing. The style comes from the royal court."},{"q":"Which city is the capital of Rwanda?","a":"Kigali","o":["Kigali","Tehran","Paris","Manila"],"f":"Kigali is the capital of Rwanda.","kind":"capital"},{"q":"Which flag belongs to Rwanda?","a":"RWA","o":["RWA","DOM","HND","SVN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Rwanda.","kind":"flag"}],"medium":[{"q":"Research on mountain gorillas in Volcanoes National Park was led for years by which American scientist?","a":"Dian Fossey","o":["Dian Fossey","Jane Goodall","Biruté Galdikas","Joy Adamson"],"f":"She founded the Karisoke center in 1967 and was killed in 1985. Goodall studied chimpanzees in Tanzania, Galdikas orangutans in Borneo, and Adamson lions in Kenya. These gorillas also live in Uganda and DR Congo."},{"q":"Imigongo panels, in black, white, and red, are built up on boards using what as the base?","a":"Cow dung","o":["Cow dung","Beeswax","Powdered glass","Papyrus pulp"],"f":"The dung is shaped into ridges and then painted. The craft is linked to the old court at Nyanza. It is wall art, not pottery."},{"q":"Intore dancers, once performers for the king, traditionally carry what?","a":"Spears and shields","o":["Spears and shields","Fishing nets","Prayer wheels","Polo mallets"],"f":"Sisal headdresses shake as they leap. The dance outlived the monarchy and is now a stage art as well as a heritage performance."},{"q":"What is the capital city of Rwanda?","a":"Kigali","o":["Kigali","Algiers","Niamey","Kampala"],"f":"Kigali is the capital of Rwanda.","kind":"capital"},{"q":"Which of these flags belongs to Rwanda?","a":"RWA","o":["RWA","DZA","ZMB","ZWE"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Rwanda.","kind":"flag"}],"hard":[{"q":"The royal court at Nyanza kept long-horned cattle called what?","a":"Inyambo","o":["Inyambo","Zebu only","Water buffalo","Bison"],"f":"Inyambo cattle have huge horns. Palace herders sang to them, a custom shown for visitors today."},{"q":"Which finely woven screens and baskets with black geometric lids are a national craft?","a":"Agaseke baskets","o":["Agaseke baskets","Persian carpets","Navajo rugs","Kente"],"f":"The agaseke is a lidded peace basket. The spiral pattern is said to show that families meet."},{"q":"King Ruganzu Ndori is a culture hero of which old kingdom?","a":"The Nyiginya kingdom","o":["The Nyiginya kingdom","The Zulu kingdom","Ashanti","Dahomey"],"f":"Royal traditions of the Nyiginya dynasty shaped the state that became Rwanda."},{"q":"Which of these cities is the capital of Rwanda?","a":"Kigali","o":["Kigali","Huye","Musanze","Rubavu"],"f":"Kigali is the capital of Rwanda.","kind":"capital"},{"q":"Which flag is the flag of Rwanda?","a":"RWA","o":["RWA","CHN","IRL","TLS"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Rwanda.","kind":"flag"}]}},{"id":"SAU","name":"Saudi Arabia","cont":"Asia","emoji":"🇸🇦","latlng":[25,45],"q":{"easy":[{"q":"Which slow-cooked rice and meat dish is the national plate?","a":"Kabsa","o":["Kabsa","Mandi","Harees","Saleeg"],"f":"Kabsa, or machboos, is spiced rice with chicken or lamb. Dried lime and tomato are typical."},{"q":"Which historic mud-brick district near Riyadh was the first home of the Saudi dynasty?","a":"Diriyah","o":["Diriyah","Jeddah","Mecca","Medina"],"f":"Diriyah's At-Turaif district was the capital of the first Saudi state in the 1700s. It is a UNESCO site."},{"q":"Which date-growing oasis in the east is one of the largest?","a":"Al-Ahsa","o":["Al-Ahsa","AlUla","Tabuk","Abha"],"f":"Al-Ahsa has vast palm groves and springs. UNESCO lists the oasis landscape."},{"q":"Which city is the capital of Saudi Arabia?","a":"Riyadh","o":["Riyadh","St. John's","Monrovia","Majuro"],"f":"Riyadh is the capital of Saudi Arabia.","kind":"capital"},{"q":"Which flag belongs to Saudi Arabia?","a":"SAU","o":["SAU","SYC","LVA","AGO"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Saudi Arabia.","kind":"flag"}],"medium":[{"q":"Hegra, also called Mada'in Salih, is a UNESCO site of rock-cut tombs made by the same people who carved Petra. Who were they?","a":"The Nabataeans","o":["The Nabataeans","The Phoenicians","The Hittites","The Sabaeans"],"f":"Hegra was their southern city. Petra, in Jordan, was the more famous one. The Sabaeans were a kingdom of ancient Yemen, and the Hittites ruled in Anatolia."},{"q":"Muslims face a cube-shaped shrine in Mecca when they pray, and the hajj ends its rites there. What is that shrine called?","a":"The Kaaba","o":["The Kaaba","The Dome of the Rock","Al-Aqsa","The Prophet's Mosque"],"f":"Pilgrims walk around it seven times. The Prophet's Mosque is in Medina. The Dome of the Rock and Al-Aqsa are in Jerusalem, not in Mecca."},{"q":"Commercial oil in the east was confirmed in 1938 when which well came in?","a":"Dammam No. 7","o":["Dammam No. 7","Spindletop","Drake's well","Baba Gurgur"],"f":"It was nicknamed Prosperity Well. Drake's well was drilled in Pennsylvania in 1859, Spindletop gushed in Texas in 1901, and Baba Gurgur is near Kirkuk in Iraq."},{"q":"What is the capital city of Saudi Arabia?","a":"Riyadh","o":["Riyadh","Malé","Damascus","Muscat"],"f":"Riyadh is the capital of Saudi Arabia.","kind":"capital"},{"q":"Which of these flags belongs to Saudi Arabia?","a":"SAU","o":["SAU","PAK","TKM","TJK"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Saudi Arabia.","kind":"flag"}],"hard":[{"q":"Mada'in Salih, or Hegra, is a Nabataean city of tombs related to which more famous city?","a":"Petra","o":["Petra","Palmyra","Baalbek","Jerash"],"f":"The Nabataeans carved facades at Hegra in the first centuries CE. It is the country's first UNESCO site."},{"q":"Which coffee, pale and spiced with cardamom, is served to guests before dates?","a":"Qahwa","o":["Qahwa","Turkish coffee","Espresso","Arabic tea only"],"f":"The dallah pot and small cups are a sign of hospitality. UNESCO lists Arabic coffee as a shared custom."},{"q":"The Hejaz Railway, built in the early 1900s, was meant to carry pilgrims to which city?","a":"Medina","o":["Medina","Riyadh","Jeddah","Dammam"],"f":"The Ottoman line ran from Damascus toward Medina. Sections and stations remain in the desert."},{"q":"Which of these cities is the capital of Saudi Arabia?","a":"Riyadh","o":["Riyadh","Jeddah","Mecca","Medina"],"f":"Riyadh is the capital of Saudi Arabia.","kind":"capital"},{"q":"Which flag is the flag of Saudi Arabia?","a":"SAU","o":["SAU","GRD","EGY","USA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Saudi Arabia.","kind":"flag"}]}},{"id":"SDN","name":"Sudan","cont":"Africa","emoji":"🇸🇩","latlng":[15,30],"q":{"easy":[{"q":"Which meeting of the White Nile and the Blue Nile happens in the capital region?","a":"The confluence at Khartoum","o":["The confluence at Khartoum","The Okavango","The Inner Niger Delta","The Sudd only"],"f":"The Blue Nile from Ethiopia and the White Nile from the lakes meet and flow north as the Nile."},{"q":"Which stew of dried meat, dried onions, and oil is a travel food of the desert edge?","a":"Shaya or mullah","o":["Shaya or mullah","Sushi","Poutine","Ceviche"],"f":"Mullah is a simple stew. Dried meat, sharmout, keeps in the heat."},{"q":"Which ancient royal cemeteries of steep small pyramids stand at Meroe?","a":"The pyramids of Meroe","o":["The pyramids of Meroe","The pyramids of Giza","The Louvre","Teotihuacan"],"f":"Meroe was a capital of the Kingdom of Kush. Its pyramids are steeper and smaller than Egypt's."},{"q":"Which city is the capital of Sudan?","a":"Khartoum","o":["Khartoum","Havana","Washington, D.C.","Luxembourg City"],"f":"Khartoum is the capital of Sudan.","kind":"capital"},{"q":"Which flag belongs to Sudan?","a":"SDN","o":["SDN","GBR","BGR","PHL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Sudan.","kind":"flag"}],"medium":[{"q":"The steep pyramids at Meroë outnumber Egypt's. They belong to rulers of which kingdom?","a":"Kush","o":["Kush","Aksum","Mali","Great Zimbabwe"],"f":"Kushite kings ruled from Napata and later Meroë. In the 8th century BCE they conquered Egypt as its 25th dynasty. Their pyramids are smaller and steeper than Giza's."},{"q":"Piye, a Kushite king, conquered Egypt and began which dynasty of pharaohs?","a":"The 25th dynasty","o":["The 25th dynasty","The 4th dynasty","The 18th dynasty","The 1st dynasty"],"f":"Taharqo, a later king of the same line, built widely in Egypt and in Nubia. The 4th dynasty raised the Great Pyramid. The 18th included Hatshepsut and Tutankhamun."},{"q":"Two branches of the Nile meet at Khartoum. Which pair?","a":"The White Nile and the Blue Nile","o":["The White Nile and the Blue Nile","The Niger and the Benue","The Blue Nile and the Zambezi","The Atbara and the Congo"],"f":"The Blue Nile, from Lake Tana in Ethiopia, brings most of the flood. The White Nile comes from the Great Lakes and flows more steadily. The Atbara joins farther north."},{"q":"What is the capital city of Sudan?","a":"Khartoum","o":["Khartoum","Gitega","Ouagadougou","Pretoria"],"f":"Khartoum is the capital of Sudan.","kind":"capital"},{"q":"Which of these flags belongs to Sudan?","a":"SDN","o":["SDN","DZA","GMB","CAF"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Sudan.","kind":"flag"}],"hard":[{"q":"Kushite kings of the 25th dynasty once ruled which neighbor as pharaohs?","a":"Egypt","o":["Egypt","Rome","Persia","Axum only later"],"f":"Around 700 BCE Kushite pharaohs governed Egypt. They left statues at Napata and Meroe."},{"q":"Which Nubian language and old Christian kingdoms lasted at Faras and Dongola?","a":"Makuria and Alwa","o":["Makuria and Alwa","The Vikings","The Inca","Songhai"],"f":"Medieval Nubian kingdoms were Christian for centuries, with cathedrals and murals, before a later turn toward Islam."},{"q":"The whorled minaret of which Sufi capital is a symbol of the 19th-century Mahdist movement?","a":"Omdurman","o":["Omdurman","Khartoum","Port Sudan","Kassala"],"f":"The Mahdi's tomb and the Khalifa's house stand in Omdurman, across the river from Khartoum."},{"q":"Which of these cities is the capital of Sudan?","a":"Khartoum","o":["Khartoum","Omdurman","Port Sudan","Nyala"],"f":"Khartoum is the capital of Sudan.","kind":"capital"},{"q":"Which flag is the flag of Sudan?","a":"SDN","o":["SDN","PSE","JOR","KWT"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Sudan.","kind":"flag"}]}},{"id":"SEN","name":"Senegal","cont":"Africa","emoji":"🇸🇳","latlng":[14,-14],"q":{"easy":[{"q":"Which island fort off Dakar remembers the Atlantic slave trade?","a":"Goree Island","o":["Goree Island","Elmina","Cape Coast","Robben Island"],"f":"The House of Slaves on Goree is a memorial. Historians debate how many people passed through this exact door, but the island was a real slave port."},{"q":"Which grilled fish with onion sauce, stuffed and spicy, is a national dish?","a":"Thieboudienne is taken","o":["Thieboudienne is taken","Yassa poulet","Sushi","Poutine"],"f":"Yassa is chicken or fish marinated in lemon and onions, then simmered. It is served with rice."},{"q":"Which pink lake north of Dakar gets its color from salt and algae?","a":"Lake Retba","o":["Lake Retba","Lake Hillier","The Dead Sea","Lake Natron"],"f":"Lake Retba, or Lac Rose, is shallow and very salty. Salt workers still rake the crust."},{"q":"Which city is the capital of Senegal?","a":"Dakar","o":["Dakar","Moscow","Mexico City","Pyongyang"],"f":"Dakar is the capital of Senegal.","kind":"capital"},{"q":"Which flag belongs to Senegal?","a":"SEN","o":["SEN","NRU","LBN","USA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Senegal.","kind":"flag"}],"medium":[{"q":"Which poet, born in Joal in 1906, was the first president and a founder of Négritude?","a":"Léopold Sédar Senghor","o":["Léopold Sédar Senghor","Aimé Césaire","Léon-Gontran Damas","Birago Diop"],"f":"He led the country from 1960 to 1980 and then stepped down. Césaire was Martinican and Damas was from French Guiana; they were his partners in the movement. Birago Diop was a Senegalese poet of other work."},{"q":"Gorée, facing Dakar, is a UNESCO memorial of the slave trade. The honest way to treat the House of Slaves is as what?","a":"A memorial, not a proven tally of captives","o":["A memorial, not a proven tally of captives","The only port that shipped captives","A Roman prison","A Dutch shipyard"],"f":"The island was one of many places in the trade. Historians dispute how many people passed through that house. The lesson is the trade, not a single number on a wall."},{"q":"Ceebu jën, a fish-and-rice dish of Saint-Louis inscribed by UNESCO in 2021, is often called what in French?","a":"Thiéboudienne","o":["Thiéboudienne","Yassa","Mafé","Pastels"],"f":"The name means rice with fish. The fish is browned, then the rice and vegetables cook in the same pot. Yassa is onion and lemon. Mafé is a peanut sauce."},{"q":"What is the capital city of Senegal?","a":"Dakar","o":["Dakar","Lusaka","Accra","Nouakchott"],"f":"Dakar is the capital of Senegal.","kind":"capital"},{"q":"Which of these flags belongs to Senegal?","a":"SEN","o":["SEN","ZAF","LBY","MAR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Senegal.","kind":"flag"}],"hard":[{"q":"Saint-Louis, a UNESCO city of colonial balconies, stands at the mouth of which river?","a":"The river on the northern border","o":["The river on the northern border","The Congo","The Nile","The Volta"],"f":"The island city was the capital of French West Africa in the 1800s before Dakar took that role."},{"q":"The Mouride Sufi order has its great mosque in which holy city?","a":"Touba","o":["Touba","Timbuktu","Kairouan","Fez"],"f":"Amadou Bamba founded the Mourides. The Grand Mosque of Touba is the heart of the pilgrimage called the Magal."},{"q":"Sabar drumming, with a talking lead drum, belongs especially to which community of the coast?","a":"The Wolof","o":["The Wolof","The Tuareg","The San","The Himba"],"f":"Sabar troupes play at wrestling matches and street parties. Dancers answer the drum's phrases."},{"q":"Which of these cities is the capital of Senegal?","a":"Dakar","o":["Dakar","Saint-Louis","Thiès","Touba"],"f":"Dakar is the capital of Senegal.","kind":"capital"},{"q":"Which flag is the flag of Senegal?","a":"SEN","o":["SEN","MLI","GNB","GIN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Senegal.","kind":"flag"}]}},{"id":"SGP","name":"Singapore","cont":"Asia","emoji":"🇸🇬","latlng":[1.36666666,103.8],"q":{"easy":[{"q":"Which chili-tomato crab is a famous restaurant dish?","a":"Chili crab","o":["Chili crab","Black pepper crab only","Soft-shell crab","King crab"],"f":"Chili crab was popularized in the 1950s. It is eaten with your hands and fried mantou buns."},{"q":"Which three-tower hotel with a boat-shaped roof deck defines the downtown bay?","a":"Marina Bay Sands","o":["Marina Bay Sands","The Raffles","The Fullerton","Gardens by the Bay"],"f":"Marina Bay Sands opened in 2010. The sky park joins the towers high above the bay."},{"q":"Which Peranakan noodle soup with coconut broth is a local staple?","a":"Laksa","o":["Laksa","Pho","Ramen","Mee rebus only"],"f":"Katong laksa is a coconut and spice soup with rice noodles and prawns. Hawker centers serve many versions."},{"q":"Which city is the capital of Singapore?","a":"Singapore","o":["Singapore","Nuku'alofa","Lomé","Amsterdam"],"f":"Singapore is the capital of Singapore.","kind":"capital"},{"q":"Which flag belongs to Singapore?","a":"SGP","o":["SGP","BLZ","MOZ","TUV"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Singapore.","kind":"flag"}],"medium":[{"q":"Who was prime minister from 1959 to 1990 and is remembered as the founding leader of the modern city-state?","a":"Lee Kuan Yew","o":["Lee Kuan Yew","Tunku Abdul Rahman","Ferdinand Marcos","Suharto"],"f":"He was born in Singapore in 1923 and died in 2015. Tunku Abdul Rahman led Malaya to independence. Marcos and Suharto led the Philippines and Indonesia."},{"q":"Open-air food centers, where stalls and shared tables serve many cuisines, were inscribed by UNESCO in 2020. What is that culture called?","a":"Hawker culture","o":["Hawker culture","Izakaya culture","Cha chaan teng culture","Dim sum culture"],"f":"From the 1970s, vendors were moved off the streets into licensed centers. One center can serve Chinese, Malay, and Indian dishes side by side. An izakaya is a Japanese bar, and a cha chaan teng is a Hong Kong cafe."},{"q":"The national flower is an orchid hybrid first raised in a local garden in 1893. What is its name?","a":"Vanda Miss Joaquim","o":["Vanda Miss Joaquim","Rafflesia arnoldii","The moth orchid","Sakura"],"f":"Agnes Joaquim, an Armenian resident, is credited with the cross of Vanda hookeriana and Vanda teres. It does not grow as a wild species. Rafflesia is a giant parasite of the rainforest, not a garden orchid."},{"q":"What is the capital city of Singapore?","a":"Singapore","o":["Singapore","Naypyidaw","Abu Dhabi","Sri Jayawardenepura Kotte"],"f":"Singapore is the capital of Singapore.","kind":"capital"},{"q":"Which of these flags belongs to Singapore?","a":"SGP","o":["SGP","LBN","GEO","AFG"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Singapore.","kind":"flag"}],"hard":[{"q":"The garden city plan from the 1960s lined roads with which imported rain trees and later local species?","a":"Street trees and parks","o":["Street trees and parks","Only orchids","Mangroves only","Desert palms"],"f":"Tree planting was policy. The aim was shade in a dense equatorial city."},{"q":"Which public-housing program, started in 1960, came to house most residents in apartment blocks?","a":"The housing board flats","o":["The housing board flats","Private bungalows","Houseboats","Kampong houses only"],"f":"The board replaced many wooden villages with high blocks. A large majority of residents now live in those flats."},{"q":"Shophouses of the old quarters mix Chinese, Malay, and European details. They are called Peranakan when linked to which community?","a":"The Straits Chinese","o":["The Straits Chinese","The Europeans only","The Bugis only","The Tamils only"],"f":"Peranakan, or Baba-Nyonya, culture grew from Chinese settlers who adopted Malay language and food."},{"q":"Which of these cities is the capital of Singapore?","a":"Singapore","o":["Singapore","Johor Bahru","Batam","Kuala Lumpur"],"f":"Singapore is the capital of Singapore.","kind":"capital"},{"q":"Which flag is the flag of Singapore?","a":"SGP","o":["SGP","MCO","IDN","POL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Singapore.","kind":"flag"}]}},{"id":"SLB","name":"Solomon Islands","cont":"Oceania","emoji":"🇸🇧","latlng":[-8,159],"q":{"easy":[{"q":"Which artificial islands of coral rock in a lagoon are a famous sight?","a":"The artificial islands of Langa Langa","o":["The artificial islands of Langa Langa","Nan Madol","The Uros","Venice"],"f":"Families built islands in the Langalanga Lagoon to live beyond mainland raids. Shell money is still made there."},{"q":"Which pudding of cassava or taro in coconut milk is festival food?","a":"Lap-lap's cousin, or poi-like pudding","o":["Lap-lap's cousin, or poi-like pudding","Sago","Rice","Breadfruit only"],"f":"Coconut cream is grated and squeezed over root puddings baked in a stone oven."},{"q":"Which WWII battle on an island of the country turned the Pacific war?","a":"Guadalcanal","o":["Guadalcanal","Midway","Iwo Jima","Peleliu"],"f":"Marines landed in 1942. Henderson Field and the waters of Ironbottom Sound were the prize."},{"q":"Which city is the capital of Solomon Islands?","a":"Honiara","o":["Honiara","Beijing","Pyongyang","Minsk"],"f":"Honiara is the capital of Solomon Islands.","kind":"capital"},{"q":"Which flag belongs to Solomon Islands?","a":"SLB","o":["SLB","PRY","LCA","LBY"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Solomon Islands.","kind":"flag"}],"medium":[{"q":"The long battle for Guadalcanal, a turning point in the Pacific War, was fought in which years?","a":"1942 to 1943","o":["1942 to 1943","1914 to 1915","1950 to 1951","1968 to 1969"],"f":"Both sides fought for Henderson Field and the surrounding seas. The campaign stopped Japan's advance farther south."},{"q":"In 1568 a Spanish explorer named the islands after King Solomon because he hoped to find what?","a":"Gold","o":["Gold","Silk","Diamonds","Amber"],"f":"Alvaro de Mendana imagined mines as rich as Solomon's. The gold was mostly a legend, and the biblical name remained."},{"q":"A nguzu nguzu, lashed to the prow of a western Solomon Islands war canoe, was meant to guard against what?","a":"Harmful spirits","o":["Harmful spirits","Icebergs","Sandstorms","Volcanic ash"],"f":"The figure often has a large head and hands held under the chin. It faced forward as the canoe traveled."},{"q":"What is the capital city of Solomon Islands?","a":"Honiara","o":["Honiara","Wellington","Canberra","Suva"],"f":"Honiara is the capital of Solomon Islands.","kind":"capital"},{"q":"Which of these flags belongs to Solomon Islands?","a":"SLB","o":["SLB","VUT","PNG","FJI"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Solomon Islands.","kind":"flag"}],"hard":[{"q":"Shell money of the Langalanga people is made from which shell?","a":"A red-lipped rock shell and white shells","o":["A red-lipped rock shell and white shells","Cowries only","Pearl oyster only","Turtle shell"],"f":"Disks are ground, drilled, and strung. Strings are still used in bride price and compensation."},{"q":"Which megapode bird incubates eggs in warm sand or volcanic soil?","a":"The Melanesian scrubfowl","o":["The Melanesian scrubfowl","The kiwi","The cassowary","The emu"],"f":"The scrubfowl buries eggs and lets heat hatch them. People have long gathered the eggs."},{"q":"The national language alongside English is a creole called what?","a":"Pijin","o":["Pijin","Tok Pisin","Bislama","Hiri Motu"],"f":"Solomon Islands Pijin grew on plantations. It is the language of markets and towns."},{"q":"Which of these cities is the capital of Solomon Islands?","a":"Honiara","o":["Honiara","Gizo","Auki","Munda"],"f":"Honiara is the capital of Solomon Islands.","kind":"capital"},{"q":"Which flag is the flag of Solomon Islands?","a":"SLB","o":["SLB","SWZ","MDV","LBN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Solomon Islands.","kind":"flag"}]}},{"id":"SLE","name":"Sierra Leone","cont":"Africa","emoji":"🇸🇱","latlng":[8.5,-11.5],"q":{"easy":[{"q":"Which huge natural harbor made the capital a landing place for freed captives in the 1790s?","a":"The wide estuary","o":["The wide estuary","Sydney Harbour","Rio's Guanabara","The Golden Horn"],"f":"Freetown was founded in 1792 by Black Loyalists and other freed people. The harbor is one of the world's largest."},{"q":"Which leafy stew with palm oil, eaten with rice, is a national dish?","a":"Cassava leaf plasas","o":["Cassava leaf plasas","Sushi","Poutine","Borscht"],"f":"Plasas is a sauce of greens. Potato leaf and cassava leaf versions are both loved."},{"q":"Which cotton cloth, dyed in stitched patterns of blue, is a famous local textile?","a":"Country cloth and gara","o":["Country cloth and gara","Kente","Batik of Java","Tartan"],"f":"Gara is indigo tie-dye. Country cloth is strip-woven cotton from upland looms."},{"q":"Which city is the capital of Sierra Leone?","a":"Freetown","o":["Freetown","Suva","Vienna","Lisbon"],"f":"Freetown is the capital of Sierra Leone.","kind":"capital"},{"q":"Which flag belongs to Sierra Leone?","a":"SLE","o":["SLE","HUN","GBR","BGR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Sierra Leone.","kind":"flag"}],"medium":[{"q":"Portuguese sailors called the coastal mountains Serra Lyoa. In English that means what?","a":"Lion Mountains","o":["Lion Mountains","Gold Coast","White Cape","Green Point"],"f":"The country's English name is a translation of the Portuguese one. The ridges behind the harbor suggested a lion. The Gold Coast was a name for a different shore, now Ghana."},{"q":"Freetown was founded in the late 18th century as a settlement for whom?","a":"Freed slaves","o":["Freed slaves","Portuguese convicts","British tea planters","French legionnaires"],"f":"Black Loyalists from the American Revolution, and later people taken off slave ships, were settled here. The British colony grew around that town. It was not a convict colony."},{"q":"Bunce Island, in the estuary above Freetown, was a British fort used for what?","a":"Holding captives for the slave trade","o":["Holding captives for the slave trade","Mining diamonds","Building locomotives","Curing tea"],"f":"Traders sent people especially toward the rice coasts of South Carolina and Georgia. The ruins are a memorial. Diamond digging came later, and inland."},{"q":"What is the capital city of Sierra Leone?","a":"Freetown","o":["Freetown","Bissau","Addis Ababa","Cairo"],"f":"Freetown is the capital of Sierra Leone.","kind":"capital"},{"q":"Which of these flags belongs to Sierra Leone?","a":"SLE","o":["SLE","BDI","DZA","EGY"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Sierra Leone.","kind":"flag"}],"hard":[{"q":"The Bunce Island fort in the estuary shipped captives especially to which region of the Americas?","a":"The rice coasts of Georgia and Carolina","o":["The rice coasts of Georgia and Carolina","Only to Brazil","Only to Peru","Only to Canada"],"f":"Traders on Bunce Island supplied rice planters who wanted people who knew rice farming."},{"q":"Fourah Bay College, founded in 1827 in Freetown, is often called the oldest western-style university in which region?","a":"West Africa","o":["West Africa","Scandinavia","The Andes","Polynesia"],"f":"Missionaries founded Fourah Bay. Students came from across British West Africa."},{"q":"The Temne and Mende are the two largest peoples. Secret societies that train young women include which one?","a":"The Sande, or Bondo","o":["The Sande, or Bondo","The Freemasons","The Olympians","The Shogunate"],"f":"Sande schools initiate girls and are known for the black sowei mask."},{"q":"Which of these cities is the capital of Sierra Leone?","a":"Freetown","o":["Freetown","Bo","Kenema","Makeni"],"f":"Freetown is the capital of Sierra Leone.","kind":"capital"},{"q":"Which flag is the flag of Sierra Leone?","a":"SLE","o":["SLE","KIR","NGA","IRN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Sierra Leone.","kind":"flag"}]}},{"id":"SLV","name":"El Salvador","cont":"North America","emoji":"🇸🇻","latlng":[13.83333333,-88.91666666],"q":{"easy":[{"q":"Which volcano overlooking the capital has a famous crater?","a":"San Salvador volcano","o":["San Salvador volcano","Izalco","Santa Ana","San Miguel"],"f":"The Quezaltepec, or San Salvador, volcano stands west of the city. Izalco nearby was once called the lighthouse of the Pacific."},{"q":"Which thick corn cakes filled with beans, cheese, or pork are the national food?","a":"Pupusas","o":["Pupusas","Arepas","Gorditas","Tortillas"],"f":"Pupusas are griddled and served with curtido, a pickled cabbage, and tomato sauce."},{"q":"Which Pacific coast surf towns, such as El Tunco, are a modern draw?","a":"The Balsamo coast","o":["The Balsamo coast","The Caribbean only","Lake Coatepeque","The gulf of Fonseca only"],"f":"Black-sand beaches face a strong Pacific break. Surfing became a national weekend culture."},{"q":"Which city is the capital of El Salvador?","a":"San Salvador","o":["San Salvador","Amman","Oslo","Vatican City"],"f":"San Salvador is the capital of El Salvador.","kind":"capital"},{"q":"Which flag belongs to El Salvador?","a":"SLV","o":["SLV","BWA","ESP","CHN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of El Salvador.","kind":"flag"}],"medium":[{"q":"Which archbishop, born in Ciudad Barrios, was shot while saying Mass in 1980 and canonized in 2018?","a":"Oscar Romero","o":["Oscar Romero","Helder Camara","Desmond Tutu","Thomas Merton"],"f":"He had denounced the army's killings during the civil war. Pope Francis declared him a saint in 2018."},{"q":"Joya de Ceren, called the Pompeii of the Americas, is a Maya farming village preserved by what around the year 600?","a":"Volcanic ash","o":["Volcanic ash","A river flood","Desert sand","Glacial ice"],"f":"People fled, so almost no bodies were found, but meals, gardens, and sleeping mats remained. It is a UNESCO site."},{"q":"The national dish is a thick stuffed corn cake cooked on a griddle and served with curtido. What is it called?","a":"A pupusa","o":["A pupusa","A tamale","An arepa","A gordita"],"f":"Curtido is a lightly fermented cabbage slaw. A national pupusa festival celebrates the many fillings, from beans and cheese to squash."},{"q":"What is the capital city of El Salvador?","a":"San Salvador","o":["San Salvador","Port-au-Prince","Panama City","Mexico City"],"f":"San Salvador is the capital of El Salvador.","kind":"capital"},{"q":"Which of these flags belongs to El Salvador?","a":"SLV","o":["SLV","MEX","ATG","KNA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of El Salvador.","kind":"flag"}],"hard":[{"q":"Which poet, born in 1935, wrote Taberna y otros lugares and was killed in 1975?","a":"Roque Dalton","o":["Roque Dalton","Miguel Angel Asturias","Ruben Dario","Ernesto Cardenal"],"f":"Dalton mixed love poems with political verse. He was killed during a split in a guerrilla group."},{"q":"Joya de Ceren, a UNESCO site, is a village buried by a volcano in about 600 CE and compared to what?","a":"Pompeii","o":["Pompeii","Herculaneum only","Akrotiri","The Minoan eruption"],"f":"Ash preserved houses, gardens, and even food. It is a snapshot of ordinary Maya life."},{"q":"Izalco volcano, born in the 1700s, was so regularly active that sailors used it as what?","a":"A lighthouse","o":["A lighthouse","A calendar","A mine","A port"],"f":"Eruptions were frequent enough to be seen at sea. The activity later quieted."},{"q":"Which of these cities is the capital of El Salvador?","a":"San Salvador","o":["San Salvador","Santa Ana","San Miguel","Santa Tecla"],"f":"San Salvador is the capital of El Salvador.","kind":"capital"},{"q":"Which flag is the flag of El Salvador?","a":"SLV","o":["SLV","HND","NIC","GTM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of El Salvador.","kind":"flag"}]}},{"id":"SMR","name":"San Marino","cont":"Europe","emoji":"🇸🇲","latlng":[43.76666666,12.41666666],"q":{"easy":[{"q":"Which mountain of three peaks is the historic heart of the republic?","a":"Mount Titano","o":["Mount Titano","The Matterhorn","Vesuvius","Olympus"],"f":"The old town and the towers sit on Titano's crest above the Italian countryside."},{"q":"Which layered wafer cake is named for those peaks?","a":"Torta Tre Monti","o":["Torta Tre Monti","Sachertorte","Tiramisù","Baklava"],"f":"The cake stacks thin hazelnut layers with chocolate or cream. It is the classic pastry shop sweet."},{"q":"Which crossbow contest between districts is still a public festival?","a":"The Palio of the crossbow","o":["The Palio of the crossbow","A joust","A regatta","A bull run"],"f":"Crossbow companies parade in medieval dress. The sport is a point of local pride."},{"q":"Which city is the capital of San Marino?","a":"San Marino","o":["San Marino","Brasília","Majuro","Manama"],"f":"San Marino is the capital of San Marino.","kind":"capital"},{"q":"Which flag belongs to San Marino?","a":"SMR","o":["SMR","KWT","LCA","URY"],"f":"Compare the colors and symbols. One of these four flags is the national flag of San Marino.","kind":"flag"}],"medium":[{"q":"Tradition says a Christian stonemason founded a community on Mount Titano in the year 301. What was his name?","a":"Marinus","o":["Marinus","Benedict","Francis","Dominic"],"f":"The story says he fled persecution in the Roman Empire and built a chapel on the mountain. San Marino means Saint Marinus, and the state calls itself the oldest republic on that basis."},{"q":"The historic center and Mount Titano are a UNESCO site crowned by three fortresses. They are usually called what?","a":"The Three Towers","o":["The Three Towers","The Three Bridges","The Three Domes","The Three Gates"],"f":"Guaita, Cesta, and Montale stand on separate crags. Their silhouettes are the image on coins and on the flag."},{"q":"San Marino is not an EU member. Under an agreement with Italy, which money do its shops use?","a":"The euro","o":["The euro","The Swiss franc","The old lira","The pound sterling"],"f":"It had used the Italian lira and later signed a deal to mint its own euro coins. Those coins are legal tender across the eurozone."},{"q":"What is the capital city of San Marino?","a":"San Marino","o":["San Marino","Madrid","Tirana","Athens"],"f":"San Marino is the capital of San Marino.","kind":"capital"},{"q":"Which of these flags belongs to San Marino?","a":"SMR","o":["SMR","MKD","VAT","FIN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of San Marino.","kind":"flag"}],"hard":[{"q":"According to tradition, a Christian stonecutter founded a community here in which century?","a":"The fourth century","o":["The fourth century","The tenth","The fifteenth","The nineteenth"],"f":"The story of Marinus says he fled persecution and built a chapel on the mountain. The date is traditional."},{"q":"Which two captains regent, elected every six months, serve as joint heads of state?","a":"The Captains Regent","o":["The Captains Regent","The co-princes of Andorra","The consuls of Rome","The doges"],"f":"Two captains, from opposing parties, hold the office together. The ceremony is held in the government palace."},{"q":"The republic survived the unification of Italy in the 1800s partly because of what protection?","a":"A long tradition of neutrality and treaties","o":["A long tradition of neutrality and treaties","A large navy","High mountains only","Membership in Austria"],"f":"Papal and later Italian recognition left the tiny state outside the new kingdom."},{"q":"Which of these cities is the capital of San Marino?","a":"San Marino","o":["San Marino","Serravalle","Borgo Maggiore","Rome"],"f":"San Marino is the capital of San Marino.","kind":"capital"},{"q":"Which flag is the flag of San Marino?","a":"SMR","o":["SMR","SLE","UGA","TTO"],"f":"Compare the colors and symbols. One of these four flags is the national flag of San Marino.","kind":"flag"}]}},{"id":"SOM","name":"Somalia","cont":"Africa","emoji":"🇸🇴","latlng":[10,49],"q":{"easy":[{"q":"Which ancient cave paintings of cattle and people, from a wetter age, cover a shelter in the north?","a":"Laas Geel","o":["Laas Geel","Lascaux","Altamira","Tassili"],"f":"Laas Geel, near Hargeisa, holds some of Africa's best-preserved rock paintings, several thousand years old."},{"q":"Which spiced rice with meat, eaten with a banana, is a feast dish?","a":"Bariis iskukaris","o":["Bariis iskukaris","Sushi","Paella","Poutine"],"f":"Somali rice is cooked with cumin, cardamom, and goat or camel. A banana on the side is traditional."},{"q":"Which tall dune and old port on the Gulf of Aden was a frankincense harbor?","a":"Berbera","o":["Berbera","Mogadishu only","Zanzibar","Aden"],"f":"Berbera looks across to Yemen. It was a stop for incense, livestock, and later colonial troops."},{"q":"Which city is the capital of Somalia?","a":"Mogadishu","o":["Mogadishu","Zagreb","Kabul","Paris"],"f":"Mogadishu is the capital of Somalia.","kind":"capital"},{"q":"Which flag belongs to Somalia?","a":"SOM","o":["SOM","BLR","IDN","SRB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Somalia.","kind":"flag"}],"medium":[{"q":"The rock shelters of Laas Geel hold vivid paintings of cattle and people. They are about how old?","a":"Several thousand years","o":["Several thousand years","A few decades","Only the 15th century","The age of dinosaurs"],"f":"Archaeologists documented them in 2002, though herders already knew the shelters. Dates are still argued, so a range of several thousand years is the careful answer. They show herders, not dinosaurs."},{"q":"A formal oral poem, the gabay, is judged especially on which craft?","a":"Alliteration and meter","o":["Alliteration and meter","End-rhyme on every line","Written calligraphy","A drum solo"],"f":"A gabay can run to a hundred lines that share one opening sound. Poets were political voices as well as artists. The poem is memorized, not calligraphed."},{"q":"In 1972 the Somali language was standardized in which script, after a literacy campaign?","a":"Latin letters","o":["Latin letters","Arabic letters","Osmanya letters","Ge'ez letters"],"f":"Osmanya, invented in the 1920s by Osman Yusuf Kenadid, was a real rival, and Arabic script had been used for centuries. Ge'ez is the script of Amharic. The 1972 choice was Latin."},{"q":"What is the capital city of Somalia?","a":"Mogadishu","o":["Mogadishu","Harare","Brazzaville","Gaborone"],"f":"Mogadishu is the capital of Somalia.","kind":"capital"},{"q":"Which of these flags belongs to Somalia?","a":"SOM","o":["SOM","STP","TGO","MRT"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Somalia.","kind":"flag"}],"hard":[{"q":"Which oral poetry, with alliteration and meter, is a high art among Somali speakers?","a":"Gabay","o":["Gabay","Haiku","The sonnet","The ghazal only of Persia"],"f":"A gabay is a long poem. Poets were political voices, and lines were memorized rather than written."},{"q":"The Shabelle and Juba rivers, rare permanent water, rise in which neighboring highlands?","a":"The Ethiopian highlands","o":["The Ethiopian highlands","The Atlas","The Drakensberg","The Ruwenzori only"],"f":"Most of Somalia is dry. The two rivers allow farming in the south before they reach the Indian Ocean."},{"q":"Frankincense from the northern trees was traded to which ancient world?","a":"Egypt and Rome","o":["Egypt and Rome","The Inca","The Maya","The Maori"],"f":"Boswellia trees of the Somali coast supplied incense for temples around the Mediterranean."},{"q":"Which of these cities is the capital of Somalia?","a":"Mogadishu","o":["Mogadishu","Kismayo","Baidoa","Marka"],"f":"Mogadishu is the capital of Somalia.","kind":"capital"},{"q":"Which flag is the flag of Somalia?","a":"SOM","o":["SOM","YEM","SLV","GHA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Somalia.","kind":"flag"}]}},{"id":"SRB","name":"Serbia","cont":"Europe","emoji":"🇷🇸","latlng":[44,21],"q":{"easy":[{"q":"Which fortress above the meeting of the Sava and the Danube is the capital's park and citadel?","a":"Kalemegdan","o":["Kalemegdan","Petrovaradin","Golubac","Maglic"],"f":"Kalemegdan's layers run from Roman Singidunum to Ottoman and Austrian walls."},{"q":"Which grilled minced sausages in flatbread are the default street meal?","a":"Cevapi","o":["Cevapi","Pljeskavica only","Burgers","Gyros"],"f":"Cevapi come with onion and kajmak, a dairy spread. The same word is used across the region."},{"q":"Which trumpet festival in a small town each August is a national gathering?","a":"The Guca festival","o":["The Guca festival","EXIT","Coachella","Roskilde"],"f":"Brass bands compete at Guca. The sound of trumpets fills the streets for days."},{"q":"Which city is the capital of Serbia?","a":"Belgrade","o":["Belgrade","Yaoundé","Kabul","Kingston"],"f":"Belgrade is the capital of Serbia.","kind":"capital"},{"q":"Which flag belongs to Serbia?","a":"SRB","o":["SRB","BDI","ECU","VUT"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Serbia.","kind":"flag"}],"medium":[{"q":"Which physicist and inventor, born in Idvor in 1854, improved long-distance telephone lines and taught at Columbia University?","a":"Mihajlo Pupin","o":["Mihajlo Pupin","Nikola Tesla","Albert Einstein","Guglielmo Marconi"],"f":"The loading coil, or Pupin coil, let telephone signals travel farther. Tesla was a Serb by heritage too, but he was born in today's Croatia, not in Idvor."},{"q":"Which tennis player, born in Belgrade in 1987, won Wimbledon for the first time in 2011?","a":"Novak Djokovic","o":["Novak Djokovic","Rafael Nadal","Roger Federer","Stan Wawrinka"],"f":"He grew up in Belgrade in the 1990s and first practiced in an emptied swimming pool. Nadal is Spanish, Federer is Swiss, and Wawrinka is Swiss."},{"q":"A slava is a family's annual feast for the saint its ancestors chose. UNESCO lists the custom as heritage of Serbia. The celebration is centered on what?","a":"A special bread and a candle","o":["A special bread and a candle","A public horse race","A midnight swim","A masked parade"],"f":"A priest or the head of the family blesses the bread, the kolac, and a boiled wheat dish called koljivo. The duty passes from father to son."},{"q":"What is the capital city of Serbia?","a":"Belgrade","o":["Belgrade","Vilnius","Riga","Minsk"],"f":"Belgrade is the capital of Serbia.","kind":"capital"},{"q":"Which of these flags belongs to Serbia?","a":"SRB","o":["SRB","UKR","SWE","GRC"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Serbia.","kind":"flag"}],"hard":[{"q":"Which medieval monasteries of the Morava valley are known for frescoes?","a":"Studenica and Sopocani","o":["Studenica and Sopocani","Rila","Ostrog","The Troodos"],"f":"Studenica was endowed by Stefan Nemanja. Its marble church holds Byzantine-influenced painting."},{"q":"The slava celebrates a family's patron saint with a candle and which special bread?","a":"A slavski kolac","o":["A slavski kolac","A pretzel","Matzo","A croissant"],"f":"The kolac is cut and blessed. The custom is a marker of Serbian Orthodox family identity."},{"q":"Nikola Tesla was an ethnic Serb whose alternating-current patents changed industry. He died in which city?","a":"New York","o":["New York","Belgrade","Budapest","Paris"],"f":"Tesla worked in the United States from the 1880s. A museum in Belgrade holds his ashes and papers."},{"q":"Which of these cities is the capital of Serbia?","a":"Belgrade","o":["Belgrade","Novi Sad","Niš","Kragujevac"],"f":"Belgrade is the capital of Serbia.","kind":"capital"},{"q":"Which flag is the flag of Serbia?","a":"SRB","o":["SRB","SEN","MOZ","MHL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Serbia.","kind":"flag"}]}},{"id":"SSD","name":"South Sudan","cont":"Africa","emoji":"🇸🇸","latlng":[7,30],"q":{"easy":[{"q":"Which huge swamp of floating plants on the White Nile dominates the center of the country?","a":"The Sudd","o":["The Sudd","The Okavango","The Everglades","The Pantanal"],"f":"The Sudd is one of the world's largest wetlands. It slows the White Nile and supports cattle camps."},{"q":"Which sorghum porridge with a side of greens or fish is daily food?","a":"Asida or kwon","o":["Asida or kwon","Sushi","Risotto","Fondue"],"f":"Sorghum and maize porridges are eaten with stews of fish from the Nile or of wild greens."},{"q":"Which cattle camp culture of the Nile floodplain measures wealth in herds?","a":"The Mundari and Dinka camps","o":["The Mundari and Dinka camps","The Maasai only","The Sami","The Mongols"],"f":"Young men cover their bodies with ash to guard against insects and live among the long-horned cattle."},{"q":"Which city is the capital of South Sudan?","a":"Juba","o":["Juba","Mexico City","Phnom Penh","Tbilisi"],"f":"Juba is the capital of South Sudan.","kind":"capital"},{"q":"Which flag belongs to South Sudan?","a":"SSD","o":["SSD","IRL","TJK","LKA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of South Sudan.","kind":"flag"}],"medium":[{"q":"A referendum led to independence on 9 July of which year?","a":"2011","o":["2011","1956","2005","2018"],"f":"The vote followed a 2005 peace agreement with Khartoum. 1956 was Sudan's own independence. The date is the fact to remember; 'newest country' is a title that expires."},{"q":"The Sudd, where the White Nile spreads out, is one of the world's largest what?","a":"Freshwater wetlands","o":["Freshwater wetlands","Sand seas","Coral reefs","Lava plateaus"],"f":"Papyrus swamp soaks up a great deal of the river. The Jonglei Canal, meant to cut through the swamp, was never finished. It is a wetland, not a dune field."},{"q":"The seasonal movement of white-eared kob across the eastern plains is one of the largest migrations of what?","a":"Land mammals","o":["Land mammals","Salmon","Monarch butterflies","Arctic terns"],"f":"Herds follow the rain in numbers that rival the famous migrations farther east. Tiang and gazelles share the plains. It is a mammal movement, not a bird or a fish run."},{"q":"What is the capital city of South Sudan?","a":"Juba","o":["Juba","Gaborone","Dakar","Windhoek"],"f":"Juba is the capital of South Sudan.","kind":"capital"},{"q":"Which of these flags belongs to South Sudan?","a":"SSD","o":["SSD","LBY","TCD","NGA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of South Sudan.","kind":"flag"}],"hard":[{"q":"Which Nile port in the north of the country was a historic steamer town?","a":"Malakal","o":["Malakal","Juba","Wau","Bentiu"],"f":"Malakal stands on the White Nile near the great swamp. Steamers once linked it with Khartoum."},{"q":"Which national park on the Ethiopian border protects a huge migration of antelope?","a":"Boma National Park","o":["Boma National Park","Kruger","Serengeti","Etosha"],"f":"Boma and Badingilo host the migration of white-eared kob, tiang, and gazelle."},{"q":"Nuer and Dinka languages belong to which family?","a":"Nilotic","o":["Nilotic","Bantu","Afroasiatic only","Khoisan"],"f":"Nilotic languages spread along the Nile. Cattle vocabulary is especially rich."},{"q":"Which of these cities is the capital of South Sudan?","a":"Juba","o":["Juba","Malakal","Wau","Bor"],"f":"Juba is the capital of South Sudan.","kind":"capital"},{"q":"Which flag is the flag of South Sudan?","a":"SSD","o":["SSD","LBR","MLI","KEN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of South Sudan.","kind":"flag"}]}},{"id":"STP","name":"São Tomé and Príncipe","cont":"Africa","emoji":"🇸🇹","latlng":[1,7],"q":{"easy":[{"q":"Which volcanic plug, a steep green tower, rises in the south of Sao Tome island?","a":"Pico Cao Grande","o":["Pico Cao Grande","Sugarloaf","The Matterhorn","Devils Tower"],"f":"Pico Cao Grande is a narrow basalt spire in the forest, hundreds of meters tall."},{"q":"Which fish stew with breadfruit or plantain is island home cooking?","a":"Calulu","o":["Calulu","Sushi","Poutine","Ceviche"],"f":"Calulu simmers fish or dried fish with greens, okra, and palm oil."},{"q":"Which old plantation houses of cocoa estates dot the islands?","a":"Rocas","o":["Rocas","Haciendas","Chateaux","Ryokans"],"f":"Rocas were cocoa and coffee estates with a hospital, a chapel, and workers' quarters."},{"q":"Which city is the capital of São Tomé and Príncipe?","a":"São Tomé","o":["São Tomé","Majuro","Pyongyang","Zagreb"],"f":"São Tomé is the capital of São Tomé and Príncipe.","kind":"capital"},{"q":"Which flag belongs to São Tomé and Príncipe?","a":"STP","o":["STP","SLB","GBR","LCA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of São Tomé and Príncipe.","kind":"flag"}],"medium":[{"q":"Pico Cão Grande, a needle of rock hundreds of meters high on the larger island, is what?","a":"A volcanic plug","o":["A volcanic plug","A coral stack","A river-cut butte","A termite mound"],"f":"It is the hard core of an old volcano, left when softer rock wore away. The islands are volcanic peaks near the equator in the Gulf of Guinea. The needle stands on São Tomé, not on the smaller island."},{"q":"Portuguese settlers found the islands empty in the late 15th century. Their first plantation crop, grown with enslaved labor, was what?","a":"Sugar","o":["Sugar","Rubber","Tea","Cloves"],"f":"Cocoa replaced sugar in the 19th century. Enslaved people were brought from the mainland. Cloves were Zanzibar's fortune, not this one's."},{"q":"Tchiloli is a local theatre of tales about Charlemagne. Performers tell the stories with what?","a":"Music, dance, and elaborate costume","o":["Music, dance, and elaborate costume","Javanese shadow puppets","Noh masks","Kabuki makeup"],"f":"The plays arrived with Portuguese culture and were remade on the islands. They are danced as much as spoken. They are not an Asian stage form."},{"q":"What is the capital city of São Tomé and Príncipe?","a":"São Tomé","o":["São Tomé","Ouagadougou","Lusaka","Dakar"],"f":"São Tomé is the capital of São Tomé and Príncipe.","kind":"capital"},{"q":"Which of these flags belongs to São Tomé and Príncipe?","a":"STP","o":["STP","GAB","GMB","SEN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of São Tomé and Príncipe.","kind":"flag"}],"hard":[{"q":"Which community, with its own creole, lives mainly along the southern coast and traces itself to people who left the plantations?","a":"The Angolares","o":["The Angolares","The Forro planters","Cape Verdean migrants","Mainland merchants only"],"f":"The Angolares kept fishing villages and a distinct language. Historians still debate the exact 16th-century origin story."},{"q":"Which Creole language and culture grew among the island-born descendants of those communities?","a":"Forro","o":["Forro","Papiamentu","Haitian Creole","Jamaican Patois"],"f":"Forro is the main Creole. Tchiloli theater, with masks and European costumes, retells medieval stories."},{"q":"The obo, the highland forest, is a refuge for which famous birds?","a":"The Sao Tome ibis and grosbeak","o":["The Sao Tome ibis and grosbeak","Penguins","Flamingos of the Rift","Ostriches"],"f":"Several birds live nowhere else. The forest is still being cleared for gardens in places."},{"q":"Which of these cities is the capital of São Tomé and Príncipe?","a":"São Tomé","o":["São Tomé","Santo António","Neves","Santana"],"f":"São Tomé is the capital of São Tomé and Príncipe.","kind":"capital"},{"q":"Which flag is the flag of São Tomé and Príncipe?","a":"STP","o":["STP","BWA","VAT","DZA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of São Tomé and Príncipe.","kind":"flag"}]}},{"id":"SUR","name":"Suriname","cont":"South America","emoji":"🇸🇷","latlng":[4,-56],"q":{"easy":[{"q":"Which colonial wooden center on the river is a UNESCO city?","a":"Paramaribo's old town","o":["Paramaribo's old town","Georgetown","Cayenne","Belem"],"f":"Paramaribo's white wooden houses and a wooden cathedral recall Dutch rule. The inner city is a UNESCO site."},{"q":"Which roti and a peanut soup, pom, a Jewish-Surinamese casserole, share the table?","a":"Pom and roti","o":["Pom and roti","Pepperpot","Feijoada","Keshi yena"],"f":"Pom is made with tayer root, chicken, and citrus. It is a festive dish of the Creole and Jewish kitchens."},{"q":"Which huge nature reserve in the center protects uncut rainforest?","a":"The central forest reserve","o":["The central forest reserve","Kaieteur","Brownsberg only","Galibi"],"f":"The UNESCO reserve covers mountains and forest with almost no roads. It is one of the largest protected tropical forests."},{"q":"Which city is the capital of Suriname?","a":"Paramaribo","o":["Paramaribo","Luxembourg City","Dili","Nuku'alofa"],"f":"Paramaribo is the capital of Suriname.","kind":"capital"},{"q":"Which flag belongs to Suriname?","a":"SUR","o":["SUR","LBN","CIV","LBR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Suriname.","kind":"flag"}],"medium":[{"q":"Which anti-colonial writer, born in Paramaribo, wrote We Slaves of Suriname?","a":"Anton de Kom","o":["Anton de Kom","Multatuli","V. S. Naipaul","Derek Walcott"],"f":"Published in 1934, the book attacks Dutch colonial rule and slavery's legacy. De Kom was later arrested by the Nazis in the Netherlands and died in a camp."},{"q":"The historic center of Paramaribo, a UNESCO site, is known for Dutch colonial buildings made largely of what?","a":"Wood","o":["Wood","Marble","Adobe","Basalt"],"f":"White wooden houses, palaces, and churches line the river. The style mixes Dutch plans with tropical timber construction."},{"q":"Newspapers, laws, and classrooms in Suriname use mainly which European language?","a":"Dutch","o":["Dutch","English","Portuguese","French"],"f":"The country was Dutch Guiana until independence in 1975. English dominates in Guyana, and French Guiana is an overseas region of France."},{"q":"What is the capital city of Suriname?","a":"Paramaribo","o":["Paramaribo","Georgetown","Lima","Santiago"],"f":"Paramaribo is the capital of Suriname.","kind":"capital"},{"q":"Which of these flags belongs to Suriname?","a":"SUR","o":["SUR","GUY","ECU","PRY"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Suriname.","kind":"flag"}],"hard":[{"q":"Which two houses of worship stand side by side in the wooden capital?","a":"A synagogue and a mosque","o":["A synagogue and a mosque","Two cathedrals","A fort and a shrine","A temple and a barracks"],"f":"The Neveh Shalom synagogue and the Keizerstraat mosque share a street. The pairing is a point of local pride."},{"q":"Maroon communities, descendants of people who escaped plantations, live along which rivers?","a":"The upland rivers","o":["The upland rivers","The Amazon only","The Orinoco","The Essequibo only"],"f":"The Saamaka and Ndyuka won treaties with the Dutch in the 1700s. Their villages keep distinct languages."},{"q":"Which Hindu and Muslim festivals, from Indian indentured ancestors, are national holidays?","a":"Holi and Eid","o":["Holi and Eid","Diwali only","Carnival only","Christmas only"],"f":"Workers from India arrived after slavery ended in 1863. Their festivals became part of the national calendar."},{"q":"Which of these cities is the capital of Suriname?","a":"Paramaribo","o":["Paramaribo","Lelydorp","Nieuw Nickerie","Moengo"],"f":"Paramaribo is the capital of Suriname.","kind":"capital"},{"q":"Which flag is the flag of Suriname?","a":"SUR","o":["SUR","MUS","TUV","KIR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Suriname.","kind":"flag"}]}},{"id":"SVK","name":"Slovakia","cont":"Europe","emoji":"🇸🇰","latlng":[48.66666666,19.5],"q":{"easy":[{"q":"Which mountains on the Polish border hold the country's highest peaks?","a":"The High Tatras","o":["The High Tatras","The Alps","The Carpathians of only Romania","The Sudetes"],"f":"Gerlachovsky stit is the highest summit. Mountain huts and tarns fill the valleys."},{"q":"Which dumplings of potato and flour, with sheep cheese and bacon, are the national dish?","a":"Bryndzove halusky","o":["Bryndzove halusky","Gnocchi","Spätzle","Pierogi"],"f":"Bryndza is a salty sheep cheese. Halusky are torn bits of dough boiled and tossed with the cheese."},{"q":"Which castle on a travertine hill is one of the largest medieval ruins in central Europe?","a":"Spis Castle","o":["Spis Castle","Bratislava Castle","Bojnice","Trencin"],"f":"Spis Castle covers a huge ridge in the east. It was a county seat of the Kingdom of Hungary."},{"q":"Which city is the capital of Slovakia?","a":"Bratislava","o":["Bratislava","Hanoi","Sri Jayawardenepura Kotte","South Tarawa"],"f":"Bratislava is the capital of Slovakia.","kind":"capital"},{"q":"Which flag belongs to Slovakia?","a":"SVK","o":["SVK","COD","BRN","GTM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Slovakia.","kind":"flag"}],"medium":[{"q":"Which leader, born in Uhrovec, tried to give Czechoslovakia socialism with a human face in 1968?","a":"Alexander Dubcek","o":["Alexander Dubcek","Vaclav Havel","Imre Nagy","Lech Walesa"],"f":"The Prague Spring ended when Warsaw Pact troops invaded in August. Dubcek was later expelled from the party, and he returned to public life only after 1989."},{"q":"Spis Castle, a UNESCO ruin above the town of Spisske Podhradie, is one of the largest castle complexes in which region?","a":"Central Europe","o":["Central Europe","Iberia","Scandinavia","The British Isles"],"f":"It grew from a 12th-century fort into a stone town on a hill. A fire in 1780 left it a ruin, which is how visitors see it now."},{"q":"Bryndzove halusky, often called the national dish, are potato dumplings topped with sheep cheese and what else?","a":"Fried bacon","o":["Fried bacon","Paprika goulash","A fried egg","Poppy seeds"],"f":"Bryndza is a tangy sheep cheese. Halusky are small dumplings pressed through holes into boiling water, cousins of Central European spaetzle."},{"q":"What is the capital city of Slovakia?","a":"Bratislava","o":["Bratislava","Warsaw","Nicosia","San Marino"],"f":"Bratislava is the capital of Slovakia.","kind":"capital"},{"q":"Which of these flags belongs to Slovakia?","a":"SVK","o":["SVK","ALB","GBR","ISL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Slovakia.","kind":"flag"}],"hard":[{"q":"Which wooden churches of the Carpathian villages are UNESCO-listed?","a":"The wooden churches of the Slovak Carpathians","o":["The wooden churches of the Slovak Carpathians","Stave churches","Kizhi","The painted monasteries"],"f":"Eastern-rite and Roman churches of logs stand in villages such as Hronsek and Kezmarok."},{"q":"The mining town of Banska Stiavnica was famous in the Habsburg era for which metal?","a":"Silver","o":["Silver","Gold of only the Andes","Tin","Uranium"],"f":"Engineers from the town helped invent modern mining pumps. The old town is a UNESCO site."},{"q":"A traditional shepherd's axe, now a folk symbol, is called what?","a":"A valaska","o":["A valaska","A tomahawk","A halberd","A katana"],"f":"The valaska has a small axe head and a walking-stick handle. Dancers still carry it."},{"q":"Which of these cities is the capital of Slovakia?","a":"Bratislava","o":["Bratislava","Košice","Nitra","Prešov"],"f":"Bratislava is the capital of Slovakia.","kind":"capital"},{"q":"Which flag is the flag of Slovakia?","a":"SVK","o":["SVK","PRY","HRV","SVN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Slovakia.","kind":"flag"}]}},{"id":"SVN","name":"Slovenia","cont":"Europe","emoji":"🇸🇮","latlng":[46.11666666,14.81666666],"q":{"easy":[{"q":"Which island church in a glacial lake, with a castle on the cliff, is the classic postcard?","a":"Lake Bled","o":["Lake Bled","Lake Bohinj","Lake Como","Hallstatt"],"f":"Bled's island is reached by a traditional pletna boat. The castle above was a medieval toll point."},{"q":"Which rolled nut cake is a holiday sweet?","a":"Potica","o":["Potica","Strudel","Baklava","Panettone"],"f":"Potica is a yeast dough rolled around walnut filling. It is baked for Easter and Christmas."},{"q":"Which show cave, full of chambers and a railway, is near the capital region's southwest?","a":"Postojna Cave","o":["Postojna Cave","Skocjan","The Blue Grotto","Lascaux"],"f":"Postojna has been a tourist cave since the 1800s. A blind salamander, the olm, lives in the underground water."},{"q":"Which city is the capital of Slovenia?","a":"Ljubljana","o":["Ljubljana","Singapore","Wellington","Kingston"],"f":"Ljubljana is the capital of Slovenia.","kind":"capital"},{"q":"Which flag belongs to Slovenia?","a":"SVN","o":["SVN","MDV","SLB","GHA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Slovenia.","kind":"flag"}],"medium":[{"q":"Which architect, born in Ljubljana, designed the city's Triple Bridge and the national library?","a":"Joze Plecnik","o":["Joze Plecnik","Otto Wagner","Le Corbusier","Antoni Gaudi"],"f":"He also remade Prague Castle for the new Czechoslovak president after 1918. His Ljubljana work mixes classical columns with local craft."},{"q":"Lake Bled's island is reached by wooden boats called pletna. The island's main landmark is what?","a":"A pilgrimage church","o":["A pilgrimage church","A royal palace","A lighthouse","A casino"],"f":"Tradition says a groom should carry his bride up the 99 steps. The castle on the cliff above the lake is a separate medieval fortress."},{"q":"The white horses of the Spanish Riding School in Vienna descend from a stud founded in 1580 at which Slovenian village?","a":"Lipica","o":["Lipica","Bled","Piran","Ptuj"],"f":"The breed is the Lipizzaner, named for that village, then in the Habsburg lands. Foals are dark and usually turn white as they grow."},{"q":"What is the capital city of Slovenia?","a":"Ljubljana","o":["Ljubljana","Paris","Andorra la Vella","Vienna"],"f":"Ljubljana is the capital of Slovenia.","kind":"capital"},{"q":"Which of these flags belongs to Slovenia?","a":"SVN","o":["SVN","GBR","NLD","CZE"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Slovenia.","kind":"flag"}],"hard":[{"q":"Which horses, bred at Lipica since 1580, became the white horses of Europe's riding schools?","a":"Lipizzaners","o":["Lipizzaners","Arabians","Andalusians","Friesians"],"f":"The stud supplied the Habsburg court. Foals are dark and lighten as they age."},{"q":"The Skocjan Caves, a UNESCO site, were cut by which disappearing river?","a":"The Reka","o":["The Reka","The Soca","The Drava","The Sava"],"f":"The Reka sinks into a huge underground canyon. The caves are among the largest known chambers."},{"q":"Which beekeeping tradition paints colorful panels on hive fronts?","a":"Painted beehive panels","o":["Painted beehive panels","Straw skeps only","Top-bar hives of Kenya","Japanese boxes"],"f":"In the 1700s and 1800s farmers painted religious and comic scenes on the wooden ends of hives."},{"q":"Which of these cities is the capital of Slovenia?","a":"Ljubljana","o":["Ljubljana","Maribor","Koper","Celje"],"f":"Ljubljana is the capital of Slovenia.","kind":"capital"},{"q":"Which flag is the flag of Slovenia?","a":"SVN","o":["SVN","SVK","HRV","PRY"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Slovenia.","kind":"flag"}]}},{"id":"SWE","name":"Sweden","cont":"Europe","emoji":"🇸🇪","latlng":[62,15],"q":{"easy":[{"q":"Which warship capsized on its maiden voyage in 1628 and was raised in 1961?","a":"The Vasa","o":["The Vasa","The Mary Rose","The Skuldelev ships","The Oseberg"],"f":"The Vasa was top-heavy with cannon and carvings. It is now a museum in Stockholm, still largely intact."},{"q":"Which meatballs in cream sauce are a famous plate, at home and abroad?","a":"Swedish meatballs","o":["Swedish meatballs","Frikadeller","Kofta","Polpette"],"f":"Kottbullar are served with potatoes, lingonberries, and gravy. The recipe varies by family."},{"q":"Which writer created Pippi Longstocking?","a":"Astrid Lindgren","o":["Astrid Lindgren","Tove Jansson","Selma Lagerlof","Andersen"],"f":"Lindgren's books began in the 1940s. Pippi lives alone with a horse and a monkey and enormous strength."},{"q":"Which city is the capital of Sweden?","a":"Stockholm","o":["Stockholm","Porto-Novo","Cairo","Santo Domingo"],"f":"Stockholm is the capital of Sweden.","kind":"capital"},{"q":"Which flag belongs to Sweden?","a":"SWE","o":["SWE","MRT","CAN","SDN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Sweden.","kind":"flag"}],"medium":[{"q":"Which botanist, born in Rashult in 1707, invented the two-name system still used for species?","a":"Carl Linnaeus","o":["Carl Linnaeus","Charles Darwin","Gregor Mendel","Alexander von Humboldt"],"f":"Homo sapiens is one of his names. He taught at Uppsala and sent students around the world to collect plants."},{"q":"Alfred Nobel, born in Stockholm, made a fortune from dynamite and left it to fund prizes. He died in which year, after writing that will?","a":"1896","o":["1896","1867","1901","1914"],"f":"Dynamite, patented in 1867, was his safer form of nitroglycerin. The first prizes were awarded in 1901, five years after his death."},{"q":"Anders Celsius, born in Uppsala, proposed a temperature scale in 1742. In his original version, what was 0 degrees?","a":"The boiling point of water","o":["The boiling point of water","The freezing point of water","Absolute zero","Body temperature"],"f":"He set 100 at freezing. After his death the scale was flipped to the form used today, with 0 at freezing and 100 at boiling."},{"q":"What is the capital city of Sweden?","a":"Stockholm","o":["Stockholm","Sofia","Luxembourg City","Ljubljana"],"f":"Stockholm is the capital of Sweden.","kind":"capital"},{"q":"Which of these flags belongs to Sweden?","a":"SWE","o":["SWE","SVK","AUT","NLD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Sweden.","kind":"flag"}],"hard":[{"q":"Which chemist in Stockholm determined atomic weights and invented modern symbols such as Fe for iron?","a":"Jons Jacob Berzelius","o":["Jons Jacob Berzelius","Scheele","Nobel","Lavoisier"],"f":"Berzelius published a table of atomic weights and the one- or two-letter symbols still used in chemistry."},{"q":"The right of public access, allemansratten, allows what?","a":"Walking and camping on wild land with care","o":["Walking and camping on wild land with care","Hunting anywhere","Driving on private roads","Fishing in every lake"],"f":"People may cross forests and fields if they do not disturb residents or damage crops."},{"q":"Which midsummer pole, dressed with flowers, is danced around in June?","a":"The maypole","o":["The maypole","A totem","A bonfire only","A Christmas tree"],"f":"Midsummer is a major holiday. People wear flower crowns and eat herring and new potatoes."},{"q":"Which of these cities is the capital of Sweden?","a":"Stockholm","o":["Stockholm","Gothenburg","Malmö","Uppsala"],"f":"Stockholm is the capital of Sweden.","kind":"capital"},{"q":"Which flag is the flag of Sweden?","a":"SWE","o":["SWE","DNK","UKR","KAZ"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Sweden.","kind":"flag"}]}},{"id":"SWZ","name":"Eswatini","cont":"Africa","emoji":"🇸🇿","latlng":[-26.5,31.5],"q":{"easy":[{"q":"Which wildlife reserve is the largest protected area in Eswatini and is known for lions?","a":"Hlane Royal National Park","o":["Hlane Royal National Park","Kruger","Etosha","Chobe"],"f":"Hlane sits in the lowveld. Visitors see lions, elephants, and rhinos on guided drives."},{"q":"Which maize porridge is a daily staple in Eswatini?","a":"Liphalishi","o":["Liphalishi","Sushi","Risotto","Fondue"],"f":"Maize porridge is eaten with vegetables or meat. Sour milk is another common side."},{"q":"The Umhlanga, or reed dance, brings young women to present reeds at which royal village?","a":"Lobamba","o":["Lobamba","Manzini","Siteki","Mbabane"],"f":"The reeds are used at the queen mother's enclosure. The ceremony is a major national gathering."},{"q":"Which city is the administrative capital of Eswatini?","a":"Mbabane","o":["Mbabane","Thimphu","Belgrade","Andorra la Vella"],"f":"Mbabane is the administrative capital. Lobamba is the royal and legislative capital.","kind":"capital"},{"q":"Which flag belongs to Eswatini?","a":"SWZ","o":["SWZ","UZB","BRB","PSE"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Eswatini.","kind":"flag"}],"medium":[{"q":"The kingdom became independent from Britain in which year, fifty years before it renamed itself in English?","a":"1968","o":["1968","1910","1966","2018"],"f":"The 2018 English name, Eswatini, means land of the Swazi and matches siSwati. 2018 was the renaming, not independence. 1966 was the year for Botswana and Lesotho."},{"q":"At Umhlanga, unmarried girls take part by doing what?","a":"Cutting reeds for the queen mother's enclosure","o":["Cutting reeds for the queen mother's enclosure","Racing horses","Diving for pearls","Weaving silk"],"f":"The reeds repair screens around the royal residence. The gathering is usually in late August or early September. Incwala, around the December solstice, is a separate royal rite."},{"q":"Incwala, the main royal ritual, is timed to what?","a":"The first fruits, near the summer solstice","o":["The first fruits, near the summer solstice","Easter only","The Arctic winter moon","The rice harvest of a delta"],"f":"Young men collect sacred branches, and the king tastes the new crops. It is older and more restricted than the reed dance. December is summer in this hemisphere."},{"q":"What is the administrative capital city of Eswatini?","a":"Mbabane","o":["Mbabane","Cairo","Banjul","Porto-Novo"],"f":"Mbabane is the administrative capital. Lobamba is the royal and legislative capital.","kind":"capital"},{"q":"Which of these flags belongs to Eswatini?","a":"SWZ","o":["SWZ","CAF","BWA","NER"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Eswatini.","kind":"flag"}],"hard":[{"q":"King Sobhuza II led the country to independence in 1968 from which empire?","a":"Britain","o":["Britain","France","Portugal","Germany"],"f":"Swaziland, now Eswatini, had been a British protectorate. Sobhuza remained king for decades."},{"q":"Incwala, the main kingship ceremony, marks which moment in the year?","a":"The first fruits","o":["The first fruits","The first snow","A lunar eclipse","The wheat harvest of Europe"],"f":"Incwala renews the king's power around the summer solstice and the new harvest."},{"q":"Which colorful cloth and leather apron is part of traditional Swazi dress at ceremonies?","a":"The emahiya and lihiya","o":["The emahiya and lihiya","The kimono","The sari","The kilt"],"f":"Women wear a wrap and an apron of dyed cloth or leather. Men may wear a loincloth of animal skin at Incwala."},{"q":"Which of these cities is the administrative capital of Eswatini?","a":"Mbabane","o":["Mbabane","Lobamba","Manzini","Siteki"],"f":"Mbabane is the administrative capital. Lobamba is the royal and legislative capital.","kind":"capital"},{"q":"Which flag is the flag of Eswatini?","a":"SWZ","o":["SWZ","ETH","PHL","PSE"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Eswatini.","kind":"flag"}]}},{"id":"SYC","name":"Seychelles","cont":"Africa","emoji":"🇸🇨","latlng":[-4.58333333,55.66666666],"q":{"easy":[{"q":"Which giant nuts, the largest seeds of any plant, wash up from a palm that grows only nearby?","a":"Coco de mer","o":["Coco de mer","Coconuts","Avocados","Walnuts"],"f":"The coco de mer palm grows in the Vallee de Mai on Praslin. Its double nut looks like a human hip."},{"q":"Which coconut-milk seafood stew is a home staple of the Creole kitchen?","a":"Fish curry","o":["Fish curry","Sushi","Poutine","Fondue"],"f":"Seychellois curries use fish or octopus, chili, and lime. Shark chutney is another island specialty."},{"q":"Which beach of huge granite boulders is one of the most photographed in the islands?","a":"Anse Source d'Argent","o":["Anse Source d'Argent","Copacabana","Waikiki","Bondi"],"f":"Anse Source d'Argent, on La Digue, has pink-gray rocks, pale sand, and shallow turquoise water."},{"q":"Which city is the capital of Seychelles?","a":"Victoria","o":["Victoria","Damascus","Ottawa","Luxembourg City"],"f":"Victoria is the capital of Seychelles.","kind":"capital"},{"q":"Which flag belongs to Seychelles?","a":"SYC","o":["SYC","AZE","BTN","DNK"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Seychelles.","kind":"flag"}],"medium":[{"q":"The coco de mer, a palm native only to these islands, produces the world's largest what?","a":"Seed","o":["Seed","Leaf","Flower","Tree trunk"],"f":"A nut can weigh more than 15 kilograms. It grows wild only in the Vallée de Mai on Praslin and on Curieuse. The species name maldivica wrongly points at the Maldives."},{"q":"Aldabra, a raised coral atoll, is famous for a huge population of what?","a":"Giant tortoises","o":["Giant tortoises","Komodo dragons","Dodos","Penguins"],"f":"Isolation saved the Aldabra giant tortoise after sailors wiped out similar animals on other Indian Ocean islands. The dodo was Mauritian. There are no Komodo dragons here."},{"q":"The islands had no residents when France began settling Mahé in 1770. Britain took them during which wars?","a":"The Napoleonic Wars","o":["The Napoleonic Wars","The Crusades","The First World War","The wars of Italian unification"],"f":"Britain administered the islands from Mauritius and made them a separate colony in 1903. There was no local population when the French arrived. Enslaved Africans were brought with the settlers."},{"q":"What is the capital city of Seychelles?","a":"Victoria","o":["Victoria","Maseru","Luanda","Lomé"],"f":"Victoria is the capital of Seychelles.","kind":"capital"},{"q":"Which of these flags belongs to Seychelles?","a":"SYC","o":["SYC","ETH","SOM","GIN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Seychelles.","kind":"flag"}],"hard":[{"q":"The islands were uninhabited until the French claimed them in the 1700s. The first settlers planted what?","a":"Cinnamon and coconuts","o":["Cinnamon and coconuts","Wheat","Potatoes","Rubber"],"f":"Spices and coconuts fed the colonial economy. Enslaved Africans and later freed people built the Creole culture."},{"q":"Which giant tortoises, relatives of those on Aldabra atoll, roam island parks?","a":"Aldabra giant tortoises","o":["Aldabra giant tortoises","Galapagos tortoises only","Desert tortoises","Sea turtles only"],"f":"Aldabra, a Seychellois atoll, holds the world's largest population of giant tortoises."},{"q":"The Kreol language is built mainly on French vocabulary with grammar shaped by which histories?","a":"African and Malagasy speech","o":["African and Malagasy speech","Norse","Quechua","Japanese"],"f":"Seychellois Creole is the first language of most people. English and French are also official."},{"q":"Which of these cities is the capital of Seychelles?","a":"Victoria","o":["Victoria","Anse Boileau","Beau Vallon","Takamaka"],"f":"Victoria is the capital of Seychelles.","kind":"capital"},{"q":"Which flag is the flag of Seychelles?","a":"SYC","o":["SYC","PRY","UZB","TUR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Seychelles.","kind":"flag"}]}},{"id":"SYR","name":"Syria","cont":"Asia","emoji":"🇸🇾","latlng":[35,38],"q":{"easy":[{"q":"Which covered market in the old city of Damascus is a famous commercial lane?","a":"Al-Hamidiyah Souq","o":["Al-Hamidiyah Souq","The Grand Bazaar","Khan el-Khalili","Mutrah"],"f":"The souq runs toward the Umayyad Mosque under a metal roof. It has been a market street for centuries."},{"q":"Which cracked-wheat ovals of meat, fried or baked, are a national dish?","a":"Kibbeh","o":["Kibbeh","Falafel","Kofta","Samosa"],"f":"Aleppo and Damascus both claim kibbeh. The fried balls are stuffed with spiced meat and nuts."},{"q":"Which wooden waterwheels on the Orontes at Hama lift water into aqueducts?","a":"Norias","o":["Norias","Sakia","Shaduf","Archimedes screws only"],"f":"The norias of Hama are huge wooden wheels. Some date from medieval repairs of older designs."},{"q":"Which city is the capital of Syria?","a":"Damascus","o":["Damascus","Reykjavík","Yamoussoukro","Freetown"],"f":"Damascus is the capital of Syria.","kind":"capital"},{"q":"Which flag belongs to Syria?","a":"SYR","o":["SYR","GBR","DNK","DMA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Syria.","kind":"flag"}],"medium":[{"q":"Which poet, born in Damascus in 1923, is famous for Arabic love poems quoted across the region?","a":"Nizar Qabbani","o":["Nizar Qabbani","Mahmoud Darwish","Khalil Gibran","Adonis"],"f":"He was a diplomat as well as a poet. Adonis, another major Syrian poet, was born in a village near Latakia, not in Damascus. Darwish was Palestinian and Gibran Lebanese."},{"q":"Tablets from Ugarit, modern Ras Shamra, preserve the earliest known what?","a":"Alphabetic cuneiform","o":["Alphabetic cuneiform","Chinese movable type","Hangul","The Greek vowel alphabet"],"f":"The city was destroyed around 1190 BCE. Its script wrote consonants with wedges. An earlier alphabet, Proto-Sinaitic, was not cuneiform, and the Greek vowels came later."},{"q":"In the 3rd century a ruler of Palmyra seized Egypt and much of the Roman East. Who was she?","a":"Zenobia","o":["Zenobia","Cleopatra","Boudica","Theodora"],"f":"She ruled for her young son after her husband Odaenathus died. The emperor Aurelian defeated her around 272. Cleopatra's Egypt was three centuries earlier, and Boudica rebelled in Britain."},{"q":"What is the capital city of Syria?","a":"Damascus","o":["Damascus","Kathmandu","Jakarta","Pyongyang"],"f":"Damascus is the capital of Syria.","kind":"capital"},{"q":"Which of these flags belongs to Syria?","a":"SYR","o":["SYR","KGZ","LKA","MMR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Syria.","kind":"flag"}],"hard":[{"q":"Which northern city is famous for a huge citadel on a mound and a long covered market?","a":"Aleppo","o":["Aleppo","Homs","Hama","Palmyra"],"f":"The citadel sits on a tell occupied for millennia. The stone fortress visitors know was built up in the 12th and 13th centuries."},{"q":"Which castle of the Knights Hospitaller in the west is one of the best-preserved crusader forts?","a":"Krak des Chevaliers","o":["Krak des Chevaliers","Kerak","Margat","Beaufort"],"f":"Krak des Chevaliers guards the Homs gap. It was built up in the 1100s and 1200s."},{"q":"Aleppo soap, famous across the region, is boiled from olive oil and what?","a":"Laurel berry oil","o":["Laurel berry oil","Palm oil","Coconut","Butter"],"f":"The soap is aged for months. Green laurel soap from Aleppo was traded as far as Europe."},{"q":"Which of these cities is the capital of Syria?","a":"Damascus","o":["Damascus","Aleppo","Homs","Latakia"],"f":"Damascus is the capital of Syria.","kind":"capital"},{"q":"Which flag is the flag of Syria?","a":"SYR","o":["SYR","EGY","IRQ","YEM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Syria.","kind":"flag"}]}},{"id":"TCD","name":"Chad","cont":"Africa","emoji":"🇹🇩","latlng":[15,19],"q":{"easy":[{"q":"Which huge shallow lake on the western border shrinks and grows with the rains?","a":"The shallow western lake","o":["The shallow western lake","Lake Victoria","Lake Baikal","Lake Titicaca"],"f":"Lake Chad is shared with Nigeria, Niger, and Cameroon. It has lost much of its open water in dry decades."},{"q":"Which millet balls with sauce are daily food in Chad?","a":"Boule","o":["Boule","Sushi","Tacos","Poutine"],"f":"Boule is a stiff millet or sorghum porridge pinched and dipped in sauce."},{"q":"Which UNESCO lakes in the far north are known for their strange colors and rocky spires?","a":"The Lakes of Ounianga","o":["The Lakes of Ounianga","Plitvice","Lake Louise","Crater Lake"],"f":"Ounianga's lakes survive in the Sahara because of a balance of groundwater and evaporation."},{"q":"Which city is the capital of Chad?","a":"N'Djamena","o":["N'Djamena","Astana","Jerusalem","Vatican City"],"f":"N'Djamena is the capital of Chad.","kind":"capital"},{"q":"Which flag belongs to Chad?","a":"TCD","o":["TCD","JOR","CHL","TON"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Chad.","kind":"flag"}],"medium":[{"q":"The Lakes of Ounianga stay full in the middle of the Sahara. They are fed mainly by what?","a":"Underground water","o":["Underground water","A glacier","The Nile flood","A pipe from the sea"],"f":"Some lakes are fresh and others, a short walk away, are extremely salty. Wind would dry them if groundwater did not keep arriving. UNESCO lists the group. They are not an irrigation project."},{"q":"The Ennedi Massif, a UNESCO plateau of sandstone, is known for what?","a":"Rock arches and prehistoric paintings","o":["Rock arches and prehistoric paintings","Roman cities","Medieval cathedrals","Terraced rice"],"f":"Arches such as Aloba stand over desert valleys. Paintings show cattle from a wetter time. Herders still use the massif. It is not a Roman ruin."},{"q":"Toumaï, a skull found in the Djurab in 2001, is the fossil Sahelanthropus. It is about how old?","a":"About 7 million years","o":["About 7 million years","About 7,000 years","About 700,000 years","About 66 million years"],"f":"It may lie near the split between humans and chimpanzees, but scientists still debate its exact place. It is not a dinosaur, and it is vastly older than the first cities."},{"q":"What is the capital city of Chad?","a":"N'Djamena","o":["N'Djamena","Bissau","Nouakchott","Moroni"],"f":"N'Djamena is the capital of Chad.","kind":"capital"},{"q":"Which of these flags belongs to Chad?","a":"TCD","o":["TCD","DZA","LBR","MUS"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Chad.","kind":"flag"}],"hard":[{"q":"The Sao civilization, known from clay figures and walled towns, lived around which body of water?","a":"The great lake on the west","o":["The great lake on the west","Lake Tanganyika","The Mediterranean","The Red Sea"],"f":"Archaeologists have found Sao terracottas and ruins south of Lake Chad dating back many centuries."},{"q":"Which wind brings dust from the Sahara across Chad in the dry season?","a":"The harmattan","o":["The harmattan","The monsoon","The mistral","The chinook"],"f":"The harmattan is a dry northeast wind. It can hide the sun in dust."},{"q":"Zakoua, a UNESCO-listed court music, belongs to which kingdom of the south?","a":"The Bagirmi","o":["The Bagirmi","The Zulu","The Ashanti","Dahomey"],"f":"Bagirmi trumpets and voices once played for the sultan. The style is still performed."},{"q":"Which of these cities is the capital of Chad?","a":"N'Djamena","o":["N'Djamena","Moundou","Sarh","Abéché"],"f":"N'Djamena is the capital of Chad.","kind":"capital"},{"q":"Which flag is the flag of Chad?","a":"TCD","o":["TCD","AND","ROU","MDA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Chad.","kind":"flag"}]}},{"id":"TGO","name":"Togo","cont":"Africa","emoji":"🇹🇬","latlng":[8,1.16666666],"q":{"easy":[{"q":"Which castle-like mud compounds of the Batammariba are a UNESCO landscape in the north?","a":"The Takienta houses","o":["The Takienta houses","The Dogon cliffs","The Casbah","The medina of Fes"],"f":"Koutammakou's tower houses are built of earth, with granaries and shrines. They are still lived in."},{"q":"Which cornmeal dough with a spicy sauce is a daily plate?","a":"Akume","o":["Akume","Sushi","Paella","Poutine"],"f":"Akume is maize or cassava dough. Sauces of okra, peanuts, or greens come with it."},{"q":"Which waterfall on the Kara region is a popular picnic spot?","a":"The Aledjo or Wome falls","o":["The Aledjo or Wome falls","Victoria Falls","Niagara","Iguazu"],"f":"Forest waterfalls in the plateau country are local landmarks above the hotter coast."},{"q":"Which city is the capital of Togo?","a":"Lomé","o":["Lomé","Kathmandu","Helsinki","Jerusalem"],"f":"Lomé is the capital of Togo.","kind":"capital"},{"q":"Which flag belongs to Togo?","a":"TGO","o":["TGO","CAN","SAU","SLV"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Togo.","kind":"flag"}],"medium":[{"q":"In Koutammakou, a UNESCO landscape, the Batammariba build tower-houses called what?","a":"Takienta","o":["Takienta","Tata forts","Ksour","Trulli"],"f":"Animals and grain sit below, and people live above, with a terrace. The same houses continue across the border in Benin. They are homes, not empty ruins."},{"q":"Sylvanus Olympio, the first president after independence in 1960, was assassinated in which year?","a":"1963","o":["1963","1958","1960","1991"],"f":"The killing was among the first military coups in independent Africa. Gnassingbé Eyadéma later dominated politics for decades. 1960 was independence, not the assassination."},{"q":"In the south, vodun shrines are part of community life, shared with Benin. Vodun is best described as what?","a":"A West African religion of spirits","o":["A West African religion of spirits","A school of Buddhism","A branch of Islam","A colonial law code"],"f":"Enslaved people carried related practices to Haiti, where they became Vodou. The shrines here and in Benin are the older home. It is a religion, not a statute book."},{"q":"What is the capital city of Togo?","a":"Lomé","o":["Lomé","Malabo","Tripoli","Lilongwe"],"f":"Lomé is the capital of Togo.","kind":"capital"},{"q":"Which of these flags belongs to Togo?","a":"TGO","o":["TGO","GMB","UGA","COD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Togo.","kind":"flag"}],"hard":[{"q":"The Mina and Ewe of the coast took part in which Atlantic commerce from Aneho?","a":"The slave trade","o":["The slave trade","The spice trade of Malacca","The fur trade","The silk trade"],"f":"European forts and African brokers shipped captives from the Bight of Benin, including this coast."},{"q":"Voodoo, called vodun, has an important annual festival in which town?","a":"Glidji","o":["Glidji","Sokode","Dapaong","Kara"],"f":"In September the people of Glidji hold a sacred stone ceremony tied to vodun priesthood."},{"q":"Kente-like strip cloth of the north is woven by which community famous for looms?","a":"The Kabye and related weavers","o":["The Kabye and related weavers","The Himba","The San","The Tuareg silversmiths only"],"f":"Narrow-strip weaving is a men's craft in parts of the north. Cloth is sewn into larger robes."},{"q":"Which of these cities is the capital of Togo?","a":"Lomé","o":["Lomé","Sokodé","Kara","Kpalimé"],"f":"Lomé is the capital of Togo.","kind":"capital"},{"q":"Which flag is the flag of Togo?","a":"TGO","o":["TGO","GHA","CMR","BEN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Togo.","kind":"flag"}]}},{"id":"THA","name":"Thailand","cont":"Asia","emoji":"🇹🇭","latlng":[15,100],"q":{"easy":[{"q":"Which palace and emerald Buddha temple complex stands by the Chao Phraya in Bangkok?","a":"The Grand Palace","o":["The Grand Palace","Wat Arun","Wat Pho","Ayutthaya"],"f":"The Grand Palace was the king's residence from 1782. The Temple of the Emerald Buddha is inside the walls."},{"q":"Which stir-fried rice noodles with tamarind, egg, and peanuts are a street classic?","a":"Pad thai","o":["Pad thai","Pad see ew","Som tam","Tom yum"],"f":"Pad thai was promoted in the mid-20th century as a national noodle dish. Stalls still cook it in a hot wok."},{"q":"Which canals and boat markets, such as Damnoen Saduak, sell fruit from the water?","a":"Floating markets","o":["Floating markets","The Tonle Sap","Inle","The Kerala backwaters"],"f":"Vendors paddle up and cook over charcoal on the boat. The markets grew from real canal trade."},{"q":"Which city is the capital of Thailand?","a":"Bangkok","o":["Bangkok","Bamako","Panama City","San Salvador"],"f":"Bangkok is the capital of Thailand.","kind":"capital"},{"q":"Which flag belongs to Thailand?","a":"THA","o":["THA","EST","USA","SRB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Thailand.","kind":"flag"}],"medium":[{"q":"Which film director, born in Bangkok in 1970, won the Palme d'Or for Uncle Boonmee Who Can Recall His Past Lives?","a":"Apichatpong Weerasethakul","o":["Apichatpong Weerasethakul","Bong Joon-ho","Ang Lee","Wong Kar-wai"],"f":"His films mix village life with ghosts and folk belief. Bong Joon-ho is South Korean, Ang Lee is Taiwanese-American, and Wong Kar-wai is from Hong Kong."},{"q":"A ruined royal city of temple prangs, north of Bangkok, was destroyed by a Burmese army in 1767. What is it called?","a":"Ayutthaya","o":["Ayutthaya","Sukhothai","Angkor","Bagan"],"f":"It had traded with Europe and Japan and was one of the largest cities of the 1600s. Sukhothai is an earlier Thai kingdom. Angkor is in Cambodia and Bagan is in Myanmar."},{"q":"The April festival of the traditional new year is famous for water thrown in the streets. What is it called?","a":"Songkran","o":["Songkran","Loy Krathong","Yi Peng","Thingyan"],"f":"It falls in the hottest weeks. Loy Krathong, with baskets of flowers set on the water, comes months later. Thingyan is the related new-year festival in Myanmar."},{"q":"What is the capital city of Thailand?","a":"Bangkok","o":["Bangkok","Baku","Ulaanbaatar","Tehran"],"f":"Bangkok is the capital of Thailand.","kind":"capital"},{"q":"Which of these flags belongs to Thailand?","a":"THA","o":["THA","UZB","LBN","IDN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Thailand.","kind":"flag"}],"hard":[{"q":"The kingdom of Sukhothai, in the 1200s, is often treated as the start of which tradition?","a":"A Thai Buddhist kingdom","o":["A Thai Buddhist kingdom","The Khmer empire","The Malacca sultanate","The Nguyen dynasty"],"f":"Sukhothai's kings patronized Theravada Buddhism. Its old city is a UNESCO park of lotus-bud towers."},{"q":"Muay Thai uses fists, feet, and which two other limbs?","a":"Elbows and knees","o":["Elbows and knees","Head and shoulder","Only feet","Sticks"],"f":"The sport grew from older battlefield arts. A traditional match begins with a dance, the wai khru."},{"q":"Which silk of the northeast, with ikat patterns, is a famous village craft?","a":"Mudmee silk","o":["Mudmee silk","Songket","Batik","Kente"],"f":"Mudmee ties the threads before dyeing. Villages in Isan still weave it on hand looms."},{"q":"Which of these cities is the capital of Thailand?","a":"Bangkok","o":["Bangkok","Chiang Mai","Phuket","Nakhon Ratchasima"],"f":"Bangkok is the capital of Thailand.","kind":"capital"},{"q":"Which flag is the flag of Thailand?","a":"THA","o":["THA","CRI","LCA","AGO"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Thailand.","kind":"flag"}]}},{"id":"TJK","name":"Tajikistan","cont":"Asia","emoji":"🇹🇯","latlng":[39,71],"q":{"easy":[{"q":"Which high mountains in the east are often called the roof of the world?","a":"The Pamirs","o":["The Pamirs","The Tian Shan only","The Altai","The Caucasus"],"f":"Much of the Pamir knot lies in Tajikistan. The Pamir Highway crosses high plateaus."},{"q":"Which rice dish with lamb and carrots is the celebration meal?","a":"Plov","o":["Plov","Osh is another name","Laghman","Manti"],"f":"Plov is cooked in a kazan, a wide pot. Chickpeas and garlic often go in."},{"q":"Which turquoise lake in the Fann Mountains is a famous trek destination?","a":"Iskanderkul","o":["Iskanderkul","Issyk-Kul","Karakul","Sarez"],"f":"Iskanderkul is named for Alexander. A waterfall drains the lake toward the Zeravshan valley."},{"q":"Which city is the capital of Tajikistan?","a":"Dushanbe","o":["Dushanbe","Lomé","Bamako","Zagreb"],"f":"Dushanbe is the capital of Tajikistan.","kind":"capital"},{"q":"Which flag belongs to Tajikistan?","a":"TJK","o":["TJK","TUV","BHS","BEL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Tajikistan.","kind":"flag"}],"medium":[{"q":"Which poet of the Samanid court, from the Panjakent area, is remembered as a founder of classical Persian verse?","a":"Rudaki","o":["Rudaki","Ferdowsi","Hafez","Omar Khayyam"],"f":"He lived in the 9th and 10th centuries, and only a fraction of his poems survive. The tomb honored today is at Panjrud, near Panjakent. Ferdowsi, Hafez, and Khayyam came later, in lands of present-day Iran."},{"q":"In the high Yaghnob valley, a small community still speaks a living descendant of which ancient language of the Silk Road?","a":"Sogdian","o":["Sogdian","Tocharian","Elamite","Hittite"],"f":"Sogdian merchants once ran caravans from Samarkand to China. Yaghnobi is the main tongue that still descends from it. Tocharian was spoken in the Tarim Basin and is extinct."},{"q":"The country's highest peak, in the Pamirs, was renamed for a 9th-century ruler who patronized Persian learning. Who?","a":"Ismail Samani","o":["Ismail Samani","Timur","Babur","Cyrus"],"f":"Soviet maps called it Stalin Peak and then Communism Peak. Ismail Samani's own tomb is in Bukhara, across the border in Uzbekistan. The Pamirs themselves are nicknamed the Roof of the World."},{"q":"What is the capital city of Tajikistan?","a":"Dushanbe","o":["Dushanbe","Bishkek","Ulaanbaatar","Islamabad"],"f":"Dushanbe is the capital of Tajikistan.","kind":"capital"},{"q":"Which of these flags belongs to Tajikistan?","a":"TJK","o":["TJK","VNM","SAU","MMR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Tajikistan.","kind":"flag"}],"hard":[{"q":"The poet Rudaki, often called the father of Persian verse, is linked to which early court?","a":"The Samanid court","o":["The Samanid court","The Mughal court","The Ottoman court","The Tang court"],"f":"Rudaki worked in the 900s. The Samanid mausoleum in Bukhara belongs to the same era of Persian revival."},{"q":"Which wild mountain sheep with huge spiral horns is a national symbol?","a":"The Marco Polo sheep","o":["The Marco Polo sheep","The argali only of Mongolia","The ibex of the Alps","The mouflon"],"f":"Marco Polo sheep graze the eastern Pamirs. Their horns can spread more than a meter."},{"q":"The ancient city of Panjakent, with Sogdian murals, lies near which modern border?","a":"The border with Uzbekistan","o":["The border with Uzbekistan","The border with China","The border with Afghanistan only in the Wakhan","The Caspian"],"f":"Sogdian merchants ran the Silk Road towns. Panjakent's paintings show banquets and gods."},{"q":"Which of these cities is the capital of Tajikistan?","a":"Dushanbe","o":["Dushanbe","Khujand","Bokhtar","Kulob"],"f":"Dushanbe is the capital of Tajikistan.","kind":"capital"},{"q":"Which flag is the flag of Tajikistan?","a":"TJK","o":["TJK","BGR","IRN","HUN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Tajikistan.","kind":"flag"}]}},{"id":"TKM","name":"Turkmenistan","cont":"Asia","emoji":"🇹🇲","latlng":[40,60],"q":{"easy":[{"q":"Which ancient Silk Road city of ruined mud brick is a UNESCO site in the east?","a":"Merv","o":["Merv","Nisa","Konye-Urgench","Urgench"],"f":"Merv was one of the great cities of the Islamic world until the Mongols sacked it in 1221."},{"q":"Which cold yogurt soup with herbs and dumplings is a summer dish?","a":"Dograma","o":["Dograma","Plov","Shashlik","Laghman"],"f":"Dograma mixes torn bread, yogurt, and herbs. It cools a hot desert afternoon."},{"q":"Which black-sand desert covers most of the country?","a":"The Karakum","o":["The Karakum","The Kyzylkum","The Gobi","The Taklamakan"],"f":"The Karakum, the black sand, stretches from the Kopet Dag to the Amu Darya."},{"q":"Which city is the capital of Turkmenistan?","a":"Ashgabat","o":["Ashgabat","Djibouti","Andorra la Vella","Majuro"],"f":"Ashgabat is the capital of Turkmenistan.","kind":"capital"},{"q":"Which flag belongs to Turkmenistan?","a":"TKM","o":["TKM","CRI","DNK","ERI"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Turkmenistan.","kind":"flag"}],"medium":[{"q":"A gas crater in the Karakum collapsed and was set alight in 1971. It became known by what nickname?","a":"The Door to Hell","o":["The Door to Hell","The Gates of Hell at Hierapolis","The Flaming Cliffs","The Eternal Flame of Yanar Dag"],"f":"Drillers hit a cavity, the ground fell in, and they lit the escaping gas expecting a short burn. It burned for decades. The Gates of Hell at Hierapolis are a Roman site in Türkiye, and the Flaming Cliffs are in Mongolia."},{"q":"A desert horse with a metallic golden coat, bred for endurance, is the breed this country prizes above others. What is it called?","a":"The Akhal-Teke","o":["The Akhal-Teke","The Arabian","The Przewalski","The Andalusian"],"f":"The shine comes from the structure of the hair, not from dye. These were the horses of Turkmen riders for centuries. Przewalski's horse is the wild horse of the Mongolian steppe."},{"q":"Merv, a UNESCO city of the Silk Road in the Margiana oasis, was destroyed in 1221 by which army?","a":"The Mongols","o":["The Mongols","The Romans","Alexander's Macedonians","The Ottomans"],"f":"Writers of the time described Merv as one of the largest cities on Earth. The Mongol attack is remembered as unusually destructive. Alexander had passed through many centuries earlier, and the city recovered."},{"q":"What is the capital city of Turkmenistan?","a":"Ashgabat","o":["Ashgabat","Sana'a","Kuwait City","Bangkok"],"f":"Ashgabat is the capital of Turkmenistan.","kind":"capital"},{"q":"Which of these flags belongs to Turkmenistan?","a":"TKM","o":["TKM","SAU","PHL","KAZ"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Turkmenistan.","kind":"flag"}],"hard":[{"q":"The Akhal-Teke, a national horse, is famous for which metallic coat?","a":"A golden sheen","o":["A golden sheen","Spots","Stripes","A draft build"],"f":"The breed was developed by desert horse people. The coat can look like polished metal."},{"q":"Which ruined capital of Khwarezm, with a tall minaret, stands near the Uzbek border?","a":"Konye-Urgench","o":["Konye-Urgench","Merv","Nisa","Balkh"],"f":"Kutlug Timur's minaret rises over the old city. UNESCO lists Konye-Urgench."},{"q":"Carpets of the Turkmen tribes use which repeated geometric motif?","a":"The gul","o":["The gul","The boteh","The dragon","The rose"],"f":"Each tribe had a gul, an octagonal emblem. The rugs are still a point of identity."},{"q":"Which of these cities is the capital of Turkmenistan?","a":"Ashgabat","o":["Ashgabat","Türkmenabat","Daşoguz","Mary"],"f":"Ashgabat is the capital of Turkmenistan.","kind":"capital"},{"q":"Which flag is the flag of Turkmenistan?","a":"TKM","o":["TKM","MMR","SOM","BRB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Turkmenistan.","kind":"flag"}]}},{"id":"TLS","name":"Timor-Leste","cont":"Asia","emoji":"🇹🇱","latlng":[-8.83333333,125.91666666],"q":{"easy":[{"q":"Which hilltop statue of Christ stands above the bay of the capital?","a":"Cristo Rei","o":["Cristo Rei","Christ the Redeemer","The Corcovado statue","Cristo de la Concordia"],"f":"Cristo Rei was built in the 1990s on a cape east of Dili. It looks over the Wetar Strait."},{"q":"Which coffee, grown in the cool highlands, is a historic export?","a":"Arabica coffee","o":["Arabica coffee","Robusta only","Tea","Cocoa"],"f":"Coffee was planted under Portuguese rule. Beans from the hills remain a small but famous crop."},{"q":"Which uninhabited island at the eastern tip is treated as sacred?","a":"Jaco Island","o":["Jaco Island","Atauro","Wetar","Alor"],"f":"Visitors are asked not to stay overnight. The island closes the eastern end of the mainland."},{"q":"Which city is the capital of Timor-Leste?","a":"Dili","o":["Dili","Lilongwe","San José","Conakry"],"f":"Dili is the capital of Timor-Leste.","kind":"capital"},{"q":"Which flag belongs to Timor-Leste?","a":"TLS","o":["TLS","EST","SSD","COL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Timor-Leste.","kind":"flag"}],"medium":[{"q":"Who, born in Dili, shared the 1996 Nobel Peace Prize for work toward a peaceful end to the occupation?","a":"José Ramos-Horta","o":["José Ramos-Horta","Xanana Gusmão","Mari Alkatiri","Nicolau Lobato"],"f":"He shared the prize with Bishop Carlos Filipe Ximenes Belo. Xanana Gusmão led the armed resistance. Nicolau Lobato was killed in 1978, before the prize existed."},{"q":"After Portugal withdrew in 1975, which country occupied the territory until a 1999 referendum?","a":"Indonesia","o":["Indonesia","Australia","The Netherlands","Japan"],"f":"Indonesia invaded in December 1975. A United Nations mission then ran the transition, and independence was restored on 20 May 2002. Japan had occupied the island only during the Second World War."},{"q":"Handwoven ceremonial cloth, with patterns that differ by region, was inscribed by UNESCO in 2021. What is it called?","a":"Tais","o":["Tais","Batik","Songket","Ikat of Sumba"],"f":"Tais is given at weddings and funerals. The method is a form of ikat, but the local name and the motifs are distinct. Sumba is an Indonesian island with its own ikat tradition."},{"q":"What is the capital city of Timor-Leste?","a":"Dili","o":["Dili","Beirut","Sri Jayawardenepura Kotte","Manama"],"f":"Dili is the capital of Timor-Leste.","kind":"capital"},{"q":"Which of these flags belongs to Timor-Leste?","a":"TLS","o":["TLS","AFG","BHR","KWT"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Timor-Leste.","kind":"flag"}],"hard":[{"q":"Sandalwood from the island drew traders from China and Europe for centuries. The wood was burned as what?","a":"Incense","o":["Incense","Food","Dye only","Medicine only"],"f":"White sandalwood was one of the most valuable woods in the Indian Ocean trade."},{"q":"Which offshore island is known for reefs and a saltwater lake?","a":"Atauro","o":["Atauro","Jaco","Alor","Wetar"],"f":"Atauro sits north of Dili. Divers visit its reefs. A raised lake, not a true marine lake of jellyfish fame, is sometimes confused with it; the reefs are the real draw."},{"q":"Fataluku and Tetun are among the local languages. Tetun is an official language alongside which European one?","a":"Portuguese","o":["Portuguese","Spanish","Dutch","English only"],"f":"Portuguese returned as an official language after independence. Indonesian is still widely understood."},{"q":"Which of these cities is the capital of Timor-Leste?","a":"Dili","o":["Dili","Baucau","Maliana","Suai"],"f":"Dili is the capital of Timor-Leste.","kind":"capital"},{"q":"Which flag is the flag of Timor-Leste?","a":"TLS","o":["TLS","CHE","WSM","BLR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Timor-Leste.","kind":"flag"}]}},{"id":"TON","name":"Tonga","cont":"Oceania","emoji":"🇹🇴","latlng":[-20,-175],"q":{"easy":[{"q":"Which blowholes and a trilithon of coral stone are famous sights?","a":"The Mapu a Vaea blowholes and the Ha'amonga","o":["The Mapu a Vaea blowholes and the Ha'amonga","Stonehenge","Nan Madol","A marae"],"f":"The Ha'amonga a Maui is a coral-stone gateway. The blowholes of Tongatapu shoot water at high tide."},{"q":"Which roast pig and root crops from an earth oven are feast food?","a":"An umu","o":["An umu","A hangi","A mumu","A luau"],"f":"Sunday umu after church is a family pattern. Taro, yam, and lu pulu of corned beef in taro leaves are common."},{"q":"Which kind of hereditary ruler is among the oldest continuous ones in the Pacific?","a":"A kingship","o":["A kingship","A presidency","A council of chiefs only","A colonial governor"],"f":"Tonga was never formally colonized. The current royal line was constituted in the 1800s by George Tupou I."},{"q":"Which city is the capital of Tonga?","a":"Nuku'alofa","o":["Nuku'alofa","Kuwait City","Port-au-Prince","Dakar"],"f":"Nuku'alofa is the capital of Tonga.","kind":"capital"},{"q":"Which flag belongs to Tonga?","a":"TON","o":["TON","CAN","CUB","MDV"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Tonga.","kind":"flag"}],"medium":[{"q":"Tonga kept its own monarchy and, unlike most Pacific islands, was never what?","a":"Annexed as a colony","o":["Annexed as a colony","Visited by Europeans","Converted to Christianity","Drawn on a map"],"f":"It was a British protected state from 1900 to 1970, but it was not taken over as a colony. The royal line continued throughout."},{"q":"The Ha'amonga 'a Maui, a coral-stone gateway on Tongatapu, is often nicknamed the Polynesian what?","a":"Stonehenge","o":["Stonehenge","Colosseum","Parthenon","Great Wall"],"f":"Two uprights support a lintel. Tradition credits the hero Maui, and a king is thought to have raised it around the 1200s."},{"q":"At a formal Tongan welcome the highest-ranking guest is served first with which pepper-root drink?","a":"Kava","o":["Kava","Mate","Sake","Mead"],"f":"The cup is passed in silence, and a set pattern of clapping is part of the etiquette. Kava is not alcoholic."},{"q":"What is the capital city of Tonga?","a":"Nuku'alofa","o":["Nuku'alofa","Port Vila","Yaren","Canberra"],"f":"Nuku'alofa is the capital of Tonga.","kind":"capital"},{"q":"Which of these flags belongs to Tonga?","a":"TON","o":["TON","KIR","MHL","WSM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Tonga.","kind":"flag"}],"hard":[{"q":"Captain Cook called the islands the Friendly Islands after a visit in which decade?","a":"The 1770s","o":["The 1770s","The 1640s","The 1800s","The 1900s"],"f":"Cook landed in 1773 and 1777. A planned attack did not happen, and the friendly name stuck."},{"q":"Which bark cloth, beaten from paper mulberry, is a ceremonial wealth?","a":"Ngatu","o":["Ngatu","Tapa of only Samoa","Kapa","Masi"],"f":"Women beat and paste the cloth, then rub brown patterns onto it. It is given at weddings and funerals."},{"q":"The map of the kingdom includes which far northern islands of coral?","a":"The Niuas","o":["The Niuas","The Ha'apai only","The Vava'u only","Tongatapu only"],"f":"Niuatoputapu and Niuafo'ou lie far closer to Samoa than to the main island. Niuafo'ou is a volcanic crater."},{"q":"Which of these cities is the capital of Tonga?","a":"Nuku'alofa","o":["Nuku'alofa","Neiafu","Pangai","Mu'a"],"f":"Nuku'alofa is the capital of Tonga.","kind":"capital"},{"q":"Which flag is the flag of Tonga?","a":"TON","o":["TON","IRQ","COD","MHL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Tonga.","kind":"flag"}]}},{"id":"TTO","name":"Trinidad and Tobago","cont":"North America","emoji":"🇹🇹","latlng":[11,-61],"q":{"easy":[{"q":"Which street food of chickpea curry in a fried wrap is a national snack?","a":"Doubles","o":["Doubles","Roti","Aloo pie","Bake and shark"],"f":"Doubles are two pieces of bara bread with curried channa. They are eaten at breakfast stands."},{"q":"Which pitch lake, a natural asphalt seep, is a famous geological site?","a":"The Pitch Lake","o":["The Pitch Lake","Lake Asphaltitis","The La Brea tar pits of California","Guanoco"],"f":"The Pitch Lake at La Brea has been mined for centuries. Walter Raleigh caulked ships with the tar."},{"q":"Which pre-Lenten festival of steelpan and costume is among the largest in the region?","a":"Carnival","o":["Carnival","Crop Over","Junkanoo","Mashramani"],"f":"Steelpans were invented here from oil drums in the 1900s. Carnival peaks on the two days before Ash Wednesday."},{"q":"Which city is the capital of Trinidad and Tobago?","a":"Port of Spain","o":["Port of Spain","Luanda","Sofia","Madrid"],"f":"Port of Spain is the capital of Trinidad and Tobago.","kind":"capital"},{"q":"Which flag belongs to Trinidad and Tobago?","a":"TTO","o":["TTO","EST","HUN","LTU"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Trinidad and Tobago.","kind":"flag"}],"medium":[{"q":"Which writer, born in Chaguanas, won the 2001 Nobel Prize in Literature?","a":"V. S. Naipaul","o":["V. S. Naipaul","Derek Walcott","Samuel Selvon","C. L. R. James"],"f":"A House for Mr Biswas draws on his father's life in Trinidad. Walcott, a later Nobel laureate, was born in St. Lucia. Selvon and James were Trinidadian but did not win the prize."},{"q":"The steelpan was invented in Trinidad in the 20th century by tuning the tops of what discarded objects?","a":"Oil drums","o":["Oil drums","Church bells","Ship anchors","Bamboo stalks"],"f":"After bans on African drums, players first used bamboo, then metal. Tuners hammer each pan into separate notes. UNESCO lists the tradition."},{"q":"The Pitch Lake at La Brea is the world's largest natural deposit of what?","a":"Asphalt","o":["Asphalt","Obsidian","Rock salt","Amber"],"f":"Parts of the surface can be walked on, and softer patches slowly swallow heavy objects. Walter Raleigh caulked his ships with the pitch in 1595."},{"q":"What is the capital city of Trinidad and Tobago?","a":"Port of Spain","o":["Port of Spain","Belmopan","Ottawa","Kingston"],"f":"Port of Spain is the capital of Trinidad and Tobago.","kind":"capital"},{"q":"Which of these flags belongs to Trinidad and Tobago?","a":"TTO","o":["TTO","LCA","SLV","DOM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Trinidad and Tobago.","kind":"flag"}],"hard":[{"q":"Which novelist, born in 1935, wrote The Dragon Can't Dance about carnival life in the capital?","a":"Earl Lovelace","o":["Earl Lovelace","Samuel Selvon","C. L. R. James","Derek Walcott"],"f":"Lovelace also wrote The Wine of Astonishment, about a Spiritual Baptist community. The carnival novel follows one neighborhood."},{"q":"Which ship brought the first indentured workers from India in 1845?","a":"The Fatel Razack","o":["The Fatel Razack","The Empire Windrush","The Mayflower","The HMS Beagle"],"f":"The Fatel Razack landed in May 1845. Indenture replaced enslaved labor on the sugar estates."},{"q":"Which scarlet ibis of the Caroni swamp is the national bird?","a":"The scarlet ibis","o":["The scarlet ibis","The flamingo","The parrot","The hummingbird"],"f":"Flocks roost in the mangroves at dusk. The ibis shares the coat of arms with the cocrico of Tobago."},{"q":"Which of these cities is the capital of Trinidad and Tobago?","a":"Port of Spain","o":["Port of Spain","San Fernando","Scarborough","Chaguanas"],"f":"Port of Spain is the capital of Trinidad and Tobago.","kind":"capital"},{"q":"Which flag is the flag of Trinidad and Tobago?","a":"TTO","o":["TTO","CZE","LSO","SOM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Trinidad and Tobago.","kind":"flag"}]}},{"id":"TUN","name":"Tunisia","cont":"Africa","emoji":"🇹🇳","latlng":[34,9],"q":{"easy":[{"q":"Which vast salt flat in the south sometimes floods and is famous for mirages?","a":"Chott el Djerid","o":["Chott el Djerid","Chott el Gharsa","Lake Ichkeul","The Gulf of Gabes"],"f":"The chott is a shallow salt lake that dries to a white crust. Film crews have used that pale surface."},{"q":"Which semolina dish with pepper sauce and egg is a everyday favorite?","a":"Couscous","o":["Couscous","Sushi","Paella","Poutine"],"f":"Tunisian couscous is often spicier than its neighbors, with harissa chili paste on the side."},{"q":"Which blue-and-white seaside village on the Mediterranean is a famous resort island town?","a":"Sidi Bou Said","o":["Sidi Bou Said","Chefchaouen","Santorini","Cinque Terre"],"f":"Sidi Bou Said's blue doors and white walls look over the Gulf of Tunis."},{"q":"Which city is the capital of Tunisia?","a":"Tunis","o":["Tunis","Lima","New Delhi","Sana'a"],"f":"Tunis is the capital of Tunisia.","kind":"capital"},{"q":"Which flag belongs to Tunisia?","a":"TUN","o":["TUN","GTM","RUS","MNG"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Tunisia.","kind":"flag"}],"medium":[{"q":"Which historian, born in Tunis in 1332, wrote the Muqaddimah on how states rise and fall?","a":"Ibn Khaldun","o":["Ibn Khaldun","Ibn Battuta","Ibn Sina","Averroes"],"f":"He served courts from Fez to Cairo and looked for patterns, not just chronicles. Ibn Battuta was the traveler from Tangier. Ibn Sina was the physician from near Bukhara. Averroes worked in Córdoba."},{"q":"Hannibal set out with elephants to cross the Alps against Rome from which city?","a":"Carthage","o":["Carthage","Leptis Magna","Alexandria","Utica"],"f":"The city stood near today's Tunis and fought Rome in three Punic Wars. Rome destroyed it in 146 BCE and later built a Roman town on the ruins. Leptis Magna is in Libya. Utica was a neighbor and a rival, not his base."},{"q":"The Roman amphitheater at El Jem, in the inland town once called Thysdrus, held about how many people?","a":"About 35,000","o":["About 35,000","About 3,500","About 350,000","About 350"],"f":"It was built in the 3rd century and is one of the largest amphitheaters anywhere. Rome's Colosseum is bigger. A great deal of the El Jem structure is still standing."},{"q":"What is the capital city of Tunisia?","a":"Tunis","o":["Tunis","Mogadishu","Gitega","Maseru"],"f":"Tunis is the capital of Tunisia.","kind":"capital"},{"q":"Which of these flags belongs to Tunisia?","a":"TUN","o":["TUN","NER","MRT","GMB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Tunisia.","kind":"flag"}],"hard":[{"q":"Which writer, born in Tunis in 1920, wrote The Pillar of Salt about growing up under colonial rule?","a":"Albert Memmi","o":["Albert Memmi","Albert Camus","Assia Djebar","Tahar Ben Jelloun"],"f":"Memmi also wrote The Colonizer and the Colonized, an essay that later scholars quoted widely."},{"q":"The amphitheater of El Jem was built for which Roman spectacle?","a":"Gladiator games","o":["Gladiator games","Greek tragedy only","Opera","Polo"],"f":"El Jem's amphitheater is one of the largest Roman arenas still standing, in a town far from Rome."},{"q":"Harissa, the chili paste, is pounded from peppers, garlic, and which spice?","a":"Caraway and coriander","o":["Caraway and coriander","Vanilla","Saffron only","Cinnamon only"],"f":"Families grind their own harissa. It seasons couscous, eggs, and sandwiches."},{"q":"Which of these cities is the capital of Tunisia?","a":"Tunis","o":["Tunis","Sfax","Sousse","Kairouan"],"f":"Tunis is the capital of Tunisia.","kind":"capital"},{"q":"Which flag is the flag of Tunisia?","a":"TUN","o":["TUN","TUR","PAK","DZA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Tunisia.","kind":"flag"}]}},{"id":"TUR","name":"Türkiye","cont":"Asia","emoji":"🇹🇷","latlng":[39,35],"q":{"easy":[{"q":"Which region of cave churches and cone-shaped rocks is in central Anatolia?","a":"Cappadocia","o":["Cappadocia","Pamukkale","Ephesus","Troy"],"f":"Soft volcanic tuff was carved into houses and churches. Hot-air balloons fly over the valleys at dawn."},{"q":"Which grilled meat on a vertical spit, sliced into bread, is a city staple?","a":"Doner kebab","o":["Doner kebab","Shish kebab","Adana kebab","Iskender"],"f":"Doner is stacked meat roasted on a turning spit. Iskender in Bursa serves it over bread with tomato and yogurt."},{"q":"Which great covered market in Istanbul has sold carpets and jewelry for centuries?","a":"The Grand Bazaar","o":["The Grand Bazaar","The Spice Bazaar only","Mutrah","Khan el-Khalili"],"f":"The Grand Bazaar grew from a market of the 1400s. Dozens of streets still sit under vaulted roofs."},{"q":"Which city is the capital of Türkiye?","a":"Ankara","o":["Ankara","St. John's","Maseru","Kingstown"],"f":"Ankara is the capital of Türkiye.","kind":"capital"},{"q":"Which flag belongs to Türkiye?","a":"TUR","o":["TUR","KEN","LTU","HND"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Türkiye.","kind":"flag"}],"medium":[{"q":"Mustafa Kemal led the war of independence and died in 1938. In 1934 parliament gave him which surname?","a":"Atatürk","o":["Atatürk","Inönü","Karabekir","Orbay"],"f":"Atatürk means father of the Turks. He was born in Salonica, now in Greece, not in Anatolia. Ismet Inönü, who succeeded him, received a different surname under the same 1934 law."},{"q":"Göbekli Tepe, in the southeast, was built around 9600 BCE. Its builders were still what?","a":"Hunter-gatherers","o":["Hunter-gatherers","Pottery-making farmers","Bronze-smithing townsfolk","Chariot armies"],"f":"The T-shaped pillars went up before pottery was in use here, and before farming was thought to come first. The site is thousands of years older than Stonehenge or the pyramids."},{"q":"Justinian's great domed church, in what is now Istanbul, was completed in 537. What is it called?","a":"Hagia Sophia","o":["Hagia Sophia","The Blue Mosque","The Süleymaniye Mosque","The Chora Church"],"f":"Anthemius of Tralles and Isidore of Miletus were its architects. The Blue Mosque and the Süleymaniye were built in Ottoman centuries. The building's legal status has changed more than once since 1453, so the question is about the 6th-century church."},{"q":"What is the capital city of Türkiye?","a":"Ankara","o":["Ankara","Hanoi","Bandar Seri Begawan","Kabul"],"f":"Ankara is the capital of Türkiye.","kind":"capital"},{"q":"Which of these flags belongs to Türkiye?","a":"TUR","o":["TUR","GEO","SAU","BGD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Türkiye.","kind":"flag"}],"hard":[{"q":"The archaeological site of Gobekli Tepe, with carved pillars, dates from about which era?","a":"The 10th millennium BCE","o":["The 10th millennium BCE","The Roman era","The Bronze Age only","The Ottoman era"],"f":"The pillars were raised by hunter-gatherers before farming villages were common. The site is in southeastern Turkey."},{"q":"Which whirling ceremony of the Mevlevi order began in Konya?","a":"The sema","o":["The sema","A dabke","A hora","A tango"],"f":"Followers of Rumi turn in long white robes. The sema is a form of remembrance, not a stage show by origin."},{"q":"The city of Ephesus holds a library facade built for whom?","a":"Celsus","o":["Celsus","Alexander","Hadrian only as a temple","Trajan"],"f":"The Library of Celsus was completed in the 100s CE. Its facade was rebuilt in the 20th century."},{"q":"Which of these cities is the capital of Türkiye?","a":"Ankara","o":["Ankara","Istanbul","Izmir","Antalya"],"f":"Ankara is the capital of Türkiye.","kind":"capital"},{"q":"Which flag is the flag of Türkiye?","a":"TUR","o":["TUR","PAK","DZA","TUN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Türkiye.","kind":"flag"}]}},{"id":"TUV","name":"Tuvalu","cont":"Oceania","emoji":"🇹🇻","latlng":[-8,178],"q":{"easy":[{"q":"What kind of island holds the villages, a thin ribbon around a lagoon?","a":"A low coral atoll","o":["A low coral atoll","A high volcanic cone","A continental shelf","A river delta"],"f":"Villages sit on the lagoon side. The widest point is only a few hundred meters."},{"q":"Which giant swamp taro is grown in pits dug to the freshwater lens?","a":"Pulaka","o":["Pulaka","Taro of dry fields","Rice","Breadfruit only"],"f":"Pulaka pits are lined and mulched. The root is a prestige food and a climate worry as saltwater rises."},{"q":"Which traditional song and fatele dance fill community halls?","a":"The fatele","o":["The fatele","The haka","The meke","The siva"],"f":"Fatele uses a wooden box drum and accelerating songs. It is the lively dance of weddings and welcomes."},{"q":"Which city is the capital of Tuvalu?","a":"Funafuti","o":["Funafuti","São Tomé","Seoul","Warsaw"],"f":"Funafuti is the capital of Tuvalu.","kind":"capital"},{"q":"Which flag belongs to Tuvalu?","a":"TUV","o":["TUV","SUR","SYR","NGA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Tuvalu.","kind":"flag"}],"medium":[{"q":"Tuvalu means eight standing together. Why was the ninth island, Nui, left out of that count?","a":"Its people spoke a different language","o":["Its people spoke a different language","It is an underwater volcano","It belongs to Fiji","It was found only by aircraft"],"f":"Nui's speech is a Micronesian language related to Gilbertese. The other islands are Polynesian, so early groupings skipped Nui."},{"q":"Before it chose the name Tuvalu, Europeans knew the group as which islands?","a":"The Ellice Islands","o":["The Ellice Islands","The Gilbert Islands","The Line Islands","The Phoenix Islands"],"f":"The name honored Alexander Ellice, owner of a British ship. Islanders voted to separate from the Gilberts and became independent in 1978."},{"q":"Funafuti and the other inhabited islands are coral atolls sitting only a few meters above what?","a":"High tide","o":["High tide","The snow line","The tree line","A desert plateau"],"f":"There is almost no high ground. King tides already wash across parts of Funafuti, so rising seas are an immediate local threat."},{"q":"What is the capital city of Tuvalu?","a":"Funafuti","o":["Funafuti","Wellington","Yaren","Apia"],"f":"Funafuti is the capital of Tuvalu.","kind":"capital"},{"q":"Which of these flags belongs to Tuvalu?","a":"TUV","o":["TUV","TON","WSM","PLW"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Tuvalu.","kind":"flag"}],"hard":[{"q":"The name Tuvalu means what in the language?","a":"Eight standing together","o":["Eight standing together","Nine islands","The friendly isles","The navigator isles"],"f":"Eight of the nine atolls were traditionally counted. The word is often explained as eight together."},{"q":"Which institution, the main denomination since the 1800s, shapes Sunday life?","a":"The main Protestant church","o":["The main Protestant church","A state mosque","A Hindu temple","A chiefly cult only"],"f":"Samoan pastors brought the London Missionary Society faith. Church choirs are a center of village life."},{"q":"The country's internet domain became famous for what kind of sales?","a":"Selling the .tv name","o":["Selling the .tv name","Phosphate","Pearls","Stamps only"],"f":"The suffix .tv was leased to a company. The fees became a meaningful part of a tiny budget."},{"q":"Which of these cities is the capital of Tuvalu?","a":"Funafuti","o":["Funafuti","Vaitupu","Nanumea","Nukufetau"],"f":"Funafuti is the capital of Tuvalu.","kind":"capital"},{"q":"Which flag is the flag of Tuvalu?","a":"TUV","o":["TUV","FJI","NZL","AUS"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Tuvalu.","kind":"flag"}]}},{"id":"TZA","name":"Tanzania","cont":"Africa","emoji":"🇹🇿","latlng":[-6,35],"q":{"easy":[{"q":"Which snow-capped mountain is the highest in Africa?","a":"Mount Kilimanjaro","o":["Mount Kilimanjaro","Mount Kenya","Mount Cameroon","Ras Dashen"],"f":"Kilimanjaro stands near the Kenyan border. Its highest point is Uhuru Peak on the Kibo crater."},{"q":"Which grilled meat and banana dishes of the coast mix African, Arab, and Indian tastes?","a":"Mishkaki and pilau","o":["Mishkaki and pilau","Sushi","Poutine","Fondue"],"f":"Mishkaki are meat skewers. Zanzibar pilau uses cloves, cinnamon, and rice."},{"q":"Which island Stone Town of carved doors was an Omani Indian-Ocean capital?","a":"Zanzibar","o":["Zanzibar","Lamu","Mombasa","Mozambique Island"],"f":"Stone Town's old palaces and the old slave market recall the clove and ivory trade."},{"q":"Which city is the official capital of Tanzania?","a":"Dodoma","o":["Dodoma","Moscow","Caracas","Bishkek"],"f":"Dodoma is the official capital. Dar es Salaam is the largest city and a former capital.","kind":"capital"},{"q":"Which flag belongs to Tanzania?","a":"TZA","o":["TZA","KHM","HND","ECU"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Tanzania.","kind":"flag"}],"medium":[{"q":"Farrokh Bulsara, later Freddie Mercury, was born in 1946 in which place?","a":"Stone Town, Zanzibar","o":["Stone Town, Zanzibar","Dar es Salaam","Nairobi","Mombasa"],"f":"His family was Parsi, from India, and lived in Zanzibar for work. He went to school in India and later formed Queen in Britain. He was not born in London."},{"q":"The highest point on Kilimanjaro, Africa's highest mountain, is called what?","a":"Uhuru Peak","o":["Uhuru Peak","Batian","Margherita Peak","Mawenzi"],"f":"Uhuru means freedom in Swahili. Mawenzi is the jagged secondary summit of the same volcano. Batian is the top of Mount Kenya. Margherita is in the Rwenzori, on the Uganda border."},{"q":"Olduvai Gorge became famous because Mary and Louis Leakey found what there?","a":"Early human fossils and stone tools","o":["Early human fossils and stone tools","Dinosaur eggs only","A pharaoh's tomb","A hoard of Roman coins"],"f":"Mary Leakey found the Zinjanthropus skull in 1959. Footprints at nearby Laetoli show early relatives walking upright. The gorge is lake sediment, not a royal cemetery."},{"q":"What is the official capital city of Tanzania?","a":"Dodoma","o":["Dodoma","Luanda","Cairo","Yamoussoukro"],"f":"Dodoma is the official capital. Dar es Salaam is the largest city and a former capital.","kind":"capital"},{"q":"Which of these flags belongs to Tanzania?","a":"TZA","o":["TZA","COG","MUS","SSD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Tanzania.","kind":"flag"}],"hard":[{"q":"Olduvai Gorge, in the Ngorongoro region, is famous for fossils of what?","a":"Early humans and stone tools","o":["Early humans and stone tools","Dinosaurs only","Roman coins","Viking ships"],"f":"Louis and Mary Leakey found early human remains and tools in the gorge. It is a key site for human origins."},{"q":"The dhows of the Swahili coast sail with which triangular sail?","a":"A lateen sail","o":["A lateen sail","A square Viking sail","A steam paddle","A rotor"],"f":"Lateen sails let dhows work the monsoon. Boatbuilders still work on beaches such as Nungwi."},{"q":"Ujamaa, the policy of the 1960s and 1970s, moved rural people into what?","a":"Collective villages","o":["Collective villages","Ski towns","Houseboats","High-rise only"],"f":"President Julius Nyerere promoted shared farming villages. The policy was later relaxed."},{"q":"Which of these cities is the official capital of Tanzania?","a":"Dodoma","o":["Dodoma","Dar es Salaam","Arusha","Mwanza"],"f":"Dodoma is the official capital. Dar es Salaam is the largest city and a former capital.","kind":"capital"},{"q":"Which flag is the flag of Tanzania?","a":"TZA","o":["TZA","ETH","CAN","ARM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Tanzania.","kind":"flag"}]}},{"id":"UGA","name":"Uganda","cont":"Africa","emoji":"🇺🇬","latlng":[1,32],"q":{"easy":[{"q":"Which mountain range on the western border has glaciers and three peaks named for colonial figures?","a":"The Rwenzori","o":["The Rwenzori","Kilimanjaro","The Drakensberg","The Atlas"],"f":"The Rwenzori, the Mountains of the Moon, stand on the Congo border. Their peaks are wet, cold, and often in cloud."},{"q":"Which street snack is a chapati rolled around an egg?","a":"A rolex","o":["A rolex","A burrito","A shawarma","A dosa"],"f":"The name comes from rolled eggs. Stalls cook the chapati with egg and vegetables and sell it at night."},{"q":"Which lake, the largest in Africa, forms the southern border?","a":"Lake Victoria","o":["Lake Victoria","Lake Tanganyika","Lake Malawi","Lake Chad"],"f":"Lake Victoria is shared with Kenya and Tanzania. The Nile leaves it at Jinja."},{"q":"Which city is the capital of Uganda?","a":"Kampala","o":["Kampala","Sarajevo","Kabul","Basseterre"],"f":"Kampala is the capital of Uganda.","kind":"capital"},{"q":"Which flag belongs to Uganda?","a":"UGA","o":["UGA","ROU","PLW","ISL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Uganda.","kind":"flag"}],"medium":[{"q":"Green cooking bananas, steamed and mashed as the staple in the south, are called what?","a":"Matoke","o":["Matoke","Posho","Chapati","Rolex"],"f":"They are a savory variety, not the sweet fruit. Posho is maize porridge. Chapati came with the Indian Ocean trade, and a rolex is a chapati rolled around egg, a street snack, not the staple."},{"q":"Bwindi Impenetrable Forest is a UNESCO park famous for tracking which animals?","a":"Mountain gorillas","o":["Mountain gorillas","Bonobos","Orangutans","Giant pandas"],"f":"A large share of the remaining mountain gorillas live in Bwindi. Others live in the Virunga volcanoes of Rwanda and DR Congo. Bonobos live only west of the Congo River."},{"q":"In 1862 Speke reached the outlet of Lake Victoria at today's Jinja and named Ripon Falls. Those falls are now what?","a":"Under the water of a dam","o":["Under the water of a dam","Taller than in 1862","A dry canyon","A marine sanctuary"],"f":"The Owen Falls dam, now called Nalubaale, covered them. Speke's claim to have found the main source of the Nile was debated for years, but the outlet is real. The water still leaves the lake here."},{"q":"What is the capital city of Uganda?","a":"Kampala","o":["Kampala","Accra","Gitega","Kigali"],"f":"Kampala is the capital of Uganda.","kind":"capital"},{"q":"Which of these flags belongs to Uganda?","a":"UGA","o":["UGA","GHA","MUS","COG"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Uganda.","kind":"flag"}],"hard":[{"q":"The Buganda kingdom, still headed by a kabaka, has its parliament at which hill in Kampala?","a":"Mengo","o":["Mengo","Kololo","Old Kampala","Nakasero"],"f":"Buganda is a constitutionally recognized kingdom inside Uganda. The kabaka's court is at Mengo."},{"q":"Which bark-cloth craft of the Baganda, beaten from a fig tree, is listed by UNESCO?","a":"Bark cloth","o":["Bark cloth","Kente","Batik","Tartan"],"f":"Men beat the inner bark of the mutuba tree into a soft terracotta cloth once worn at court."},{"q":"Idi Amin's rule in the 1970s expelled which community of traders?","a":"People of South Asian origin","o":["People of South Asian origin","The Maasai","The Tuareg","The San"],"f":"In 1972 Asian Ugandans, many of them citizens, were given days to leave. Many later returned."},{"q":"Which of these cities is the capital of Uganda?","a":"Kampala","o":["Kampala","Gulu","Mbarara","Jinja"],"f":"Kampala is the capital of Uganda.","kind":"capital"},{"q":"Which flag is the flag of Uganda?","a":"UGA","o":["UGA","VNM","PHL","ATG"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Uganda.","kind":"flag"}]}},{"id":"UKR","name":"Ukraine","cont":"Europe","emoji":"🇺🇦","latlng":[49,32],"q":{"easy":[{"q":"Which cathedral of golden mosaics, begun in the 1000s, stands in Kyiv?","a":"Saint Sophia Cathedral","o":["Saint Sophia Cathedral","Saint Basil's","The Lavra caves only","Saint Isaac's"],"f":"Yaroslav the Wise founded Saint Sophia. Its mosaics and frescoes survive from Kyivan Rus."},{"q":"Which boiled dumplings with potato, cheese, or cherry are a home dish?","a":"Varenyky","o":["Varenyky","Pelmeni","Pierogi","Khinkali"],"f":"Varenyky are pinched closed and served with sour cream or fried onions. Sweet versions hold fruit."},{"q":"Which embroidered shirt is worn on feast days and as a national symbol?","a":"The vyshyvanka","o":["The vyshyvanka","The kimono","The kilt","The sari"],"f":"Patterns differ by region. A day in May is set aside for wearing the shirt."},{"q":"Which city is the capital of Ukraine?","a":"Kyiv","o":["Kyiv","Naypyidaw","Antananarivo","Riyadh"],"f":"Kyiv is the capital of Ukraine.","kind":"capital"},{"q":"Which flag belongs to Ukraine?","a":"UKR","o":["UKR","AFG","SYC","MOZ"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Ukraine.","kind":"flag"}],"medium":[{"q":"Which engineer, born in Zhytomyr in 1907, was the chief designer of the Soviet program that put the first satellite and the first person into space?","a":"Sergei Korolev","o":["Sergei Korolev","Wernher von Braun","Yuri Gagarin","Konstantin Tsiolkovsky"],"f":"His identity was kept secret during his life, and he was called only the chief designer. Gagarin was the pilot, not the engineer who built the rocket."},{"q":"On 26 April 1986 a reactor exploded at which nuclear plant north of Kyiv?","a":"Chernobyl","o":["Chernobyl","Zaporizhzhia","Fukushima","Three Mile Island"],"f":"A flawed test and a dangerous reactor design drove the explosion. A concrete and steel shelter now covers the ruined unit, and the exclusion zone remains."},{"q":"Pysanky are Easter eggs decorated by drawing a design in wax and dipping the egg in dye. The wax is used so that each layer does what?","a":"It protects the color underneath","o":["It protects the color underneath","It hardens the shell into porcelain","It adds the dye itself","It makes the egg edible"],"f":"The method is the same idea as batik. Traditional patterns include wheat, stars, and endless lines, and regions had their own symbols."},{"q":"What is the capital city of Ukraine?","a":"Kyiv","o":["Kyiv","Warsaw","London","Belgrade"],"f":"Kyiv is the capital of Ukraine.","kind":"capital"},{"q":"Which of these flags belongs to Ukraine?","a":"UKR","o":["UKR","BLR","ROU","VAT"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Ukraine.","kind":"flag"}],"hard":[{"q":"The Cossack host of the Dnieper rapids had its fortified camp called what?","a":"The Sich","o":["The Sich","The Kremlin","The Horde","The Bastion"],"f":"The Zaporozhian Sich was a self-governing camp of Cossacks. It shaped Ukrainian political memory."},{"q":"Which black-earth grain has made the country a historic breadbasket?","a":"Wheat","o":["Wheat","Rice","Rye only","Maize only"],"f":"The steppe soils are among the richest farmland. Wheat and sunflower fields cover huge areas."},{"q":"Pysanky are eggs decorated by writing with wax and dye. The word is related to what verb?","a":"To write","o":["To write","To bake","To hunt","To sail"],"f":"A stylus draws wax lines so each dye bath colors only the open shell. The eggs are an Easter art."},{"q":"Which of these cities is the capital of Ukraine?","a":"Kyiv","o":["Kyiv","Lviv","Odesa","Kharkiv"],"f":"Kyiv is the capital of Ukraine.","kind":"capital"},{"q":"Which flag is the flag of Ukraine?","a":"UKR","o":["UKR","KAZ","SWE","HUN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Ukraine.","kind":"flag"}]}},{"id":"URY","name":"Uruguay","cont":"South America","emoji":"🇺🇾","latlng":[-33,-56],"q":{"easy":[{"q":"Which beef-filled pastry and a grill of short ribs are everyday food?","a":"The empanada and asado","o":["The empanada and asado","Feijoada","Ceviche","Arepa"],"f":"A Uruguayan empanada is baked, with beef, egg, and olive. The asado is as central as in Argentina."},{"q":"Which old town on the Rio de la Plata has a famous theater and a rambla?","a":"Montevideo's Ciudad Vieja","o":["Montevideo's Ciudad Vieja","Colonia","Punta del Este","Salto"],"f":"The Solis Theatre and the pedestrian streets of the old city face the wide river."},{"q":"Which colonial Portuguese town on the river, founded in 1680, is a UNESCO site?","a":"Colonia del Sacramento","o":["Colonia del Sacramento","Montevideo","Carmelo","Fray Bentos"],"f":"Colonia changed hands between Spain and Portugal. Its cobbled streets face Buenos Aires across the water."},{"q":"Which city is the capital of Uruguay?","a":"Montevideo","o":["Montevideo","Seoul","Washington, D.C.","Banjul"],"f":"Montevideo is the capital of Uruguay.","kind":"capital"},{"q":"Which flag belongs to Uruguay?","a":"URY","o":["URY","HND","NIC","GNB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Uruguay.","kind":"flag"}],"medium":[{"q":"Which writer of unsettling jungle stories, born in Salto, is a classic of River Plate literature?","a":"Horacio Quiroga","o":["Horacio Quiroga","Jorge Luis Borges","Pablo Neruda","Gabriel Garcia Marquez"],"f":"Collections such as Cuentos de amor de locura y de muerte draw on the forests of Misiones, where he lived for years after leaving Uruguay."},{"q":"Uruguay hosted and won the first FIFA World Cup in which year?","a":"1930","o":["1930","1924","1934","1950"],"f":"The final was in Montevideo, and Uruguay beat Argentina 4-2. The 1950 tournament, a common wrong guess, was the one Uruguay won in Brazil."},{"q":"Colonia del Sacramento, a UNESCO old town on the River Plate, was founded in 1680 by settlers from which country?","a":"Portugal","o":["Portugal","Britain","The Netherlands","France"],"f":"Spain and Portugal traded control of the outpost for a century. Its cobbled streets still show that tug-of-war."},{"q":"What is the capital city of Uruguay?","a":"Montevideo","o":["Montevideo","Paramaribo","Buenos Aires","Santiago"],"f":"Montevideo is the capital of Uruguay.","kind":"capital"},{"q":"Which of these flags belongs to Uruguay?","a":"URY","o":["URY","BRA","COL","PRY"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Uruguay.","kind":"flag"}],"hard":[{"q":"Which 1950 World Cup result, the Maracanazo, is a national sporting memory?","a":"A 2-1 win in the final","o":["A 2-1 win in the final","A loss to Argentina","A draw with Germany","A win over England"],"f":"Uruguay beat Brazil 2-1 in Rio in the final. The upset is still retold."},{"q":"The candombe drum groups of the southern neighborhoods descend from which communities?","a":"Enslaved Africans in Montevideo","o":["Enslaved Africans in Montevideo","Italian immigrants only","Guarani missions","Gauchos"],"f":"Barrels of three sizes play candombe. Calls and drums fill the streets in summer parades."},{"q":"Which beef-processing town on the river gave its name to a canned pie?","a":"Fray Bentos","o":["Fray Bentos","Paysandu","Salto","Mercedes"],"f":"A British-owned plant at Fray Bentos shipped corned beef worldwide. The industrial landscape is a UNESCO site."},{"q":"Which of these cities is the capital of Uruguay?","a":"Montevideo","o":["Montevideo","Salto","Paysandú","Punta del Este"],"f":"Montevideo is the capital of Uruguay.","kind":"capital"},{"q":"Which flag is the flag of Uruguay?","a":"URY","o":["URY","ARG","AZE","AGO"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Uruguay.","kind":"flag"}]}},{"id":"USA","name":"United States","cont":"North America","emoji":"🇺🇸","latlng":[38,-97],"q":{"easy":[{"q":"Which canyon cut by the Colorado River is a famous national park in Arizona?","a":"The Grand Canyon","o":["The Grand Canyon","Zion","Bryce","Canyonlands"],"f":"The Grand Canyon is about 446 kilometers long. The river has cut through rock for millions of years."},{"q":"Which sweetened dish of meat and corn, and a roasted turkey, mark a November holiday?","a":"Thanksgiving dinner","o":["Thanksgiving dinner","The Fourth of July barbecue","A clambake","A luau"],"f":"Thanksgiving recalls a harvest meal and is now a national Thursday of turkey, pie, and family travel."},{"q":"Which inventor's laboratories produced the practical light bulb and the phonograph?","a":"Thomas Edison","o":["Thomas Edison","Tesla","Bell","Ford"],"f":"Edison opened the Menlo Park and later West Orange labs. He held a huge number of patents, with a team of assistants."},{"q":"Which city is the capital of United States?","a":"Washington, D.C.","o":["Washington, D.C.","Pyongyang","Bandar Seri Begawan","Reykjavík"],"f":"Washington, D.C. is the capital of United States.","kind":"capital"},{"q":"Which flag belongs to United States?","a":"USA","o":["USA","TCD","GNB","GRC"],"f":"Compare the colors and symbols. One of these four flags is the national flag of United States.","kind":"flag"}],"medium":[{"q":"Which biologist, born in Springdale, Pennsylvania, helped start the modern environmental movement with the 1962 book Silent Spring?","a":"Rachel Carson","o":["Rachel Carson","John Muir","Aldo Leopold","Henry David Thoreau"],"f":"The book showed how the pesticide DDT harmed birds and other wildlife. Muir, Leopold, and Thoreau wrote earlier classics, not Silent Spring."},{"q":"Yellowstone, set aside in 1872, is recognized as the world's first what?","a":"National park","o":["National park","National forest","Wildlife refuge","Marine sanctuary"],"f":"President Ulysses S. Grant signed the law. Its geysers, including Old Faithful, sit on one of the largest volcanic systems on the continent."},{"q":"Jazz took shape in the early 1900s especially in which city, from blues, ragtime, and brass-band traditions?","a":"New Orleans","o":["New Orleans","Chicago","New York","Kansas City"],"f":"Those other cities became jazz capitals later. The early style grew in the city's African American neighborhoods, including the brass bands of funerals and parades."},{"q":"What is the capital city of United States?","a":"Washington, D.C.","o":["Washington, D.C.","Belmopan","Kingston","Nassau"],"f":"Washington, D.C. is the capital of United States.","kind":"capital"},{"q":"Which of these flags belongs to United States?","a":"USA","o":["USA","DOM","TTO","CUB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of United States.","kind":"flag"}],"hard":[{"q":"Which 1776 document declared the colonies independent of Britain?","a":"The Declaration of Independence","o":["The Declaration of Independence","The Constitution","The Bill of Rights","The Articles of Confederation"],"f":"The Continental Congress adopted the Declaration on 4 July 1776. Thomas Jefferson was the main drafter."},{"q":"Which park, created in 1872, is often counted as the world's first national park?","a":"Yellowstone","o":["Yellowstone","Yosemite","Acadia","The Grand Canyon"],"f":"Yellowstone protects geysers and wildlife across Wyoming, Montana, and Idaho. Congress set it aside in 1872."},{"q":"Which music, born in New Orleans, mixes brass bands, blues, and ragtime?","a":"Jazz","o":["Jazz","Blues only","Country","Hip-hop"],"f":"Early jazz grew in the early 1900s from African American and Creole neighborhoods. Louis Armstrong carried it north."},{"q":"Which of these cities is the capital of United States?","a":"Washington, D.C.","o":["Washington, D.C.","New York","Los Angeles","Chicago"],"f":"Washington, D.C. is the capital of United States.","kind":"capital"},{"q":"Which flag is the flag of United States?","a":"USA","o":["USA","MYS","LBR","MAR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of United States.","kind":"flag"}]}},{"id":"UZB","name":"Uzbekistan","cont":"Asia","emoji":"🇺🇿","latlng":[41,64],"q":{"easy":[{"q":"Which old city of trading domes and a famous minaret was an emirate capital?","a":"Bukhara","o":["Bukhara","Samarkand","Khiva","Tashkent"],"f":"Bukhara's Kalon minaret and covered bazaars anchored the Silk Road. The old town is a UNESCO site."},{"q":"Which round bread, stamped in the center and baked in a tandoor, is never set upside down?","a":"Non","o":["Non","Lavash","Pita","Naan"],"f":"Non is torn by hand. The patterned center is the baker's mark, and custom treats the bread with respect."},{"q":"Which walled city of blue tile and a khan's palace stands in the northwest?","a":"Khiva","o":["Khiva","Bukhara","Shakhrisabz","Termez"],"f":"Khiva's Itchan Kala is a museum city of madrasas. It was the last major khanate capital in the region."},{"q":"Which city is the capital of Uzbekistan?","a":"Tashkent","o":["Tashkent","Tallinn","Freetown","Guatemala City"],"f":"Tashkent is the capital of Uzbekistan.","kind":"capital"},{"q":"Which flag belongs to Uzbekistan?","a":"UZB","o":["UZB","USA","MRT","CRI"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Uzbekistan.","kind":"flag"}],"medium":[{"q":"Which physician, born near Bukhara around 980, wrote the Canon of Medicine?","a":"Ibn Sina","o":["Ibn Sina","Al-Biruni","Al-Khwarizmi","Al-Farabi"],"f":"Latin Europe knew him as Avicenna, and the Canon stayed a medical textbook for centuries. Al-Biruni was a great scientist of Khwarizm. Al-Khwarizmi gave his name to the algorithm. Neither wrote this book."},{"q":"The Registan, a square framed by three tiled madrasas, is the heart of which city?","a":"Samarkand","o":["Samarkand","Bukhara","Khiva","Merv"],"f":"Timur made Samarkand his seat in the late 14th century, but the madrasas on the square are mostly 15th to 17th century. His grandson Ulugh Beg built the oldest of the three. Merv is in Turkmenistan."},{"q":"UNESCO inscribed the culture of rice cooked in one cauldron with meat, carrots, and chickpeas. What is that dish called?","a":"Plov","o":["Plov","Lagman","Shashlik","Manti"],"f":"It is also called palov or osh, and the inscription dates to 2016. An oshpaz cooks it for weddings in a giant kazan. Lagman is noodles, and manti are steamed dumplings."},{"q":"What is the capital city of Uzbekistan?","a":"Tashkent","o":["Tashkent","Tokyo","Thimphu","Hanoi"],"f":"Tashkent is the capital of Uzbekistan.","kind":"capital"},{"q":"Which of these flags belongs to Uzbekistan?","a":"UZB","o":["UZB","LKA","LBN","YEM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Uzbekistan.","kind":"flag"}],"hard":[{"q":"Which poet of the 1400s wrote a Khamsa in Chagatai Turkic and is honored as a founder of that literature?","a":"Alisher Navoi","o":["Alisher Navoi","Ferdowsi","Rumi","Rudaki"],"f":"Navoi served a Timurid court in Herat. His Chagatai poems are a root of the modern literary language."},{"q":"Ulugh Beg's observatory in Samarkand measured the stars in which century?","a":"The 1400s","o":["The 1400s","The 800s","The 1800s","The 400s"],"f":"Ulugh Beg, a Timurid ruler, built a giant sextant. His star catalog was among the best before telescopes."},{"q":"The Aral Sea, on the northwest border, shrank after rivers were diverted mainly for what crop?","a":"Cotton","o":["Cotton","Rice","Wheat","Tea"],"f":"Canals took the Amu Darya and Syr Darya into cotton fields. The sea split into smaller salty lakes."},{"q":"Which of these cities is the capital of Uzbekistan?","a":"Tashkent","o":["Tashkent","Samarkand","Bukhara","Namangan"],"f":"Tashkent is the capital of Uzbekistan.","kind":"capital"},{"q":"Which flag is the flag of Uzbekistan?","a":"UZB","o":["UZB","MNE","MOZ","HTI"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Uzbekistan.","kind":"flag"}]}},{"id":"VAT","name":"Vatican City","cont":"Europe","emoji":"🇻🇦","latlng":[41.9,12.45],"q":{"easy":[{"q":"Which vast church is built over the site tradition calls the tomb of Saint Peter?","a":"St. Peter's Basilica","o":["St. Peter's Basilica","The Lateran","Santa Maria Maggiore","The Pantheon"],"f":"The present basilica was built in the 1500s and 1600s over an older church. Michelangelo designed its dome."},{"q":"Who is the head of state of this city-state?","a":"The Pope","o":["The Pope","A president","A king","A council of cardinals only"],"f":"The Pope is bishop of Rome and sovereign of the Vatican City State. Cardinals elect him."},{"q":"Which museum complex includes the Raphael Rooms and classical sculptures?","a":"The Vatican Museums","o":["The Vatican Museums","The Louvre","The Uffizi","The Prado"],"f":"The museums grew from papal collections. Visitors follow a long route that ends at the Sistine Chapel."},{"q":"Which city is the capital of Vatican City?","a":"Vatican City","o":["Vatican City","Kuwait City","Dili","Beirut"],"f":"Vatican City is the capital of Vatican City.","kind":"capital"},{"q":"Which flag belongs to Vatican City?","a":"VAT","o":["VAT","NZL","KGZ","SSD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Vatican City.","kind":"flag"}],"medium":[{"q":"Michelangelo painted the ceiling of the Sistine Chapel between 1508 and 1512. The most famous panel shows God reaching toward whom?","a":"Adam","o":["Adam","Moses","David","Peter"],"f":"He worked on scaffolding just under the vault, mostly lying on his back. The Last Judgment, on the altar wall, came later, in the 1530s."},{"q":"The Swiss Guard, founded in 1506, still protects the pope. New recruits must be Swiss Catholic men who have finished what?","a":"Swiss military training","o":["Swiss military training","A degree in theology","Service in the French Foreign Legion","A vow of silence"],"f":"Their striped Renaissance uniform is for ceremony. On 6 May 1527 many guards died covering the pope's escape during the Sack of Rome, which is why new members are sworn in on that date."},{"q":"Vatican City is the world's smallest country by land area. It became an independent state in 1929 under which agreement with Italy?","a":"The Lateran Treaty","o":["The Lateran Treaty","The Treaty of Versailles","The Congress of Vienna","The Schengen Agreement"],"f":"From 1870 until 1929 the popes had refused to recognize the Italian kingdom that had taken Rome. The treaty created the present state of about 44 hectares."},{"q":"What is the capital city of Vatican City?","a":"Vatican City","o":["Vatican City","Monaco","Reykjavík","Dublin"],"f":"Vatican City is the capital of Vatican City.","kind":"capital"},{"q":"Which of these flags belongs to Vatican City?","a":"VAT","o":["VAT","LTU","CHE","ALB"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Vatican City.","kind":"flag"}],"hard":[{"q":"The Swiss Guard, founded in 1506, still wears a uniform of stripes and serves as what?","a":"The Pope's bodyguard","o":["The Pope's bodyguard","A ceremonial navy","The choir","The fire brigade only"],"f":"Recruits come from Switzerland and swear an oath on 6 May, the anniversary of a stand during the sack of Rome."},{"q":"The Lateran Treaty of 1929, with Italy, created the modern state and settled what?","a":"The pope's territorial sovereignty","o":["The pope's territorial sovereignty","A union with France","A seat at the League only","A colonial empire"],"f":"Italy recognized the Vatican City State as independent. The popes had been without a state since 1870."},{"q":"Latin is still an official language of the Holy See. A modern news bulletin in Latin is called what?","a":"Acta or the Latin news service","o":["Acta or the Latin news service","The Vulgate","The Codex","The Missal only"],"f":"The Holy See has published Latin news under titles such as Acta Apostolicae Sedis for official acts."},{"q":"Which of these cities is the capital of Vatican City?","a":"Vatican City","o":["Vatican City","Rome","Ostia","Frascati"],"f":"Vatican City is the capital of Vatican City.","kind":"capital"},{"q":"Which flag is the flag of Vatican City?","a":"VAT","o":["VAT","BGR","UGA","LSO"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Vatican City.","kind":"flag"}]}},{"id":"VCT","name":"Saint Vincent and the Grenadines","cont":"North America","emoji":"🇻🇨","latlng":[13.25,-61.2],"q":{"easy":[{"q":"Which volcano's crater is a hike and a garden above the capital region?","a":"La Soufriere","o":["La Soufriere","The Pitons","Kick-'em-Jenny","Mount Pelee"],"f":"La Soufriere on St. Vincent has erupted many times, including a major eruption in 2021."},{"q":"Which roasted breadfruit and fried jackfish are a simple plate?","a":"Roast breadfruit and jackfish","o":["Roast breadfruit and jackfish","Oil down","Cou-cou","Fungee"],"f":"Breadfruit, introduced in the 1790s, is roasted on a fire. Jackfish is a common catch."},{"q":"Which Grenadine island of reefs and a famous salt-water navigation is a yachting center?","a":"Bequia","o":["Bequia","Mustique","Canouan","Union Island"],"f":"Bequia has a boatbuilding tradition and a whaling history under a limited aboriginal exemption. It is the largest Grenadine of the state."},{"q":"Which city is the capital of Saint Vincent and the Grenadines?","a":"Kingstown","o":["Kingstown","Canberra","Prague","Ulaanbaatar"],"f":"Kingstown is the capital of Saint Vincent and the Grenadines.","kind":"capital"},{"q":"Which flag belongs to Saint Vincent and the Grenadines?","a":"VCT","o":["VCT","MAR","PRT","AFG"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Saint Vincent and the Grenadines.","kind":"flag"}],"medium":[{"q":"Which poet and jazz flugelhorn player, born in St. Vincent, performed in Britain with the Joe Harriott quintet?","a":"Shake Keane","o":["Shake Keane","Wynton Marsalis","Hugh Masekela","Dizzy Gillespie"],"f":"His poem cycle The Volcano Suite responds to the 1979 eruption of La Soufriere. He later returned home to work in cultural affairs."},{"q":"In 1793 William Bligh finally landed breadfruit trees here, meant to provide cheap food for whom?","a":"Enslaved plantation workers","o":["Enslaved plantation workers","The royal navy's officers","A new wine industry","Migrating songbirds"],"f":"His first voyage ended in the 1789 mutiny on the Bounty. Kingstown's botanic garden, founded in 1765, is among the oldest in the Americas and still grows breadfruit."},{"q":"La Soufriere, the island's active volcano, forced large evacuations with an explosive eruption in which year?","a":"2021","o":["2021","1995","2004","2010"],"f":"Earlier eruptions in 1902 and 1979 had also emptied the slopes. A lava dome in the crater collapses during the biggest blasts."},{"q":"What is the capital city of Saint Vincent and the Grenadines?","a":"Kingstown","o":["Kingstown","Belmopan","Roseau","Port-au-Prince"],"f":"Kingstown is the capital of Saint Vincent and the Grenadines.","kind":"capital"},{"q":"Which of these flags belongs to Saint Vincent and the Grenadines?","a":"VCT","o":["VCT","KNA","ATG","TTO"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Saint Vincent and the Grenadines.","kind":"flag"}],"hard":[{"q":"The botanical garden in the capital region is among the oldest in the Americas and once grew what transplanted crop?","a":"Breadfruit","o":["Breadfruit","Rubber","Tea","Wheat"],"f":"Captain Bligh's second voyage brought breadfruit from the Pacific in the 1790s. A descendant tree is pointed out in the garden."},{"q":"Which parrot, the national bird, lives in the mountain forest?","a":"The St. Vincent parrot","o":["The St. Vincent parrot","The sisserou","The St. Lucia parrot","The macaw"],"f":"Amazona guildingii is endemic. Its colors vary from bronze to green."},{"q":"Carib petroglyphs at which river site are a precolonial trace?","a":"The Yambou petroglyphs","o":["The Yambou petroglyphs","The Boiling Lake","Argyle","The Rabacca"],"f":"Stones along the Yambou, or Layou, valley carry carved faces. They are among the island's oldest artworks."},{"q":"Which of these cities is the capital of Saint Vincent and the Grenadines?","a":"Kingstown","o":["Kingstown","Georgetown","Barrouallie","Chateaubelair"],"f":"Kingstown is the capital of Saint Vincent and the Grenadines.","kind":"capital"},{"q":"Which flag is the flag of Saint Vincent and the Grenadines?","a":"VCT","o":["VCT","AUT","BIH","RWA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Saint Vincent and the Grenadines.","kind":"flag"}]}},{"id":"VEN","name":"Venezuela","cont":"South America","emoji":"🇻🇪","latlng":[8,-66],"q":{"easy":[{"q":"Which Caribbean town of earthen houses, founded in 1527, is a UNESCO site?","a":"Coro","o":["Coro","Cartagena","Santo Domingo","Campeche"],"f":"Santa Ana de Coro mixes Caribbean, Dutch, and Spanish building traditions. Many houses are built of earth."},{"q":"Which shredded-beef plate with black beans and rice is a national dish?","a":"Pabellon criollo","o":["Pabellon criollo","Arepa only","Hallaca","Cachapa"],"f":"Pabellon is beef, beans, rice, and fried plantain. Arepas, corn cakes, come with almost everything."},{"q":"Which cable car and forested mountain stand over the capital?","a":"El Avila, or Waraira Repano","o":["El Avila, or Waraira Repano","Pico Bolivar","Roraima","The Andes of Merida only"],"f":"The Avila range separates the city from the Caribbean. A cable car climbs to a high station."},{"q":"Which city is the capital of Venezuela?","a":"Caracas","o":["Caracas","Ouagadougou","Vientiane","Kathmandu"],"f":"Caracas is the capital of Venezuela.","kind":"capital"},{"q":"Which flag belongs to Venezuela?","a":"VEN","o":["VEN","CUB","KGZ","CHN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Venezuela.","kind":"flag"}],"medium":[{"q":"Which leader, born in Caracas, led independence armies across northern South America and gave his name to Bolivia?","a":"Simon Bolivar","o":["Simon Bolivar","Jose de San Martin","Bernardo O'Higgins","Antonio Jose de Sucre"],"f":"Bolivar's campaigns helped free Venezuela, Colombia, Ecuador, Peru, and Bolivia from Spanish rule. Sucre, a close general, was a different person."},{"q":"Which cascade in Canaima National Park is recognized as the world's highest uninterrupted waterfall?","a":"Angel Falls","o":["Angel Falls","Kaieteur Falls","Iguazu Falls","Gocta Falls"],"f":"It drops off Auyan-tepui. The English name honors pilot Jimmie Angel, who landed on the mesa in 1937, not a biblical angel. The Pemon name is Kerepakupai-meru."},{"q":"Over Lake Maracaibo, the Catatumbo region is famous for storms that produce what on many nights of the year?","a":"Frequent lightning","o":["Frequent lightning","Nightly snow","Red sandstorms","Auroras"],"f":"Warm lake air meets cooler winds from the Andes, building huge thunderclouds. Sailors once used the flashes as a natural lighthouse."},{"q":"What is the capital city of Venezuela?","a":"Caracas","o":["Caracas","Georgetown","Montevideo","Buenos Aires"],"f":"Caracas is the capital of Venezuela.","kind":"capital"},{"q":"Which of these flags belongs to Venezuela?","a":"VEN","o":["VEN","URY","GUY","ARG"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Venezuela.","kind":"flag"}],"hard":[{"q":"Which kinetic artist, born in Ciudad Bolivar in 1923, made the Penetrables that visitors walk through?","a":"Jesus Rafael Soto","o":["Jesus Rafael Soto","Carlos Cruz-Diez","Alexander Calder","Yaacov Agam"],"f":"Soto was a leader of kinetic art. A museum of his work stands in his hometown."},{"q":"The llanos, the great plains, flood each year and support which traditional cowboy?","a":"The llanero","o":["The llanero","The gaucho","The huaso","The charro"],"f":"Llaneros herd cattle from horseback and play joropo music on harp and maracas."},{"q":"Lake Maracaibo's nighttime lightning storm, Catatumbo, is caused by what meeting?","a":"Warm lake air and cool mountain air","o":["Warm lake air and cool mountain air","A volcano","A permanent fire","The aurora"],"f":"Storms form where moisture from the lake hits the Andes. The lightning is frequent for much of the year."},{"q":"Which of these cities is the capital of Venezuela?","a":"Caracas","o":["Caracas","Maracaibo","Valencia","Maracay"],"f":"Caracas is the capital of Venezuela.","kind":"capital"},{"q":"Which flag is the flag of Venezuela?","a":"VEN","o":["VEN","ECU","COL","AUS"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Venezuela.","kind":"flag"}]}},{"id":"VNM","name":"Vietnam","cont":"Asia","emoji":"🇻🇳","latlng":[16.16666666,107.83333333],"q":{"easy":[{"q":"Which rice-noodle soup with herbs and beef or chicken is the national breakfast?","a":"Pho","o":["Pho","Bun bo Hue","Banh mi","Com tam"],"f":"Pho simmers beef bones for hours. It is served with lime, basil, and chili."},{"q":"Which tunic worn over trousers is a national garment?","a":"The ao dai","o":["The ao dai","The hanbok","The kimono","The sari"],"f":"The ao dai is a long fitted tunic with side slits. It is worn at school ceremonies and festivals."},{"q":"Which old trading port of yellow houses and lanterns is a UNESCO town?","a":"Hoi An","o":["Hoi An","Hue","Hanoi","Da Nang"],"f":"Hoi An's Japanese bridge and Chinese shophouses recall a river port that silted up and kept its old streets."},{"q":"Which city is the capital of Vietnam?","a":"Hanoi","o":["Hanoi","Paris","Copenhagen","Oslo"],"f":"Hanoi is the capital of Vietnam.","kind":"capital"},{"q":"Which flag belongs to Vietnam?","a":"VNM","o":["VNM","ESP","DJI","BGR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Vietnam.","kind":"flag"}],"medium":[{"q":"Which poet, born in 1766, wrote The Tale of Kieu, the classic verse novel of the language?","a":"Nguyễn Du","o":["Nguyễn Du","Ho Xuan Huong","Nguyen Trai","Ho Chi Minh"],"f":"The story follows Kieu, who sacrifices herself for her family. Ho Xuan Huong wrote sharp folk poems, Nguyen Trai was a 15th-century statesman, and Ho Chi Minh wrote political verse, not this tale."},{"q":"Thousands of limestone towers rise from the sea in the northeast, a UNESCO landscape whose name means descending dragon. What is the bay called?","a":"Ha Long Bay","o":["Ha Long Bay","Phang Nga Bay","Lan Ha Bay","Bai Tu Long Bay"],"f":"Fishers still live on the water, and the limestone is full of caves. Phang Nga is a similar bay in Thailand. Lan Ha and Bai Tu Long are neighboring waters, not the named UNESCO bay of the descending dragon."},{"q":"Puppets on poles, hidden under the water, perform on a flooded stage. That art is called what?","a":"Water puppetry","o":["Water puppetry","Shadow puppetry","Noh","Wayang kulit"],"f":"It grew up in the flooded rice fields of the Red River delta. The puppeteers stand in the water behind a screen. Wayang kulit is the leather shadow theatre of Indonesia."},{"q":"What is the capital city of Vietnam?","a":"Hanoi","o":["Hanoi","Dili","Kathmandu","Naypyidaw"],"f":"Hanoi is the capital of Vietnam.","kind":"capital"},{"q":"Which of these flags belongs to Vietnam?","a":"VNM","o":["VNM","JPN","PSE","AFG"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Vietnam.","kind":"flag"}],"hard":[{"q":"The Tale of Kieu, a verse novel by Nguyen Du, follows a woman who does what to save her family?","a":"Sacrifices her own freedom","o":["Sacrifices her own freedom","Becomes a queen","Sails to France","Invents the ao dai"],"f":"Nguyen Du wrote in the early 1800s, borrowing a Chinese plot and making it Vietnamese. The poem is memorized in school."},{"q":"Which fish sauce, fermented from anchovies, seasons almost every savory dish?","a":"Nuoc mam","o":["Nuoc mam","Soy sauce","Fish sauce of only Thailand","Garum only of Rome"],"f":"Nuoc mam ages in wooden vats, especially on Phu Quoc and in Phan Thiet. A few drops salt a bowl of rice."},{"q":"Water puppets, a northern art, are operated how?","a":"By puppeteers standing in the water behind a screen","o":["By puppeteers standing in the water behind a screen","By strings from above","By shadows","By computers"],"f":"The form grew in flooded rice fields. Dragons and fish appear to swim."},{"q":"Which of these cities is the capital of Vietnam?","a":"Hanoi","o":["Hanoi","Ho Chi Minh City","Da Nang","Hue"],"f":"Hanoi is the capital of Vietnam.","kind":"capital"},{"q":"Which flag is the flag of Vietnam?","a":"VNM","o":["VNM","MAR","CHN","HUN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Vietnam.","kind":"flag"}]}},{"id":"VUT","name":"Vanuatu","cont":"Oceania","emoji":"🇻🇺","latlng":[-16,167],"q":{"easy":[{"q":"Which volcano on Tanna island, reached by a road of ash, glows at night?","a":"Mount Yasur","o":["Mount Yasur","Ambrym","Ambae","Lopevi"],"f":"Yasur has been erupting for centuries. Visitors can look into the crater when the activity allows."},{"q":"Which drink of kava, called here by a local name, is the men's evening drink?","a":"Kava, or malok","o":["Kava, or malok","Tea","Coffee","Beer only"],"f":"Shells of kava are passed in nakamals, the meeting grounds. The drink is bitter and calming."},{"q":"Which land-diving ritual, the ancestor of bungee, is performed on Pentecost island?","a":"The nagol","o":["The nagol","The haka","Firewalking","A cargo cult dance"],"f":"Men jump from towers with vines tied to their ankles. The dive is a yam-harvest rite."},{"q":"Which city is the capital of Vanuatu?","a":"Port Vila","o":["Port Vila","Bucharest","Nairobi","Tehran"],"f":"Port Vila is the capital of Vanuatu.","kind":"capital"},{"q":"Which flag belongs to Vanuatu?","a":"VUT","o":["VUT","CPV","UZB","NGA"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Vanuatu.","kind":"flag"}],"medium":[{"q":"On Pentecost Island, men jump from tall towers with vines tied to their ankles. What is this called?","a":"Land diving","o":["Land diving","Firewalking","Pearl diving","Outrigger racing"],"f":"The nagol jumps are meant to bless the yam harvest. Films of the dives inspired modern bungee jumping."},{"q":"Before independence in 1980, Britain and France ruled the islands at the same time under what system?","a":"A condominium","o":["A condominium","A caliphate","A shogunate","A city-state"],"f":"The New Hebrides had two police forces, two courts, and two school systems. People joked that even the rules of the road were doubled."},{"q":"Mount Yasur on Tanna is famous because visitors can watch which frequent volcanic activity from the rim?","a":"Bursts of lava","o":["Bursts of lava","A boiling mud pot only","Calving glaciers","Sand avalanches"],"f":"Yasur has erupted almost continuously for centuries. Its regular explosions make it one of the most approachable active volcanoes."},{"q":"What is the capital city of Vanuatu?","a":"Port Vila","o":["Port Vila","Nuku'alofa","South Tarawa","Ngerulmud"],"f":"Port Vila is the capital of Vanuatu.","kind":"capital"},{"q":"Which of these flags belongs to Vanuatu?","a":"VUT","o":["VUT","FSM","PLW","KIR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Vanuatu.","kind":"flag"}],"hard":[{"q":"Which joint British and French rule, a condominium, governed the islands until 1980?","a":"The Condominium of the New Hebrides","o":["The Condominium of the New Hebrides","A German colony","A Japanese mandate","An American territory"],"f":"Two flags, two police forces, and two school systems ran side by side. Independence created Vanuatu."},{"q":"Bislama, the national creole, grew from which trade language?","a":"Plantation and ship English","o":["Plantation and ship English","French only","Polynesian","Chinese"],"f":"Bislama is close to Tok Pisin and Solomon Pijin. It is the language of parliament and markets."},{"q":"The cargo cults of Tanna, including the John Frum movement, arose around which century's wars?","a":"The 20th","o":["The 20th","The 18th","The 16th","The 21st only"],"f":"John Frum followers expect a return of goods and a just order. The movement is a documented response to colonial and wartime upheaval."},{"q":"Which of these cities is the capital of Vanuatu?","a":"Port Vila","o":["Port Vila","Luganville","Isangel","Lakatoro"],"f":"Port Vila is the capital of Vanuatu.","kind":"capital"},{"q":"Which flag is the flag of Vanuatu?","a":"VUT","o":["VUT","CUB","SGP","VNM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Vanuatu.","kind":"flag"}]}},{"id":"WSM","name":"Samoa","cont":"Oceania","emoji":"🇼🇸","latlng":[-13.58333333,-172.33333333],"q":{"easy":[{"q":"Which lava-coast blowholes on Savai'i shoot spray high when the swell rises?","a":"The Alofaaga blowholes","o":["The Alofaaga blowholes","The To Sua trench","The Papaseea slide","Afu Aau falls"],"f":"Ocean swell is forced through lava tubes and explodes upward. The place is also called the Taga blowholes."},{"q":"Which roast pig and palusami of coconut cream and taro leaves are a feast?","a":"Umu pork and palusami","o":["Umu pork and palusami","Luau only of Hawaii","Hangi","Mumu"],"f":"An umu is the earth oven. Palusami wraps taro leaves around coconut cream."},{"q":"Which tattoo from the waist to the knees is a man's traditional mark?","a":"The pe'a","o":["The pe'a","The tatau of only Tonga","The moko","The sak yant"],"f":"The pe'a is applied with bone or steel combs over many days. It is a passage to adulthood."},{"q":"Which city is the capital of Samoa?","a":"Apia","o":["Apia","Santo Domingo","Phnom Penh","Reykjavík"],"f":"Apia is the capital of Samoa.","kind":"capital"},{"q":"Which flag belongs to Samoa?","a":"WSM","o":["WSM","SLE","BLR","TJK"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Samoa.","kind":"flag"}],"medium":[{"q":"Which novelist, a founder of modern Pacific literature, was born in Apia?","a":"Albert Wendt","o":["Albert Wendt","Chinua Achebe","Gabriel Garcia Marquez","Derek Walcott"],"f":"His novel Leaves of the Banyan Tree follows a Samoan family across generations. He also taught and championed other Pacific writers."},{"q":"Which author of Treasure Island lived his last years in Samoa and is buried on Mount Vaea?","a":"Robert Louis Stevenson","o":["Robert Louis Stevenson","Robert Burns","Walter Scott","Arthur Conan Doyle"],"f":"Stevenson settled at Vailima, above Apia, in 1890 and died there in 1894. Samoans called him Tusitala, the teller of tales."},{"q":"Traditional Samoan tatau is tapped into the skin with a comb made of bone or tusk and what else?","a":"A wooden mallet","o":["A wooden mallet","A quill pen","A hot iron brand","A sewing needle"],"f":"The English word tattoo comes from Polynesian tatau. A full pe'a or malu is a long, painful ceremony and a major mark of identity."},{"q":"What is the capital city of Samoa?","a":"Apia","o":["Apia","Majuro","Yaren","Nuku'alofa"],"f":"Apia is the capital of Samoa.","kind":"capital"},{"q":"Which of these flags belongs to Samoa?","a":"WSM","o":["WSM","VUT","FJI","TON"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Samoa.","kind":"flag"}],"hard":[{"q":"The country was named for which geographic feature by Europeans, and later took a name meaning what?","a":"The sacred center, or Sa-moa as explained locally","o":["The sacred center, or Sa-moa as explained locally","The navigator islands only","The friendly islands","The savage islands"],"f":"Samoa is often glossed as sacred center. The old European name was the Navigator Islands."},{"q":"Which title of a high chief, and the talking chief, structure a village council?","a":"Ali'i and tulafale","o":["Ali'i and tulafale","A king only","A president only","A priest only"],"f":"The tulafale speaks for the chief. Fine mats, ie toga, are the highest valuables exchanged."},{"q":"Which cyclone in 1990 and another in 1991 flattened much of the islands and changed the economy?","a":"Cyclones Ofa and Val","o":["Cyclones Ofa and Val","Winston","Pam","Haiyan"],"f":"The twin cyclones destroyed crops and houses. Many people moved to New Zealand and Australia afterward."},{"q":"Which of these cities is the capital of Samoa?","a":"Apia","o":["Apia","Salelologa","Mulifanua","Leulumoega"],"f":"Apia is the capital of Samoa.","kind":"capital"},{"q":"Which flag is the flag of Samoa?","a":"WSM","o":["WSM","RUS","USA","COG"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Samoa.","kind":"flag"}]}},{"id":"YEM","name":"Yemen","cont":"Asia","emoji":"🇾🇪","latlng":[15,48],"q":{"easy":[{"q":"Which stew of lamb, fenugreek froth, and vegetables is the national lunch?","a":"Saltah","o":["Saltah","Mandi","Kabsa","Harees"],"f":"Saltah is eaten from a shared pot, the maqla. A fenugreek foam, holba, sits on top."},{"q":"Which curved dagger worn at the waist is part of formal dress?","a":"The jambiya","o":["The jambiya","The khanjar of Oman only","The kukri","The kris"],"f":"The jambiya's handle can be wood, horn, or the prized rhinoceros horn of older pieces. It is a mark of adulthood."},{"q":"Which mud-brick tower town in the Hadramaut is nicknamed a desert Manhattan?","a":"Shibam","o":["Shibam","Sana'a old city","Zabid","Thula"],"f":"Shibam's houses rise many stories inside a walled square. It is a UNESCO site."},{"q":"Which city is the constitutional capital of Yemen?","a":"Sana'a","o":["Sana'a","Zagreb","Pretoria","Amsterdam"],"f":"Sana'a is the historic capital named in the constitution. Aden is a major southern port.","kind":"capital"},{"q":"Which flag belongs to Yemen?","a":"YEM","o":["YEM","ZWE","LBY","SOM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Yemen.","kind":"flag"}],"medium":[{"q":"On Socotra, an umbrella-shaped tree that bleeds red resin grows wild nowhere else. What is it called?","a":"The dragon blood tree","o":["The dragon blood tree","The baobab","The frankincense tree","The coco de mer"],"f":"The species is Dracaena cinnabari, and the resin was used as dye and medicine. Frankincense trees grow on the southern Arabian mainland. The coco de mer is a palm of the Seychelles."},{"q":"A Red Sea port gave its name to a style of coffee because the beans were shipped from there. What was the port?","a":"Mocha","o":["Mocha","Aden","Muscat","Jeddah"],"f":"The coffee plant was domesticated in the Ethiopian highlands. Yemeni merchants made the drink a world trade, and Europeans first met the beans at Mocha. The plant was not native to Arabia."},{"q":"Shibam, a UNESCO town of mud-brick tower houses in the Hadramaut, is nicknamed what?","a":"The Manhattan of the desert","o":["The Manhattan of the desert","The Venice of the East","The Pompeii of Arabia","The Petra of the South"],"f":"Most of the towers were built from the 16th century on, packed inside a walled rectangle and rebuilt after floods. They are mud brick, not the stone tombs of Petra."},{"q":"What is the constitutional capital city of Yemen?","a":"Sana'a","o":["Sana'a","Phnom Penh","Kathmandu","Bangkok"],"f":"Sana'a is the historic capital named in the constitution. Aden is a major southern port.","kind":"capital"},{"q":"Which of these flags belongs to Yemen?","a":"YEM","o":["YEM","ARM","MNG","QAT"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Yemen.","kind":"flag"}],"hard":[{"q":"Mocha, the old coffee port on the Red Sea, gave its name to what?","a":"A coffee style","o":["A coffee style","A spice","A ship","A cloth"],"f":"Coffee from the highlands was shipped through al-Mukha. European languages kept the port's name for the drink."},{"q":"The island of Socotra, in the Arabian Sea, is famous for which strange trees?","a":"Dragon's blood trees","o":["Dragon's blood trees","Baobabs","Joshua trees","Monkey-puzzle trees"],"f":"Dracaena cinnabari has an umbrella shape. Its red resin was a dye and a medicine."},{"q":"Which Jewish and Muslim tradition of chanting poetry in Sana'a was listed by UNESCO?","a":"The songs of Sana'a","o":["The songs of Sana'a","Ghazals of only Persia","Flamenco","Qawwali"],"f":"Al-Ghina al-San'ani is a classical song with the oud. It was a refined urban art."},{"q":"Which of these cities is the constitutional capital of Yemen?","a":"Sana'a","o":["Sana'a","Aden","Taiz","Al Hudaydah"],"f":"Sana'a is the historic capital named in the constitution. Aden is a major southern port.","kind":"capital"},{"q":"Which flag is the flag of Yemen?","a":"YEM","o":["YEM","IRQ","EGY","SYR"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Yemen.","kind":"flag"}]}},{"id":"ZAF","name":"South Africa","cont":"Africa","emoji":"🇿🇦","latlng":[-29,24],"q":{"easy":[{"q":"Which flat-topped mountain stands over the harbor of Cape Town?","a":"Table Mountain","o":["Table Mountain","Aconcagua","Kilimanjaro","Mount Sinai"],"f":"Table Mountain's sandstone cliffs face the Atlantic and the Indian Ocean. A cable car climbs the plateau."},{"q":"Which dried seasoned meat is a classic snack?","a":"Biltong","o":["Biltong","Sushi","Jerky of only North America","Pemmican"],"f":"Biltong is cured with vinegar and spices and dried in the air. It came from older drying traditions of the trek."},{"q":"Which leader, freed in 1990 after decades in prison, became president in 1994?","a":"Nelson Mandela","o":["Nelson Mandela","Kwame Nkrumah","Jomo Kenyatta","Julius Nyerere"],"f":"Mandela led the transition from apartheid. He served one term and died in 2013."},{"q":"Which city is the administrative capital of South Africa, where the president's offices sit?","a":"Pretoria","o":["Pretoria","Suva","Ottawa","Bishkek"],"f":"Pretoria is the administrative capital. Cape Town is the legislative capital, and Bloemfontein is the judicial capital.","kind":"capital"},{"q":"Which flag belongs to South Africa?","a":"ZAF","o":["ZAF","PHL","ARG","MNG"],"f":"Compare the colors and symbols. One of these four flags is the national flag of South Africa.","kind":"flag"}],"medium":[{"q":"Nelson Mandela was born in 1918 in which village?","a":"Mvezo","o":["Mvezo","Soweto","Qunu","Johannesburg"],"f":"He grew up in Qunu, nearby, in the Thembu line. Soweto was the township of his later politics. He became president in 1994, after 27 years in prison."},{"q":"On 3 December 1967 Christiaan Barnard led the first human-to-human heart transplant at which hospital?","a":"Groote Schuur Hospital","o":["Groote Schuur Hospital","Baragwanath Hospital","The Mayo Clinic","Hammersmith Hospital"],"f":"Louis Washkansky lived 18 days. The donor was Denise Darvall. Barnard had trained partly in the United States, but the operation was in Cape Town."},{"q":"In 1925 Abraham Perold crossed Pinot Noir with Cinsaut, then called Hermitage, and created which grape?","a":"Pinotage","o":["Pinotage","Chenin blanc","Cabernet Sauvignon","Shiraz"],"f":"The name joins Pinot and Hermitage. He planted the seeds at Stellenbosch and almost forgot them. Chenin blanc is widely grown here too, but it is a French grape, not this cross."},{"q":"What is the administrative capital of South Africa, home to the president's offices?","a":"Pretoria","o":["Pretoria","Nairobi","Djibouti","Niamey"],"f":"Pretoria is the administrative capital. Cape Town is the legislative capital, and Bloemfontein is the judicial capital.","kind":"capital"},{"q":"Which of these flags belongs to South Africa?","a":"ZAF","o":["ZAF","TUN","LBR","SSD"],"f":"Compare the colors and symbols. One of these four flags is the national flag of South Africa.","kind":"flag"}],"hard":[{"q":"The Cradle of Humankind near Johannesburg holds caves with fossils of what?","a":"Early human relatives","o":["Early human relatives","Dinosaur eggs only","Roman mosaics","Pharaohs"],"f":"Sterkfontein and nearby caves have yielded australopithecine fossils, including the skull called Mrs Ples."},{"q":"Which 1976 protest by students in Soweto began over which school language?","a":"Afrikaans as a teaching language","o":["Afrikaans as a teaching language","Latin","Japanese","Arabic"],"f":"On 16 June 1976 students marched against being taught in Afrikaans. The day is now Youth Day."},{"q":"Pinotage, a red wine, was bred in 1925 by crossing pinot noir with which grape?","a":"Hermitage, or cinsaut","o":["Hermitage, or cinsaut","Cabernet","Riesling","Merlot"],"f":"A professor in Stellenbosch created the cross. It later became a signature South African red."},{"q":"Which of these cities is the administrative capital of South Africa?","a":"Pretoria","o":["Pretoria","Cape Town","Bloemfontein","Johannesburg"],"f":"Pretoria is the administrative capital. Cape Town is the legislative capital, and Bloemfontein is the judicial capital.","kind":"capital"},{"q":"Which flag is the flag of South Africa?","a":"ZAF","o":["ZAF","JPN","ETH","IDN"],"f":"Compare the colors and symbols. One of these four flags is the national flag of South Africa.","kind":"flag"}]}},{"id":"ZMB","name":"Zambia","cont":"Africa","emoji":"🇿🇲","latlng":[-15,30],"q":{"easy":[{"q":"Which huge man-made lake on the Zambezi is shared with Zimbabwe?","a":"Lake Kariba","o":["Lake Kariba","Lake Volta","Lake Nasser","Lake Mead"],"f":"Kariba Dam, finished in 1959, flooded a gorge and created one of the world's largest reservoirs."},{"q":"Which relish of greens cooked in ground peanuts is served beside the maize porridge?","a":"Ifisashi","o":["Ifisashi","Chikanda","Kapenta","Vitumbuwa"],"f":"Leafy vegetables or pumpkin leaves simmer in peanut flour. It is an ordinary home dish."},{"q":"Which national park on the Luangwa River is famous for walking safaris and leopards?","a":"South Luangwa","o":["South Luangwa","Kruger","Etosha","Chobe"],"f":"South Luangwa pioneered walking safaris. Thorn trees and oxbow lagoons hold large cats and elephants."},{"q":"Which city is the capital of Zambia?","a":"Lusaka","o":["Lusaka","Beirut","Port-au-Prince","Jakarta"],"f":"Lusaka is the capital of Zambia.","kind":"capital"},{"q":"Which flag belongs to Zambia?","a":"ZMB","o":["ZMB","VCT","VUT","DOM"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Zambia.","kind":"flag"}],"medium":[{"q":"Who led the country to independence in 1964 and was its first president?","a":"Kenneth Kaunda","o":["Kenneth Kaunda","Robert Mugabe","Julius Nyerere","Samora Machel"],"f":"He headed the United National Independence Party and ruled until 1991. Independence Day is 24 October 1964. Mugabe, Nyerere, and Machel led Zimbabwe, Tanzania, and Mozambique."},{"q":"Livingstone named a waterfall Victoria Falls. The older name, Mosi-oa-Tunya, means what?","a":"The smoke that thunders","o":["The smoke that thunders","The boiling pot","The place of rainbows","The end of the river"],"f":"The falls stand on the border with Zimbabwe, so neither country owns them alone. Mist rises far above the gorge, which is the smoke. The Boiling Pot is a gorge downstream, a different feature."},{"q":"The maize porridge eaten by hand with a relish of vegetables, beans, or fish is called what?","a":"Nshima","o":["Nshima","Fufu","Injera","Couscous"],"f":"Neighbors call a similar porridge nsima or sadza. Many people do not count a meal as real without it. Fufu is a pounded root, and injera is a fermented bread."},{"q":"What is the capital city of Zambia?","a":"Lusaka","o":["Lusaka","Asmara","Gaborone","Pretoria"],"f":"Lusaka is the capital of Zambia.","kind":"capital"},{"q":"Which of these flags belongs to Zambia?","a":"ZMB","o":["ZMB","GIN","COD","LSO"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Zambia.","kind":"flag"}],"hard":[{"q":"Which red metal made the northern mining towns rich in the 1900s?","a":"Copper","o":["Copper","Gold","Diamonds","Tin"],"f":"Ndola, Kitwe, and neighboring cities sit on one of the world's great copper deposits."},{"q":"Which masked dance of the Lozi and related peoples marks the Kuomboka, when the king moves off the flood?","a":"The royal barge ceremony","o":["The royal barge ceremony","The haka","Intore","Gule Wamkulu"],"f":"At Kuomboka the Lozi king leaves the flooded Zambezi plain on a painted barge for higher ground."},{"q":"Kenneth Kaunda led the country to independence in 1964 from which empire?","a":"Britain","o":["Britain","France","Portugal","Belgium"],"f":"Kaunda's slogan was One Zambia, One Nation. He ruled until multiparty elections in 1991."},{"q":"Which of these cities is the capital of Zambia?","a":"Lusaka","o":["Lusaka","Ndola","Kitwe","Livingstone"],"f":"Lusaka is the capital of Zambia.","kind":"capital"},{"q":"Which flag is the flag of Zambia?","a":"ZMB","o":["ZMB","TON","SSD","AFG"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Zambia.","kind":"flag"}]}},{"id":"ZWE","name":"Zimbabwe","cont":"Africa","emoji":"🇿🇼","latlng":[-20,30],"q":{"easy":[{"q":"Which ruined stone city of the 11th to 15th centuries gave the country its name?","a":"The mortarless stone city","o":["The mortarless stone city","Kilwa","Timbuktu","Axum"],"f":"Great Zimbabwe's walls were built without mortar. It was the capital of a Shona kingdom that traded gold."},{"q":"Which maize porridge is the daily starch?","a":"Sadza","o":["Sadza","Sushi","Paella","Poutine"],"f":"Sadza is maize porridge, like nshima next door. It is eaten with greens, beans, or meat."},{"q":"Which balancing granite rocks near the capital are a famous natural sculpture?","a":"The Balancing Rocks","o":["The Balancing Rocks","Uluru","The Tsingy","Meteora"],"f":"The Epworth balancing rocks are stacked boulders of granite, a common sight on the highveld."},{"q":"Which city is the capital of Zimbabwe?","a":"Harare","o":["Harare","Tashkent","Chișinău","Baghdad"],"f":"Harare is the capital of Zimbabwe.","kind":"capital"},{"q":"Which flag belongs to Zimbabwe?","a":"ZWE","o":["ZWE","BTN","GUY","POL"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Zimbabwe.","kind":"flag"}],"medium":[{"q":"Great Zimbabwe, the stone city that gave the country its name, flourished mainly in which centuries?","a":"The 11th to the 15th","o":["The 11th to the 15th","The 1st to the 3rd","The 18th and the 19th","The 7th century BCE"],"f":"Walls were stacked without mortar, and gold went out to the Indian Ocean. Early European visitors doubted that local people built it; archaeology shows they did. The modern state took the name at independence in 1980."},{"q":"A sculpture movement encouraged from the 1950s, strongly associated with Shona artists, is known for carving what?","a":"Local stone such as serpentine","o":["Local stone such as serpentine","Imported Carrara marble only","Ice","Venetian glass"],"f":"Frank McEwen at the National Gallery supported the early workshop. Artists such as Nicholas Mukomberanwa became famous. The stone is local, and the styles are modern, not copies of the ancient birds."},{"q":"Which novelist, born in Mutoko in 1959, wrote Nervous Conditions?","a":"Tsitsi Dangarembga","o":["Tsitsi Dangarembga","Doris Lessing","NoViolet Bulawayo","Yvonne Vera"],"f":"The novel, published in 1988, follows Tambu. Vera and Bulawayo are also major novelists from this country. Lessing grew up here but was born in Iran, and she did not write that book."},{"q":"What is the capital city of Zimbabwe?","a":"Harare","o":["Harare","Juba","Algiers","Gaborone"],"f":"Harare is the capital of Zimbabwe.","kind":"capital"},{"q":"Which of these flags belongs to Zimbabwe?","a":"ZWE","o":["ZWE","BFA","GNB","MDG"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Zimbabwe.","kind":"flag"}],"hard":[{"q":"The stone birds carved at Great Zimbabwe became a national emblem. They were found in which part of the site?","a":"The Hill Complex","o":["The Hill Complex","The Great Enclosure only","The valley market","A Roman forum"],"f":"Soapstone birds stood on columns in the eastern enclosure of the hill. Several were taken to South Africa and later returned."},{"q":"Mbira music plucks metal keys on a board. The instrument is also called what?","a":"A thumb piano","o":["A thumb piano","A violin","A flute","A drum"],"f":"The mbira dza vadzimu is played to call ancestral spirits. Bottles or shells buzz on the board."},{"q":"The Shona and Ndebele are the two largest peoples. The Ndebele kingdom of the 1800s was founded by whom?","a":"Mzilikazi","o":["Mzilikazi","Shaka","Moshoeshoe","Cetshwayo"],"f":"Mzilikazi broke from Shaka's Zulu kingdom and led his followers north, founding a state at Bulawayo."},{"q":"Which of these cities is the capital of Zimbabwe?","a":"Harare","o":["Harare","Bulawayo","Mutare","Gweru"],"f":"Harare is the capital of Zimbabwe.","kind":"capital"},{"q":"Which flag is the flag of Zimbabwe?","a":"ZWE","o":["ZWE","DZA","POL","TUV"],"f":"Compare the colors and symbols. One of these four flags is the national flag of Zimbabwe.","kind":"flag"}]}},{"id":"ATA","name":"Antarctica","cont":"Antarctica","emoji":"🇦🇶","latlng":[-90,0],"q":{"easy":[{"q":"Which large penguin incubates its egg on the sea ice through the Antarctic winter?","a":"The emperor penguin","o":["The emperor penguin","The Adelie penguin","The king penguin","The Galapagos penguin"],"f":"The male emperor balances the egg on his feet for about two months while the female feeds at sea."},{"q":"Which ocean surrounds the continent?","a":"The Southern Ocean","o":["The Southern Ocean","The Arctic Ocean","The Indian Ocean only","The Mediterranean"],"f":"The Southern Ocean rings Antarctica. Its current isolates the cold waters around the ice."},{"q":"Which dry, ice-free valleys near McMurdo Sound are a famous polar desert?","a":"The McMurdo Dry Valleys","o":["The McMurdo Dry Valleys","The Sahara","The Atacama","The Gobi"],"f":"The Dry Valleys receive almost no snow. Mummified seals and salt lakes lie among the rocks."},{"q":"What is the capital of Antarctica?","a":"There is no capital","o":["There is no capital","Oslo","Canberra","Wellington"],"f":"The 1959 Antarctic Treaty sets the continent aside for peace and science. Antarctica has no capital city.","kind":"capital"},{"q":"Which flag belongs to Antarctica?","a":"NONE","o":["NONE","BRA","JPN","CAN"],"f":"The 1959 Antarctic Treaty sets the continent aside for peace and science. Antarctica has no national flag.","kind":"flag"}],"medium":[{"q":"Who led the first expedition confirmed to reach the South Pole, arriving in December 1911?","a":"Roald Amundsen","o":["Roald Amundsen","Robert Falcon Scott","Ernest Shackleton","Richard Byrd"],"f":"Amundsen's team skied with sled dogs and reached the pole on 14 December 1911. Scott arrived about a month later, and his party died on the return."},{"q":"Which volcano on Ross Island is the world's southernmost active volcano and holds a lava lake?","a":"Mount Erebus","o":["Mount Erebus","Mount Vinson","Mount Etna","Deception Island"],"f":"Erebus has been erupting for decades. Deception Island, farther north, is also an Antarctic volcano, but it is not the southernmost."},{"q":"Through the Antarctic winter, a male emperor penguin balances the single egg on his feet and covers it with what?","a":"A flap of belly skin","o":["A flap of belly skin","A nest of twigs","A burrow of sand","A ring of stones"],"f":"He does not eat for about two months while the female returns to the sea. Chicks hatch into one of the coldest seasons on Earth."},{"q":"Which is the capital city of Antarctica?","a":"There is no capital","o":["There is no capital","Pretoria","Buenos Aires","Wellington"],"f":"The 1959 Antarctic Treaty sets the continent aside for peace and science. Antarctica has no capital city.","kind":"capital"},{"q":"Which of these flags belongs to Antarctica?","a":"NONE","o":["NONE","KEN","IND","MEX"],"f":"The 1959 Antarctic Treaty sets the continent aside for peace and science. Antarctica has no national flag.","kind":"flag"}],"hard":[{"q":"Ernest Shackleton's ship Endurance was crushed by ice in 1915 during an attempt to do what?","a":"Cross the continent","o":["Cross the continent","Reach the North Pole","Find a northwest passage","Map Australia"],"f":"Shackleton's men camped on the ice, then reached Elephant Island. He sailed a small boat to South Georgia for help."},{"q":"Which freshwater lake lies under kilometers of ice near the Russian research station?","a":"Lake Vostok","o":["Lake Vostok","Lake Baikal","Lake Erie","Lake Vanda only"],"f":"Lake Vostok is one of the largest subglacial lakes. Scientists debate how to sample it without contamination."},{"q":"The ozone hole over the continent, reported in 1985, was linked to which chemicals?","a":"Chlorofluorocarbons","o":["Chlorofluorocarbons","Carbon dioxide only","Methane from cattle","Sulfur from volcanoes only"],"f":"British scientists at Halley station measured the spring ozone loss. A global treaty later cut CFCs."},{"q":"Which of these is the capital of Antarctica?","a":"There is no capital","o":["There is no capital","McMurdo Station","Ushuaia","Punta Arenas"],"f":"The 1959 Antarctic Treaty sets the continent aside for peace and science. Antarctica has no capital city.","kind":"capital"},{"q":"Which flag is the flag of Antarctica?","a":"NONE","o":["NONE","CHL","ARG","NOR"],"f":"The 1959 Antarctic Treaty sets the continent aside for peace and science. Antarctica has no national flag.","kind":"flag"}]}}];
